/// Provider-neutral reasoning operator used by a structured reader draft.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum GroundedReasoningOperatorKind {
    /// Direct source extraction or one typed scalar value.
    Direct,
    /// Complete source-cited item ledger and deterministic materialization.
    CollectionLedger,
    /// Distinct source-cited units whose validated ledger length is the count.
    CountLedger,
    /// A source-stated schedule or dated occurrence ledger yielding a cadence.
    FrequencyCadence,
    /// Comparison of named or grounded candidate hypotheses.
    HypothesisComparison,
    /// Resolve one requested scalar value from a source-grounded directed
    /// relationship anchor.
    ///
    /// A direct requested-type value and a contract-authorized stable public
    /// one-hop projection use the same structural operation. Citation and role
    /// validation do not prove that source prose semantically entails the
    /// declared relationship, its participants, or the projected value.
    RelationValueResolution,
    /// Bounded join between an event anchor and an attribute-bearing source.
    EventAttributeJoin,
    /// Calendar point or bounded period. A direct value preserves the typed
    /// query granularity; a derived point subtracts a source-cited exact
    /// integral elapsed duration from a source-cited reference day.
    ///
    /// The arithmetic is deterministic, but its inputs remain consumer claims:
    /// citation membership does not prove semantic entailment by source prose.
    TemporalPoint,
    /// Explicit duration or bounded calculation from temporal boundaries.
    TemporalSpan,
}

/// One complete structured reasoning operation.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct GroundedReasoningOperator {
    kind: GroundedReasoningOperatorKind,
    inputs: Vec<GroundedOperatorInput>,
    compared_candidates: Vec<GroundedComparedCandidate>,
    output: Option<String>,
    unresolved_competitors: Vec<String>,
}

impl GroundedReasoningOperator {
    /// Create an empty operator of one kind.
    pub fn new(kind: GroundedReasoningOperatorKind) -> Self {
        Self {
            kind,
            inputs: Vec::new(),
            compared_candidates: Vec::new(),
            output: None,
            unresolved_competitors: Vec::new(),
        }
    }

    /// Attach role-labelled finding inputs.
    pub fn with_inputs(mut self, inputs: Vec<GroundedOperatorInput>) -> Self {
        self.inputs = inputs;
        self
    }

    /// Attach candidates explicitly assessed by a hypothesis comparison.
    pub fn with_compared_candidates(
        mut self,
        compared_candidates: Vec<GroundedComparedCandidate>,
    ) -> Self {
        self.compared_candidates = compared_candidates;
        self
    }

    /// Attach the operator's proposed final output.
    pub fn with_output(mut self, output: impl Into<String>) -> Self {
        self.output = Some(output.into());
        self
    }

    /// Attach competitors that remain materially unresolved.
    pub fn with_unresolved_competitors(mut self, unresolved_competitors: Vec<String>) -> Self {
        self.unresolved_competitors = unresolved_competitors;
        self
    }

    /// Return the operator kind.
    pub const fn kind(&self) -> GroundedReasoningOperatorKind {
        self.kind
    }

    /// Return role-labelled finding inputs.
    pub fn inputs(&self) -> &[GroundedOperatorInput] {
        &self.inputs
    }

    /// Return explicitly assessed candidates.
    pub fn compared_candidates(&self) -> &[GroundedComparedCandidate] {
        &self.compared_candidates
    }

    /// Return the proposed final operator output.
    pub fn output(&self) -> Option<&str> {
        self.output.as_deref()
    }

    /// Return candidates that remain unresolved.
    pub fn unresolved_competitors(&self) -> &[String] {
        &self.unresolved_competitors
    }
}

