/// Typed provider output accepted by deterministic reader reconciliation.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct GroundedAnswerDraft {
    /// Proposed shortest complete answer.
    pub candidate_answer: String,
    /// Source-cited final values, or distinct list items and counted events.
    pub answer_items: Vec<GroundedAnswerItem>,
    /// Every source node cited anywhere in the analysis.
    pub cited_source_node_ids: Vec<NodeId>,
    /// Whether the analysis found a required missing or ambiguous premise.
    pub missing_or_ambiguous: bool,
    /// Whether a count or collection intentionally resolved to no items.
    ///
    /// This distinguishes a declared empty result from a missing item ledger.
    /// It does not establish that the search was semantically complete.
    pub empty_item_set: bool,
    /// Structured findings retained by new adapters. Empty preserves the
    /// legacy source-membership-only contract.
    findings: Vec<GroundedEvidenceFinding>,
    /// Typed reasoning operation retained by new adapters.
    reasoning_operator: Option<GroundedReasoningOperator>,
}

impl GroundedAnswerDraft {
    /// Create a typed draft parsed by a consumer adapter.
    pub fn new(
        candidate_answer: impl Into<String>,
        answer_items: Vec<GroundedAnswerItem>,
        cited_source_node_ids: Vec<NodeId>,
        missing_or_ambiguous: bool,
    ) -> Self {
        Self {
            candidate_answer: candidate_answer.into(),
            answer_items,
            cited_source_node_ids,
            missing_or_ambiguous,
            empty_item_set: false,
            findings: Vec::new(),
            reasoning_operator: None,
        }
    }

    /// Mark a count or collection draft as an intentionally empty result.
    pub fn with_empty_item_set(mut self, empty_item_set: bool) -> Self {
        self.empty_item_set = empty_item_set;
        self
    }

    /// Attach structured source-grounded findings.
    pub fn with_findings(mut self, findings: Vec<GroundedEvidenceFinding>) -> Self {
        self.findings = findings;
        self
    }

    /// Attach the typed reasoning operation used by this draft.
    pub fn with_reasoning_operator(mut self, operator: GroundedReasoningOperator) -> Self {
        self.reasoning_operator = Some(operator);
        self
    }

    /// Return structured findings retained by this draft.
    pub fn findings(&self) -> &[GroundedEvidenceFinding] {
        &self.findings
    }

    /// Return the typed reasoning operation retained by this draft.
    pub fn reasoning_operator(&self) -> Option<&GroundedReasoningOperator> {
        self.reasoning_operator.as_ref()
    }
}

/// Whether a structurally valid grounded draft proposes an answer.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum GroundedDraftDisposition {
    /// The draft proposes a grounded candidate for final verification.
    Answerable,
    /// The draft reports that a required premise remains absent or ambiguous.
    Unresolved,
}

/// Structural status presented to the bounded reader-recovery policy.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum GroundedDraftStatus {
    /// The provider response could not be parsed or structurally validated.
    Invalid,
    /// The validated draft proposes a grounded candidate.
    Answerable,
    /// The validated draft reports a required unresolved premise.
    Unresolved,
}

impl GroundedDraftStatus {
    /// Derive recovery status from a core validation result.
    pub fn from_validation(validation: &GroundedDraftValidationResult) -> Self {
        match validation {
            Ok(validation) => match validation.disposition {
                GroundedDraftDisposition::Answerable => Self::Answerable,
                GroundedDraftDisposition::Unresolved => Self::Unresolved,
            },
            Err(_) => Self::Invalid,
        }
    }
}

/// Whether the current final-reader output is an answer or an abstention.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum ReaderFinalDisposition {
    /// The reader returned a non-abstaining answer.
    Answer,
    /// The reader reported that no answer was available.
    Abstention,
}

/// Authority available to a structurally valid grounded adjudication.
///
/// Source membership and commit-bound source roles are useful validation
/// constraints, but neither proves that the cited prose semantically entails
/// a generated answer. [`Self::ManifestEntailed`] is reserved for a future
/// engine-issued claim manifest that binds a typed proposition to the exact
/// readout receipt. Merely constructing this enum never creates such proof.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum GroundedClaimAuthority {
    /// Validation proves only that every citation belongs to delivered input.
    MembershipOnly,
    /// An engine-issued receipt additionally binds closed source roles.
    SourceRoleBound,
    /// An engine-issued manifest proves the typed claim is entailed.
    ManifestEntailed,
}

impl GroundedClaimAuthority {
    /// Return whether this authority can independently justify replacing a
    /// useful direct candidate in a future enforcement policy.
    pub const fn permits_semantic_overwrite(self) -> bool {
        matches!(self, Self::ManifestEntailed)
    }
}

/// Narrow surface relationship between a direct candidate and a materialized
/// typed answer. This classification is telemetry, not semantic equivalence.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum GroundedCandidateSurfaceRelation {
    /// The typed draft materialized to no answer.
    NoMaterializedAnswer,
    /// The direct reader abstained or supplied no candidate to compare.
    NoDirectCandidate,
    /// Conservative scalar normalization produced the same surface value.
    Convergent,
    /// The two normalized surfaces differ.
    Different,
}

/// Authority-aware action recommended by the non-mutating shadow policy.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum GroundedAdjudicationShadowAction {
    /// No materialized answer exists, so abstention remains appropriate.
    PreserveAbstention,
    /// The typed answer converges with the direct candidate.
    AcceptConvergentAnswer,
    /// Entailed authority permits a correction to replace the direct answer.
    AcceptAuthoritativeCorrection,
    /// A differing membership-only answer needs independent conflict proof.
    VerifyConflictBeforeOverwrite,
    /// Entailed authority permits an answer after an independent abstention.
    AcceptAuthoritativeIndependentAnswer,
    /// Membership or source-role authority cannot resolve an abstention alone.
    RequireEntailmentBeforeIndependentAnswer,
}

/// Observational result of the authority-aware adjudication shadow policy.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub struct GroundedAdjudicationShadowAssessment {
    authority: GroundedClaimAuthority,
    surface_relation: GroundedCandidateSurfaceRelation,
    action: GroundedAdjudicationShadowAction,
}

impl GroundedAdjudicationShadowAssessment {
    /// Authority available to the validated draft.
    pub const fn authority(&self) -> GroundedClaimAuthority {
        self.authority
    }

    /// Conservative surface relationship to the direct candidate.
    pub const fn surface_relation(&self) -> GroundedCandidateSurfaceRelation {
        self.surface_relation
    }

    /// Action a future authority-aware policy would require.
    pub const fn action(&self) -> GroundedAdjudicationShadowAction {
        self.action
    }
}

/// Next operation in the direct-first grounded readout protocol.
///
/// The protocol keeps provider calls outside the engine. A reader-owning
/// consumer executes the selected operation, parses any structured response
/// into [`GroundedAnswerDraft`], and returns it to this contract for the next
/// deterministic transition.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum GroundedReadoutAction {
    /// Return the original non-abstaining direct candidate byte-for-byte.
    ReturnDirectCandidate,
    /// Adjudicate a non-abstaining direct candidate as untrusted control state.
    AdjudicateDirectCandidate,
    /// Adjudicate from the delivered evidence without carrying an abstention
    /// candidate or its rationale into the structured pass.
    AdjudicateEvidenceIndependently,
    /// Repair one invalid adjudicated draft, then validate it again.
    RepairAdjudicatedDraft,
    /// Deterministically materialize one valid answerable adjudicated draft.
    MaterializeAdjudicatedDraft,
    /// Preserve the original non-abstaining direct candidate after the one
    /// structured repair budget has been exhausted.
    PreserveDirectCandidate,
    /// Preserve an abstention because the typed result is unresolved or the
    /// one structured repair budget has been exhausted.
    PreserveAbstention,
}

/// Next bounded recovery operation for a reader-owning consumer.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum GroundedDraftRecoveryAction {
    /// Keep the reader's non-abstaining final answer unchanged.
    AcceptFinalAnswer,
    /// Keep the abstention; no further recovery operation is safe or available.
    PreserveAbstention,
    /// Repair the invalid structured draft once, then validate it again.
    RepairDraft,
    /// Reverify an answerable draft once against the delivered evidence.
    ReverifyAnswerableDraft,
    /// Reconsider one unresolved draft once against the complete delivered
    /// evidence, then preserve any repeated abstention.
    ReverifyUnresolvedDraft,
}

/// Per-read state that bounds draft repair and answer reverification.
///
/// The state contains no provider or global data. A transport owns one state
/// for one final-answer attempt and executes the action returned by
/// [`RecallReaderContract::next_recovery_action`].
/// Each state instance permits at most one repair and one reverification. The
/// reverification budget is shared by answerable and unresolved drafts.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
#[non_exhaustive]
pub struct GroundedDraftRecoveryState {
    repair_attempted: bool,
    reverification_attempted: bool,
}

impl GroundedDraftRecoveryState {
    /// Create an unused recovery budget.
    pub fn new() -> Self {
        Self::default()
    }

    /// Return whether a structured-draft repair has already been selected.
    pub fn repair_attempted(&self) -> bool {
        self.repair_attempted
    }

    /// Return whether answer reverification has already been selected.
    pub fn reverification_attempted(&self) -> bool {
        self.reverification_attempted
    }
}

/// Commit-safe source roles retained for one resolved event-boundary recall.
///
/// Values of this type are issued only by the prepared-rerank completion path
/// after the event-boundary route has been revalidated and its raw sources
/// have survived visible delivery. Public access is intentionally read-only:
/// ordinary source membership cannot manufacture temporal-role authority.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct EventBoundaryEvidence {
    direction: TemporalBoundaryDirection,
    anchor_source_node_ids: Vec<NodeId>,
    target_source_node_ids: Vec<NodeId>,
}

impl EventBoundaryEvidence {
    /// Strict side of the boundary authorized by this receipt.
    pub const fn direction(&self) -> TemporalBoundaryDirection {
        self.direction
    }

    /// Canonical raw sources that establish the boundary event.
    pub fn anchor_source_node_ids(&self) -> &[NodeId] {
        &self.anchor_source_node_ids
    }

    /// Canonical raw sources on the requested side of the boundary.
    pub fn target_source_node_ids(&self) -> &[NodeId] {
        &self.target_source_node_ids
    }
}

/// Render the closed, provider-neutral authority carried by one event-boundary
/// receipt. The result contains no query, evidence, fact, or model text.
pub(super) fn event_boundary_authority_guidance(evidence: &EventBoundaryEvidence) -> String {
    let direction = match evidence.direction() {
        TemporalBoundaryDirection::Before => "before",
        TemporalBoundaryDirection::After => "after",
    };
    let render_source_ids = |source_node_ids: &[NodeId]| {
        source_node_ids
            .iter()
            .map(|source_node_id| format!("node:{}", source_node_id.0))
            .collect::<Vec<_>>()
            .join(", ")
    };
    format!(
        "Event-boundary authority: direction={direction}; anchor sources=[{}]; target sources=[{}]. Use at least one anchor-only premise through a premise input. Target-only contextual premises are allowed. Never mix anchor and target citations in one premise. Cite eligible collection findings and final answer items only from target sources.",
        render_source_ids(evidence.anchor_source_node_ids()),
        render_source_ids(evidence.target_source_node_ids()),
    )
}

/// Additional commit-safe authority available to grounded-draft validation.
///
/// [`Self::membership_only`] preserves the long-standing source-membership
/// contract. A context carrying event-boundary evidence is issued by
/// [`Memory::readout_for_reranked`](super::Memory::readout_for_reranked) from a
/// completed prepared-rerank receipt; callers cannot create that authority
/// from a later [`Recall`](crate::memory::Recall) reconstruction.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
#[non_exhaustive]
pub struct GroundedDraftValidationContext {
    event_boundary_evidence: Option<EventBoundaryEvidence>,
    bound_plan: Option<RecallPlan>,
    bound_source_node_ids: Vec<NodeId>,
}

impl GroundedDraftValidationContext {
    /// Create a context that verifies delivered-source membership only.
    pub const fn membership_only() -> Self {
        Self {
            event_boundary_evidence: None,
            bound_plan: None,
            bound_source_node_ids: Vec::new(),
        }
    }

    /// Return the commit-safe event-boundary source roles, when available.
    pub const fn event_boundary_evidence(&self) -> Option<&EventBoundaryEvidence> {
        self.event_boundary_evidence.as_ref()
    }

    /// Return the strongest authority this exact validation context carries.
    ///
    /// Event-boundary evidence binds source roles but still does not prove
    /// free-form semantic entailment, so it cannot authorize an overwrite by
    /// itself.
    pub const fn claim_authority(&self) -> GroundedClaimAuthority {
        if self.event_boundary_evidence.is_some() {
            GroundedClaimAuthority::SourceRoleBound
        } else {
            GroundedClaimAuthority::MembershipOnly
        }
    }

    pub(super) fn with_event_boundary_evidence(
        evidence: EventBoundaryEvidence,
        plan: &RecallPlan,
        delivered_source_node_ids: &[NodeId],
    ) -> Self {
        let mut bound_source_node_ids = delivered_source_node_ids.to_vec();
        bound_source_node_ids.sort_unstable();
        bound_source_node_ids.dedup();
        Self {
            event_boundary_evidence: Some(evidence),
            bound_plan: Some(plan.clone()),
            bound_source_node_ids,
        }
    }

    pub(super) fn is_bound_to(
        &self,
        plan: &RecallPlan,
        delivered_source_node_ids: &[NodeId],
    ) -> bool {
        let mut delivered = delivered_source_node_ids.to_vec();
        delivered.sort_unstable();
        delivered.dedup();
        self.bound_plan.as_ref() == Some(plan) && self.bound_source_node_ids == delivered
    }
}

/// Successful structural validation of one provider-neutral grounded draft.
///
/// Validation establishes source membership and the minimum typed draft shape;
/// it does not verify that a cited source semantically entails the answer.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct GroundedDraftValidation {
    /// Whether the provider proposed an answer or reported an unresolved gap.
    pub disposition: GroundedDraftDisposition,
    /// Sorted, de-duplicated delivered sources cited by the draft or its items.
    pub validated_source_node_ids: Vec<NodeId>,
    /// Number of answer items submitted by the consumer.
    pub answer_item_count: usize,
}

/// Result of deterministic grounded-draft structural validation.
pub type GroundedDraftValidationResult =
    Result<GroundedDraftValidation, GroundedDraftValidationError>;

/// One typed reason a grounded draft cannot be accepted as structurally valid.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum GroundedDraftValidationFailure {
    /// The proposed candidate answer is blank after trimming.
    MissingCandidate,
    /// An answerable draft has no delivered source citation.
    MissingGroundingCitation,
    /// A draft reports an unresolved gap while still proposing a candidate.
    CandidatePresentForUnresolved,
    /// A draft reports an unresolved gap while still proposing final items.
    AnswerItemsPresentForUnresolved,
    /// An unresolved draft also claims an intentionally empty result set.
    EmptyItemSetPresentForUnresolved,
    /// A non-empty count or collection omitted its required item ledger.
    MissingAnswerItemsForPopulatedSet,
    /// A typed scalar draft did not provide exactly one answer item.
    StructuredScalarAnswerItemCount {
        /// Number of answer items supplied by the draft.
        actual_count: usize,
    },
    /// A typed scalar candidate and its sole answer item normalize differently.
    ScalarCandidateDoesNotMatchAnswerItem,
    /// A binary hypothesis candidate or operator output lacks explicit yes/no
    /// polarity.
    BinaryCandidateMissingExplicitPolarity,
    /// A binary hypothesis states polarity without a concrete grounded
    /// discriminator or supporting phrase.
    BinaryCandidateMissingConcreteSupport,
    /// A temporal-point operator did not supply one unambiguous source-grounded
    /// direct or reference ISO calendar day.
    InvalidTemporalPointReference,
    /// A temporal-point operator did not supply exactly one exact positive
    /// integral duration expressed in days, weeks, or calendar months.
    InvalidTemporalPointElapsedDuration,
    /// A temporal-point candidate was not the canonical calendar day verified
    /// directly or computed from its grounded reference and duration inputs.
    TemporalPointCandidateDoesNotMatchComputed,
    /// An answerable event-boundary collection has no commit-safe role receipt.
    MissingEventBoundaryEvidence,
    /// An event-boundary receipt has empty, duplicate, overlapping, or
    /// undelivered source roles.
    InvalidEventBoundaryEvidence,
    /// The receipt authorizes the opposite side of the event boundary from the
    /// reader contract.
    EventBoundaryDirectionMismatch {
        /// Direction required by the reader contract, or `None` for an
        /// unresolved boundary direction.
        expected: Option<TemporalBoundaryDirection>,
        /// Direction authorized by the prepared-rerank receipt.
        actual: TemporalBoundaryDirection,
    },
    /// No premise finding is grounded exclusively in boundary-anchor sources.
    MissingEventBoundaryAnchorPremise,
    /// An anchor-grounded premise exists but is not consumed by a
    /// [`GroundedOperatorInputRole::Premise`] input.
    EventBoundaryAnchorPremiseNotConsumed,
    /// A consumed premise mixes anchor and target roles or cites a source in
    /// neither role. Anchor-only and target-only premises remain distinct and
    /// valid.
    EventBoundaryPremiseCitationOutsideAnchor {
        /// Zero-based premise-finding position.
        finding_index: usize,
        /// Cited source outside the receipt's anchor role.
        source_node_id: NodeId,
    },
    /// An eligible collection finding cites a source outside the receipt's
    /// target role.
    EventBoundaryItemCitationOutsideTarget {
        /// Zero-based item-finding position.
        finding_index: usize,
        /// Cited source outside the receipt's target role.
        source_node_id: NodeId,
    },
    /// A final collection item cites a source outside the receipt's target
    /// role.
    EventBoundaryAnswerItemCitationOutsideTarget {
        /// Zero-based final-item position.
        item_index: usize,
        /// Cited source outside the receipt's target role.
        source_node_id: NodeId,
    },
    /// A collection candidate omitted one value present in its source-cited
    /// item ledger.
    CollectionCandidateMissingAnswerItem {
        /// Zero-based ledger item absent from the candidate answer.
        item_index: usize,
    },
    /// Two count or collection ledger entries normalize to the same value.
    DuplicateNormalizedAnswerItem {
        /// First zero-based occurrence of the normalized value.
        first_item_index: usize,
        /// Later zero-based occurrence that must be merged or removed.
        duplicate_item_index: usize,
    },
    /// A count or collection declared empty while still supplying items.
    AnswerItemsPresentForEmptyItemSet,
    /// An intentionally empty item set was declared for a scalar answer shape.
    EmptyItemSetUnsupportedForAnswerShape,
    /// A count candidate was not a canonical unsigned base-10 integer.
    InvalidCountCandidate,
    /// A count candidate did not equal the number of submitted answer items.
    CountCandidateDoesNotMatchAnswerItems {
        /// Count proposed by the draft candidate.
        candidate_count: usize,
        /// Number of distinct submitted event items.
        answer_item_count: usize,
    },
    /// A count unit or frequency occurrence did not consume exactly one item
    /// finding.
    ///
    /// This structural check makes each ledger entry independently cited and
    /// countable. It cannot prove that a consumer's free-form item value is
    /// semantically atomic.
    LedgerItemFindingCount {
        /// Zero-based answer-item position.
        item_index: usize,
        /// Number of distinct item findings referenced by that answer item.
        actual_count: usize,
    },
    /// A strict count-ledger item omitted its stable occurrence identity.
    MissingCountOccurrenceKey {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// A strict count-ledger item omitted its occurrence lifecycle state.
    MissingCountOccurrenceActuality {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// A non-occurred finding was promoted into a strict count ledger.
    CountOccurrenceNotOccurred {
        /// Zero-based finding position.
        finding_index: usize,
        /// Provider-declared lifecycle state rejected from the count.
        actuality: GroundedOccurrenceActuality,
    },
    /// A strict count-ledger item also claimed to be a duplicate finding.
    CountItemHasDuplicateReference {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// Two eligible strict count-ledger items used one occurrence identity.
    DuplicateCountOccurrenceKey {
        /// First zero-based item-finding position using the identity.
        first_finding_index: usize,
        /// Later zero-based item-finding position using the identity.
        duplicate_finding_index: usize,
    },
    /// A finding with duplicate metadata was not excluded from the result.
    DuplicateOccurrenceFindingNotExcluded {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// A duplicate finding did not point directly at one existing canonical finding.
    ///
    /// Empty, unknown, self-referential, chained, and cyclic targets all fail
    /// this structural check.
    InvalidDuplicateOccurrenceTarget {
        /// Zero-based duplicate-finding position.
        finding_index: usize,
    },
    /// A duplicate finding omitted or contradicted its canonical occurrence metadata.
    InvalidDuplicateOccurrenceMetadata {
        /// Zero-based duplicate-finding position.
        finding_index: usize,
    },
    /// A top-level draft citation was not among the delivered source ids.
    UnknownDraftCitation {
        /// Undelivered source id supplied by the draft.
        source_node_id: NodeId,
    },
    /// One submitted answer item has a blank value.
    EmptyAnswerItemValue {
        /// Zero-based answer-item position.
        item_index: usize,
    },
    /// One submitted answer item has no citation.
    MissingAnswerItemCitation {
        /// Zero-based answer-item position.
        item_index: usize,
    },
    /// An item citation is absent from the draft's declared citation union.
    AnswerItemCitationMissingFromDraft {
        /// Zero-based answer-item position.
        item_index: usize,
        /// Item citation missing from the top-level draft union.
        source_node_id: NodeId,
    },
    /// An answer-item citation was not among the delivered source ids.
    UnknownAnswerItemCitation {
        /// Zero-based answer-item position.
        item_index: usize,
        /// Undelivered source id supplied by that item.
        source_node_id: NodeId,
    },
    /// A structured finding has no stable identifier.
    EmptyFindingId {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// Two structured findings use the same identifier.
    DuplicateFindingId {
        /// First zero-based occurrence of the identifier.
        first_finding_index: usize,
        /// Later zero-based occurrence that must be renamed or removed.
        duplicate_finding_index: usize,
    },
    /// A structured finding has no source-grounded fact text.
    EmptyFindingFact {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// A structured finding cites no source.
    MissingFindingCitation {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// A finding citation is absent from the draft citation union.
    FindingCitationMissingFromDraft {
        /// Zero-based finding position.
        finding_index: usize,
        /// Finding citation missing from the top-level union.
        source_node_id: NodeId,
    },
    /// A structured finding cites a source that was not delivered.
    UnknownFindingCitation {
        /// Zero-based finding position.
        finding_index: usize,
        /// Undelivered source id supplied by the finding.
        source_node_id: NodeId,
    },
    /// An eligible item finding has no final answer value.
    MissingItemFindingAnswerValue {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// An eligible item finding is absent from the answer-item ledger.
    ItemFindingNotConsumed {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// An eligible item finding was consumed by more than one ledger item.
    ItemFindingConsumedMultipleTimes {
        /// Zero-based finding position.
        finding_index: usize,
        /// Number of answer items that referenced the finding.
        consumption_count: usize,
    },
    /// An answer item does not preserve its item finding's normalized value.
    ItemFindingValueMismatch {
        /// Zero-based finding position.
        finding_index: usize,
        /// Zero-based answer-item position.
        item_index: usize,
    },
    /// A typed answer item does not identify any consumed finding.
    MissingAnswerItemFindingReference {
        /// Zero-based answer-item position.
        item_index: usize,
    },
    /// An answer item refers to an unknown finding identifier.
    UnknownAnswerItemFindingReference {
        /// Zero-based answer-item position.
        item_index: usize,
        /// Unknown stable finding identifier.
        finding_id: String,
    },
    /// An excluded finding was incorrectly promoted to a final answer item.
    ExcludedFindingReferencedByAnswerItem {
        /// Zero-based answer-item position.
        item_index: usize,
        /// Zero-based excluded-finding position.
        finding_index: usize,
    },
    /// An item-ledger answer item consumed a premise instead of an item finding.
    NonItemFindingReferencedByLedgerItem {
        /// Zero-based answer-item position.
        item_index: usize,
        /// Zero-based premise-finding position.
        finding_index: usize,
    },
    /// An answer item omitted one of its referenced finding's citations.
    AnswerItemMissingFindingCitation {
        /// Zero-based answer-item position.
        item_index: usize,
        /// Zero-based referenced-finding position.
        finding_index: usize,
        /// Source that must be present on the answer item.
        source_node_id: NodeId,
    },
    /// An excluded finding does not state why it is ineligible.
    MissingFindingExclusionReason {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// An eligible item finding also carries an exclusion explanation.
    ItemFindingHasExclusionReason {
        /// Zero-based finding position.
        finding_index: usize,
    },
    /// A scalar relationship operator placed an answer-value input before one
    /// or more source-grounded relation-premise inputs.
    RelationPremiseMustPrecedeAnswerValue,
    /// One finding was reused as both the relation anchor and its resolved
    /// requested value instead of retaining distinct roles.
    RelationFindingUsedByBothRoles {
        /// Zero-based finding position used by both roles.
        finding_index: usize,
    },
    /// A scalar relationship operator assigned a finding disposition that does
    /// not match its semantic input role.
    RelationFindingDispositionMismatch {
        /// Zero-based finding position.
        finding_index: usize,
        /// Operator role whose disposition obligation was violated.
        role: GroundedOperatorInputRole,
    },
    /// The sole scalar answer item did not consume one relation-resolution
    /// finding referenced by its operator.
    RelationAnswerItemMissingOperatorFinding {
        /// Zero-based finding position omitted from the answer item.
        finding_index: usize,
        /// Operator role under which the finding was consumed.
        role: GroundedOperatorInputRole,
    },
    /// A resolved scalar relationship value retained one or more material
    /// competitors instead of returning an unresolved draft.
    RelationValueHasUnresolvedCompetitors,
    /// A typed draft omitted the reasoning operator required by its query.
    MissingReasoningOperator,
    /// The supplied reasoning operator does not match the requested answer.
    UnexpectedReasoningOperatorKind {
        /// Operator kind required by the reader contract.
        expected: GroundedReasoningOperatorKind,
        /// Operator kind supplied by the draft.
        actual: GroundedReasoningOperatorKind,
    },
    /// A reasoning operator refers to an unknown finding identifier.
    UnknownOperatorFindingReference {
        /// Unknown stable finding identifier.
        finding_id: String,
    },
    /// A reasoning-operator input referred to an excluded finding.
    ExcludedFindingReferencedByOperatorInput {
        /// Zero-based excluded-finding position.
        finding_index: usize,
    },
    /// An item-ledger or explicit-schedule input referred to a premise finding.
    NonItemFindingReferencedByOperatorItemInput {
        /// Zero-based premise-finding position.
        finding_index: usize,
    },
    /// A compared hypothesis referred to an excluded finding.
    ExcludedFindingReferencedByComparedCandidate {
        /// Zero-based excluded-finding position.
        finding_index: usize,
    },
    /// A reasoning operator omitted one required semantic input role.
    MissingOperatorInputRole {
        /// Input role required by the operator contract.
        role: GroundedOperatorInputRole,
    },
    /// A reasoning operator input omitted one required known finding.
    OperatorOmittedFinding {
        /// Zero-based finding position.
        finding_index: usize,
        /// Input role that must consume the finding.
        role: GroundedOperatorInputRole,
    },
    /// A cadence inferred from occurrences had fewer than three distinct
    /// source-grounded observations.
    InsufficientFrequencyOccurrences {
        /// Number of distinct occurrence findings consumed by the operator.
        actual_count: usize,
    },
    /// A hypothesis operator did not assess any candidates.
    MissingComparedCandidates,
    /// A hypothesis operator omitted one explicitly named query alternative.
    MissingComparedAlternative {
        /// Query-derived alternative that was not compared.
        value: String,
    },
    /// A resolved hypothesis output did not name any assessed candidate.
    HypothesisOutputDoesNotMatchComparedCandidate,
    /// An answerable typed draft omitted its operator output.
    MissingOperatorOutput,
    /// An operator output does not match the candidate answer.
    OperatorOutputDoesNotMatchCandidate,
    /// An unresolved typed draft still proposes an operator output.
    OperatorOutputPresentForUnresolved,
}

impl GroundedDraftValidationFailure {
    /// Stable provider-neutral name used by repair instructions and telemetry.
    pub fn code(&self) -> &'static str {
        match self {
            Self::MissingCandidate => "MissingCandidate",
            Self::MissingGroundingCitation => "MissingGroundingCitation",
            Self::CandidatePresentForUnresolved => "CandidatePresentForUnresolved",
            Self::AnswerItemsPresentForUnresolved => "AnswerItemsPresentForUnresolved",
            Self::EmptyItemSetPresentForUnresolved => "EmptyItemSetPresentForUnresolved",
            Self::MissingAnswerItemsForPopulatedSet => "MissingAnswerItemsForPopulatedSet",
            Self::StructuredScalarAnswerItemCount { .. } => "StructuredScalarAnswerItemCount",
            Self::ScalarCandidateDoesNotMatchAnswerItem => "ScalarCandidateDoesNotMatchAnswerItem",
            Self::BinaryCandidateMissingExplicitPolarity => {
                "BinaryCandidateMissingExplicitPolarity"
            }
            Self::BinaryCandidateMissingConcreteSupport => "BinaryCandidateMissingConcreteSupport",
            Self::InvalidTemporalPointReference => "InvalidTemporalPointReference",
            Self::InvalidTemporalPointElapsedDuration => "InvalidTemporalPointElapsedDuration",
            Self::TemporalPointCandidateDoesNotMatchComputed => {
                "TemporalPointCandidateDoesNotMatchComputed"
            }
            Self::MissingEventBoundaryEvidence => "MissingEventBoundaryEvidence",
            Self::InvalidEventBoundaryEvidence => "InvalidEventBoundaryEvidence",
            Self::EventBoundaryDirectionMismatch { .. } => "EventBoundaryDirectionMismatch",
            Self::MissingEventBoundaryAnchorPremise => "MissingEventBoundaryAnchorPremise",
            Self::EventBoundaryAnchorPremiseNotConsumed => "EventBoundaryAnchorPremiseNotConsumed",
            Self::EventBoundaryPremiseCitationOutsideAnchor { .. } => {
                "EventBoundaryPremiseCitationOutsideAnchor"
            }
            Self::EventBoundaryItemCitationOutsideTarget { .. } => {
                "EventBoundaryItemCitationOutsideTarget"
            }
            Self::EventBoundaryAnswerItemCitationOutsideTarget { .. } => {
                "EventBoundaryAnswerItemCitationOutsideTarget"
            }
            Self::CollectionCandidateMissingAnswerItem { .. } => {
                "CollectionCandidateMissingAnswerItem"
            }
            Self::DuplicateNormalizedAnswerItem { .. } => "DuplicateNormalizedAnswerItem",
            Self::AnswerItemsPresentForEmptyItemSet => "AnswerItemsPresentForEmptyItemSet",
            Self::EmptyItemSetUnsupportedForAnswerShape => "EmptyItemSetUnsupportedForAnswerShape",
            Self::InvalidCountCandidate => "InvalidCountCandidate",
            Self::CountCandidateDoesNotMatchAnswerItems { .. } => {
                "CountCandidateDoesNotMatchAnswerItems"
            }
            Self::LedgerItemFindingCount { .. } => "LedgerItemFindingCount",
            Self::MissingCountOccurrenceKey { .. } => "MissingCountOccurrenceKey",
            Self::MissingCountOccurrenceActuality { .. } => "MissingCountOccurrenceActuality",
            Self::CountOccurrenceNotOccurred { .. } => "CountOccurrenceNotOccurred",
            Self::CountItemHasDuplicateReference { .. } => "CountItemHasDuplicateReference",
            Self::DuplicateCountOccurrenceKey { .. } => "DuplicateCountOccurrenceKey",
            Self::DuplicateOccurrenceFindingNotExcluded { .. } => {
                "DuplicateOccurrenceFindingNotExcluded"
            }
            Self::InvalidDuplicateOccurrenceTarget { .. } => "InvalidDuplicateOccurrenceTarget",
            Self::InvalidDuplicateOccurrenceMetadata { .. } => "InvalidDuplicateOccurrenceMetadata",
            Self::UnknownDraftCitation { .. } => "UnknownDraftCitation",
            Self::EmptyAnswerItemValue { .. } => "EmptyAnswerItemValue",
            Self::MissingAnswerItemCitation { .. } => "MissingAnswerItemCitation",
            Self::AnswerItemCitationMissingFromDraft { .. } => "AnswerItemCitationMissingFromDraft",
            Self::UnknownAnswerItemCitation { .. } => "UnknownAnswerItemCitation",
            Self::EmptyFindingId { .. } => "EmptyFindingId",
            Self::DuplicateFindingId { .. } => "DuplicateFindingId",
            Self::EmptyFindingFact { .. } => "EmptyFindingFact",
            Self::MissingFindingCitation { .. } => "MissingFindingCitation",
            Self::FindingCitationMissingFromDraft { .. } => "FindingCitationMissingFromDraft",
            Self::UnknownFindingCitation { .. } => "UnknownFindingCitation",
            Self::MissingItemFindingAnswerValue { .. } => "MissingItemFindingAnswerValue",
            Self::ItemFindingNotConsumed { .. } => "ItemFindingNotConsumed",
            Self::ItemFindingConsumedMultipleTimes { .. } => "ItemFindingConsumedMultipleTimes",
            Self::ItemFindingValueMismatch { .. } => "ItemFindingValueMismatch",
            Self::MissingAnswerItemFindingReference { .. } => "MissingAnswerItemFindingReference",
            Self::UnknownAnswerItemFindingReference { .. } => "UnknownAnswerItemFindingReference",
            Self::ExcludedFindingReferencedByAnswerItem { .. } => {
                "ExcludedFindingReferencedByAnswerItem"
            }
            Self::NonItemFindingReferencedByLedgerItem { .. } => {
                "NonItemFindingReferencedByLedgerItem"
            }
            Self::AnswerItemMissingFindingCitation { .. } => "AnswerItemMissingFindingCitation",
            Self::MissingFindingExclusionReason { .. } => "MissingFindingExclusionReason",
            Self::ItemFindingHasExclusionReason { .. } => "ItemFindingHasExclusionReason",
            Self::RelationPremiseMustPrecedeAnswerValue => "RelationPremiseMustPrecedeAnswerValue",
            Self::RelationFindingUsedByBothRoles { .. } => "RelationFindingUsedByBothRoles",
            Self::RelationFindingDispositionMismatch { .. } => "RelationFindingDispositionMismatch",
            Self::RelationAnswerItemMissingOperatorFinding { .. } => {
                "RelationAnswerItemMissingOperatorFinding"
            }
            Self::RelationValueHasUnresolvedCompetitors => "RelationValueHasUnresolvedCompetitors",
            Self::MissingReasoningOperator => "MissingReasoningOperator",
            Self::UnexpectedReasoningOperatorKind { .. } => "UnexpectedReasoningOperatorKind",
            Self::UnknownOperatorFindingReference { .. } => "UnknownOperatorFindingReference",
            Self::ExcludedFindingReferencedByOperatorInput { .. } => {
                "ExcludedFindingReferencedByOperatorInput"
            }
            Self::NonItemFindingReferencedByOperatorItemInput { .. } => {
                "NonItemFindingReferencedByOperatorItemInput"
            }
            Self::ExcludedFindingReferencedByComparedCandidate { .. } => {
                "ExcludedFindingReferencedByComparedCandidate"
            }
            Self::MissingOperatorInputRole { .. } => "MissingOperatorInputRole",
            Self::OperatorOmittedFinding { .. } => "OperatorOmittedFinding",
            Self::InsufficientFrequencyOccurrences { .. } => "InsufficientFrequencyOccurrences",
            Self::MissingComparedCandidates => "MissingComparedCandidates",
            Self::MissingComparedAlternative { .. } => "MissingComparedAlternative",
            Self::HypothesisOutputDoesNotMatchComparedCandidate => {
                "HypothesisOutputDoesNotMatchComparedCandidate"
            }
            Self::MissingOperatorOutput => "MissingOperatorOutput",
            Self::OperatorOutputDoesNotMatchCandidate => "OperatorOutputDoesNotMatchCandidate",
            Self::OperatorOutputPresentForUnresolved => "OperatorOutputPresentForUnresolved",
        }
    }
}

impl std::fmt::Display for GroundedDraftValidationFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::MissingCandidate => formatter.write_str(self.code()),
            Self::MissingGroundingCitation => formatter.write_str(self.code()),
            Self::CandidatePresentForUnresolved => formatter.write_str(self.code()),
            Self::AnswerItemsPresentForUnresolved => formatter.write_str(self.code()),
            Self::EmptyItemSetPresentForUnresolved => formatter.write_str(self.code()),
            Self::MissingAnswerItemsForPopulatedSet => formatter.write_str(self.code()),
            Self::StructuredScalarAnswerItemCount { actual_count } => {
                write!(formatter, "{}(items {actual_count})", self.code())
            }
            Self::ScalarCandidateDoesNotMatchAnswerItem => formatter.write_str(self.code()),
            Self::BinaryCandidateMissingExplicitPolarity => formatter.write_str(self.code()),
            Self::BinaryCandidateMissingConcreteSupport => formatter.write_str(self.code()),
            Self::InvalidTemporalPointReference
            | Self::InvalidTemporalPointElapsedDuration
            | Self::TemporalPointCandidateDoesNotMatchComputed => formatter.write_str(self.code()),
            Self::MissingEventBoundaryEvidence
            | Self::InvalidEventBoundaryEvidence
            | Self::MissingEventBoundaryAnchorPremise
            | Self::EventBoundaryAnchorPremiseNotConsumed => formatter.write_str(self.code()),
            Self::EventBoundaryDirectionMismatch { expected, actual } => write!(
                formatter,
                "{}(expected {expected:?}, actual {actual:?})",
                self.code()
            ),
            Self::EventBoundaryPremiseCitationOutsideAnchor {
                finding_index,
                source_node_id,
            }
            | Self::EventBoundaryItemCitationOutsideTarget {
                finding_index,
                source_node_id,
            } => write!(
                formatter,
                "{}(finding {finding_index}, source #{})",
                self.code(),
                source_node_id.0
            ),
            Self::EventBoundaryAnswerItemCitationOutsideTarget {
                item_index,
                source_node_id,
            } => write!(
                formatter,
                "{}(item {item_index}, source #{})",
                self.code(),
                source_node_id.0
            ),
            Self::CollectionCandidateMissingAnswerItem { item_index } => {
                write!(formatter, "{}(item {item_index})", self.code())
            }
            Self::DuplicateNormalizedAnswerItem {
                first_item_index,
                duplicate_item_index,
            } => write!(
                formatter,
                "{}(first item {first_item_index}, duplicate item {duplicate_item_index})",
                self.code()
            ),
            Self::AnswerItemsPresentForEmptyItemSet => formatter.write_str(self.code()),
            Self::EmptyItemSetUnsupportedForAnswerShape => formatter.write_str(self.code()),
            Self::InvalidCountCandidate => formatter.write_str(self.code()),
            Self::CountCandidateDoesNotMatchAnswerItems {
                candidate_count,
                answer_item_count,
            } => write!(
                formatter,
                "{}(candidate {candidate_count}, items {answer_item_count})",
                self.code()
            ),
            Self::LedgerItemFindingCount {
                item_index,
                actual_count,
            } => write!(
                formatter,
                "{}(item {item_index}, item findings {actual_count})",
                self.code()
            ),
            Self::MissingCountOccurrenceKey { finding_index }
            | Self::MissingCountOccurrenceActuality { finding_index }
            | Self::CountItemHasDuplicateReference { finding_index }
            | Self::DuplicateOccurrenceFindingNotExcluded { finding_index }
            | Self::InvalidDuplicateOccurrenceTarget { finding_index }
            | Self::InvalidDuplicateOccurrenceMetadata { finding_index } => {
                write!(formatter, "{}(finding {finding_index})", self.code())
            }
            Self::CountOccurrenceNotOccurred {
                finding_index,
                actuality,
            } => write!(
                formatter,
                "{}(finding {finding_index}, actuality {actuality:?})",
                self.code()
            ),
            Self::DuplicateCountOccurrenceKey {
                first_finding_index,
                duplicate_finding_index,
            } => write!(
                formatter,
                "{}(first finding {first_finding_index}, duplicate finding {duplicate_finding_index})",
                self.code()
            ),
            Self::UnknownDraftCitation { source_node_id } => {
                write!(formatter, "{}(source #{})", self.code(), source_node_id.0)
            }
            Self::EmptyAnswerItemValue { item_index }
            | Self::MissingAnswerItemCitation { item_index } => {
                write!(formatter, "{}(item {item_index})", self.code())
            }
            Self::AnswerItemCitationMissingFromDraft {
                item_index,
                source_node_id,
            } => write!(
                formatter,
                "{}(item {item_index}, source #{})",
                self.code(),
                source_node_id.0
            ),
            Self::UnknownAnswerItemCitation {
                item_index,
                source_node_id,
            } => write!(
                formatter,
                "{}(item {item_index}, source #{})",
                self.code(),
                source_node_id.0
            ),
            Self::EmptyFindingId { finding_index }
            | Self::EmptyFindingFact { finding_index }
            | Self::MissingFindingCitation { finding_index }
            | Self::MissingItemFindingAnswerValue { finding_index }
            | Self::ItemFindingNotConsumed { finding_index }
            | Self::MissingFindingExclusionReason { finding_index }
            | Self::ItemFindingHasExclusionReason { finding_index }
            | Self::RelationFindingUsedByBothRoles { finding_index } => {
                write!(formatter, "{}(finding {finding_index})", self.code())
            }
            Self::DuplicateFindingId {
                first_finding_index,
                duplicate_finding_index,
            } => write!(
                formatter,
                "{}(first finding {first_finding_index}, duplicate finding {duplicate_finding_index})",
                self.code()
            ),
            Self::FindingCitationMissingFromDraft {
                finding_index,
                source_node_id,
            }
            | Self::UnknownFindingCitation {
                finding_index,
                source_node_id,
            } => write!(
                formatter,
                "{}(finding {finding_index}, source #{})",
                self.code(),
                source_node_id.0
            ),
            Self::ItemFindingConsumedMultipleTimes {
                finding_index,
                consumption_count,
            } => write!(
                formatter,
                "{}(finding {finding_index}, items {consumption_count})",
                self.code()
            ),
            Self::ItemFindingValueMismatch {
                finding_index,
                item_index,
            }
            | Self::ExcludedFindingReferencedByAnswerItem {
                item_index,
                finding_index,
            }
            | Self::NonItemFindingReferencedByLedgerItem {
                item_index,
                finding_index,
            } => write!(
                formatter,
                "{}(finding {finding_index}, item {item_index})",
                self.code()
            ),
            Self::MissingAnswerItemFindingReference { item_index } => {
                write!(formatter, "{}(item {item_index})", self.code())
            }
            Self::UnknownAnswerItemFindingReference {
                item_index,
                finding_id,
            } => write!(
                formatter,
                "{}(item {item_index}, finding {finding_id:?})",
                self.code()
            ),
            Self::AnswerItemMissingFindingCitation {
                item_index,
                finding_index,
                source_node_id,
            } => write!(
                formatter,
                "{}(item {item_index}, finding {finding_index}, source #{})",
                self.code(),
                source_node_id.0
            ),
            Self::RelationFindingDispositionMismatch {
                finding_index,
                role,
            }
            | Self::RelationAnswerItemMissingOperatorFinding {
                finding_index,
                role,
            } => write!(
                formatter,
                "{}(finding {finding_index}, role {role:?})",
                self.code()
            ),
            Self::RelationPremiseMustPrecedeAnswerValue
            | Self::RelationValueHasUnresolvedCompetitors
            | Self::MissingReasoningOperator
            | Self::MissingComparedCandidates
            | Self::HypothesisOutputDoesNotMatchComparedCandidate
            | Self::MissingOperatorOutput
            | Self::OperatorOutputDoesNotMatchCandidate
            | Self::OperatorOutputPresentForUnresolved => formatter.write_str(self.code()),
            Self::UnexpectedReasoningOperatorKind { expected, actual } => write!(
                formatter,
                "{}(expected {expected:?}, actual {actual:?})",
                self.code()
            ),
            Self::UnknownOperatorFindingReference { finding_id } => {
                write!(formatter, "{}(finding {finding_id:?})", self.code())
            }
            Self::ExcludedFindingReferencedByOperatorInput { finding_index }
            | Self::NonItemFindingReferencedByOperatorItemInput { finding_index }
            | Self::ExcludedFindingReferencedByComparedCandidate { finding_index } => {
                write!(formatter, "{}(finding {finding_index})", self.code())
            }
            Self::MissingOperatorInputRole { role } => {
                write!(formatter, "{}(role {role:?})", self.code())
            }
            Self::OperatorOmittedFinding {
                finding_index,
                role,
            } => write!(
                formatter,
                "{}(finding {finding_index}, role {role:?})",
                self.code()
            ),
            Self::InsufficientFrequencyOccurrences { actual_count } => {
                write!(formatter, "{}(occurrences {actual_count})", self.code())
            }
            Self::MissingComparedAlternative { value } => {
                write!(formatter, "{}(alternative {value:?})", self.code())
            }
        }
    }
}

/// Complete set of typed failures found in one validation pass.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct GroundedDraftValidationError {
    /// Failures in deterministic validation order.
    pub failures: Vec<GroundedDraftValidationFailure>,
}

impl std::fmt::Display for GroundedDraftValidationError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let rendered = self
            .failures
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(", ");
        write!(formatter, "grounded draft validation failed: {rendered}")
    }
}

impl std::error::Error for GroundedDraftValidationError {}

fn collection_answer_misses_item(answer: &str, items: &[String]) -> bool {
    let answer_tokens = collection_token_counts(answer);
    items.iter().any(|item| {
        let item_tokens = collection_token_counts(item);
        !item_tokens.is_empty()
            && item_tokens.iter().any(|(token, count)| {
                answer_tokens.get(token).copied().unwrap_or_default() < *count
            })
    })
}

fn normalize_collection_item(value: &str) -> String {
    value
        .split(|character: char| !character.is_alphanumeric())
        .filter(|part| !part.is_empty())
        .map(str::to_lowercase)
        .collect::<Vec<_>>()
        .join(" ")
}

fn collection_token_counts(value: &str) -> HashMap<String, usize> {
    let mut counts = HashMap::new();
    for token in value
        .split(|character: char| !character.is_alphanumeric())
        .filter(|token| token.len() > 1)
        .map(str::to_lowercase)
        .filter(|token| {
            !matches!(
                token.as_str(),
                "a" | "an"
                    | "and"
                    | "at"
                    | "by"
                    | "for"
                    | "from"
                    | "in"
                    | "of"
                    | "on"
                    | "the"
                    | "to"
                    | "with"
            )
        })
        .map(|token| {
            if token.len() > 5 && token.ends_with("ies") {
                format!("{}y", &token[..token.len() - 3])
            } else if token.len() > 4 && token.ends_with('s') && !token.ends_with("ss") {
                token[..token.len() - 1].to_owned()
            } else {
                token
            }
        })
    {
        *counts.entry(token).or_insert(0) += 1;
    }
    counts
}

fn query_presents_explicit_alternatives(query: &str) -> bool {
    let normalized = format!(" {} ", query.trim().to_ascii_lowercase());
    if !normalized.contains(" or ") {
        return false;
    }
    let alternative_tail_starts_with_negation =
        normalized.rsplit_once(" or ").is_some_and(|(_, tail)| {
            let mut words = tail
                .split(|character: char| !character.is_alphabetic())
                .filter(|word| !word.is_empty());
            let first = words.next();
            matches!(first, Some("not")) || (matches!(first, Some("no")) && words.next().is_none())
        });
    if alternative_tail_starts_with_negation {
        return false;
    }
    if [
        " either ",
        " whether ",
        " choose ",
        " selects ",
        " select ",
        " prefers ",
        " prefer ",
        " more likely ",
    ]
    .iter()
    .any(|marker| normalized.contains(marker))
    {
        return true;
    }

    query_starts_with_binary_auxiliary(query)
        && conservatively_split_binary_complements(query).is_some()
}

fn conservatively_split_binary_complements(query: &str) -> Option<(String, String)> {
    if !query_starts_with_binary_auxiliary(query) {
        return None;
    }
    let lowercase = query.to_ascii_lowercase();
    let separator = lowercase.find(" or ")?;
    let raw_left = &query[..separator];
    let mut raw_right = &query[separator.saturating_add(4)..];
    for terminator in ['?', '.', ';', ','] {
        if let Some(index) = raw_right.find(terminator) {
            raw_right = &raw_right[..index];
        }
    }
    let clean = |value: &str| {
        value
            .trim()
            .trim_matches(|character: char| {
                matches!(character, '?' | '.' | ',' | ';' | ':' | '"' | '\'')
            })
            .trim()
            .to_owned()
    };
    let right = clean(raw_right);
    let right_words = right.split_whitespace().count();
    if !(1..=8).contains(&right_words) {
        return None;
    }

    let left_words = raw_left.split_whitespace().collect::<Vec<_>>();
    if left_words.len() < 2 {
        return None;
    }
    let available = left_words.len().saturating_sub(1);
    if available < right_words {
        return None;
    }
    let mut start = left_words.len().saturating_sub(right_words);
    if start > 1
        && matches!(
            left_words[start.saturating_sub(1)]
                .trim_matches(|character: char| !character.is_alphabetic())
                .to_ascii_lowercase()
                .as_str(),
            "a" | "an" | "the"
        )
    {
        start = start.saturating_sub(1);
    }
    let mut left = clean(&left_words[start..].join(" "));
    let left_lowercase = left.to_ascii_lowercase();
    for preposition in ["at ", "by ", "from ", "in ", "near ", "on ", "to "] {
        if left_lowercase.starts_with(preposition) {
            left = left[preposition.len()..].trim().to_owned();
            break;
        }
    }

    let acceptable = |value: &str| {
        let count = value.split_whitespace().count();
        (1..=8).contains(&count) && !normalize_collection_item(value).is_empty()
    };
    if !acceptable(&left)
        || !acceptable(&right)
        || normalize_collection_item(&left) == normalize_collection_item(&right)
    {
        return None;
    }
    Some((left, right))
}

fn conservatively_named_alternatives(query: &str) -> Option<Vec<String>> {
    if !query_presents_explicit_alternatives(query) {
        return None;
    }
    let lowercase = query.to_ascii_lowercase();
    let separator = lowercase.find(" or ")?;
    let raw_left = &query[..separator];
    let mut raw_right = &query[separator.saturating_add(4)..];
    for terminator in ['?', '.', ';', ','] {
        if let Some(index) = raw_right.find(terminator) {
            raw_right = &raw_right[..index];
        }
    }

    let lowercase_left = raw_left.to_ascii_lowercase();
    let marked_left = [
        " more likely to ",
        " more likely ",
        " whether ",
        " either ",
        " choose ",
        " select ",
        " selects ",
        " prefer ",
        " prefers ",
        " enjoy ",
        " interested in ",
    ]
    .iter()
    .filter_map(|marker| {
        lowercase_left
            .rfind(marker)
            .map(|index| (index.saturating_add(marker.len()), *marker))
    })
    .max_by_key(|(index, _)| *index);
    let raw_left = if let Some((index, _)) = marked_left {
        raw_left[index..].to_owned()
    } else if let Some((left, _)) = conservatively_split_binary_complements(query) {
        left
    } else {
        let words = raw_left.split_whitespace().collect::<Vec<_>>();
        if words.len() > 4 {
            return None;
        }
        let lowered_words = words
            .iter()
            .map(|word| {
                word.trim_matches(|character: char| !character.is_alphanumeric())
                    .to_ascii_lowercase()
            })
            .collect::<Vec<_>>();
        let prefix_len = match lowered_words.as_slice() {
            [auxiliary, pronoun, ..]
                if matches!(
                    auxiliary.as_str(),
                    "is" | "are" | "was" | "were" | "would" | "could" | "should"
                ) && matches!(pronoun.as_str(), "it" | "this" | "that") =>
            {
                2
            }
            _ => 0,
        };
        words.get(prefix_len..)?.join(" ")
    };

    let clean = |value: &str| {
        let trimmed = value
            .trim()
            .trim_matches(|character: char| {
                matches!(character, '?' | '.' | ',' | ';' | ':' | '"' | '\'')
            })
            .trim();
        trimmed
            .strip_prefix("either ")
            .unwrap_or(trimmed)
            .trim()
            .to_owned()
    };
    let left = clean(&raw_left);
    let right = clean(raw_right);
    let acceptable = |value: &str| {
        let count = value.split_whitespace().count();
        (1..=8).contains(&count) && !normalize_collection_item(value).is_empty()
    };
    if !acceptable(&left)
        || !acceptable(&right)
        || normalize_collection_item(&left) == normalize_collection_item(&right)
    {
        return None;
    }
    Some(vec![left, right])
}

fn alternative_matches(expected: &str, actual: &str) -> bool {
    let expected = normalized_phrase(expected);
    let actual = normalized_phrase(actual);
    !expected.is_empty()
        && !actual.is_empty()
        && (expected == actual
            || normalized_contains_phrase(&actual, &expected)
            || normalized_contains_phrase(&expected, &actual))
}

fn binary_answer_has_explicit_polarity(value: &str) -> bool {
    normalized_phrase(value)
        .split_whitespace()
        .take(3)
        .any(|token| matches!(token, "yes" | "no"))
}

fn binary_answer_has_concrete_support(value: &str) -> bool {
    let normalized = normalized_phrase(value);
    let words = normalized.split_whitespace().collect::<Vec<_>>();
    let Some(polarity_index) = words
        .iter()
        .take(3)
        .position(|word| matches!(*word, "yes" | "no"))
    else {
        return false;
    };
    words[polarity_index.saturating_add(1)..]
        .iter()
        .any(|word| {
            !matches!(
                *word,
                "a" | "absolutely"
                    | "an"
                    | "and"
                    | "are"
                    | "as"
                    | "because"
                    | "can"
                    | "certainly"
                    | "could"
                    | "definitely"
                    | "did"
                    | "do"
                    | "does"
                    | "had"
                    | "has"
                    | "have"
                    | "he"
                    | "i"
                    | "indeed"
                    | "is"
                    | "it"
                    | "likely"
                    | "no"
                    | "not"
                    | "probably"
                    | "she"
                    | "should"
                    | "that"
                    | "the"
                    | "they"
                    | "this"
                    | "was"
                    | "we"
                    | "were"
                    | "would"
                    | "yes"
                    | "you"
            )
        })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TemporalPointCalculationError {
    Reference,
    Duration,
    Unavailable,
}

fn deterministic_temporal_point(
    draft: &GroundedAnswerDraft,
    operator: &GroundedReasoningOperator,
    granularity: RequestedTemporalGranularity,
) -> Result<String, TemporalPointCalculationError> {
    // This is a conditional derivation over typed finding values. The
    // surrounding validator proves their citations are delivered, not that the
    // cited prose semantically entails those values.
    let has_direct_value = operator
        .inputs()
        .iter()
        .any(|input| input.role() == GroundedOperatorInputRole::AnswerValue);
    let has_reference_or_duration = operator.inputs().iter().any(|input| {
        matches!(
            input.role(),
            GroundedOperatorInputRole::ReferenceTime | GroundedOperatorInputRole::ElapsedDuration
        )
    });
    if has_direct_value {
        if has_reference_or_duration {
            return Err(TemporalPointCalculationError::Reference);
        }
        let direct = temporal_point_input_value(
            draft,
            operator,
            GroundedOperatorInputRole::AnswerValue,
            TemporalPointCalculationError::Reference,
        )?;
        return validate_direct_temporal_point(direct, granularity)
            .ok_or(TemporalPointCalculationError::Reference);
    }
    let reference = temporal_point_input_value(
        draft,
        operator,
        GroundedOperatorInputRole::ReferenceTime,
        TemporalPointCalculationError::Reference,
    )?;
    let duration = temporal_point_input_value(
        draft,
        operator,
        GroundedOperatorInputRole::ElapsedDuration,
        TemporalPointCalculationError::Duration,
    )?;
    let reference_day =
        parse_exact_iso_calendar_day(reference).ok_or(TemporalPointCalculationError::Reference)?;
    let elapsed = parse_exact_temporal_point_elapsed(duration)
        .ok_or(TemporalPointCalculationError::Duration)?;
    let result_day = subtract_temporal_point_elapsed(reference_day, elapsed)
        .ok_or(TemporalPointCalculationError::Reference)?;
    format_iso_calendar_day(result_day).ok_or(TemporalPointCalculationError::Reference)
}

fn requested_temporal_granularity(spec: &RequestedAnswerSpec) -> RequestedTemporalGranularity {
    spec.temporal_granularity()
        .unwrap_or(RequestedTemporalGranularity::ExactDay)
}

fn validate_direct_temporal_point(
    value: &str,
    granularity: RequestedTemporalGranularity,
) -> Option<String> {
    let value = value.trim();
    if let Some(day) = parse_exact_iso_calendar_day(value) {
        return format_iso_calendar_day(day);
    }
    if granularity == RequestedTemporalGranularity::EvidenceCompatible
        && is_supported_grounded_calendar_expression(value)
    {
        return Some(value.to_owned());
    }
    None
}

fn is_supported_grounded_calendar_expression(value: &str) -> bool {
    if value.is_empty() || value.len() > 128 {
        return false;
    }
    if parse_unambiguous_calendar_day(value).is_some() {
        return true;
    }

    let normalized = normalized_phrase(value);
    let words = normalized.split_whitespace().collect::<Vec<_>>();
    if is_supported_named_month_period(&words) || is_supported_named_week_period(&words) {
        return true;
    }

    let Some((start, end)) = split_grounded_calendar_range(value) else {
        return false;
    };
    let Some(start) = parse_unambiguous_calendar_day(start) else {
        return false;
    };
    let Some(end) = parse_unambiguous_calendar_day(end) else {
        return false;
    };
    start <= end
}

fn split_grounded_calendar_range(value: &str) -> Option<(&str, &str)> {
    let normalized_case = value.to_ascii_lowercase();
    for separator in [" through ", " until ", " to ", " – ", " — ", " - "] {
        let Some(separator_index) = normalized_case.find(separator) else {
            continue;
        };
        let suffix_offset = separator_index.checked_add(separator.len())?;
        if normalized_case[suffix_offset..].contains(separator) {
            return None;
        }
        let start = value.get(..separator_index)?.trim();
        let end = value.get(suffix_offset..)?.trim();
        return (!start.is_empty() && !end.is_empty()).then_some((start, end));
    }
    None
}

fn is_supported_named_month_period(words: &[&str]) -> bool {
    match words {
        [month, year] => {
            calendar_month_number(month).is_some() && parse_calendar_year(year).is_some()
        }
        [qualifier, month, year] => {
            matches!(*qualifier, "early" | "mid" | "late")
                && calendar_month_number(month).is_some()
                && parse_calendar_year(year).is_some()
        }
        _ => false,
    }
}

fn is_supported_named_week_period(words: &[&str]) -> bool {
    matches!(
        words,
        ["first" | "second" | "third" | "fourth" | "last", "week", "of", month, year]
            if calendar_month_number(month).is_some() && parse_calendar_year(year).is_some()
    )
}

fn parse_unambiguous_calendar_day(value: &str) -> Option<i64> {
    if let Some(day) = parse_exact_iso_calendar_day(value) {
        return Some(day);
    }
    let normalized = normalized_phrase(value);
    let words = normalized.split_whitespace().collect::<Vec<_>>();
    parse_calendar_day_words(&words)
}

fn parse_calendar_day_words(words: &[&str]) -> Option<i64> {
    let [first, second, third] = words else {
        return None;
    };
    let (year, month, day) = if let (Some(day), Some(month), Some(year)) = (
        parse_calendar_day_number(first),
        calendar_month_number(second),
        parse_calendar_year(third),
    ) {
        (year, month, day)
    } else if let (Some(month), Some(day), Some(year)) = (
        calendar_month_number(first),
        parse_calendar_day_number(second),
        parse_calendar_year(third),
    ) {
        (year, month, day)
    } else {
        return None;
    };
    if !(1..=12).contains(&month) || !(1..=31).contains(&day) {
        return None;
    }
    let day_index = temporal_point_days_from_civil(year, month, day);
    (temporal_point_civil_from_days(day_index) == (year, month, day)).then_some(day_index)
}

fn parse_calendar_year(value: &str) -> Option<i64> {
    let year = value.parse::<i64>().ok()?;
    (1970..=2200).contains(&year).then_some(year)
}

fn parse_calendar_day_number(value: &str) -> Option<u32> {
    let digits = value
        .strip_suffix("st")
        .or_else(|| value.strip_suffix("nd"))
        .or_else(|| value.strip_suffix("rd"))
        .or_else(|| value.strip_suffix("th"))
        .unwrap_or(value);
    digits
        .parse::<u32>()
        .ok()
        .filter(|day| (1..=31).contains(day))
}

fn calendar_month_number(value: &str) -> Option<u32> {
    match value {
        "january" | "jan" => Some(1),
        "february" | "feb" => Some(2),
        "march" | "mar" => Some(3),
        "april" | "apr" => Some(4),
        "may" => Some(5),
        "june" | "jun" => Some(6),
        "july" | "jul" => Some(7),
        "august" | "aug" => Some(8),
        "september" | "sep" | "sept" => Some(9),
        "october" | "oct" => Some(10),
        "november" | "nov" => Some(11),
        "december" | "dec" => Some(12),
        _ => None,
    }
}

fn temporal_point_input_value<'a>(
    draft: &'a GroundedAnswerDraft,
    operator: &GroundedReasoningOperator,
    role: GroundedOperatorInputRole,
    invalid: TemporalPointCalculationError,
) -> Result<&'a str, TemporalPointCalculationError> {
    let mut finding_ids = operator
        .inputs()
        .iter()
        .filter(|input| input.role() == role)
        .flat_map(GroundedOperatorInput::finding_ids)
        .map(|finding_id| finding_id.trim())
        .filter(|finding_id| !finding_id.is_empty())
        .collect::<Vec<_>>();
    finding_ids.sort_unstable();
    finding_ids.dedup();
    let [finding_id] = finding_ids.as_slice() else {
        return Err(invalid);
    };
    let mut matching_findings = draft
        .findings()
        .iter()
        .filter(|finding| finding.id().trim() == *finding_id);
    let Some(finding) = matching_findings.next() else {
        return Err(TemporalPointCalculationError::Unavailable);
    };
    if matching_findings.next().is_some()
        || finding.disposition() == GroundedFindingDisposition::Excluded
    {
        return Err(TemporalPointCalculationError::Unavailable);
    }
    finding
        .answer_value()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or(invalid)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ExactTemporalPointElapsed {
    FixedDays(i64),
    CalendarMonths(i64),
}

fn parse_exact_temporal_point_elapsed(value: &str) -> Option<ExactTemporalPointElapsed> {
    let normalized = normalized_phrase(value);
    let words = normalized.split_whitespace().collect::<Vec<_>>();
    let [amount, unit] = words.as_slice() else {
        return None;
    };
    let amount = match *amount {
        "a" | "an" | "one" => 1,
        "two" => 2,
        "three" => 3,
        "four" => 4,
        "five" => 5,
        "six" => 6,
        "seven" => 7,
        "eight" => 8,
        "nine" => 9,
        "ten" => 10,
        "eleven" => 11,
        "twelve" => 12,
        digits => digits.parse::<i64>().ok()?,
    };
    if amount <= 0 {
        return None;
    }
    match *unit {
        "day" | "days" => Some(ExactTemporalPointElapsed::FixedDays(amount)),
        "week" | "weeks" => amount
            .checked_mul(7)
            .map(ExactTemporalPointElapsed::FixedDays),
        "month" | "months" => Some(ExactTemporalPointElapsed::CalendarMonths(amount)),
        _ => None,
    }
}

fn subtract_temporal_point_elapsed(
    reference_day: i64,
    elapsed: ExactTemporalPointElapsed,
) -> Option<i64> {
    match elapsed {
        ExactTemporalPointElapsed::FixedDays(days) => reference_day.checked_sub(days),
        ExactTemporalPointElapsed::CalendarMonths(months) => {
            let (year, month, day) = temporal_point_civil_from_days(reference_day);
            let reference_month = year
                .checked_mul(12)?
                .checked_add(i64::from(month).checked_sub(1)?)?;
            let target_month = reference_month.checked_sub(months)?;
            let target_year = target_month.div_euclid(12);
            let target_month = u32::try_from(target_month.rem_euclid(12) + 1).ok()?;
            let target_day = day.min(temporal_point_days_in_month(target_year, target_month)?);
            Some(temporal_point_days_from_civil(
                target_year,
                target_month,
                target_day,
            ))
        }
    }
}

fn temporal_point_days_in_month(year: i64, month: u32) -> Option<u32> {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => Some(31),
        4 | 6 | 9 | 11 => Some(30),
        2 if year.rem_euclid(4) == 0
            && (year.rem_euclid(100) != 0 || year.rem_euclid(400) == 0) =>
        {
            Some(29)
        }
        2 => Some(28),
        _ => None,
    }
}

fn parse_exact_iso_calendar_day(value: &str) -> Option<i64> {
    let value = value.trim();
    let bytes = value.as_bytes();
    if bytes.len() != 10
        || bytes.get(4) != Some(&b'-')
        || bytes.get(7) != Some(&b'-')
        || bytes
            .iter()
            .enumerate()
            .any(|(index, byte)| !matches!(index, 4 | 7) && !byte.is_ascii_digit())
    {
        return None;
    }
    let year = value.get(..4)?.parse::<i64>().ok()?;
    let month = value.get(5..7)?.parse::<u32>().ok()?;
    let day = value.get(8..)?.parse::<u32>().ok()?;
    if !(1970..=2200).contains(&year) || !(1..=12).contains(&month) || !(1..=31).contains(&day) {
        return None;
    }
    let day_index = temporal_point_days_from_civil(year, month, day);
    (temporal_point_civil_from_days(day_index) == (year, month, day)).then_some(day_index)
}

fn format_iso_calendar_day(day_index: i64) -> Option<String> {
    let (year, month, day) = temporal_point_civil_from_days(day_index);
    (1970..=2200)
        .contains(&year)
        .then(|| format!("{year:04}-{month:02}-{day:02}"))
}

fn temporal_point_days_from_civil(year: i64, month: u32, day: u32) -> i64 {
    let year = if month <= 2 { year - 1 } else { year };
    let era = year.div_euclid(400);
    let year_of_era = year - era * 400;
    let adjusted_month = ((month + 9) % 12) as i64;
    let day_of_year = (153 * adjusted_month + 2) / 5 + day as i64 - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era - 719_468
}

fn temporal_point_civil_from_days(day_index: i64) -> (i64, u32, u32) {
    let adjusted_day = day_index + 719_468;
    let era = adjusted_day.div_euclid(146_097);
    let day_of_era = adjusted_day - era * 146_097;
    let year_of_era =
        (day_of_era - day_of_era / 1460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let mut year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let adjusted_month = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * adjusted_month + 2) / 5 + 1;
    let month = if adjusted_month < 10 {
        adjusted_month + 3
    } else {
        adjusted_month - 9
    };
    if month <= 2 {
        year += 1;
    }
    (year, month as u32, day as u32)
}

fn query_starts_with_binary_auxiliary(query: &str) -> bool {
    let first = query
        .trim_start()
        .split(|character: char| !character.is_alphabetic())
        .next()
        .unwrap_or_default()
        .to_ascii_lowercase();
    matches!(
        first.as_str(),
        "am" | "are"
            | "can"
            | "could"
            | "did"
            | "do"
            | "does"
            | "had"
            | "has"
            | "have"
            | "is"
            | "may"
            | "might"
            | "should"
            | "was"
            | "were"
            | "will"
            | "would"
    )
}

fn query_requests_composite_synthesis(query: &str) -> bool {
    if query_presents_explicit_alternatives(query) {
        return false;
    }

    let words = query_words(query);
    let Some(interrogative_index) = words
        .iter()
        .position(|word| matches!(word.as_str(), "what" | "which"))
    else {
        return false;
    };
    let is_auxiliary = |word: &str| {
        matches!(
            word,
            "am" | "are"
                | "can"
                | "could"
                | "did"
                | "do"
                | "does"
                | "had"
                | "has"
                | "have"
                | "is"
                | "may"
                | "might"
                | "should"
                | "was"
                | "were"
                | "will"
                | "would"
        )
    };
    let answer_phrase_end = words
        .iter()
        .enumerate()
        .skip(interrogative_index.saturating_add(1))
        .find_map(|(index, word)| is_auxiliary(word).then_some(index))
        .unwrap_or(words.len());
    let answer_phrase = &words[interrogative_index.saturating_add(1)..answer_phrase_end];

    let requests_advice = words[interrogative_index] == "what"
        && answer_phrase.iter().any(|word| word.as_str() == "advice");
    let explicitly_singular_advice = answer_phrase.windows(3).any(|window| {
        matches!(window[0].as_str(), "a" | "one" | "single")
            && window[1] == "piece"
            && window[2] == "of"
    }) || answer_phrase.windows(2).any(|window| {
        matches!(
            window[0].as_str(),
            "best" | "key" | "main" | "primary" | "specific"
        ) && window[1] == "advice"
    });
    if requests_advice && explicitly_singular_advice {
        return false;
    }

    let asks_open_synthesis_verb = answer_phrase.is_empty()
        && words
            .get(interrogative_index.saturating_add(1))
            .is_some_and(|word| is_auxiliary(word))
        && words.iter().any(|word| {
            matches!(
                word.as_str(),
                "advise"
                    | "advised"
                    | "advises"
                    | "learn"
                    | "learned"
                    | "learns"
                    | "recommend"
                    | "recommended"
                    | "recommends"
            )
        });
    if !requests_advice && !asks_open_synthesis_verb {
        return false;
    }

    let is_synthesis_action = |word: &str| {
        matches!(
            word,
            "advise"
                | "advised"
                | "advises"
                | "gave"
                | "give"
                | "given"
                | "gives"
                | "learn"
                | "learned"
                | "learns"
                | "offer"
                | "offered"
                | "offers"
                | "provide"
                | "provided"
                | "provides"
                | "recommend"
                | "recommended"
                | "recommends"
                | "share"
                | "shared"
                | "shares"
        )
    };
    let is_source_term = |word: &str| {
        !matches!(
            word,
            "a" | "an" | "her" | "his" | "my" | "our" | "the" | "their" | "your"
        ) && !word.ends_with("ly")
    };
    let has_coordinated_sources = |source_phrase: &[String]| {
        source_phrase
            .iter()
            .enumerate()
            .filter(|(_, word)| word.as_str() == "and")
            .any(|(and_index, _)| {
                source_phrase[..and_index]
                    .iter()
                    .rev()
                    .any(|word| is_source_term(word))
                    && source_phrase[and_index.saturating_add(1)..]
                        .iter()
                        .any(|word| is_source_term(word))
            })
    };

    words
        .iter()
        .enumerate()
        .skip(answer_phrase_end)
        .filter(|(_, word)| is_synthesis_action(word))
        .any(|(action_index, _)| {
            words[..action_index]
                .iter()
                .rposition(|word| is_auxiliary(word))
                .is_some_and(|auxiliary_index| {
                    has_coordinated_sources(&words[auxiliary_index.saturating_add(1)..action_index])
                })
        })
}

fn infer_requested_answer_spec(plan: &RecallPlan) -> RequestedAnswerSpec {
    let role = if query_requests_elapsed_duration(&plan.query) {
        RequestedAnswerRole::ElapsedSpan
    } else if plan.answer_shape == AnswerShape::Temporal
        && query_requests_temporal_point(&plan.query)
    {
        RequestedAnswerRole::TemporalPoint
    } else if plan.answer_shape != AnswerShape::Count
        && query_presents_explicit_alternatives(&plan.query)
    {
        RequestedAnswerRole::HypothesisChoice
    } else if query_requests_predicate_descriptor(&plan.query) {
        RequestedAnswerRole::PredicateDescriptor
    } else if query_requests_method(&plan.query) {
        RequestedAnswerRole::Method
    } else if plan.answer_shape == AnswerShape::Fact && plan_uses_temporal_readout(plan) {
        RequestedAnswerRole::EventAttribute
    } else {
        RequestedAnswerRole::Value
    };
    let modality = infer_requested_answer_modality(&plan.query);
    let requests_composite_synthesis = query_requests_composite_synthesis(&plan.query);
    let cardinality = match (role, plan.answer_shape, plan.coverage) {
        (RequestedAnswerRole::Method, _, _) => RequestedAnswerCardinality::Multiple,
        (_, _, RecallCoverage::Exhaustive) => RequestedAnswerCardinality::Exhaustive,
        (_, AnswerShape::Collection, _) | (_, _, RecallCoverage::Multiple) => {
            RequestedAnswerCardinality::Multiple
        }
        _ if requests_composite_synthesis => RequestedAnswerCardinality::Multiple,
        _ => RequestedAnswerCardinality::One,
    };
    let mut spec = RequestedAnswerSpec::new(role, modality, cardinality);
    if let Some(value_target) = infer_requested_value_target(&plan.query) {
        spec = spec.with_value_target(value_target);
    }
    if role == RequestedAnswerRole::TemporalPoint {
        let temporal_granularity = if query_requests_exact_calendar_day(&plan.query) {
            RequestedTemporalGranularity::ExactDay
        } else {
            RequestedTemporalGranularity::EvidenceCompatible
        };
        spec = spec.with_temporal_granularity(temporal_granularity);
    }
    spec
}

fn query_explicitly_requests_stable_public_relation(
    query: &str,
    spec: &RequestedAnswerSpec,
) -> bool {
    let Some(target) = spec.value_target() else {
        return false;
    };
    let words = query_words(query);
    let has_word = |needle: &str| words.iter().any(|word| word == needle);
    let target_words = query_words(target);
    let geographic_target = target_words.iter().any(|word| {
        matches!(
            word.as_str(),
            "city"
                | "cities"
                | "country"
                | "countries"
                | "nation"
                | "nations"
                | "province"
                | "provinces"
                | "state"
                | "states"
                | "territory"
                | "territories"
                | "town"
                | "towns"
        )
    });
    let geographic_relation = words.iter().any(|word| {
        matches!(
            word.as_str(),
            "contain" | "contained" | "contains" | "locate" | "located" | "lies" | "situated"
        )
    }) || words
        .windows(2)
        .any(|window| window[0] == "in" && window[1] == "which")
        || words.last().is_some_and(|word| word == "in");
    let authorship_target = target_words.iter().any(|word| {
        matches!(
            word.as_str(),
            "author"
                | "authors"
                | "composer"
                | "composers"
                | "songwriter"
                | "songwriters"
                | "writer"
                | "writers"
        )
    });
    let authorship_relation = words.iter().any(|word| {
        matches!(
            word.as_str(),
            "author" | "authored" | "compose" | "composed" | "composer" | "wrote" | "written"
        )
    });
    let maker_target = target_words.iter().any(|word| {
        matches!(
            word.as_str(),
            "manufacturer" | "manufacturers" | "producer" | "producers"
        )
    });
    let maker_relation = words
        .iter()
        .any(|word| matches!(word.as_str(), "made" | "manufactured" | "produced"));

    (geographic_target && geographic_relation)
        || (authorship_target && authorship_relation)
        || (maker_target && maker_relation)
        || (authorship_target && (has_word("tune") || has_word("tunes")))
}

fn query_words(query: &str) -> Vec<String> {
    query
        .trim()
        .to_lowercase()
        .split(|character: char| !character.is_alphanumeric() && character != '\'')
        .filter(|word| !word.is_empty())
        .map(str::to_owned)
        .collect()
}

fn query_requests_predicate_descriptor(query: &str) -> bool {
    let words = query_words(query);
    words.first().is_some_and(|word| word == "how")
        && words
            .get(1)
            .is_some_and(|word| matches!(word.as_str(), "does" | "did"))
        && words
            .iter()
            .any(|word| matches!(word.as_str(), "describe" | "describes" | "described"))
}

fn query_requests_method(query: &str) -> bool {
    let words = query_words(query);
    let starts_with_how = matches!(
        words.as_slice(),
        [first, auxiliary, ..]
            if first == "how" && matches!(auxiliary.as_str(), "did" | "does" | "has" | "have")
    );
    let asks_in_what_way = words.windows(3).any(|window| {
        window[0] == "in" && window[1] == "what" && matches!(window[2].as_str(), "way" | "ways")
    });
    let asks_named_method = words.windows(2).any(|window| {
        window[0] == "what" && matches!(window[1].as_str(), "method" | "methods" | "way" | "ways")
    }) && words
        .iter()
        .any(|word| matches!(word.as_str(), "use" | "used" | "uses" | "using"));
    let asks_for_steps = matches!(words.as_slice(), [first, second, ..] if first == "what" && matches!(second.as_str(), "step" | "steps"))
        && words
            .iter()
            .any(|word| matches!(word.as_str(), "take" | "taken" | "takes" | "took"));
    let asks_by_what_means = words
        .windows(3)
        .any(|window| window[0] == "by" && window[1] == "what" && window[2] == "means");
    if !(starts_with_how
        || asks_in_what_way
        || asks_named_method
        || asks_for_steps
        || asks_by_what_means)
    {
        return false;
    }
    let normalized = normalized_phrase(query);
    if query_requests_elapsed_duration(query)
        || normalized_contains_phrase(&normalized, "how often")
        || normalized_contains_phrase(&normalized, "over time")
        || words.windows(2).any(|window| window == ["been", "doing"])
        || words.iter().any(|word| {
            matches!(
                word.as_str(),
                "affect"
                    | "affected"
                    | "became"
                    | "become"
                    | "describe"
                    | "described"
                    | "experience"
                    | "experienced"
                    | "fail"
                    | "failed"
                    | "feel"
                    | "felt"
                    | "happen"
                    | "happened"
                    | "know"
                    | "knew"
                    | "occur"
                    | "occurred"
                    | "react"
                    | "reacted"
                    | "respond"
                    | "responded"
            )
        })
    {
        return false;
    }
    if words.last().is_some_and(|word| {
        matches!(
            word.as_str(),
            "change"
                | "changed"
                | "connect"
                | "connected"
                | "develop"
                | "developed"
                | "die"
                | "died"
                | "end"
                | "ended"
                | "evolve"
                | "evolved"
                | "go"
                | "happen"
                | "happened"
                | "launch"
                | "launched"
                | "perform"
                | "performed"
                | "progress"
                | "progressed"
                | "went"
        )
    }) || normalized_contains_phrase(&normalized, "each other")
    {
        return false;
    }
    if let Some(meet_index) = words
        .iter()
        .position(|word| matches!(word.as_str(), "meet" | "met"))
    {
        let performance_target = words[meet_index.saturating_add(1)..].iter().any(|word| {
            matches!(
                word.as_str(),
                "deadline"
                    | "deadlines"
                    | "demand"
                    | "demands"
                    | "goal"
                    | "goals"
                    | "need"
                    | "needs"
                    | "quota"
                    | "quotas"
                    | "requirement"
                    | "requirements"
                    | "standard"
                    | "standards"
                    | "target"
                    | "targets"
            )
        });
        if !performance_target {
            return false;
        }
    }
    let describes_change = words.iter().any(|word| {
        matches!(
            word.as_str(),
            "change" | "changed" | "evolve" | "evolved" | "progress" | "progressed"
        )
    }) && words
        .iter()
        .any(|word| matches!(word.as_str(), "state" | "status" | "trend"));
    !describes_change
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FactualActionProjection {
    Method,
    PerformedActionItem,
    ResultValue,
}

#[derive(Debug)]
struct FactualActionRequest {
    projection: FactualActionProjection,
    query_terms: HashSet<String>,
    target_terms: HashSet<String>,
    exact_subject: Option<String>,
    requested_value_kind: Option<String>,
    requested_lifecycle_head: Option<String>,
}

fn explicit_single_action_subject(words: &[String]) -> Option<String> {
    let contains_multiple_subjects = words
        .iter()
        .any(|word| matches!(word.as_str(), "and" | "or"));
    let contains_clause_or_voice_marker = words.iter().any(|word| {
        matches!(
            word.as_str(),
            "am" | "are"
                | "been"
                | "being"
                | "can"
                | "could"
                | "did"
                | "do"
                | "does"
                | "had"
                | "has"
                | "have"
                | "if"
                | "is"
                | "may"
                | "might"
                | "should"
                | "that"
                | "to"
                | "unless"
                | "was"
                | "were"
                | "who"
                | "will"
                | "would"
        )
    });
    let has_explicit_subject_term = words.iter().any(|word| {
        !matches!(
            word.as_str(),
            "a" | "an"
                | "he"
                | "her"
                | "hers"
                | "him"
                | "his"
                | "it"
                | "its"
                | "our"
                | "ours"
                | "she"
                | "the"
                | "their"
                | "theirs"
                | "them"
                | "they"
                | "we"
                | "you"
                | "your"
                | "yours"
        )
    });
    (!words.is_empty()
        && !contains_multiple_subjects
        && !contains_clause_or_voice_marker
        && has_explicit_subject_term)
        .then(|| words.join(" "))
}

fn normalized_exact_action_subject(value: &str) -> String {
    let normalized = normalized_phrase(value);
    normalized
        .strip_prefix("the ")
        .or_else(|| normalized.strip_prefix("an "))
        .or_else(|| normalized.strip_prefix("a "))
        .unwrap_or(&normalized)
        .to_owned()
}

fn exact_action_subject_matches(left: &str, right: &str) -> bool {
    let left = normalized_exact_action_subject(left);
    !left.is_empty() && left == normalized_exact_action_subject(right)
}

fn lifecycle_action_lemma(word: &str) -> Option<&'static str> {
    match word {
        "build" | "builds" | "building" | "built" => Some("build"),
        "create" | "created" | "creates" | "creating" => Some("create"),
        "develop" | "developed" | "developing" | "develops" => Some("develop"),
        "make" | "made" | "makes" | "making" => Some("make"),
        "produce" | "produced" | "produces" | "producing" => Some("produce"),
        _ => None,
    }
}

fn requested_value_kind(words: &[String]) -> Option<String> {
    let kind = words.iter().rev().find(|word| {
        !matches!(
            word.as_str(),
            "a" | "an"
                | "category"
                | "categories"
                | "kind"
                | "kinds"
                | "of"
                | "sort"
                | "sorts"
                | "the"
                | "type"
                | "types"
        )
    })?;
    let normalized = normalize_facet_term(kind);
    (!normalized.is_empty()).then_some(normalized)
}

fn performed_action_item_request(words: &[String]) -> Option<String> {
    if !matches!(
        words,
        [interrogative, auxiliary, ..]
            if interrogative == "what"
                && matches!(auxiliary.as_str(), "had" | "has" | "have")
    ) {
        return None;
    }
    let done_positions = words
        .iter()
        .enumerate()
        .skip(2)
        .filter_map(|(index, word)| (word == "done").then_some(index))
        .collect::<Vec<_>>();
    let [done_index] = done_positions.as_slice() else {
        return None;
    };
    explicit_single_action_subject(&words[2..*done_index])
}

fn result_value_action_request(
    words: &[String],
) -> Option<(String, HashSet<String>, String, String)> {
    if !words
        .first()
        .is_some_and(|word| matches!(word.as_str(), "what" | "which"))
    {
        return None;
    }
    let auxiliary_positions = words
        .iter()
        .enumerate()
        .skip(2)
        .filter_map(|(index, word)| {
            matches!(word.as_str(), "did" | "had" | "has" | "have").then_some(index)
        })
        .collect::<Vec<_>>();
    let [auxiliary_index] = auxiliary_positions.as_slice() else {
        return None;
    };
    let target_words = &words[1..*auxiliary_index];
    if target_words
        .iter()
        .any(|word| matches!(word.as_str(), "and" | "or"))
    {
        return None;
    }
    let requested_value_kind = requested_value_kind(target_words)?;
    let target_terms = facet_terms(&target_words.join(" "));
    if target_terms.is_empty() {
        return None;
    }

    let controls = words
        .windows(3)
        .enumerate()
        .skip(auxiliary_index.saturating_add(1))
        .filter_map(|(index, window)| {
            if matches!(
                window[0].as_str(),
                "attempt" | "attempted" | "attempts" | "try" | "tried" | "tries"
            ) && window[1] == "to"
            {
                lifecycle_action_lemma(&window[2]).map(|head| (index, head))
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    let [(control_index, lifecycle_head)] = controls.as_slice() else {
        return None;
    };
    if *control_index + 3 != words.len() {
        return None;
    }
    let subject =
        explicit_single_action_subject(&words[auxiliary_index.saturating_add(1)..*control_index])?;
    Some((
        subject,
        target_terms,
        requested_value_kind,
        (*lifecycle_head).to_owned(),
    ))
}

fn factual_action_request(plan: &RecallPlan) -> Option<FactualActionRequest> {
    let requested = infer_requested_answer_spec(plan);
    if requested.modality() != RequestedAnswerModality::Factual
        || plan.derivation != RecallDerivation::Extractive
        || temporal_constraint_blocks_expansion(plan)
    {
        return None;
    }
    let query_terms = facet_terms(&plan.query);
    if requested.role() == RequestedAnswerRole::Method
        && matches!(
            plan.answer_shape,
            AnswerShape::Collection | AnswerShape::Relationship
        )
    {
        return Some(FactualActionRequest {
            projection: FactualActionProjection::Method,
            target_terms: query_terms.clone(),
            query_terms,
            exact_subject: None,
            requested_value_kind: None,
            requested_lifecycle_head: None,
        });
    }
    if requested.role() != RequestedAnswerRole::Value
        || plan.answer_shape != AnswerShape::Collection
    {
        return None;
    }
    let words = query_words(&plan.query);
    if words.iter().any(|word| {
        matches!(
            word.as_str(),
            "can't"
                | "cannot"
                | "could"
                | "couldn't"
                | "didn't"
                | "doesn't"
                | "don't"
                | "future"
                | "hadn't"
                | "hasn't"
                | "haven't"
                | "if"
                | "intend"
                | "intended"
                | "intending"
                | "intends"
                | "may"
                | "might"
                | "never"
                | "not"
                | "plan"
                | "planned"
                | "planning"
                | "plans"
                | "possible"
                | "possibly"
                | "potentially"
                | "should"
                | "shouldn't"
                | "unless"
                | "want"
                | "wanted"
                | "wanting"
                | "wants"
                | "will"
                | "won't"
                | "would"
                | "wouldn't"
        )
    }) {
        return None;
    }
    if let Some(subject) = performed_action_item_request(&words) {
        return Some(FactualActionRequest {
            projection: FactualActionProjection::PerformedActionItem,
            target_terms: query_terms.clone(),
            query_terms,
            exact_subject: Some(subject),
            requested_value_kind: None,
            requested_lifecycle_head: None,
        });
    }
    let (subject, target_terms, requested_value_kind, requested_lifecycle_head) =
        result_value_action_request(&words)?;
    Some(FactualActionRequest {
        projection: FactualActionProjection::ResultValue,
        query_terms,
        target_terms,
        exact_subject: Some(subject),
        requested_value_kind: Some(requested_value_kind),
        requested_lifecycle_head: Some(requested_lifecycle_head),
    })
}

fn factual_method_request(plan: &RecallPlan) -> Option<FactualActionRequest> {
    factual_action_request(plan)
        .filter(|request| request.projection == FactualActionProjection::Method)
}

pub(super) fn is_factual_method_request(plan: &RecallPlan) -> bool {
    factual_method_request(plan).is_some()
}

pub(super) fn is_factual_action_request(plan: &RecallPlan) -> bool {
    factual_action_request(plan).is_some()
}

fn infer_requested_answer_modality(query: &str) -> RequestedAnswerModality {
    let words = query_words(query);
    if query_is_polite_request(query) {
        return RequestedAnswerModality::Factual;
    }
    if words
        .iter()
        .any(|word| matches!(word.as_str(), "likely" | "probably" | "infer" | "imply"))
        || (words.iter().any(|word| word == "would") && !query_uses_habitual_would(&words))
        || query_uses_inferential_suggest(&words)
    {
        RequestedAnswerModality::Likely
    } else if words.iter().any(|word| {
        matches!(
            word.as_str(),
            "could" | "might" | "possibly" | "potentially"
        )
    }) || (words.iter().any(|word| word == "may") && !query_uses_calendar_may(query))
    {
        RequestedAnswerModality::Possible
    } else {
        RequestedAnswerModality::Factual
    }
}

fn query_is_polite_request(query: &str) -> bool {
    let normalized = normalized_phrase(query);
    [
        "could you tell",
        "could you remind",
        "could you explain",
        "would you tell",
        "would you remind",
        "would you explain",
        "would you say",
        "can you tell",
        "can you remind",
    ]
    .iter()
    .any(|prefix| normalized.starts_with(prefix))
}

fn query_uses_habitual_would(words: &[String]) -> bool {
    words.iter().any(|word| {
        matches!(
            word.as_str(),
            "often" | "usually" | "always" | "habitually" | "regularly"
        )
    }) || words.windows(2).any(|window| {
        matches!(
            window,
            [left, right]
                if (left == "every" && matches!(right.as_str(), "day" | "week" | "month" | "year"))
                    || (left == "used" && right == "to")
        )
    })
}

fn query_uses_inferential_suggest(words: &[String]) -> bool {
    let Some(suggest_index) = words
        .iter()
        .position(|word| matches!(word.as_str(), "suggest" | "suggests" | "suggested"))
    else {
        return false;
    };
    !words[..suggest_index].iter().any(|word| word == "did")
}

fn query_uses_calendar_may(query: &str) -> bool {
    let tokens = query
        .split(|character: char| !character.is_alphanumeric())
        .filter(|token| !token.is_empty())
        .collect::<Vec<_>>();
    tokens.iter().enumerate().any(|(index, token)| {
        *token == "May"
            && (tokens
                .get(index.saturating_add(1))
                .is_some_and(|next| next.bytes().all(|byte| byte.is_ascii_digit()))
                || index
                    .checked_sub(1)
                    .and_then(|index| tokens.get(index))
                    .is_some_and(|previous| {
                        matches!(
                            previous.to_ascii_lowercase().as_str(),
                            "in" | "on" | "during" | "since" | "until"
                        )
                    }))
    })
}

fn infer_requested_value_target(query: &str) -> Option<String> {
    let normalized = query.trim().to_lowercase();
    let words: Vec<_> = normalized
        .split(|character: char| !character.is_alphanumeric() && character != '\'')
        .filter(|word| !word.is_empty())
        .map(|word| word.strip_suffix("'s").unwrap_or(word))
        .collect();
    let interrogative = words
        .iter()
        .position(|word| matches!(*word, "what" | "which" | "who" | "how"))?;
    let phrase_start = interrogative.saturating_add(1);
    let phrase_end = words
        .iter()
        .enumerate()
        .skip(phrase_start)
        .take(8)
        .find_map(|(index, word)| requested_value_phrase_boundary(word).then_some(index))
        .unwrap_or_else(|| words.len().min(phrase_start.saturating_add(8)));
    let phrase = &words[phrase_start..phrase_end];

    for (offset, word) in phrase.iter().enumerate() {
        let index = phrase_start.saturating_add(offset);
        let previous = index
            .checked_sub(1)
            .and_then(|index| words.get(index))
            .copied();
        let target = match *word {
            "state" | "province" | "territory" | "country" | "nation" | "city" | "town"
            | "composer" | "songwriter" | "author" | "writer" | "manufacturer" | "organization"
            | "organisation" | "occupation" | "profession" | "position" | "role" => {
                (*word).to_owned()
            }
            "states" | "provinces" | "territories" | "countries" | "nations" | "cities"
            | "towns" | "composers" | "songwriters" | "authors" | "writers" | "manufacturers"
            | "organizations" | "organisations" | "occupations" | "professions" | "positions"
            | "roles" | "medium" | "mediums" => (*word).to_owned(),
            "company" | "companies" => requested_company_target(phrase, offset, word),
            "brand" | "brands" => (*word).to_owned(),
            "game" | "games" => requested_game_target(phrase, offset),
            "trait" | "traits" => match previous {
                Some("personality") => "personality traits".to_owned(),
                Some("character") => "character traits".to_owned(),
                _ => "descriptive trait".to_owned(),
            },
            "descriptor" | "descriptors" | "description" => "descriptor".to_owned(),
            "job" => match phrase.get(offset.saturating_add(1)).copied() {
                Some("title") => "job title".to_owned(),
                _ => "job or role".to_owned(),
            },
            "title" => match previous {
                Some("game") => "game title".to_owned(),
                Some("book") => "book title".to_owned(),
                Some("song") => "song title".to_owned(),
                Some("job") => "job title".to_owned(),
                _ => "title".to_owned(),
            },
            _ => continue,
        };
        return Some(target);
    }

    let has_word = |needle: &str| words.contains(&needle);
    if words.first() == Some(&"who") && (has_word("wrote") || has_word("written")) {
        return Some("author".to_owned());
    }
    if words.first() == Some(&"who") && (has_word("composed") || has_word("composer")) {
        return Some("composer".to_owned());
    }
    if matches!(words.get(interrogative), Some(&"what" | &"which"))
        && (has_word("shop") || has_word("store"))
    {
        return Some("shop or store name".to_owned());
    }
    if (has_word("describe") || has_word("described") || has_word("describes"))
        && matches!(words.first(), Some(&"what" | &"how"))
    {
        if has_word("feeling") || has_word("feelings") {
            return Some("predicate descriptor applied to the feeling".to_owned());
        }
        return Some("descriptor".to_owned());
    }
    if words.first() == Some(&"what")
        && words
            .iter()
            .any(|word| matches!(*word, "could" | "may" | "might" | "would"))
        && has_word("do")
        && has_word("after")
    {
        return Some("possible action".to_owned());
    }
    if normalized.contains("name of the game") {
        return Some("game title".to_owned());
    }
    None
}

fn requested_value_phrase_boundary(word: &str) -> bool {
    matches!(
        word,
        "am" | "are"
            | "can"
            | "could"
            | "did"
            | "do"
            | "does"
            | "had"
            | "has"
            | "have"
            | "is"
            | "may"
            | "might"
            | "should"
            | "was"
            | "were"
            | "will"
            | "would"
    )
}

fn requested_company_target(phrase: &[&str], company_offset: usize, head: &str) -> String {
    let modifiers = phrase[..company_offset]
        .iter()
        .rev()
        .take(3)
        .copied()
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .filter(|word| {
            !matches!(
                *word,
                "a" | "an" | "the" | "specific" | "likely" | "popular" | "renowned"
            )
        })
        .collect::<Vec<_>>();
    if modifiers.is_empty() {
        head.to_owned()
    } else {
        format!("{} {head}", modifiers.join(" "))
    }
}

fn requested_game_target(phrase: &[&str], game_offset: usize) -> String {
    let requests_kind = phrase[..game_offset]
        .windows(2)
        .any(|window| matches!(window, ["type" | "types" | "kind" | "kinds", "of"]));
    if requests_kind {
        "game type".to_owned()
    } else {
        "game title".to_owned()
    }
}

fn requested_answer_spec_instruction(
    spec: &RequestedAnswerSpec,
    allows_public_one_hop: bool,
    include_query_literals: bool,
) -> String {
    let mut instruction = requested_answer_spec_obligation(spec, include_query_literals);
    if allows_public_one_hop {
        instruction.push(' ');
        instruction.push_str(&public_one_hop_result_instruction(spec));
    }
    instruction
}

fn requested_answer_spec_obligation(
    spec: &RequestedAnswerSpec,
    include_query_literals: bool,
) -> String {
    let role = match spec.role() {
        RequestedAnswerRole::Value => {
            "return the requested value itself rather than a nearby anchor or effect"
        }
        RequestedAnswerRole::PredicateDescriptor => {
            "return the exact descriptor or characterization the named speaker applied to the queried subject, not the subject, resulting feeling, effect, content, or object being described"
        }
        RequestedAnswerRole::Method => {
            "return the means or method by which the action was performed, not its outcome, motivation, or an unperformed plan"
        }
        RequestedAnswerRole::HypothesisChoice => {
            "compare every named alternative and return the best-supported choice by name; retain unresolved competitors when the evidence does not distinguish them"
        }
        RequestedAnswerRole::EventAttribute => {
            "return the requested attribute of the time-scoped grounded event, keeping the event anchor separate from the attribute value"
        }
        RequestedAnswerRole::TemporalPoint => match requested_temporal_granularity(spec) {
            RequestedTemporalGranularity::ExactDay => {
                "return the exact requested calendar day, not an elapsed-duration string; use a directly grounded day when stated, otherwise keep the grounded reference day and exact elapsed duration in separate inputs and subtract the duration deterministically"
            }
            RequestedTemporalGranularity::EvidenceCompatible => {
                "return the narrowest unambiguous calendar value supported by evidence without inventing day precision; a grounded day, named month and year, qualified early/mid/late month, or bounded absolute calendar range is eligible, while a raw duration or unresolved relative phrase is not"
            }
        },
        RequestedAnswerRole::ElapsedSpan => {
            "return an elapsed span from grounded compatible boundaries or an explicit grounded duration, preserving lower-bound or approximate qualifiers"
        }
    };
    let modality = match spec.modality() {
        RequestedAnswerModality::Factual => "factual",
        RequestedAnswerModality::Likely => {
            "likely: compare grounded support and contradiction without requiring the conclusion verbatim"
        }
        RequestedAnswerModality::Possible => {
            "possible: return only supported possibilities and preserve uncertainty"
        }
    };
    let cardinality = match spec.cardinality() {
        RequestedAnswerCardinality::One => "one final value",
        RequestedAnswerCardinality::Multiple => "all distinct supported values requested",
        RequestedAnswerCardinality::Exhaustive => {
            "every distinct supported value in the bounded delivered evidence"
        }
    };
    let mut instruction = format!(
        "Typed answer obligation: role={role}; modality={modality}; cardinality={cardinality}."
    );
    if include_query_literals && let Some(target) = spec.value_target() {
        instruction.push_str(" Requested answer type: ");
        instruction.push_str(target);
        instruction.push_str(
            ". Keep that requested value separate from any grounded anchor used to derive it; do not return the anchor as though it were the requested value.",
        );
    }
    instruction
}

fn public_one_hop_result_instruction(spec: &RequestedAnswerSpec) -> String {
    let mut instruction = "This typed policy permits one stable public one-hop relation step from each source-grounded anchor to the requested answer type. One-hop limits relation depth, not result cardinality: map multiple grounded anchors independently. Return neither a grounded anchor nor an intermediate relation value as the answer, and never use public knowledge to invent a personal, session-specific, or changing fact."
        .to_owned();
    match (spec.modality(), spec.cardinality()) {
        (
            RequestedAnswerModality::Possible,
            RequestedAnswerCardinality::Multiple | RequestedAnswerCardinality::Exhaustive,
        ) => instruction.push_str(
            " For this possible multi-value request, one specific grounded entity may yield every member only when the relation is explicitly closed, small, stable, and canonical for the requested type. A broad region, category, or open-ended membership is not a closed result set. Preserve a separate source-grounded premise for the anchor and a distinct item finding and ledger entry for every derived value; otherwise leave the set unresolved instead of choosing or expanding arbitrarily.",
        ),
        (RequestedAnswerModality::Factual, RequestedAnswerCardinality::One) => {
            instruction.push_str(
                " For this singular factual request, return exactly one stable, unambiguous requested-type value; if the one-step relation has competing values, do not choose arbitrarily.",
            );
        }
        _ => {}
    }
    instruction
}

fn relation_value_resolution_instruction(allows_public_one_hop: bool) -> &'static str {
    if allows_public_one_hop {
        "This scalar relationship answer requires RelationValueResolution. First record the source-grounded directed relation or event anchor as one or more Premise findings, then record the single requested-type final value as one or more distinct Item findings and consume them through separate Premise and AnswerValue inputs in that order. The AnswerValue may be stated directly by delivered evidence or may be exactly one stable public relation step from the grounded anchor under the typed one-hop policy; public knowledge must not supply the personal relation, its participants, modality, or time. The sole answer item must consume every relation-resolution finding, and its value, every Item answer_value, the candidate, and the operator output must agree. If a material competitor remains, return an unresolved draft without an output."
    } else {
        "This scalar relationship answer requires RelationValueResolution. First record the source-grounded directed relation or event anchor as one or more Premise findings, then record the single directly source-grounded requested-type final value as one or more distinct Item findings and consume them through separate Premise and AnswerValue inputs in that order. This plan does not authorize a public projection. The sole answer item must consume every relation-resolution finding, and its value, every Item answer_value, the candidate, and the operator output must agree. If a material competitor remains, return an unresolved draft without an output."
    }
}

const NAMED_PREFERENCE_FULFILLMENT_RULE: &str = "For this scalar likely or possible typed-value inference, use HypothesisComparison and treat both passages as CandidateSupport only when the same subject first states an explicit candidate-specific preference or intention naming the candidate and later actually fulfills the same compatible role or category. The later fulfillment need not repeat the candidate name, and that omission is not a missing evidence slot. Do not connect a mere list mention, name occurrence, topic overlap, different subject, different relation, plan, hypothetical, or unfulfilled intention. Reject the identity when an equally or more strongly supported competitor or a concrete contradiction remains.";

const TEMPORAL_SCHEDULE_IDENTITY_RULE: &str = "For a when-did or take-place question, when an event-specific source supplies a scheduled absolute or relative time and a later source only reports that the same event is underway without its own start or event date, retain the earlier value explicitly as the scheduled time, not as an unqualified proven occurrence time. Resolve a relative schedule against that source's observation time. The later underway observation establishes only that the event began no later than that observation; its timestamp is not a replacement start or event date and does not prove the original schedule was honored. Require the same subject and event identity rather than topic similarity. Reject the schedule when any source reschedules, postpones, cancels, or supplies a contradictory actual start, and do not treat the schedule alone as proof of completion.";

fn temporal_point_stage_instruction(
    stage: RecallReaderStage,
    granularity: RequestedTemporalGranularity,
) -> &'static str {
    match (stage, granularity) {
        (RecallReaderStage::Answer, RequestedTemporalGranularity::ExactDay) => {
            "Return an exact calendar day, never a duration string. Use one answer_value input when a source directly states an unambiguous day. When the evidence instead states an elapsed duration relative to an observation or reference day, ground each value in a separate finding, normalize the reference as YYYY-MM-DD, and subtract the exact positive integer duration. Days and weeks use fixed-day subtraction; exact integral calendar months use Gregorian month subtraction with the day clamped to the target month's last valid day. Do not mix the two modes or convert years, approximate or compound durations, or ambiguous numeric dates."
        }
        (RecallReaderStage::Reflection, RequestedTemporalGranularity::ExactDay) => {
            "Build a source-cited temporal-point operation. If a source directly states the requested day, put that exact YYYY-MM-DD value in one answer_value finding. Otherwise keep exactly one unambiguous YYYY-MM-DD observation or reference day and one exact positive integral duration in separate findings, label them reference_time and elapsed_duration, and derive the YYYY-MM-DD result by subtraction. Accept only days, weeks, or calendar months; clamp an exact calendar-month result to the target month's last valid Gregorian day. A duration alone is not a when-answer; leave the point unresolved when the reference, duration, direction, or calendar interpretation is ambiguous."
        }
        (
            RecallReaderStage::Verification | RecallReaderStage::Repair,
            RequestedTemporalGranularity::ExactDay,
        ) => {
            "Verify a directly cited answer_value day, or recompute the temporal point from the cited reference_time and elapsed_duration findings. Do not mix those modes. Require exact YYYY-MM-DD calendar values and, for subtraction, one exact positive integral duration in days, weeks, or calendar months; apply Gregorian last-day clamping to month subtraction and make the candidate, sole answer item, and operator output equal the verified or computed YYYY-MM-DD value. Reject a duration string as the final answer, approximate, compound, or yearly duration, ambiguous numeric date, missing role, or unsupported citation."
        }
        (RecallReaderStage::Answer, RequestedTemporalGranularity::EvidenceCompatible) => {
            "Return the narrowest unambiguous calendar value supported for the event; a generic when-question does not require an invented day. Use one answer_value input for an exact YYYY-MM-DD day, a named month and year, an early/mid/late qualified month, a first/second/third/fourth/last week of a named month and year, or a bounded range whose two endpoints are unambiguous absolute days. Resolve a source-relative expression such as next month or last week against that source's observation time before putting the resolved value in answer_value. Alternatively, derive an exact day from one grounded YYYY-MM-DD reference_time minus one exact positive integral elapsed_duration. Never return a raw duration, bare unresolved relative phrase, vague approximation, bare year, or locale-ambiguous numeric date."
        }
        (RecallReaderStage::Reflection, RequestedTemporalGranularity::EvidenceCompatible) => {
            "Build a source-cited temporal-point operation at the evidence-supported granularity. Prefer one direct answer_value finding when the source states or source-time resolution yields an unambiguous day, named month and year, qualified early/mid/late month, named ordinal week of a month and year, or bounded range with two absolute day endpoints. Do not demand day precision when the evidence supports only one of those coarser values. Otherwise keep exactly one YYYY-MM-DD reference_time and one exact positive integral elapsed_duration in separate findings and subtract it to derive an exact day. A duration alone or an unresolved expression such as last week is not a when-answer; leave unsupported, vague, or locale-ambiguous values unresolved."
        }
        (
            RecallReaderStage::Verification | RecallReaderStage::Repair,
            RequestedTemporalGranularity::EvidenceCompatible,
        ) => {
            "Verify one directly cited evidence-compatible calendar answer_value, or recompute an exact day from the cited reference_time and elapsed_duration findings; never mix the modes. A direct value may be an exact YYYY-MM-DD day, named month and year, early/mid/late qualified month, first/second/third/fourth/last week of a named month and year, or a bounded range with two unambiguous absolute day endpoints. Make the candidate, sole answer item, and operator output equal that verified or computed value. Reject raw durations, unresolved relative phrases, vague approximations, bare years, locale-ambiguous numeric dates, missing roles, and unsupported citations."
        }
    }
}

fn plan_requires_relation_value_resolution(plan: &RecallPlan, spec: &RequestedAnswerSpec) -> bool {
    plan.answer_shape == AnswerShape::Relationship
        && !plan_uses_temporal_readout(plan)
        && spec.role() == RequestedAnswerRole::Value
        && spec.cardinality() == RequestedAnswerCardinality::One
        && spec.value_target().is_some()
}

fn plan_supports_named_preference_fulfillment(
    plan: &RecallPlan,
    spec: &RequestedAnswerSpec,
) -> bool {
    plan.answer_shape == AnswerShape::Inference
        && plan.derivation == RecallDerivation::GroundedInference
        && spec.role() == RequestedAnswerRole::Value
        && spec.cardinality() == RequestedAnswerCardinality::One
        && matches!(
            spec.modality(),
            RequestedAnswerModality::Likely | RequestedAnswerModality::Possible
        )
        && spec.value_target().is_some()
}

fn append_requested_answer_spec_instruction(
    instruction: &mut String,
    spec: &RequestedAnswerSpec,
    allows_public_one_hop: bool,
    include_query_literals: bool,
) {
    if !instruction.is_empty() {
        instruction.push(' ');
    }
    instruction.push_str(&requested_answer_spec_instruction(
        spec,
        allows_public_one_hop,
        include_query_literals,
    ));
}

#[cfg(test)]
fn product_reader_guidance(plan: &RecallPlan) -> String {
    plan.reader_contract().context_guidance()
}

fn query_requests_elapsed_duration(query: &str) -> bool {
    let normalized_query = normalized_phrase(query);
    normalized_contains_phrase(&normalized_query, "how long")
        || normalized_query.contains("duration")
        || normalized_query.contains("elapsed")
        || normalized_query.contains("얼마나 오래")
        || normalized_query.contains("얼마 동안")
}

fn query_requests_temporal_point(query: &str) -> bool {
    let words = query_words(query);
    query_requests_exact_calendar_day(query)
        || words.iter().any(|word| word == "when")
        || words.windows(2).any(|window| {
            matches!(window[0].as_str(), "what" | "which")
                && matches!(
                    window[1].as_str(),
                    "date" | "day" | "month" | "week" | "year"
                )
        })
        || query.contains("언제")
}

fn query_requests_exact_calendar_day(query: &str) -> bool {
    let words = query_words(query);
    words.windows(2).any(|window| {
        matches!(window[0].as_str(), "what" | "which")
            && matches!(window[1].as_str(), "date" | "day")
    }) || words
        .windows(2)
        .any(|window| window[0] == "exact" && matches!(window[1].as_str(), "date" | "day"))
        || query.contains("정확한 날짜")
        || query.contains("몇 월 며칠")
        || query.contains("몇월 며칠")
}

fn product_reader_guidance_for_plan(plan: &RecallPlan) -> String {
    let requests_duration = query_requests_elapsed_duration(&plan.query);
    let requests_temporal_point = query_requests_temporal_point(&plan.query);
    let requested_spec = infer_requested_answer_spec(plan);
    let temporal_fact = plan_uses_temporal_readout(plan)
        && !matches!(
            plan.answer_shape,
            AnswerShape::Temporal | AnswerShape::Frequency
        );
    let inference_collection = plan.answer_shape == AnswerShape::Collection
        && plan.derivation == RecallDerivation::GroundedInference;
    let guidance = match plan.answer_shape {
        AnswerShape::Fact if temporal_fact => {
            "Use the source and resolved event times to choose the evidence that covers the \
             requested date or interval, then answer the requested attribute exactly. Observation \
             time is only an anchor for resolving relative expressions such as yesterday, last \
             week, or for a month; do not substitute a nearby event. If the anchored event omits \
             the attribute, use a later explicit value only from an uninterrupted same-speaker, \
             same-session topical chain with compatible entity and activity references and no \
             competing value; cite both sources."
        }
        AnswerShape::Fact => {
            "Prefer the most explicit source passage. Answer the requested attribute and \
             granularity exactly; when asked how a source describes something, preserve its \
             explicit descriptive word or phrase rather than a nearby effect or paraphrase. Do \
             not substitute a nearby detail, and do not abstain when an explicit answer is \
             present."
        }
        AnswerShape::Temporal if requests_duration => {
            "Build one source-grounded chronological event chain: establish entity identity, a \
             start or first active observation, projection, intervening progress, completion or \
             end, and the latest active observation. Resolve aliases \
             and generic references only under same-speaker ownership plus same-session linkage \
             or compatible cross-session event continuity; lexical similarity alone is not \
             enough. A projection is a forecast, not an observed end. Use an explicit grounded \
             duration when available; otherwise compute grounded start-to-actual-completion \
             elapsed time. If completion is absent but at least two observations establish the \
             same ongoing event, report only the first-to-latest lower bound with at least or so \
             far. Preserve approximate wording and never use retrieval time."
        }
        AnswerShape::Temporal if requests_temporal_point => temporal_point_stage_instruction(
            RecallReaderStage::Answer,
            requested_temporal_granularity(&requested_spec),
        ),
        AnswerShape::Temporal => {
            "Answer from source and resolved event-time annotations. Resolve relative expressions \
             against their source observation, and preserve the event's time rather than \
             substituting retrieval time."
        }
        AnswerShape::Frequency => {
            "Separate distinct dated instances of the requested event from emergencies and other \
             event kinds. Distinguish an explicit schedule from observed recurrence. State a \
             regular observed cadence only when at least three occurrences provide two reasonably \
             consistent intervals; otherwise use an approximate range or irregular description."
        }
        AnswerShape::Count => {
            "Count distinct supported events or items once. Give every candidate occurrence a \
             stable identity and actuality; count occurred canonical findings only, retain other \
             modalities as excluded findings, and point excluded duplicate representations \
             directly at their canonical finding. Do not infer unobserved instances or derive \
             occurrence identity from source id alone."
        }
        AnswerShape::Collection if inference_collection => {
            "Return every distinct plausible item requested by the question. Ground all personal \
             or changing premises in the evidence, then use stable, widely known background \
             knowledge only to bridge those premises; preserve alternatives instead of choosing \
             one arbitrarily. Keep each item as the shortest source-specific action, object, or \
             value that answers the requested predicate, not a broad topic label."
        }
        AnswerShape::Collection => {
            "Return every distinct item explicitly supported by the evidence. Preserve subject \
             and source ownership, do not add merely plausible items, and keep the shortest \
             source-specific action, object, or value rather than a broad topic label."
        }
        AnswerShape::Relationship if plan_uses_temporal_readout(plan) => {
            "Combine the source-grounded time or event anchor with the evidence that resolves its \
             referenced entity, place, or relationship. State the resulting directed relation \
             concisely while preserving attribution, modality, and temporal order."
        }
        AnswerShape::Relationship => {
            "Combine every source passage required by the relationship, then state only the \
             directed relationship, comparison, or reason they support. Preserve attribution, \
             modality, and temporal order."
        }
        AnswerShape::Inference => {
            "Ground every personal, session-specific, or changing premise in the source \
             evidence. Stable, widely known background knowledge may bridge those grounded \
             premises to the most conventional value or one concise conclusion; never invent \
             personal facts or merely restate the clue. For a yes/no or likely question, give the \
             supported conclusion even when the source does not state a prediction verbatim: the \
             required slots are the premises that discriminate among candidates, not an explicit \
             future conclusion. Compare a recent same-action outcome, explicit preference or \
             intention, and a later unnamed but category-compatible role against competing \
             candidates. A personal candidate name must occur in the delivered evidence, public \
             knowledge may supply only one stable category bridge, and similarly supported \
             competitors remain alternatives. Preserve modality and time."
        }
    };
    let mut guidance = guidance.to_owned();
    if temporal_constraint_is_trend(plan) {
        guidance.push_str(
            " Build a chronological ledger of grounded observations before stating a change or pattern. Preserve modality: a plan, condition, or hypothetical is not an observed completion merely because time passed.",
        );
    }
    if plan.answer_shape == AnswerShape::Temporal && !requests_duration {
        guidance.push(' ');
        guidance.push_str(TEMPORAL_SCHEDULE_IDENTITY_RULE);
    }
    if plan_requires_relation_value_resolution(plan, &requested_spec) {
        guidance.push(' ');
        guidance.push_str(relation_value_resolution_instruction(
            requested_spec.role() == RequestedAnswerRole::Value
                && requested_spec.value_target().is_some()
                && (plan.derivation == RecallDerivation::GroundedInference
                    || query_explicitly_requests_stable_public_relation(
                        &plan.query,
                        &requested_spec,
                    )),
        ));
    }
    if requested_spec.role() == RequestedAnswerRole::Value
        && requested_spec.value_target().is_some()
        && (plan.derivation == RecallDerivation::GroundedInference
            || query_explicitly_requests_stable_public_relation(&plan.query, &requested_spec))
    {
        guidance.push(' ');
        guidance.push_str(&public_one_hop_result_instruction(&requested_spec));
    }
    if plan_supports_named_preference_fulfillment(plan, &requested_spec) {
        guidance.push(' ');
        guidance.push_str(NAMED_PREFERENCE_FULFILLMENT_RULE);
    }
    guidance
}

/// Source-aware selection applied before normal package validation.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
#[non_exhaustive]
pub enum EvidenceSelection {
    /// Choose the policy from the complete deterministic [`RecallPlan`].
    ///
    /// Direct queries preserve the reranker's first eight rows, then prefer
    /// tail rows that add canonical raw evidence before backfilling redundant
    /// representations. Inference and date queries remove candidates that
    /// contribute no new canonical raw evidence. Enumeration, relationship,
    /// and frequency queries additionally preserve source-session diversity.
    #[default]
    Auto,
    /// Preserve the supplied ranking byte-for-byte.
    Relevance,
    /// Keep only the highest-ranked representation of an identical raw-source set.
    DistinctSources,
    /// Keep a candidate only when it contributes at least one raw source that
    /// higher-ranked candidates have not covered, then backfill from later candidates.
    SourceCoverage,
    /// Preserve a bounded burst of evidence from each source session before
    /// backfilling additional candidates from already saturated sessions.
    ///
    /// This protects multi-event and multi-source queries from spending their
    /// entire evidence budget on overlapping turns from one conversation
    /// without discarding a small same-session evidence chain.
    SourceSessionCoverage,
}

/// Options for model-free deep recall through [`Memory`](super::Memory).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub struct DeepRecallOptions {
    /// Maximum number of ranked evidence representations in the final package.
    pub limit: usize,
    /// Source-aware selection policy.
    pub selection: EvidenceSelection,
}

/// Options for the canonical production reranked-recall pipeline.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct RerankedRecallOptions {
    /// Number of cognitive readout candidates compiled into evidence documents.
    pub candidate_limit: usize,
    /// Cognitive search/package width before local reranking.
    ///
    /// This remains at least 20 by default even when a caller requests only a
    /// few final hits. The broader reranker candidate surface is retained in
    /// diagnostics independently of this package width.
    pub search_limit: usize,
    /// Final source-aware selection and package options.
    pub deep: DeepRecallOptions,
    /// Optional graph scope applied during cognitive search, before reranking.
    pub scope: Option<ScopePath>,
    /// Whether the production path may shrink one-fact delivery below the
    /// caller's maximum while retaining temporal and complex-query widths.
    pub adaptive_delivery: bool,
}

impl RerankedRecallOptions {
    /// Build the latency-sensitive profile shared by product consumers.
    ///
    /// Cognitive search uses at least 20 seeds/results and exposes up to
    /// [`DEFAULT_RERANK_CANDIDATE_LIMIT`] evidence documents to the local
    /// reranker; the final package is capped at `limit`.
    pub fn new(limit: usize) -> Self {
        Self {
            candidate_limit: DEFAULT_RERANK_CANDIDATE_LIMIT,
            search_limit: limit.max(DEFAULT_RERANK_SEARCH_LIMIT),
            deep: DeepRecallOptions::new(limit),
            scope: None,
            adaptive_delivery: true,
        }
    }

    /// Override the reranker candidate pool width.
    pub fn with_candidate_limit(mut self, candidate_limit: usize) -> Self {
        self.candidate_limit = candidate_limit;
        self
    }

    /// Override the cognitive search width independently of the final hit cap.
    pub fn with_search_limit(mut self, search_limit: usize) -> Self {
        self.search_limit = search_limit;
        self
    }

    /// Override the source-aware evidence-selection policy.
    pub fn with_selection(mut self, selection: EvidenceSelection) -> Self {
        self.deep.selection = selection;
        self
    }

    /// Restrict cognitive search and all downstream reranking to `scope`.
    pub fn with_scope(mut self, scope: ScopePath) -> Self {
        self.scope = Some(scope);
        self
    }

    /// Enable or disable question-shape-aware final evidence caps.
    ///
    /// Disabling this preserves the exact caller-supplied final maximum. It
    /// does not change cognitive search or reranker candidate widths.
    pub fn with_adaptive_delivery(mut self, adaptive_delivery: bool) -> Self {
        self.adaptive_delivery = adaptive_delivery;
        self
    }
}

impl DeepRecallOptions {
    /// Build the default automatic deep-readout profile.
    pub fn new(limit: usize) -> Self {
        Self {
            limit,
            selection: EvidenceSelection::Auto,
        }
    }

    /// Override the deterministic evidence-selection policy.
    pub fn with_selection(mut self, selection: EvidenceSelection) -> Self {
        self.selection = selection;
        self
    }
}

fn recall_intent_for(answer_shape: AnswerShape, has_temporal_constraint: bool) -> RecallIntent {
    if matches!(answer_shape, AnswerShape::Temporal | AnswerShape::Frequency)
        || has_temporal_constraint
    {
        RecallIntent::Temporal
    } else if matches!(answer_shape, AnswerShape::Count | AnswerShape::Collection) {
        RecallIntent::Enumeration
    } else if matches!(
        answer_shape,
        AnswerShape::Relationship | AnswerShape::Inference
    ) {
        RecallIntent::Relational
    } else {
        RecallIntent::Direct
    }
}

fn effective_recall_intent(plan: &RecallPlan) -> RecallIntent {
    recall_intent_for(
        plan.answer_shape,
        !matches!(
            plan.effective_temporal_constraint(),
            EffectiveTemporalConstraint::None
        ),
    )
}

pub(super) fn plan_has_temporal_constraint(plan: &RecallPlan) -> bool {
    !matches!(
        plan.effective_temporal_constraint(),
        EffectiveTemporalConstraint::None
    )
}

pub(super) fn plan_uses_temporal_readout(plan: &RecallPlan) -> bool {
    effective_recall_intent(plan) == RecallIntent::Temporal
}

pub(super) fn plan_allows_historical_expired(plan: &RecallPlan) -> bool {
    matches!(
        plan.effective_temporal_constraint(),
        EffectiveTemporalConstraint::Trend
    )
}

fn temporal_constraint_blocks_expansion(plan: &RecallPlan) -> bool {
    matches!(
        plan.effective_temporal_constraint(),
        EffectiveTemporalConstraint::CalendarRange
            | EffectiveTemporalConstraint::EventBoundary
            | EffectiveTemporalConstraint::LegacyUnknown
    )
}

fn temporal_constraint_is_trend(plan: &RecallPlan) -> bool {
    plan.effective_temporal_constraint() == EffectiveTemporalConstraint::Trend
}

fn temporal_boundary_direction(word: &str) -> Option<TemporalBoundaryDirection> {
    match word {
        "before" => Some(TemporalBoundaryDirection::Before),
        "after" => Some(TemporalBoundaryDirection::After),
        _ => None,
    }
}

fn boundary_token_is_idiom(words: &[&str], index: usize) -> bool {
    matches!(
        words.get(index..index.saturating_add(2)),
        Some(["after", "all"] | ["before", "long"])
    )
}

fn calendar_boundary_operand(words: &[&str], boundary_index: usize) -> bool {
    let operand = &words[boundary_index.saturating_add(1)..];
    let Some(first) = operand.first().copied() else {
        return false;
    };
    const MONTHS: &[&str] = &[
        "january",
        "february",
        "march",
        "april",
        "may",
        "june",
        "july",
        "august",
        "september",
        "october",
        "november",
        "december",
    ];
    const NUMBER_WORDS: &[&str] = &[
        "a", "an", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
        "eleven", "twelve",
    ];
    const TIME_UNITS: &[&str] = &[
        "day", "days", "week", "weeks", "month", "months", "year", "years",
    ];
    let numeric_value = first.parse::<u32>().ok();
    let ordinal = ["st", "nd", "rd", "th"].iter().any(|suffix| {
        first
            .strip_suffix(suffix)
            .is_some_and(|value| value.parse::<u32>().is_ok())
    });
    let numeric_calendar_operand = numeric_value
        .is_some_and(|value| (1970..=2200).contains(&value))
        || (numeric_value.is_some() || ordinal || NUMBER_WORDS.contains(&first))
            && operand
                .get(1)
                .is_some_and(|next| MONTHS.contains(next) || TIME_UNITS.contains(next));
    if MONTHS.contains(&first)
        || matches!(
            first,
            "today" | "tonight" | "tomorrow" | "yesterday" | "last" | "this" | "next"
        )
        || numeric_calendar_operand
    {
        return true;
    }
    matches!(operand, ["the", "year", year, ..] if year.parse::<u32>().is_ok())
}

fn event_boundary_has_operand(words: &[&str], boundary_index: usize) -> bool {
    words[boundary_index.saturating_add(1)..]
        .iter()
        .copied()
        .find(|word| !matches!(*word, "a" | "an" | "the"))
        .is_some_and(|word| {
            !matches!(
                word,
                "and"
                    | "or"
                    | "but"
                    | "all"
                    | "long"
                    | "when"
                    | "what"
                    | "which"
                    | "who"
                    | "where"
                    | "why"
            )
        })
}

fn infer_temporal_constraint(normalized: &str, words: &[&str]) -> TemporalConstraint {
    let boundary_tokens: Vec<_> = words
        .iter()
        .enumerate()
        .filter_map(|(index, word)| {
            temporal_boundary_direction(word)
                .filter(|_| !boundary_token_is_idiom(words, index))
                .map(|direction| (index, direction))
        })
        .collect();
    if boundary_tokens.len() > 1 {
        return TemporalConstraint::ambiguous_event_boundary();
    }
    if let Some((boundary_index, direction)) = boundary_tokens.first().copied() {
        if calendar_boundary_operand(words, boundary_index) {
            return TemporalConstraint::calendar_boundary(direction);
        }
        if event_boundary_has_operand(words, boundary_index) {
            return TemporalConstraint::event_boundary(direction);
        }
    }

    const CLASSIFICATION_NOW: u64 = 1_700_000_000_000;
    if !crate::query::temporal::parse_time_cues(normalized, CLASSIFICATION_NOW).is_empty()
        || words.contains(&"ago")
        || normalized.contains("지난주")
        || normalized.contains("지난달")
        || normalized.contains("작년")
    {
        return TemporalConstraint::calendar_range();
    }
    if words.windows(2).any(|window| window == ["over", "time"]) {
        return TemporalConstraint::trend();
    }
    TemporalConstraint::none()
}

fn infer_plan(query: &str, answer_shape_hint: Option<AnswerShape>) -> RecallPlan {
    let normalized = query.trim().to_lowercase();
    let words: Vec<_> = normalized
        .split(|character: char| !character.is_alphanumeric() && character != '\'')
        .filter(|word| !word.is_empty())
        .collect();

    let has_word = |needle: &str| words.contains(&needle);
    let has_sequence = |needles: &[&str]| {
        !needles.is_empty() && words.windows(needles.len()).any(|window| window == needles)
    };
    let has_any_sequence =
        |sequences: &[&[&str]]| sequences.iter().any(|sequence| has_sequence(sequence));

    // These are locale rule packs rather than sentence prefixes: interrogative
    // phrases may occur anywhere in a polite wrapper or inverted question.
    const EN_TEMPORAL_TARGETS: &[&[&str]] = &[
        &["how", "long"],
        &["how", "often"],
        &["what", "date"],
        &["what", "day"],
        &["what", "month"],
        &["what", "week"],
        &["what", "year"],
        &["which", "date"],
        &["which", "day"],
        &["which", "month"],
        &["which", "week"],
        &["which", "year"],
    ];
    const EN_COUNT_TARGETS: &[&[&str]] = &[&["how", "many"], &["number", "of"]];
    const EN_COLLECTION_TARGETS: &[&[&str]] = &[
        &["list"],
        &["list", "all"],
        &["in", "what", "ways"],
        &["what", "are"],
        &["which", "are"],
    ];

    let requests_temporal_answer = query_requests_exact_calendar_day(query)
        || has_word("when")
        || has_any_sequence(EN_TEMPORAL_TARGETS)
        || has_word("duration")
        || has_word("elapsed")
        || normalized.contains("언제")
        || normalized.contains("얼마나 오래")
        || normalized.contains("얼마 동안")
        || normalized.contains("몇 년")
        || normalized.contains("몇년")
        || normalized.contains("몇 월")
        || normalized.contains("몇월")
        || normalized.contains("몇 주")
        || normalized.contains("몇주")
        || normalized.contains("며칠");
    let requests_count = has_any_sequence(EN_COUNT_TARGETS)
        || normalized.contains("몇 번")
        || normalized.contains("몇번")
        || normalized.contains("몇 개")
        || normalized.contains("몇개");
    let interrogative_object_phrase = words
        .iter()
        .position(|word| matches!(*word, "what" | "which"))
        .map_or_else(Vec::new, |start| {
            words[start.saturating_add(1)..]
                .iter()
                .take_while(|word| {
                    !matches!(
                        **word,
                        "am" | "are"
                            | "can"
                            | "could"
                            | "did"
                            | "do"
                            | "does"
                            | "had"
                            | "has"
                            | "have"
                            | "is"
                            | "may"
                            | "might"
                            | "should"
                            | "was"
                            | "were"
                            | "will"
                            | "would"
                    )
                })
                .copied()
                .collect()
        });
    let requests_plural_object = !interrogative_object_phrase
        .iter()
        .any(|word| word.ends_with("'s"))
        && interrogative_object_phrase
            .iter()
            .any(|word| word.len() > 3 && word.ends_with('s') && !matches!(*word, "this" | "thus"));
    let requests_coordinated_object = interrogative_object_phrase.contains(&"and")
        && !interrogative_object_phrase.contains(&"between")
        && interrogative_object_phrase
            .iter()
            .filter(|word| !matches!(**word, "and" | "new" | "other"))
            .count()
            >= 2;
    let requests_activity_kinds = has_sequence(&["what", "kind", "of"])
        && words
            .iter()
            .filter(|word| matches!(**word, "did" | "do" | "does" | "done"))
            .count()
            >= 2;
    let interrogative_has_sequence = |needles: &[&str]| {
        !needles.is_empty()
            && interrogative_object_phrase
                .windows(needles.len())
                .any(|window| window == needles)
    };
    let requests_explicit_partial_collection = interrogative_object_phrase
        .iter()
        .any(|word| matches!(*word, "some" | "example" | "examples"))
        || interrogative_has_sequence(&["a", "few"])
        || interrogative_has_sequence(&["one", "of"])
        || has_any_sequence(&[
            &["what", "are", "some"],
            &["which", "are", "some"],
            &["what", "are", "example"],
            &["what", "are", "examples"],
            &["which", "are", "example"],
            &["which", "are", "examples"],
            &["what", "are", "a", "few"],
            &["which", "are", "a", "few"],
            &["list", "some"],
            &["list", "an", "example"],
            &["list", "examples"],
            &["list", "a", "few"],
        ]);
    let exhaustive_marker_in_answer_request = interrogative_object_phrase
        .iter()
        .any(|word| matches!(*word, "all" | "every" | "each"))
        || matches!(words.as_slice(), ["name", "all" | "every" | "each", ..])
        || (requests_plural_object && words.iter().any(|word| matches!(*word, "every" | "each")))
        || has_any_sequence(&[
            &["list", "all"],
            &["list", "every"],
            &["list", "each"],
            &["what", "are", "all"],
            &["which", "are", "all"],
        ]);
    let requests_exhaustive_collection = !requests_explicit_partial_collection
        && (has_word("list") || exhaustive_marker_in_answer_request);
    let requests_composite_synthesis = query_requests_composite_synthesis(query);
    let requests_collection = has_any_sequence(EN_COLLECTION_TARGETS)
        || exhaustive_marker_in_answer_request
        || (matches!(words.as_slice(), ["what", "has" | "have", ..]) && has_word("done"))
        || requests_plural_object
        || requests_coordinated_object
        || requests_activity_kinds
        || requests_composite_synthesis
        || normalized.contains("무엇들이")
        || normalized.contains("어떤 것들이");
    let requests_relationship = has_any_sequence(&[
        &["relationship", "between"],
        &["connection", "between"],
        &["in", "common"],
    ]) || matches!(
        words.as_slice(),
        ["how", "did" | "does" | "has" | "have", ..]
    ) || has_word("meet")
        || has_word("met")
        || (has_word("where") && has_word("from") && (has_word("move") || has_word("moved")))
        || has_word("why")
        || has_word("both")
        || has_word("compare")
        || has_word("causes")
        || has_word("reasons")
        || normalized.contains("관계")
        || normalized.contains("공통")
        || normalized.contains("원인");
    let starts_yes_no_question = words.first().is_some_and(|word| {
        matches!(
            *word,
            "am" | "are"
                | "can"
                | "could"
                | "did"
                | "do"
                | "does"
                | "has"
                | "have"
                | "is"
                | "might"
                | "should"
                | "was"
                | "were"
                | "will"
                | "would"
        )
    });
    let requests_comparative_preference = has_word("prefer")
        && (has_sequence(&["more", "than"]) || has_sequence(&["rather", "than"]));
    let requests_modal_inference =
        infer_requested_answer_modality(query) != RequestedAnswerModality::Factual;
    let requests_inference = requests_modal_inference
        || has_any_sequence(&[
            &["what", "could"],
            &["how", "might"],
            &["how", "would"],
            &["what", "kind", "of", "person"],
        ])
        || (starts_yes_no_question && !query_is_polite_request(query))
        || requests_comparative_preference
        || normalized.contains("것 같")
        || normalized.contains("가능성이");

    let requests_frequency_answer = has_sequence(&["how", "often"]);
    let inferred_answer_shape = if requests_frequency_answer {
        AnswerShape::Frequency
    } else if requests_temporal_answer {
        AnswerShape::Temporal
    } else if requests_count {
        AnswerShape::Count
    } else if requests_collection {
        AnswerShape::Collection
    } else if requests_relationship {
        AnswerShape::Relationship
    } else if requests_inference {
        AnswerShape::Inference
    } else {
        AnswerShape::Fact
    };
    let answer_shape = answer_shape_hint.unwrap_or(inferred_answer_shape);
    let coverage = match answer_shape {
        AnswerShape::Collection if requests_explicit_partial_collection => RecallCoverage::Multiple,
        AnswerShape::Collection if requests_exhaustive_collection => RecallCoverage::Exhaustive,
        AnswerShape::Collection => RecallCoverage::Multiple,
        AnswerShape::Count | AnswerShape::Frequency => RecallCoverage::Exhaustive,
        _ => RecallCoverage::Focused,
    };

    let temporal_constraint = infer_temporal_constraint(&normalized, &words);
    let has_temporal_constraint = temporal_constraint.is_active();
    let recall_intent = recall_intent_for(answer_shape, has_temporal_constraint);
    let derivation = if requests_inference || requests_composite_synthesis {
        RecallDerivation::GroundedInference
    } else {
        RecallDerivation::Extractive
    };

    RecallPlan {
        query: query.trim().to_owned(),
        recall_intent,
        answer_shape,
        derivation,
        coverage,
        has_temporal_constraint,
        temporal_constraint,
    }
}

pub(super) fn adaptive_delivery_limit(plan: &RecallPlan, requested_limit: usize) -> usize {
    if effective_recall_intent(plan) == RecallIntent::Direct {
        requested_limit.min(DEFAULT_SIMPLE_DELIVERY_LIMIT)
    } else {
        requested_limit
    }
}

pub(crate) fn temporal_evidence_matches(query: &str, evidence: &str) -> bool {
    fn normalized_term(mut term: String) -> String {
        if term.len() > 5 && (term.ends_with("ies") || term.ends_with("ied")) {
            term.truncate(term.len() - 3);
            term.push('y');
        } else if term.len() > 5 && term.ends_with("ing") {
            term.truncate(term.len() - 3);
            let bytes = term.as_bytes();
            let doubled_ending =
                bytes.len() >= 2 && bytes[bytes.len() - 1] == bytes[bytes.len() - 2];
            if doubled_ending {
                term.pop();
            }
        } else if term.len() > 4 && term.ends_with("ed") {
            term.truncate(term.len() - 2);
            let bytes = term.as_bytes();
            let doubled_ending =
                bytes.len() >= 2 && bytes[bytes.len() - 1] == bytes[bytes.len() - 2];
            if doubled_ending {
                term.pop();
            }
        } else if term.len() > 4 && term.ends_with("es") {
            term.truncate(term.len() - 2);
        } else if term.len() > 3 && term.ends_with('s') && !term.ends_with("ss") {
            term.pop();
        }
        term
    }

    fn terms(value: &str) -> HashSet<String> {
        value
            .split(|character: char| !character.is_alphanumeric())
            .filter(|term| term.len() > 2)
            .map(str::to_lowercase)
            .filter(|term| {
                !matches!(
                    term.as_str(),
                    "about"
                        | "after"
                        | "ago"
                        | "before"
                        | "could"
                        | "date"
                        | "day"
                        | "did"
                        | "does"
                        | "during"
                        | "for"
                        | "from"
                        | "get"
                        | "got"
                        | "had"
                        | "has"
                        | "have"
                        | "her"
                        | "him"
                        | "his"
                        | "last"
                        | "month"
                        | "next"
                        | "please"
                        | "remember"
                        | "tell"
                        | "the"
                        | "their"
                        | "this"
                        | "was"
                        | "week"
                        | "were"
                        | "what"
                        | "when"
                        | "which"
                        | "would"
                        | "year"
                        | "you"
                )
            })
            .map(normalized_term)
            .collect()
    }

    let query_terms = terms(query);
    if query_terms.is_empty() {
        return false;
    }
    let evidence_terms = terms(evidence);
    let overlap = query_terms.intersection(&evidence_terms).count();
    overlap >= query_terms.len().min(2)
}

