#[allow(clippy::too_many_arguments)]
pub(crate) fn compile_ranking_with_atomic_chains_and_required_source_groups_at<
    S: StorageAdapter,
>(
    storage: &S,
    plan: &RecallPlan,
    ranking: &[RerankedCandidate],
    selection: EvidenceSelection,
    limit: usize,
    routed_atomic_sources: &[AtomicSourceMarker],
    atomic_relation_paths: &[AtomicRelationPath],
    premise_bundle: Option<&PremiseBundleTrace>,
    event_boundary_group: Option<&EventBoundarySourceGroup>,
    as_of: crate::graph::Timestamp,
    query_scope: &ScopePath,
) -> Result<Vec<RerankedCandidate>, Error> {
    let automatic = selection == EvidenceSelection::Auto;
    let resolved_selection = match selection {
        EvidenceSelection::Auto => match plan.answer_shape {
            AnswerShape::Collection | AnswerShape::Count | AnswerShape::Frequency => {
                EvidenceSelection::SourceSessionCoverage
            }
            AnswerShape::Relationship if plan_has_temporal_constraint(plan) => {
                EvidenceSelection::SourceCoverage
            }
            AnswerShape::Relationship => EvidenceSelection::SourceSessionCoverage,
            AnswerShape::Inference => EvidenceSelection::SourceCoverage,
            AnswerShape::Temporal => EvidenceSelection::SourceCoverage,
            AnswerShape::Fact if plan_has_temporal_constraint(plan) => {
                EvidenceSelection::SourceCoverage
            }
            AnswerShape::Fact => EvidenceSelection::Relevance,
        },
        explicit => explicit,
    };

    let baseline = match resolved_selection {
        EvidenceSelection::Auto | EvidenceSelection::Relevance => Ok(ranking.to_vec()),
        EvidenceSelection::DistinctSources => distinct_source_ranking(storage, ranking),
        EvidenceSelection::SourceCoverage => source_coverage_ranking(storage, ranking),
        EvidenceSelection::SourceSessionCoverage => {
            source_session_coverage_ranking(storage, ranking, limit)
        }
    }?;
    if !automatic {
        return Ok(baseline);
    }
    let baseline = if effective_recall_intent(plan) == RecallIntent::Direct {
        head_preserving_source_coverage_ranking(storage, &baseline, limit)?
    } else {
        baseline
    };
    let routed_atomic_sources = validated_final_selection_atomic_source_markers(
        storage,
        plan,
        routed_atomic_sources,
        as_of,
        query_scope,
    )?;
    let claim_ranking = claim_slot_coverage_ranking(
        storage,
        plan,
        ranking,
        &baseline,
        limit,
        &routed_atomic_sources,
    )?;
    let temporal_fact_ranking = temporal_fact_witness_ranking(
        storage,
        plan,
        ranking,
        &claim_ranking,
        limit,
        &routed_atomic_sources,
    )?;
    let chain_ranking = atomic_chain_group_ranking(
        storage,
        plan,
        ranking,
        &temporal_fact_ranking,
        limit,
        atomic_relation_paths,
    )?;
    let premise_ranking = premise_bundle_group_ranking(
        storage,
        ranking,
        &chain_ranking,
        limit,
        premise_bundle,
        atomic_relation_paths,
    )?;
    event_boundary_source_group_ranking(
        storage,
        ranking,
        &premise_ranking,
        limit,
        event_boundary_group,
        atomic_relation_paths,
        premise_bundle,
    )
}

fn head_preserving_source_coverage_ranking<S: StorageAdapter>(
    storage: &S,
    ranking: &[RerankedCandidate],
    limit: usize,
) -> Result<Vec<RerankedCandidate>, Error> {
    let head_limit = ranking.len().min(limit).min(8);
    let mut covered_sources = HashSet::new();
    let mut selected = Vec::with_capacity(ranking.len());
    for candidate in ranking.iter().take(head_limit) {
        covered_sources.extend(canonical_sources(storage, candidate.node_id)?);
        selected.push(*candidate);
    }

    let mut deferred = Vec::new();
    for candidate in ranking.iter().skip(head_limit) {
        let sources = canonical_sources(storage, candidate.node_id)?;
        if sources
            .iter()
            .any(|source| !covered_sources.contains(source))
        {
            covered_sources.extend(sources);
            selected.push(*candidate);
        } else {
            deferred.push(*candidate);
        }
    }
    selected.extend(deferred);
    Ok(selected)
}

fn claim_slot_coverage_ranking<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    ranking: &[RerankedCandidate],
    baseline: &[RerankedCandidate],
    limit: usize,
    routed_atomic_sources: &[AtomicSourceMarker],
) -> Result<Vec<RerankedCandidate>, Error> {
    claim_slot_coverage_ranking_with_head_protection(
        storage,
        plan,
        ranking,
        baseline,
        limit,
        routed_atomic_sources,
        true,
    )
}

#[allow(clippy::too_many_arguments)]
fn claim_slot_coverage_ranking_with_head_protection<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    ranking: &[RerankedCandidate],
    baseline: &[RerankedCandidate],
    limit: usize,
    routed_atomic_sources: &[AtomicSourceMarker],
    protect_reranked_head: bool,
) -> Result<Vec<RerankedCandidate>, Error> {
    if !uses_atomic_fact_expansion(plan) || limit == 0 {
        return Ok(baseline.to_vec());
    }

    let routed_atomic_sources = live_atomic_source_markers(storage, routed_atomic_sources)?;
    let mut claim_sources: HashMap<AtomicFactId, HashSet<NodeId>> = HashMap::new();
    // Marker order is the atomic router's query-relative ranking. Preserve it
    // through final evidence selection instead of letting HashMap iteration or
    // a second-stage document rank silently choose a different claim.
    let mut claim_priority = HashMap::new();
    let mut method_semantic_claims = HashSet::new();
    let method_request = factual_action_request(plan);
    let requires_relationship_claim_match =
        plan.answer_shape == AnswerShape::Relationship && !plan_uses_temporal_readout(plan);
    for (priority, marker) in routed_atomic_sources.iter().enumerate() {
        let Some(fact_id) = marker.fact_id else {
            continue;
        };
        let fact = storage.get_atomic_fact(fact_id)?;
        if let Some(request) = method_request.as_ref() {
            if marker.kind_priority == 0 {
                if !semantic_factual_action_fact_is_eligible(plan, request, fact) {
                    continue;
                }
                method_semantic_claims.insert(fact_id);
            } else if !structural_factual_action_fact_is_eligible(plan, request, fact) {
                continue;
            }
        }
        if requires_relationship_claim_match
            && trace_atomic_fact_relevance(plan, None, None, fact).is_none()
        {
            continue;
        }
        claim_priority.entry(fact_id).or_insert(priority);
        claim_sources
            .entry(fact_id)
            .or_default()
            .insert(marker.source_node_id);
    }
    if claim_sources.is_empty() {
        return Ok(baseline.to_vec());
    }
    enum ClaimCoverage {
        Legacy,
        Grounded {
            evidence_source: NodeId,
            evidence_span: String,
        },
        Invalid,
    }
    let mut claim_coverage = HashMap::new();
    let mut claim_keys = HashMap::new();
    let mut claim_sessions = HashMap::new();
    for fact_id in claim_sources.keys().copied() {
        let fact = storage.get_atomic_fact(fact_id)?;
        claim_sessions.insert(fact_id, fact.source_session_id.clone());
        if let Some(claim_key) = source_grounded_atomic_claim_key(storage, fact)? {
            claim_keys.insert(fact_id, claim_key);
        }
        let evidence_source = fact
            .metadata
            .get("anamnesis:evidence-source-node-id")
            .and_then(|value| value.parse::<u64>().ok())
            .map(NodeId);
        let evidence_start = fact
            .metadata
            .get("anamnesis:evidence-span-start")
            .and_then(|value| value.parse::<usize>().ok());
        let evidence_end = fact
            .metadata
            .get("anamnesis:evidence-span-end")
            .and_then(|value| value.parse::<usize>().ok());
        let ground_object = fact.metadata.get("anamnesis:ground-object");
        let requires_exact_object = fact.metadata.contains_key("anamnesis:evidence-object");
        let evidence_object = fact
            .metadata
            .get("anamnesis:evidence-object")
            .or(ground_object);
        let has_grounding_metadata = evidence_source.is_some()
            || evidence_start.is_some()
            || evidence_end.is_some()
            || ground_object.is_some()
            || evidence_object.is_some();
        let coverage = match (
            evidence_source,
            evidence_start,
            evidence_end,
            evidence_object,
        ) {
            (Some(evidence_source), Some(start), Some(end), Some(object))
                if claim_sources
                    .get(&fact_id)
                    .is_some_and(|sources| sources.contains(&evidence_source)) =>
            {
                match storage.get_node(evidence_source) {
                    Ok(source) => match source.content.get(start..end) {
                        Some(evidence_span)
                            if if requires_exact_object {
                                evidence_span.contains(object)
                            } else {
                                normalized_phrase(evidence_span)
                                    .contains(&normalized_phrase(object))
                            } =>
                        {
                            ClaimCoverage::Grounded {
                                evidence_source,
                                evidence_span: evidence_span.to_owned(),
                            }
                        }
                        _ => ClaimCoverage::Invalid,
                    },
                    Err(Error::NodeNotFound(_)) => ClaimCoverage::Invalid,
                    Err(error) => return Err(error),
                }
            }
            _ if !has_grounding_metadata => ClaimCoverage::Legacy,
            _ => ClaimCoverage::Invalid,
        };
        claim_coverage.insert(fact_id, coverage);
    }

    let mut source_cache = HashMap::new();
    let mut covered_claim_cache = HashMap::new();
    for candidate in ranking.iter().chain(baseline) {
        if let std::collections::hash_map::Entry::Vacant(entry) =
            source_cache.entry(candidate.node_id)
        {
            let candidate_sources = canonical_sources(storage, candidate.node_id)?
                .into_iter()
                .collect::<HashSet<_>>();
            let candidate_content = &storage.get_node(candidate.node_id)?.content;
            let covered = claim_sources
                .iter()
                .filter_map(|(fact_id, sources)| {
                    let covers = match claim_coverage.get(fact_id) {
                        Some(ClaimCoverage::Grounded {
                            evidence_source,
                            evidence_span,
                        }) => {
                            candidate_sources.contains(evidence_source)
                                && candidate_content.contains(evidence_span)
                        }
                        Some(ClaimCoverage::Legacy) => sources
                            .iter()
                            .any(|source| candidate_sources.contains(source)),
                        Some(ClaimCoverage::Invalid) | None => false,
                    };
                    covers.then_some(*fact_id)
                })
                .collect::<HashSet<_>>();
            entry.insert(candidate_sources);
            covered_claim_cache.insert(candidate.node_id, covered);
        }
    }
    let covered_claims = |node_id: NodeId| -> HashSet<AtomicFactId> {
        covered_claim_cache
            .get(&node_id)
            .cloned()
            .unwrap_or_default()
    };

    let mut selected: Vec<_> = baseline.iter().take(limit).copied().collect();
    let mut coverage_counts = HashMap::new();
    for candidate in &selected {
        for fact_id in covered_claims(candidate.node_id) {
            *coverage_counts.entry(fact_id).or_insert(0usize) += 1;
        }
    }
    let mut missing: HashSet<_> = claim_sources
        .keys()
        .filter(|fact_id| !coverage_counts.contains_key(fact_id))
        .copied()
        .collect();
    if missing.is_empty() {
        return Ok(baseline.to_vec());
    }
    // The reranker's authoritative head is never removed. At the default
    // twenty-fragment width this freezes the first twelve rows and lets at
    // most four tail rows change, only when all of a victim's canonical raw
    // evidence remains represented.
    let head_limit = if protect_reranked_head {
        selected
            .len()
            .min(limit.saturating_mul(3).div_ceil(5).max(1))
    } else {
        0
    };
    let mut replacements = 0usize;
    const MAX_CLAIM_REPLACEMENTS: usize = 4;
    let grounded_reserve_limit = if is_factual_action_request(plan) {
        MAX_CLAIM_REPLACEMENTS
    } else {
        match (plan.answer_shape, plan.coverage) {
            (AnswerShape::Collection, RecallCoverage::Exhaustive) => MAX_CLAIM_REPLACEMENTS,
            (AnswerShape::Collection, _)
                if plan.derivation == RecallDerivation::GroundedInference =>
            {
                2
            }
            (AnswerShape::Collection, _) => 1,
            (AnswerShape::Inference, _) => 1,
            (AnswerShape::Relationship, _) if !plan_uses_temporal_readout(plan) => 1,
            _ => 0,
        }
    };
    let mut grounded_reserves_used = 0usize;
    const MAX_METHOD_SEMANTIC_RESERVES: usize = 2;
    let mut method_semantic_reserves_used = 0usize;
    let mut method_semantic_sessions = HashSet::new();
    let mut method_semantic_keys = Vec::new();
    for fact_id in method_semantic_claims
        .iter()
        .filter(|fact_id| coverage_counts.contains_key(fact_id))
    {
        if let Some(session) = claim_sessions.get(fact_id) {
            method_semantic_sessions.insert(session.clone());
        }
        if let Some(claim_key) = claim_keys.get(fact_id) {
            method_semantic_keys.push(claim_key.clone());
        }
    }

    while !missing.is_empty() && replacements < MAX_CLAIM_REPLACEMENTS {
        let selected_ids: HashSet<_> = selected.iter().map(|candidate| candidate.node_id).collect();
        let represented_claim_keys: Vec<_> = coverage_counts
            .keys()
            .filter_map(|fact_id| claim_keys.get(fact_id))
            .collect();
        let best_candidate = ranking
            .iter()
            .enumerate()
            .filter(|(_, candidate)| !selected_ids.contains(&candidate.node_id))
            .filter_map(|(rank, candidate)| {
                let claims = covered_claims(candidate.node_id);
                let mut regular_missing_claims = claims
                    .iter()
                    .filter(|fact_id| {
                        missing.contains(fact_id) && !method_semantic_claims.contains(fact_id)
                    })
                    .copied()
                    .collect::<Vec<_>>();
                regular_missing_claims.sort_by_key(|fact_id| {
                    (
                        claim_priority.get(fact_id).copied().unwrap_or(usize::MAX),
                        *fact_id,
                    )
                });
                let semantic_claim = (method_semantic_reserves_used < MAX_METHOD_SEMANTIC_RESERVES)
                    .then(|| {
                        let mut candidates = claims
                            .iter()
                            .filter(|fact_id| {
                                missing.contains(fact_id)
                                    && method_semantic_claims.contains(fact_id)
                            })
                            .copied()
                            .collect::<Vec<_>>();
                        candidates.sort_by_key(|fact_id| {
                            (
                                claim_priority.get(fact_id).copied().unwrap_or(usize::MAX),
                                *fact_id,
                            )
                        });
                        candidates.into_iter().find(|fact_id| {
                            let session_is_distinct = claim_sessions
                                .get(fact_id)
                                .is_some_and(|session| !method_semantic_sessions.contains(session));
                            let claim_is_distinct = claim_keys.get(fact_id).is_some_and(|claim| {
                                represented_claim_keys.iter().all(|represented| {
                                    !atomic_claims_are_near_duplicates(claim, represented)
                                }) && method_semantic_keys.iter().all(|reserved| {
                                    !atomic_claims_are_near_duplicates(claim, reserved)
                                })
                            });
                            session_is_distinct && claim_is_distinct
                        })
                    })
                    .flatten();
                let mut admitted_missing_claims = regular_missing_claims;
                admitted_missing_claims.extend(semantic_claim);
                let gain = admitted_missing_claims.len();
                let grounded_gain = admitted_missing_claims
                    .iter()
                    .filter(|fact_id| {
                        matches!(
                            claim_coverage.get(fact_id),
                            Some(ClaimCoverage::Grounded { .. })
                        )
                    })
                    .count();
                let best_claim_priority = admitted_missing_claims
                    .iter()
                    .filter_map(|fact_id| claim_priority.get(fact_id))
                    .copied()
                    .min()
                    .unwrap_or(usize::MAX);
                (gain > 0).then_some((
                    rank,
                    *candidate,
                    claims,
                    gain,
                    grounded_gain,
                    best_claim_priority,
                    semantic_claim,
                ))
            })
            .max_by(|left, right| {
                if method_request.is_some() {
                    right.0.cmp(&left.0)
                } else {
                    left.4
                        .cmp(&right.4)
                        .then_with(|| left.3.cmp(&right.3))
                        .then_with(|| right.5.cmp(&left.5))
                        .then_with(|| right.0.cmp(&left.0))
                }
            });
        let Some((_, candidate, candidate_claims, _, grounded_gain, _, semantic_claim)) =
            best_candidate
        else {
            break;
        };
        let candidate_has_missing_grounded_claim = grounded_gain > 0;

        if selected.len() < limit {
            selected.push(candidate);
        } else {
            let victim = (head_limit..selected.len()).rev().find_map(|index| {
                let victim_node_id = selected[index].node_id;
                let victim_sources = source_cache
                    .get(&victim_node_id)
                    .cloned()
                    .unwrap_or_default();
                let mut sources_without_victim = source_cache
                    .get(&candidate.node_id)
                    .cloned()
                    .unwrap_or_default();
                for retained in selected
                    .iter()
                    .filter(|retained| retained.node_id != victim_node_id)
                {
                    if let Some(sources) = source_cache.get(&retained.node_id) {
                        sources_without_victim.extend(sources);
                    }
                }
                let preserves_raw_evidence = victim_sources
                    .iter()
                    .all(|source| sources_without_victim.contains(source));
                let victim_claims = covered_claims(victim_node_id);
                let preserves_claim_coverage = victim_claims.iter().all(|fact_id| {
                    coverage_counts.get(fact_id).copied().unwrap_or_default()
                        + usize::from(candidate_claims.contains(fact_id))
                        > 1
                });
                let uses_grounded_complex_reserve = grounded_reserves_used < grounded_reserve_limit
                    && candidate_has_missing_grounded_claim
                    && victim_claims.is_empty();
                ((preserves_raw_evidence || uses_grounded_complex_reserve)
                    && preserves_claim_coverage)
                    .then_some((
                        index,
                        uses_grounded_complex_reserve && !preserves_raw_evidence,
                    ))
            });
            let Some((victim, used_grounded_reserve)) = victim else {
                break;
            };
            selected[victim] = candidate;
            grounded_reserves_used += usize::from(used_grounded_reserve);
        }

        replacements += 1;
        if let Some(fact_id) = semantic_claim {
            method_semantic_reserves_used += 1;
            if let Some(session) = claim_sessions.get(&fact_id) {
                method_semantic_sessions.insert(session.clone());
            }
            if let Some(claim_key) = claim_keys.get(&fact_id) {
                method_semantic_keys.push(claim_key.clone());
            }
        }
        coverage_counts.clear();
        for selected_candidate in &selected {
            for fact_id in covered_claims(selected_candidate.node_id) {
                *coverage_counts.entry(fact_id).or_insert(0usize) += 1;
            }
        }
        missing.retain(|fact_id| !coverage_counts.contains_key(fact_id));
    }

    if replacements == 0 {
        Ok(baseline.to_vec())
    } else {
        Ok(selected)
    }
}

fn temporal_fact_witness_ranking<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    ranking: &[RerankedCandidate],
    baseline: &[RerankedCandidate],
    limit: usize,
    routed_atomic_sources: &[AtomicSourceMarker],
) -> Result<Vec<RerankedCandidate>, Error> {
    if limit == 0
        || !plan_uses_temporal_readout(plan)
        || plan.answer_shape != AnswerShape::Fact
        || temporal_constraint_is_trend(plan)
        || routed_atomic_sources.is_empty()
    {
        return Ok(baseline.to_vec());
    }

    let witness_sources: HashSet<_> = routed_atomic_sources
        .iter()
        .filter(|marker| marker.kind_priority == 0 && marker.fact_id.is_some())
        .map(|marker| marker.source_node_id)
        .collect();
    if witness_sources.is_empty() {
        return Ok(baseline.to_vec());
    }

    let mut selected: Vec<_> = baseline.iter().take(limit).copied().collect();
    let mut selected_source_ids = HashSet::new();
    for candidate in &selected {
        selected_source_ids.extend(canonical_sources(storage, candidate.node_id)?);
    }
    if witness_sources
        .iter()
        .any(|source| selected_source_ids.contains(source))
    {
        return Ok(baseline.to_vec());
    }

    // The input is the externally scored candidate surface. Select the first
    // still-missing witness in that order and never consult an internal score
    // or fact priority to choose the final document.
    let selected_ids: HashSet<_> = selected.iter().map(|candidate| candidate.node_id).collect();
    let mut witness = None;
    for candidate in ranking.iter().take(DEFAULT_RERANK_CANDIDATE_LIMIT) {
        if selected_ids.contains(&candidate.node_id) {
            continue;
        }
        let sources = canonical_sources(storage, candidate.node_id)?;
        if sources
            .iter()
            .any(|source| witness_sources.contains(source))
        {
            witness = Some(*candidate);
            break;
        }
    }
    let Some(witness) = witness else {
        return Ok(baseline.to_vec());
    };

    if selected.len() < limit {
        selected.push(witness);
        return Ok(selected);
    }
    let protected_head = selected
        .len()
        .min(limit.saturating_mul(3).div_ceil(5).max(1));
    let Some(victim) = (protected_head..selected.len()).next_back() else {
        return Ok(baseline.to_vec());
    };
    selected[victim] = witness;
    Ok(selected)
}

fn atomic_chain_group_ranking<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    ranking: &[RerankedCandidate],
    baseline: &[RerankedCandidate],
    limit: usize,
    paths: &[AtomicRelationPath],
) -> Result<Vec<RerankedCandidate>, Error> {
    const MAX_CHAIN_GROUPS: usize = 2;
    const MAX_CHAIN_ADDITIONS: usize = 4;

    if limit == 0
        || paths.is_empty()
        || plan_has_temporal_constraint(plan)
        || is_factual_method_request(plan)
        || !matches!(
            plan.answer_shape,
            AnswerShape::Relationship | AnswerShape::Inference
        )
    {
        return Ok(baseline.to_vec());
    }

    let mut source_cache: HashMap<NodeId, HashSet<NodeId>> = HashMap::new();
    for candidate in ranking.iter().chain(baseline) {
        if let std::collections::hash_map::Entry::Vacant(entry) =
            source_cache.entry(candidate.node_id)
        {
            entry.insert(
                canonical_sources(storage, candidate.node_id)?
                    .into_iter()
                    .collect(),
            );
        }
    }

    let covers = |candidates: &[RerankedCandidate], required: &HashSet<NodeId>| {
        let mut covered = HashSet::new();
        for candidate in candidates {
            if let Some(sources) = source_cache.get(&candidate.node_id) {
                covered.extend(sources.iter().copied());
            }
        }
        required.iter().all(|source| covered.contains(source))
    };

    let mut selected: Vec<_> = baseline.iter().take(limit).copied().collect();
    let head_limit = selected
        .len()
        .min(limit.saturating_mul(3).div_ceil(5).max(1));
    let mut protected_sources = HashSet::new();
    let mut accepted_groups = 0usize;
    let mut additions_used = 0usize;
    let mut changed = false;

    for path in paths {
        if accepted_groups >= MAX_CHAIN_GROUPS || additions_used >= MAX_CHAIN_ADDITIONS {
            break;
        }
        let required: HashSet<_> = path.source_groups.iter().flatten().copied().collect();
        if required.is_empty() {
            continue;
        }
        if covers(&selected, &required) {
            protected_sources.extend(required);
            continue;
        }

        let representable: HashSet<_> = ranking
            .iter()
            .filter_map(|candidate| source_cache.get(&candidate.node_id))
            .flat_map(|sources| sources.iter().copied())
            .collect();
        if !required.iter().all(|source| representable.contains(source)) {
            continue;
        }

        let selected_ids: HashSet<_> = selected.iter().map(|candidate| candidate.node_id).collect();
        let mut additions = Vec::new();
        let mut missing = required
            .iter()
            .filter(|source| {
                !selected.iter().any(|candidate| {
                    source_cache
                        .get(&candidate.node_id)
                        .is_some_and(|sources| sources.contains(source))
                })
            })
            .copied()
            .collect::<HashSet<_>>();
        while !missing.is_empty() && additions_used + additions.len() < MAX_CHAIN_ADDITIONS {
            let addition_ids: HashSet<_> = additions
                .iter()
                .map(|candidate: &RerankedCandidate| candidate.node_id)
                .collect();
            let best = ranking
                .iter()
                .enumerate()
                .filter(|(_, candidate)| {
                    !selected_ids.contains(&candidate.node_id)
                        && !addition_ids.contains(&candidate.node_id)
                })
                .filter_map(|(rank, candidate)| {
                    let gain = source_cache
                        .get(&candidate.node_id)
                        .map(|sources| sources.intersection(&missing).count())
                        .unwrap_or_default();
                    (gain > 0).then_some((gain, rank, *candidate))
                })
                .max_by(|left, right| left.0.cmp(&right.0).then_with(|| right.1.cmp(&left.1)));
            let Some((_, _, addition)) = best else {
                break;
            };
            if let Some(sources) = source_cache.get(&addition.node_id) {
                missing.retain(|source| !sources.contains(source));
            }
            additions.push(addition);
        }
        if !missing.is_empty() || additions.is_empty() {
            continue;
        }

        let spare = limit.saturating_sub(selected.len());
        let replacements_needed = additions.len().saturating_sub(spare);
        let mut required_after_change = protected_sources.clone();
        required_after_change.extend(required.iter().copied());
        let mut victims = Vec::new();
        for index in (head_limit..selected.len()).rev() {
            if victims.len() >= replacements_needed {
                break;
            }
            let mut trial = selected
                .iter()
                .enumerate()
                .filter(|(candidate_index, _)| {
                    *candidate_index != index && !victims.contains(candidate_index)
                })
                .map(|(_, candidate)| *candidate)
                .collect::<Vec<_>>();
            trial.extend(additions.iter().copied());
            if covers(&trial, &required_after_change) {
                victims.push(index);
            }
        }
        if victims.len() != replacements_needed {
            continue;
        }
        victims.sort_unstable();
        let mut next = selected
            .iter()
            .copied()
            .enumerate()
            .filter(|(index, _)| victims.binary_search(index).is_err())
            .map(|(_, candidate)| candidate)
            .collect::<Vec<_>>();
        next.extend(additions.iter().copied());
        if next.len() > limit || !covers(&next, &required_after_change) {
            // No partial chain is admitted when the complete bounded source
            // group cannot survive the final evidence width.
            continue;
        }
        selected = next;
        protected_sources = required_after_change;
        accepted_groups += 1;
        additions_used += additions.len();
        changed = true;
    }

    if changed {
        Ok(selected)
    } else {
        Ok(baseline.to_vec())
    }
}

fn required_source_group_ranking<S: StorageAdapter>(
    storage: &S,
    ranking: &[RerankedCandidate],
    baseline: &[RerankedCandidate],
    limit: usize,
    required: &HashSet<NodeId>,
    protected_groups: &[HashSet<NodeId>],
    max_additions: usize,
) -> Result<Vec<RerankedCandidate>, Error> {
    const IMMUTABLE_FINAL_HEAD: usize = 12;

    if required.is_empty() || limit == 0 || max_additions == 0 {
        return Ok(baseline.to_vec());
    }

    let mut source_cache: HashMap<NodeId, HashSet<NodeId>> = HashMap::new();
    for candidate in ranking.iter().chain(baseline) {
        if let std::collections::hash_map::Entry::Vacant(entry) =
            source_cache.entry(candidate.node_id)
        {
            entry.insert(
                canonical_sources(storage, candidate.node_id)?
                    .into_iter()
                    .collect(),
            );
        }
    }
    let covers = |candidates: &[RerankedCandidate], required: &HashSet<NodeId>| {
        let mut covered = HashSet::new();
        for candidate in candidates {
            if let Some(sources) = source_cache.get(&candidate.node_id) {
                covered.extend(sources.iter().copied());
            }
        }
        required.is_subset(&covered)
    };

    let mut selected: Vec<_> = baseline.iter().take(limit).copied().collect();
    if covers(&selected, required) {
        return Ok(baseline.to_vec());
    }
    let representable: HashSet<_> = ranking
        .iter()
        .filter_map(|candidate| source_cache.get(&candidate.node_id))
        .flat_map(|sources| sources.iter().copied())
        .collect();
    if !required.is_subset(&representable) {
        return Ok(baseline.to_vec());
    }

    let selected_ids: HashSet<_> = selected.iter().map(|candidate| candidate.node_id).collect();
    let mut covered = HashSet::new();
    for candidate in &selected {
        if let Some(sources) = source_cache.get(&candidate.node_id) {
            covered.extend(sources.iter().copied());
        }
    }
    let mut missing: HashSet<_> = required.difference(&covered).copied().collect();
    let mut additions = Vec::new();
    while !missing.is_empty() && additions.len() < max_additions {
        let addition_ids: HashSet<_> = additions
            .iter()
            .map(|candidate: &RerankedCandidate| candidate.node_id)
            .collect();
        let best = ranking
            .iter()
            .enumerate()
            .filter(|(_, candidate)| {
                !selected_ids.contains(&candidate.node_id)
                    && !addition_ids.contains(&candidate.node_id)
            })
            .filter_map(|(rank, candidate)| {
                let gain = source_cache
                    .get(&candidate.node_id)
                    .map(|sources| sources.intersection(&missing).count())
                    .unwrap_or_default();
                (gain > 0).then_some((gain, rank, *candidate))
            })
            .max_by(|left, right| left.0.cmp(&right.0).then_with(|| right.1.cmp(&left.1)));
        let Some((_, _, addition)) = best else {
            break;
        };
        if let Some(sources) = source_cache.get(&addition.node_id) {
            missing.retain(|source| !sources.contains(source));
        }
        additions.push(addition);
    }
    if !missing.is_empty() || additions.is_empty() {
        return Ok(baseline.to_vec());
    }

    let mut protected_sources = HashSet::new();
    for group in protected_groups {
        if !group.is_empty() && covers(&selected, group) {
            protected_sources.extend(group.iter().copied());
        }
    }
    protected_sources.extend(required.iter().copied());
    let spare = limit.saturating_sub(selected.len());
    let replacements_needed = additions.len().saturating_sub(spare);
    let head_limit = selected.len().min(IMMUTABLE_FINAL_HEAD);
    let mut victims = Vec::new();
    for index in (head_limit..selected.len()).rev() {
        if victims.len() >= replacements_needed {
            break;
        }
        let mut trial = selected
            .iter()
            .enumerate()
            .filter(|(candidate_index, _)| {
                *candidate_index != index && !victims.contains(candidate_index)
            })
            .map(|(_, candidate)| *candidate)
            .collect::<Vec<_>>();
        trial.extend(additions.iter().copied());
        if covers(&trial, &protected_sources) {
            victims.push(index);
        }
    }
    if victims.len() != replacements_needed {
        return Ok(baseline.to_vec());
    }
    victims.sort_unstable();
    selected = selected
        .into_iter()
        .enumerate()
        .filter(|(index, _)| victims.binary_search(index).is_err())
        .map(|(_, candidate)| candidate)
        .collect();
    selected.extend(additions);
    if selected.len() > limit || !covers(&selected, &protected_sources) {
        return Ok(baseline.to_vec());
    }
    Ok(selected)
}

fn premise_bundle_group_ranking<S: StorageAdapter>(
    storage: &S,
    ranking: &[RerankedCandidate],
    baseline: &[RerankedCandidate],
    limit: usize,
    bundle: Option<&PremiseBundleTrace>,
    atomic_relation_paths: &[AtomicRelationPath],
) -> Result<Vec<RerankedCandidate>, Error> {
    const MAX_BUNDLE_ADDITIONS: usize = 2;

    let Some(bundle) = bundle.filter(|bundle| premise_bundle_trace_is_well_formed(bundle)) else {
        return Ok(baseline.to_vec());
    };
    let required = bundle
        .members
        .iter()
        .map(|member| member.source_node_id)
        .collect::<HashSet<_>>();
    let protected_groups = atomic_relation_paths
        .iter()
        .map(|path| path.source_groups.iter().flatten().copied().collect())
        .collect::<Vec<HashSet<_>>>();
    required_source_group_ranking(
        storage,
        ranking,
        baseline,
        limit,
        &required,
        &protected_groups,
        MAX_BUNDLE_ADDITIONS,
    )
}

fn event_boundary_source_group_ranking<S: StorageAdapter>(
    storage: &S,
    ranking: &[RerankedCandidate],
    baseline: &[RerankedCandidate],
    limit: usize,
    group: Option<&EventBoundarySourceGroup>,
    atomic_relation_paths: &[AtomicRelationPath],
    premise_bundle: Option<&PremiseBundleTrace>,
) -> Result<Vec<RerankedCandidate>, Error> {
    const MAX_EVENT_BOUNDARY_GROUP_ADDITIONS: usize = 2;

    let Some(group) = group.filter(|group| event_boundary_source_group_is_well_formed(group))
    else {
        return Ok(baseline.to_vec());
    };
    let mut retained_anchor = None;
    for candidate in baseline.iter().take(limit) {
        let sources = canonical_sources(storage, candidate.node_id)?
            .into_iter()
            .collect::<HashSet<_>>();
        if let Some(member) = group
            .anchors
            .iter()
            .find(|member| sources.contains(&member.source_node_id))
        {
            retained_anchor = Some(member.source_node_id);
            break;
        }
    }
    let Some(retained_anchor) = retained_anchor else {
        // A target-side reserve is authorized only when the reranker retained
        // grounded evidence for the boundary itself. Otherwise the complete
        // group fails closed rather than manufacturing a temporal premise.
        return Ok(baseline.to_vec());
    };
    let mut selected_targets = Vec::new();
    for candidate in ranking {
        let sources = canonical_sources(storage, candidate.node_id)?
            .into_iter()
            .collect::<HashSet<_>>();
        for member in &group.targets {
            if sources.contains(&member.source_node_id)
                && !selected_targets.contains(&member.source_node_id)
            {
                selected_targets.push(member.source_node_id);
                if selected_targets.len() == MAX_EVENT_BOUNDARY_GROUP_ADDITIONS {
                    break;
                }
            }
        }
        if selected_targets.len() == MAX_EVENT_BOUNDARY_GROUP_ADDITIONS {
            break;
        }
    }
    if selected_targets.is_empty() {
        return Ok(baseline.to_vec());
    }
    let mut required = selected_targets.into_iter().collect::<HashSet<_>>();
    required.insert(retained_anchor);
    let mut protected_groups = atomic_relation_paths
        .iter()
        .map(|path| path.source_groups.iter().flatten().copied().collect())
        .collect::<Vec<HashSet<_>>>();
    if let Some(bundle) =
        premise_bundle.filter(|bundle| premise_bundle_trace_is_well_formed(bundle))
    {
        protected_groups.push(
            bundle
                .members
                .iter()
                .map(|member| member.source_node_id)
                .collect(),
        );
    }
    required_source_group_ranking(
        storage,
        ranking,
        baseline,
        limit,
        &required,
        &protected_groups,
        MAX_EVENT_BOUNDARY_GROUP_ADDITIONS,
    )
}

pub(super) fn compile_atomic_chain_source_ranking_with_required_source_groups<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    ranking: &[RerankedCandidate],
    limit: usize,
    paths: &[AtomicRelationPath],
    premise_bundle: Option<&PremiseBundleTrace>,
    event_boundary_group: Option<&EventBoundarySourceGroup>,
) -> Result<Vec<RerankedCandidate>, Error> {
    let chain_ranking = atomic_chain_group_ranking(storage, plan, ranking, ranking, limit, paths)?;
    let premise_ranking = premise_bundle_group_ranking(
        storage,
        ranking,
        &chain_ranking,
        limit,
        premise_bundle,
        paths,
    )?;
    event_boundary_source_group_ranking(
        storage,
        ranking,
        &premise_ranking,
        limit,
        event_boundary_group,
        paths,
        premise_bundle,
    )
}

/// Reapply strict factual-action claim coverage after a bound document has
/// been hydrated back into its individual raw sources.
///
/// Document-level selection may cover an exact action span through one member
/// of a multi-source document. Hydration expands that document, so the final
/// fragment cap must protect the exact byte-grounded marker source again. All
/// non-action projections preserve the existing source order byte-for-byte.
pub(super) fn compile_strict_factual_action_source_ranking_at<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    ranking: &[RerankedCandidate],
    limit: usize,
    routed_atomic_markers: &[AtomicSourceMarker],
    as_of: crate::graph::Timestamp,
    query_scope: &ScopePath,
) -> Result<Vec<RerankedCandidate>, Error> {
    if strict_factual_action_request(plan).is_none() || limit == 0 {
        return Ok(ranking.to_vec());
    }
    let validated = validated_final_selection_atomic_source_markers(
        storage,
        plan,
        routed_atomic_markers,
        as_of,
        query_scope,
    )?;
    let mut selected = claim_slot_coverage_ranking_with_head_protection(
        storage, plan, ranking, ranking, limit, &validated, false,
    )?;
    selected.truncate(limit);
    Ok(selected)
}

fn distinct_source_ranking<S: StorageAdapter>(
    storage: &S,
    ranking: &[RerankedCandidate],
) -> Result<Vec<RerankedCandidate>, Error> {
    let mut seen = HashSet::new();
    let mut selected = Vec::with_capacity(ranking.len());
    for candidate in ranking {
        let sources = canonical_sources(storage, candidate.node_id)?;
        if seen.insert(sources) {
            selected.push(*candidate);
        }
    }
    Ok(selected)
}

fn source_coverage_ranking<S: StorageAdapter>(
    storage: &S,
    ranking: &[RerankedCandidate],
) -> Result<Vec<RerankedCandidate>, Error> {
    let mut covered = HashSet::new();
    let mut selected = Vec::with_capacity(ranking.len());
    for candidate in ranking {
        let sources = canonical_sources(storage, candidate.node_id)?;
        if sources.iter().any(|source| !covered.contains(source)) {
            covered.extend(sources);
            selected.push(*candidate);
        }
    }
    Ok(selected)
}

fn temporal_successor<S: StorageAdapter>(
    storage: &S,
    source: NodeId,
) -> Result<Option<NodeId>, Error> {
    let predecessor = storage.get_node(source)?;
    let mut successors = Vec::new();
    for edge_id in storage.edges_from(source) {
        let edge = storage.get_edge(*edge_id)?;
        if edge.edge_type != EdgeType::Temporal {
            continue;
        }
        let successor = storage.get_node(edge.target)?;
        if successor.node_type == KnowledgeType::Episodic
            && successor.origin.session_id == predecessor.origin.session_id
            && successor.origin.scope == predecessor.origin.scope
            && successor.created_at >= predecessor.created_at
            && successor
                .valid_from
                .is_none_or(|valid_from| valid_from <= successor.created_at)
            && successor.valid_until.is_none()
            && !successor
                .metadata
                .get("retracted")
                .is_some_and(|value| value == "true")
        {
            successors.push((successor.created_at, successor.id));
        }
    }
    successors.sort_unstable();
    Ok(successors.into_iter().next().map(|(_, node_id)| node_id))
}

fn temporal_predecessor<S: StorageAdapter>(
    storage: &S,
    source: NodeId,
) -> Result<Option<NodeId>, Error> {
    let answer = storage.get_node(source)?;
    let mut predecessors = Vec::new();
    for edge_id in storage.edges_to(source) {
        let edge = storage.get_edge(*edge_id)?;
        if edge.edge_type != EdgeType::Temporal {
            continue;
        }
        let predecessor = storage.get_node(edge.source)?;
        if predecessor.node_type == KnowledgeType::Episodic
            && predecessor.origin.session_id == answer.origin.session_id
            && predecessor.origin.scope == answer.origin.scope
            && predecessor.created_at <= answer.created_at
            && predecessor
                .valid_from
                .is_none_or(|valid_from| valid_from <= answer.created_at)
            && predecessor.valid_until.is_none()
            && !predecessor
                .metadata
                .get("retracted")
                .is_some_and(|value| value == "true")
        {
            predecessors.push((predecessor.created_at, predecessor.id));
        }
    }
    predecessors.sort_unstable();
    Ok(predecessors.pop().map(|(_, node_id)| node_id))
}

const MAX_SAME_SESSION_REPLY_ROUTES: usize = 2;

fn reply_body_explicitly_targets_question_speaker(
    question_speaker: &str,
    answer_speaker: &str,
    answer_content: &str,
) -> bool {
    let normalized_question_speaker = normalized_phrase(question_speaker);
    let normalized_answer_speaker = normalized_phrase(answer_speaker);
    let normalized_answer = normalized_phrase(answer_content);
    if normalized_question_speaker.is_empty() || normalized_answer.is_empty() {
        return false;
    }

    // Canonical conversation content commonly retains a leading `Speaker:`
    // label in addition to its trusted speaker tag. Ignore only the exact
    // tagged speaker at the beginning; a name elsewhere remains answer text.
    let mut body = if normalized_answer == normalized_answer_speaker {
        ""
    } else {
        normalized_answer
            .strip_prefix(&normalized_answer_speaker)
            .and_then(|suffix| suffix.strip_prefix(' '))
            .unwrap_or(&normalized_answer)
    };

    // One bounded discourse marker may precede the grammatical owner. This
    // admits `Yes, Alice ...` and `Well, you ...`, but `No, I ... Alice ...`
    // still fails closed instead of borrowing a mere later name mention.
    if let Some((first, rest)) = body.split_once(' ')
        && matches!(
            first,
            "yes" | "no" | "well" | "indeed" | "certainly" | "absolutely"
        )
    {
        body = rest;
    }

    body == normalized_question_speaker
        || body
            .strip_prefix(&normalized_question_speaker)
            .is_some_and(|suffix| suffix.starts_with(' '))
        || body.split_whitespace().next().is_some_and(|word| {
            matches!(word, "you" | "your" | "yours" | "yourself" | "yourselves")
        })
}

/// Keep immediate-reply recovery on the owner named by the query.
///
/// A retrieved question can be lexically close to the query even when it is a
/// named subject asking a different speaker about that speaker's own state.
/// Following that edge would turn the other speaker's reply into evidence for
/// the named subject. When the query explicitly names the question speaker, an
/// answer by somebody else is retained only if the query names that answerer
/// or the answer body begins by explicitly assigning the reply to the named
/// question speaker (`Alice ...` or `you ...`). Untagged legacy turns and
/// questions whose speaker is not the named subject retain the established
/// recovery behavior.
fn same_session_reply_preserves_named_speaker_ownership(
    plan: &RecallPlan,
    question: &crate::graph::Node,
    answer: &crate::graph::Node,
) -> bool {
    let (question_speaker, _) = parse_entity_tags(&question.entity_tags);
    let Some(question_speaker) = question_speaker else {
        return true;
    };
    let normalized_query = normalized_phrase(&plan.query);
    let normalized_question_speaker = normalized_phrase(&question_speaker);
    if normalized_question_speaker.is_empty()
        || !normalized_contains_phrase(&normalized_query, &normalized_question_speaker)
    {
        return true;
    }

    let (answer_speaker, _) = parse_entity_tags(&answer.entity_tags);
    answer_speaker.is_some_and(|speaker| {
        let normalized_answer_speaker = normalized_phrase(&speaker);
        !normalized_answer_speaker.is_empty()
            && (normalized_contains_phrase(&normalized_query, &normalized_answer_speaker)
                || reply_body_explicitly_targets_question_speaker(
                    &question_speaker,
                    &speaker,
                    &answer.content,
                ))
    })
}

/// Recover an immediate answer when cognitive search retrieved its question.
///
/// Dialogue embeddings often make a query-like source turn rank above the
/// short reply that actually supplies its value. For complex, non-temporal
/// recall, this lane follows only one explicit Temporal edge to a live raw turn
/// in the same session and scope. The question/answer pair must overlap the
/// current query, already represented answers are skipped, and the globally
/// bounded result still enters the ordinary reranker rather than bypassing it.
pub(super) fn route_same_session_reply_sources<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    ranking: &[crate::query::ReadoutCandidate],
    query_embeddings: &[&[f64]],
    now: crate::graph::Timestamp,
    scope: &ScopePath,
    strict_action_source_ids: &HashSet<NodeId>,
) -> Result<Vec<crate::query::ReadoutCandidate>, Error> {
    if temporal_constraint_blocks_expansion(plan)
        || !uses_complex_expansion(plan)
        || ranking.is_empty()
    {
        return Ok(Vec::new());
    }
    let query_facets = facet_terms(&plan.query);
    if query_facets.is_empty() {
        return Ok(Vec::new());
    }
    let required_overlap = query_facets.len().min(2);
    let strict_action_request = strict_factual_action_request(plan);

    let mut represented_sources = HashSet::new();
    for candidate in ranking {
        represented_sources.extend(canonical_sources(storage, candidate.node_id)?);
    }

    let mut inspected_questions = HashSet::new();
    let mut routed = Vec::new();
    for (ranking_index, candidate) in ranking.iter().enumerate() {
        for question_source in canonical_sources(storage, candidate.node_id)? {
            if !inspected_questions.insert(question_source) {
                continue;
            }
            let question = storage.get_node(question_source)?;
            if question.node_type != KnowledgeType::Episodic
                || !question.content.trim_end().ends_with('?')
            {
                continue;
            }
            let Some(answer_source) = temporal_successor(storage, question_source)? else {
                continue;
            };
            if represented_sources.contains(&answer_source) {
                continue;
            }
            let answer = storage.get_node(answer_source)?;
            let exact_action_speaker_matches =
                strict_action_request.as_ref().is_none_or(|request| {
                    request.exact_subject.as_ref().is_some_and(|subject| {
                        parse_entity_tags(&answer.entity_tags)
                            .0
                            .is_some_and(|speaker| exact_action_subject_matches(&speaker, subject))
                    })
                });
            if (strict_action_request.is_some()
                && !strict_action_source_ids.contains(&answer_source))
                || !exact_action_speaker_matches
                || !same_session_reply_preserves_named_speaker_ownership(plan, question, answer)
                || answer.content.trim().is_empty()
                || answer.created_at > now
                || answer
                    .metadata
                    .get("retracted")
                    .is_some_and(|value| value == "true")
                || !validity_window_matches_plan(plan, answer.valid_from, answer.valid_until, now)
                || !atomic_scope_is_visible(scope, &answer.origin.scope)
            {
                continue;
            }
            let pair_facets = facet_terms(&format!("{} {}", question.content, answer.content));
            let query_facet_overlap = query_facets.intersection(&pair_facets).count();
            if query_facet_overlap < required_overlap {
                continue;
            }
            let embedding_cosine = answer.embedding.as_ref().map_or(0.0, |embedding| {
                max_query_cosine(query_embeddings, embedding)
            });
            let activation = candidate.activation.max(f64::EPSILON);
            routed.push((
                query_facet_overlap,
                ranking_index,
                crate::query::ReadoutCandidate {
                    node_id: answer_source,
                    score: candidate.score,
                    activation,
                    phi: embedding_cosine,
                    embedding_cosine,
                    salience: storage.get_salience(answer_source)?,
                    impedance: (-activation.ln()).max(0.0),
                    scope_weight: crate::query::scoring::scope_weight(scope, &answer.origin.scope),
                    trust_weight: 1.0,
                    stress: 0.0,
                },
            ));
        }
    }
    routed.sort_by(|left, right| {
        right
            .0
            .cmp(&left.0)
            .then_with(|| left.1.cmp(&right.1))
            .then_with(|| left.2.node_id.cmp(&right.2.node_id))
    });
    let mut admitted = HashSet::new();
    Ok(routed
        .into_iter()
        .filter_map(|(_, _, candidate)| admitted.insert(candidate.node_id).then_some(candidate))
        .take(MAX_SAME_SESSION_REPLY_ROUTES)
        .collect())
}

fn source_session_coverage_ranking<S: StorageAdapter>(
    storage: &S,
    ranking: &[RerankedCandidate],
    limit: usize,
) -> Result<Vec<RerankedCandidate>, Error> {
    // Preserve room for at least one other source session at small final
    // widths, while allowing a larger evidence chain from one session when the
    // caller has explicitly budgeted a broader context.
    let max_primary_per_session = limit.saturating_mul(4).div_ceil(5).clamp(2, 10);

    let mut covered_sources = HashSet::new();
    let mut session_counts = HashMap::new();
    let mut primary = Vec::with_capacity(ranking.len());
    let mut deferred = Vec::new();

    for candidate in ranking {
        let sources = canonical_sources(storage, candidate.node_id)?;
        let new_sources: Vec<_> = sources
            .into_iter()
            .filter(|source| !covered_sources.contains(source))
            .collect();
        if new_sources.is_empty() {
            continue;
        }
        covered_sources.extend(new_sources.iter().copied());

        let mut sessions = Vec::new();
        for source_id in &new_sources {
            let session_id = storage.get_node(*source_id)?.origin.session_id.clone();
            if !sessions.contains(&session_id) {
                sessions.push(session_id);
            }
        }
        if sessions.iter().any(|session| {
            session_counts.get(session).copied().unwrap_or_default() < max_primary_per_session
        }) {
            for session in sessions {
                *session_counts.entry(session).or_insert(0usize) += 1;
            }
            primary.push(*candidate);
        } else {
            deferred.push(*candidate);
        }
    }

    if primary.len() < limit {
        primary.extend(deferred.into_iter().take(limit - primary.len()));
    }
    primary.truncate(limit);
    Ok(primary)
}

pub(super) fn canonical_sources<S: StorageAdapter>(
    storage: &S,
    node_id: NodeId,
) -> Result<Vec<NodeId>, Error> {
    let node = storage.get_node(node_id)?;
    if node.node_type == KnowledgeType::Episodic {
        return Ok(vec![node_id]);
    }

    let mut sources = extracted_episodic_sources(storage, node_id)?;
    if sources.len() == 1
        && node.node_type == KnowledgeType::Semantic
        && !node
            .entity_tags
            .iter()
            .any(|tag| tag == "anamnesis:derived")
    {
        extend_window_sources(storage, node.content.as_str(), sources[0], &mut sources)?;
    }
    if sources.is_empty() {
        sources.push(node_id);
    }
    sources.sort_unstable();
    sources.dedup();
    Ok(sources)
}

pub(crate) fn compile_evidence_documents<S: StorageAdapter>(
    storage: &S,
    ranking: &[crate::query::ReadoutCandidate],
    limit: usize,
) -> Result<Vec<EvidenceDocument>, Error> {
    let candidate_surface: HashSet<_> = ranking
        .iter()
        .take(limit)
        .map(|candidate| candidate.node_id)
        .collect();
    let mut covered_sources = HashSet::new();
    let mut documents = Vec::new();
    let mut document_by_node = HashMap::new();

    for candidate in ranking.iter().take(limit) {
        let candidate_sources = canonical_sources(storage, candidate.node_id)?;
        let new_sources: Vec<_> = candidate_sources
            .into_iter()
            .filter(|source| covered_sources.insert(*source))
            .collect();
        if new_sources.is_empty() {
            continue;
        }

        let mut fallback_sources = Vec::new();
        for source_id in new_sources {
            if candidate_surface.contains(&source_id) {
                let text = render_source(storage, source_id)?;
                let index = documents.len();
                documents.push(EvidenceDocument::from_raw(source_id, vec![source_id], text));
                document_by_node.insert(source_id, index);
            } else {
                fallback_sources.push(source_id);
            }
        }
        if fallback_sources.is_empty() {
            continue;
        }
        let fallback_text = fallback_sources
            .iter()
            .map(|source_id| render_source(storage, *source_id))
            .collect::<Result<Vec<_>, _>>()?
            .join("\n");
        if let Some(index) = document_by_node.get(&candidate.node_id).copied() {
            let document = &mut documents[index];
            document.source_node_ids.extend(fallback_sources);
            if !fallback_text.is_empty() {
                if !document.text.is_empty() {
                    document.text.push('\n');
                }
                document.text.push_str(&fallback_text);
                document.rerank_text = document.text.clone();
            }
        } else {
            let text = if fallback_text.trim().is_empty() {
                storage.get_node(candidate.node_id)?.content.clone()
            } else {
                fallback_text
            };
            let index = documents.len();
            documents.push(EvidenceDocument::from_raw(
                candidate.node_id,
                fallback_sources,
                text,
            ));
            document_by_node.insert(candidate.node_id, index);
        }
    }

    Ok(documents)
}

const MAX_NATIVE_SEMANTIC_RERANK_CHARS: usize = 4_096;

/// Resolve the complete canonical dialogue window stored in one Semantic node
/// back to the exact raw turns that formed it.
///
/// Canonical `Memory` windows are one of `current`, `previous\ncurrent`,
/// `current\nnext`, or `previous\ncurrent\nnext`. We deliberately inspect the
/// temporal neighbors without applying scope or liveness filters here: those
/// nodes are authority dependencies even when they are now retracted, stale,
/// or outside the query scope, and prepared reranking must reject the native
/// window rather than silently forgetting the contributor.
fn native_semantic_window_sources<S: StorageAdapter>(
    storage: &S,
    semantic_id: NodeId,
) -> Result<Option<Vec<NodeId>>, Error> {
    let semantic = storage.get_node(semantic_id)?;
    if semantic.node_type != KnowledgeType::Semantic || semantic.content.trim().is_empty() {
        return Ok(None);
    }

    let extracted = extracted_episodic_sources(storage, semantic_id)?;
    if extracted.len() != 1 {
        return Ok(None);
    }
    let center_id = extracted[0];
    let center = storage.get_node(center_id)?;
    if center.node_type != KnowledgeType::Episodic
        || center.origin.session_id != semantic.origin.session_id
    {
        return Ok(None);
    }

    let mut predecessors = Vec::new();
    for edge_id in storage.edges_to(center_id) {
        let edge = storage.get_edge(*edge_id)?;
        if edge.edge_type != EdgeType::Temporal {
            continue;
        }
        let candidate = storage.get_node(edge.source)?;
        if candidate.node_type == KnowledgeType::Episodic
            && candidate.origin.session_id == center.origin.session_id
            && candidate.created_at <= center.created_at
        {
            predecessors.push(candidate.id);
        }
    }
    predecessors.sort_unstable();
    predecessors.dedup();

    let mut successors = Vec::new();
    for edge_id in storage.edges_from(center_id) {
        let edge = storage.get_edge(*edge_id)?;
        if edge.edge_type != EdgeType::Temporal {
            continue;
        }
        let candidate = storage.get_node(edge.target)?;
        if candidate.node_type == KnowledgeType::Episodic
            && candidate.origin.session_id == center.origin.session_id
            && candidate.created_at >= center.created_at
        {
            successors.push(candidate.id);
        }
    }
    successors.sort_unstable();
    successors.dedup();

    let window = semantic.content.as_str();
    let center_text = center.content.as_str();
    if window == center_text {
        return Ok(Some(vec![center_id]));
    }

    for predecessor_id in &predecessors {
        let predecessor = storage.get_node(*predecessor_id)?;
        let prefix = format!("{}\n{center_text}", predecessor.content);
        if window == prefix {
            let mut sources = vec![*predecessor_id, center_id];
            for duplicate_id in &predecessors {
                if storage.get_node(*duplicate_id)?.content == predecessor.content {
                    sources.push(*duplicate_id);
                }
            }
            sources.sort_unstable();
            sources.dedup();
            return Ok(Some(sources));
        }
        let Some(successor_text) = window
            .strip_prefix(prefix.as_str())
            .and_then(|suffix| suffix.strip_prefix('\n'))
        else {
            continue;
        };
        let mut matching_successors = Vec::new();
        for successor_id in &successors {
            if storage.get_node(*successor_id)?.content == successor_text {
                matching_successors.push(*successor_id);
            }
        }
        if !matching_successors.is_empty() {
            let mut sources = vec![center_id];
            for duplicate_id in &predecessors {
                if storage.get_node(*duplicate_id)?.content == predecessor.content {
                    sources.push(*duplicate_id);
                }
            }
            sources.extend(matching_successors);
            sources.sort_unstable();
            sources.dedup();
            return Ok(Some(sources));
        }
    }

    let Some(successor_text) = window
        .strip_prefix(center_text)
        .and_then(|suffix| suffix.strip_prefix('\n'))
    else {
        return Ok(None);
    };
    let mut sources = vec![center_id];
    for successor_id in successors {
        if storage.get_node(successor_id)?.content == successor_text {
            sources.push(successor_id);
        }
    }
    if sources.len() == 1 {
        return Ok(None);
    }
    sources.sort_unstable();
    sources.dedup();
    Ok(Some(sources))
}

fn apply_native_semantic_rerank_surface<S: StorageAdapter>(
    storage: &S,
    semantic_id: NodeId,
    document: &mut EvidenceDocument,
) -> Result<(), Error> {
    let node = storage.get_node(semantic_id)?;
    if node.node_type != KnowledgeType::Semantic {
        return Ok(());
    }

    document.rerank_text = document.text.clone();
    document.scoring_source_node_ids = document.source_node_ids.clone();
    document.representative_text_is_bound = false;
    let Some(scoring_sources) = native_semantic_window_sources(storage, semantic_id)? else {
        return Ok(());
    };

    let mut chars = node.content.chars();
    let mut native_surface: String = chars
        .by_ref()
        .take(MAX_NATIVE_SEMANTIC_RERANK_CHARS.saturating_sub(1))
        .collect();
    if chars.next().is_some() {
        native_surface.push('…');
    }
    document.rerank_text = native_surface;
    for scoring_source in scoring_sources {
        document.add_scoring_source(scoring_source);
    }
    document.representative_text_is_bound = true;
    Ok(())
}

/// Group overlapping candidates by their canonical source set.
///
/// Every returned document remains authoritative raw evidence. Collection and
/// inference plans use a source-bound native Semantic window as a bounded
/// reranker surface for ownership, purpose, and coreference. Exhaustive
/// coverage is handled by the preceding coverage-aware ranking stage; this
/// compiler still groups overlapping representations of the same raw sources.
fn compile_semantic_group_documents<S: StorageAdapter>(
    storage: &S,
    ranking: &[crate::query::ReadoutCandidate],
    limit: usize,
) -> Result<Vec<EvidenceDocument>, Error> {
    let candidates = &ranking[..ranking.len().min(limit)];
    let candidate_surface: HashSet<_> = candidates
        .iter()
        .map(|candidate| candidate.node_id)
        .collect();
    let mut semantically_represented_sources = HashSet::new();
    for candidate in candidates {
        let node = storage.get_node(candidate.node_id)?;
        if node.node_type == KnowledgeType::Semantic {
            semantically_represented_sources.extend(canonical_sources(storage, candidate.node_id)?);
        }
    }

    let mut seen_source_sets = HashSet::new();
    let mut represented_nodes = HashSet::new();
    let mut documents = Vec::new();
    for candidate in candidates {
        let node = storage.get_node(candidate.node_id)?;
        if node.node_type == KnowledgeType::Episodic
            && semantically_represented_sources.contains(&candidate.node_id)
        {
            continue;
        }

        let mut representative = candidate.node_id;
        let mut source_node_ids = canonical_sources(storage, candidate.node_id)?;
        if node.node_type == KnowledgeType::Semantic
            && let Some(last_source) = source_node_ids.last().copied()
            && storage
                .get_node(last_source)?
                .content
                .trim_end()
                .ends_with('?')
            && let Some(next_source) = temporal_successor(storage, last_source)?
            && candidate_surface.contains(&next_source)
        {
            representative = next_source;
            source_node_ids.push(next_source);
            source_node_ids.sort_unstable();
            source_node_ids.dedup();
        }
        if !seen_source_sets.insert(source_node_ids.clone()) {
            continue;
        }
        if !represented_nodes.insert(representative) {
            continue;
        }

        let text = source_node_ids
            .iter()
            .map(|source_id| render_source(storage, *source_id))
            .collect::<Result<Vec<_>, _>>()?
            .join("\n");
        let mut document = EvidenceDocument::from_raw(representative, source_node_ids, text);
        apply_native_semantic_rerank_surface(storage, candidate.node_id, &mut document)?;
        documents.push(document);
    }
    Ok(documents)
}

const MAX_SAME_SESSION_REPLY_BRIDGES: usize = 2;
const MAX_REPLY_QUESTION_CHARS: usize = 512;

#[derive(Debug, Clone, Copy)]
struct SameSessionReplyBridge {
    answer_document_index: usize,
    question_source: NodeId,
    query_facet_overlap: usize,
}

/// Add bounded dialogue context to the reranker surface without changing the
/// authoritative evidence documents.
///
/// A raw answer can score poorly after a Semantic dialogue window is split
/// into canonical source documents because the question that gives the answer
/// its meaning lives in the preceding turn. Reattach that question only for
/// scoring when the answer is already a native candidate, the predecessor is
/// a live same-scope turn connected by an immediate same-session temporal edge,
/// and the pair matches the query. The document count, representative ids, raw
/// source ids, and emitted text remain byte-for-byte unchanged.
fn apply_bounded_same_session_reply_context<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    documents: &mut [EvidenceDocument],
) -> Result<(), Error> {
    if plan_has_temporal_constraint(plan)
        || !matches!(
            plan.answer_shape,
            AnswerShape::Relationship | AnswerShape::Inference
        )
        || documents.len() < 2
    {
        return Ok(());
    }
    let query_facets = facet_terms(&plan.query);
    if query_facets.is_empty() {
        return Ok(());
    }
    let required_overlap = query_facets.len().min(2);

    let mut source_documents = HashMap::new();
    for (document_index, document) in documents.iter().enumerate() {
        for source_id in &document.source_node_ids {
            source_documents.entry(*source_id).or_insert(document_index);
        }
    }
    let mut native_answers: Vec<_> = source_documents.keys().copied().collect();
    native_answers.sort_unstable();

    let mut bridge_by_answer = HashMap::new();
    for answer_source in native_answers {
        let Some(question_source) = temporal_predecessor(storage, answer_source)? else {
            continue;
        };
        let question = storage.get_node(question_source)?;
        if question.node_type != KnowledgeType::Episodic
            || !question.content.trim_end().ends_with('?')
        {
            continue;
        }
        let Some(&answer_document_index) = source_documents.get(&answer_source) else {
            continue;
        };
        if documents[answer_document_index]
            .source_node_ids
            .contains(&question_source)
        {
            continue;
        }

        let answer = storage.get_node(answer_source)?;
        if !same_session_reply_preserves_named_speaker_ownership(plan, question, answer) {
            continue;
        }
        let pair_facets = facet_terms(&format!("{} {}", question.content, answer.content));
        let query_facet_overlap = query_facets.intersection(&pair_facets).count();
        if query_facet_overlap < required_overlap {
            continue;
        }
        let candidate = SameSessionReplyBridge {
            answer_document_index,
            question_source,
            query_facet_overlap,
        };
        bridge_by_answer
            .entry(answer_document_index)
            .and_modify(|current: &mut SameSessionReplyBridge| {
                if candidate.query_facet_overlap > current.query_facet_overlap
                    || (candidate.query_facet_overlap == current.query_facet_overlap
                        && candidate.question_source < current.question_source)
                {
                    *current = candidate;
                }
            })
            .or_insert(candidate);
    }

    let mut bridges: Vec<_> = bridge_by_answer.into_values().collect();
    bridges.sort_by(|left, right| {
        right
            .query_facet_overlap
            .cmp(&left.query_facet_overlap)
            .then_with(|| left.answer_document_index.cmp(&right.answer_document_index))
            .then_with(|| left.question_source.cmp(&right.question_source))
    });
    bridges.truncate(MAX_SAME_SESSION_REPLY_BRIDGES);

    for bridge in bridges {
        let question = render_source(storage, bridge.question_source)?;
        let mut chars = question.chars();
        let bounded_question: String = chars.by_ref().take(MAX_REPLY_QUESTION_CHARS).collect();
        let bounded_question = if chars.next().is_some() {
            format!("{bounded_question}…")
        } else {
            bounded_question
        };
        let document = &mut documents[bridge.answer_document_index];
        let answer_surface = std::mem::take(&mut document.rerank_text);
        document.rerank_text = format!(
            "Immediate same-session question:\n{bounded_question}\nResponse evidence:\n{answer_surface}"
        );
        document.add_scoring_source(bridge.question_source);
    }

    Ok(())
}

#[derive(Debug)]
struct PreselectionCandidate {
    ranking_index: usize,
    node_type: KnowledgeType,
    source_node_ids: Vec<NodeId>,
    source_sessions: Vec<String>,
    query_facets: HashSet<String>,
    atomic_fact_ids: HashSet<AtomicFactId>,
    embedding_cosine: f64,
    atomic_bridge: Option<TemporalBridgeSignal>,
}

const MAX_TRACE_ATOMIC_FACT_REQUIREMENTS: usize = 16;
const MAX_TRACE_ATOMIC_PRESELECTION_REPLACEMENTS: usize = 2;
const MAX_TRACE_ATOMIC_PRESELECTION_PER_SESSION: usize = 1;
const MAX_METHOD_TRACE_ATOMIC_PRESELECTION_REPLACEMENTS: usize = 4;
const MAX_METHOD_TRACE_ATOMIC_PRESELECTION_PER_SESSION: usize = 2;
fn trace_atomic_preselection_budget(plan: &RecallPlan) -> (usize, usize) {
    if is_factual_action_request(plan) {
        (
            MAX_METHOD_TRACE_ATOMIC_PRESELECTION_REPLACEMENTS,
            MAX_METHOD_TRACE_ATOMIC_PRESELECTION_PER_SESSION,
        )
    } else {
        (
            MAX_TRACE_ATOMIC_PRESELECTION_REPLACEMENTS,
            MAX_TRACE_ATOMIC_PRESELECTION_PER_SESSION,
        )
    }
}

#[derive(Debug)]
struct PreselectionAtomicFactRequirement {
    evidence_source: NodeId,
    evidence_span: String,
}

#[derive(Debug, Default)]
struct PreselectionSlotCoverage {
    atomic_fact_ids: HashSet<AtomicFactId>,
}

#[derive(Debug, Default)]
struct TraceAtomicPreselection {
    required_fact_ids: HashSet<AtomicFactId>,
    requirements: HashMap<AtomicFactId, PreselectionAtomicFactRequirement>,
    priority: HashMap<AtomicFactId, usize>,
}

fn trace_atomic_fact_relevance(
    plan: &RecallPlan,
    method_request: Option<&FactualActionRequest>,
    result_value_witness_sources: Option<&HashSet<NodeId>>,
    fact: &AtomicFact,
) -> Option<(usize, usize)> {
    if atomic_subject_matches(&plan.query, &fact.metadata) == 0 {
        return None;
    }
    if method_request.is_some_and(|request| {
        !authoritative_factual_action_fact_is_eligible(
            plan,
            request,
            fact,
            result_value_witness_sources,
        )
    }) {
        return None;
    }
    let subject_terms =
        atomic_routing_subject(&fact.metadata).map_or_else(HashSet::new, facet_terms);
    let mut query_terms = facet_terms(&plan.query);
    query_terms.retain(|term| !subject_terms.contains(term));
    let normalized_query = normalized_phrase(&plan.query);
    for tag in &fact.entity_tags {
        let tag = tag.trim();
        let likely_named_entity = tag
            .split_whitespace()
            .all(|part| part.chars().next().is_some_and(char::is_uppercase));
        if likely_named_entity {
            let normalized_tag = normalized_phrase(tag);
            if normalized_tag.len() > 2
                && normalized_contains_phrase(&normalized_query, &normalized_tag)
            {
                for entity_term in facet_terms(tag) {
                    query_terms.remove(&entity_term);
                }
            }
        }
    }

    let mut fact_terms = facet_terms(&fact.content);
    if let Some(relation) = atomic_routing_relation(&fact.metadata) {
        fact_terms.extend(facet_terms(relation));
    }
    if let Some(object) = atomic_routing_object(&fact.metadata) {
        fact_terms.extend(facet_terms(object));
    }
    if let Some(evidence_object) = fact.metadata.get("anamnesis:evidence-object") {
        fact_terms.extend(facet_terms(evidence_object));
    }
    fact_terms.retain(|term| !subject_terms.contains(term));
    let facet_overlap = method_request.map_or_else(
        || query_terms.intersection(&fact_terms).count(),
        |request| method_action_target_overlap(request, fact),
    );
    if method_request.is_some() {
        return Some((usize::from(facet_overlap > 0) * 4, facet_overlap));
    }
    let relation_terms =
        atomic_routing_relation(&fact.metadata).map_or_else(HashSet::new, facet_terms);
    let assessment_query = query_terms
        .iter()
        .any(|term| matches!(term.as_str(), "personality" | "person" | "trait"));
    let assessment_relation = relation_terms
        .iter()
        .any(|term| matches!(term.as_str(), "assess" | "describ" | "characteriz"));
    let typed_priority = inference_fact_kind_priority(plan, &fact.metadata)
        .max(usize::from(assessment_query && assessment_relation) * 4);
    (facet_overlap > 0 || typed_priority > 0).then_some((typed_priority, facet_overlap))
}

/// Find grounded facts attached to the actual deeper cognitive trace rather
/// than treating every globally routed fact as a required answer slot.
///
/// The reverse join is deliberately fail-closed: a fact must bind to a
/// canonical source present at ranks 51..N, name the exact query subject, and
/// contribute either a non-subject query facet or a typed inference facet.
/// It remains an eligibility signal only; raw source evidence is still the
/// sole document and package surface.
fn trace_atomic_preselection<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    ranking: &[crate::query::ReadoutCandidate],
    inspected: usize,
    as_of: crate::graph::Timestamp,
    query_scope: &ScopePath,
) -> Result<TraceAtomicPreselection, Error> {
    if !uses_complex_expansion(plan) || ranking.len() <= inspected {
        return Ok(TraceAtomicPreselection::default());
    }

    let mut source_rank = HashMap::new();
    for (ranking_index, candidate) in ranking.iter().enumerate().skip(inspected) {
        for source_id in canonical_sources(storage, candidate.node_id)? {
            source_rank.entry(source_id).or_insert(ranking_index);
        }
    }
    if source_rank.is_empty() {
        return Ok(TraceAtomicPreselection::default());
    }

    let method_request = factual_action_request(plan);
    let fact_ids = storage.all_atomic_fact_ids();
    let strict_action_authority = match method_request.as_ref() {
        Some(request) if request.projection != FactualActionProjection::Method => Some(
            factual_action_authority(storage, plan, request, &fact_ids, as_of, query_scope)?,
        ),
        _ => None,
    };
    let mut eligible = Vec::new();
    for fact_id in fact_ids {
        let fact = storage.get_atomic_fact(fact_id)?;
        let Some(binding) = atomic_evidence_binding(fact) else {
            continue;
        };
        let Some(&ranking_index) = source_rank.get(&binding.evidence_source) else {
            continue;
        };
        if strict_action_authority.as_ref().is_some_and(|authority| {
            authority.evidence_source_by_fact.get(&fact_id) != Some(&binding.evidence_source)
        }) {
            continue;
        }
        let Some((typed_priority, facet_overlap)) = trace_atomic_fact_relevance(
            plan,
            method_request.as_ref(),
            strict_action_authority
                .as_ref()
                .map(|authority| &authority.result_value_witness_sources),
            fact,
        ) else {
            continue;
        };
        let Some((evidence_source, evidence_span)) =
            grounded_atomic_fact(storage, fact, binding.evidence_source)?
        else {
            continue;
        };
        eligible.push((
            fact_id,
            typed_priority,
            facet_overlap,
            method_request
                .as_ref()
                .map_or(0.0, |_| ranking[ranking_index].embedding_cosine),
            ranking_index,
            evidence_source,
            evidence_span,
        ));
    }
    if method_request.is_some() {
        eligible.retain(|(_, _, overlap, cosine, ..)| *overlap > 0 || *cosine > 0.0);
        // Method questions commonly mix actions that repeat the requested
        // predicate with actions whose wording only implies it. Reserve half
        // of the four actionable trace slots for exact facets, then fill the
        // other half by source-level semantic affinity. The remaining bounded
        // requirements retain the ordinary deterministic ordering.
        const METHOD_LEXICAL_TRACE_QUOTA: usize = 2;
        const METHOD_PRIORITY_TRACE_QUOTA: usize = 4;
        let mut lexical = eligible.clone();
        lexical.retain(|(_, _, overlap, ..)| *overlap > 0);
        lexical.sort_by(
            |(left_id, _, left_overlap, left_cosine, left_rank, ..),
             (right_id, _, right_overlap, right_cosine, right_rank, ..)| {
                right_overlap
                    .cmp(left_overlap)
                    .then_with(|| right_cosine.total_cmp(left_cosine))
                    .then_with(|| left_rank.cmp(right_rank))
                    .then_with(|| left_id.cmp(right_id))
            },
        );
        let mut semantic_scores: Vec<_> = eligible
            .iter()
            .filter_map(|(_, _, _, cosine, ..)| (*cosine > 0.0).then_some(*cosine))
            .collect();
        semantic_scores.sort_by(f64::total_cmp);
        let semantic_floor = semantic_scores
            .get(semantic_scores.len().saturating_sub(1) / 2)
            .copied()
            .unwrap_or(0.0);
        let mut semantic = eligible.clone();
        semantic.retain(|(_, _, overlap, cosine, ..)| {
            *cosine > 0.0 && (*overlap > 0 || *cosine > semantic_floor)
        });
        semantic.sort_by(
            |(left_id, _, left_overlap, left_cosine, left_rank, ..),
             (right_id, _, right_overlap, right_cosine, right_rank, ..)| {
                right_cosine
                    .total_cmp(left_cosine)
                    .then_with(|| right_overlap.cmp(left_overlap))
                    .then_with(|| left_rank.cmp(right_rank))
                    .then_with(|| left_id.cmp(right_id))
            },
        );
        eligible.sort_by(
            |(left_id, left_typed, left_overlap, left_cosine, left_rank, ..),
             (right_id, right_typed, right_overlap, right_cosine, right_rank, ..)| {
                right_typed
                    .cmp(left_typed)
                    .then_with(|| right_overlap.cmp(left_overlap))
                    .then_with(|| right_cosine.total_cmp(left_cosine))
                    .then_with(|| left_rank.cmp(right_rank))
                    .then_with(|| left_id.cmp(right_id))
            },
        );

        let mut balanced = Vec::with_capacity(eligible.len());
        let mut admitted = HashSet::new();
        for candidate in lexical
            .iter()
            .take(METHOD_LEXICAL_TRACE_QUOTA)
            .chain(semantic.iter())
        {
            if balanced.len() >= METHOD_PRIORITY_TRACE_QUOTA {
                break;
            }
            if admitted.insert(candidate.0) {
                balanced.push(candidate.clone());
            }
        }
        for candidate in &eligible {
            if admitted.insert(candidate.0) {
                balanced.push(candidate.clone());
            }
        }
        eligible = balanced;
    } else {
        eligible.sort_by(
            |(left_id, left_typed, left_overlap, left_cosine, left_rank, ..),
             (right_id, right_typed, right_overlap, right_cosine, right_rank, ..)| {
                right_typed
                    .cmp(left_typed)
                    .then_with(|| right_overlap.cmp(left_overlap))
                    .then_with(|| right_cosine.total_cmp(left_cosine))
                    .then_with(|| left_rank.cmp(right_rank))
                    .then_with(|| left_id.cmp(right_id))
            },
        );
    }

    let mut selected = TraceAtomicPreselection::default();
    for (priority, (fact_id, _, _, _, _, evidence_source, evidence_span)) in eligible
        .into_iter()
        .take(MAX_TRACE_ATOMIC_FACT_REQUIREMENTS)
        .enumerate()
    {
        selected.required_fact_ids.insert(fact_id);
        selected.requirements.insert(
            fact_id,
            PreselectionAtomicFactRequirement {
                evidence_source,
                evidence_span,
            },
        );
        selected.priority.insert(fact_id, priority);
    }
    Ok(selected)
}

fn covered_preselection_slots(
    head: &PreselectionSlotCoverage,
    tail: &[PreselectionCandidate],
    chosen_indices: &HashSet<usize>,
    excluded_index: Option<usize>,
    added: Option<&PreselectionCandidate>,
) -> PreselectionSlotCoverage {
    let mut covered = PreselectionSlotCoverage {
        atomic_fact_ids: head.atomic_fact_ids.clone(),
    };
    for candidate in tail {
        if chosen_indices.contains(&candidate.ranking_index)
            && Some(candidate.ranking_index) != excluded_index
        {
            covered
                .atomic_fact_ids
                .extend(candidate.atomic_fact_ids.iter().copied());
        }
    }
    if let Some(candidate) = added {
        covered
            .atomic_fact_ids
            .extend(candidate.atomic_fact_ids.iter().copied());
    }
    covered
}

fn preselection_atomic_fact_ids<S: StorageAdapter>(
    storage: &S,
    node_id: NodeId,
    source_node_ids: &[NodeId],
    requirements: &HashMap<AtomicFactId, PreselectionAtomicFactRequirement>,
) -> Result<HashSet<AtomicFactId>, Error> {
    let candidate_content = &storage.get_node(node_id)?.content;
    Ok(requirements
        .iter()
        .filter_map(|(fact_id, requirement)| {
            let covered = source_node_ids.contains(&requirement.evidence_source)
                && candidate_content.contains(&requirement.evidence_span);
            covered.then_some(*fact_id)
        })
        .collect())
}

fn normalize_facet_term(term: &str) -> String {
    let term = term.trim_matches('\'');
    match term {
        "authors" => "author".to_owned(),
        "books" => "book".to_owned(),
        "cities" => "city".to_owned(),
        "developed" | "developing" => "develop".to_owned(),
        "favorite" | "favorites" | "favourite" | "favourites" | "preferred" | "prefers" => {
            "prefer".to_owned()
        }
        "games" => "game".to_owned(),
        "moved" | "moving" => "move".to_owned(),
        "planned" | "planning" => "plan".to_owned(),
        "states" => "state".to_owned(),
        "visited" | "visiting" => "visit".to_owned(),
        _ if term.len() > 5 && term.ends_with("ies") => {
            format!("{}y", &term[..term.len() - 3])
        }
        _ if term.len() > 5 && term.ends_with("ing") => term[..term.len() - 3].to_owned(),
        _ if term.len() > 4 && term.ends_with("ed") => term[..term.len() - 2].to_owned(),
        _ if term.len() > 4 && term.ends_with('s') => term[..term.len() - 1].to_owned(),
        _ => term.to_owned(),
    }
}

pub(super) fn facet_terms(value: &str) -> HashSet<String> {
    value
        .split(|character: char| !character.is_alphanumeric() && character != '\'')
        .filter(|term| term.len() > 2)
        .map(str::to_lowercase)
        .filter(|term| {
            !matches!(
                term.as_str(),
                "about"
                    | "all"
                    | "also"
                    | "and"
                    | "are"
                    | "based"
                    | "been"
                    | "between"
                    | "can"
                    | "connection"
                    | "could"
                    | "did"
                    | "does"
                    | "done"
                    | "for"
                    | "from"
                    | "had"
                    | "has"
                    | "have"
                    | "how"
                    | "infer"
                    | "kind"
                    | "likely"
                    | "list"
                    | "might"
                    | "please"
                    | "relationship"
                    | "remember"
                    | "should"
                    | "suggest"
                    | "tell"
                    | "that"
                    | "the"
                    | "their"
                    | "them"
                    | "then"
                    | "there"
                    | "these"
                    | "they"
                    | "this"
                    | "those"
                    | "was"
                    | "were"
                    | "what"
                    | "when"
                    | "where"
                    | "which"
                    | "who"
                    | "why"
                    | "will"
                    | "with"
                    | "would"
                    | "you"
            )
        })
        .map(|term| normalize_facet_term(&term))
        .filter(|term| term.len() > 2)
        .collect()
}

fn source_sessions<S: StorageAdapter>(
    storage: &S,
    source_node_ids: &[NodeId],
) -> Result<Vec<String>, Error> {
    let mut sessions = Vec::new();
    for source_node_id in source_node_ids {
        let session = storage.get_node(*source_node_id)?.origin.session_id.clone();
        if !sessions.contains(&session) {
            sessions.push(session);
        }
    }
    Ok(sessions)
}

fn candidate_facet_terms<S: StorageAdapter>(
    storage: &S,
    node_id: NodeId,
    source_node_ids: &[NodeId],
    query_facets: &HashSet<String>,
) -> Result<HashSet<String>, Error> {
    let mut terms = facet_terms(&storage.get_node(node_id)?.content);
    for source_node_id in source_node_ids {
        terms.extend(facet_terms(&storage.get_node(*source_node_id)?.content));
    }
    Ok(query_facets.intersection(&terms).cloned().collect())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TemporalBridgeSignal {
    kind_priority: usize,
    seed_rank: usize,
    distance: usize,
    backward_hops: usize,
}

fn bridge_signal_is_better(candidate: TemporalBridgeSignal, current: TemporalBridgeSignal) -> bool {
    candidate.kind_priority > current.kind_priority
        || (candidate.kind_priority == current.kind_priority
            && (candidate.distance < current.distance
                || (candidate.distance == current.distance
                    && (candidate.backward_hops < current.backward_hops
                        || (candidate.backward_hops == current.backward_hops
                            && candidate.seed_rank < current.seed_rank)))))
}

fn temporal_bridge_signals<S: StorageAdapter>(
    storage: &S,
    routed_atomic_sources: &[(NodeId, usize)],
    max_hops: usize,
) -> Result<HashMap<NodeId, TemporalBridgeSignal>, Error> {
    let mut signals = HashMap::new();
    let mut queue = VecDeque::new();
    let mut seen_seeds = HashSet::new();
    for (seed_rank, &(source_node_id, kind_priority)) in routed_atomic_sources.iter().enumerate() {
        if !seen_seeds.insert(source_node_id) {
            continue;
        }
        let source = storage.get_node(source_node_id)?;
        if source.node_type != KnowledgeType::Episodic {
            continue;
        }
        let signal = TemporalBridgeSignal {
            // Only recurring conventions warrant directional expansion ahead
            // of ordinary semantic relevance. Other typed facts still route
            // their exact raw sources through the atomic lane.
            kind_priority: usize::from(kind_priority == 3),
            seed_rank,
            distance: 0,
            backward_hops: 0,
        };
        signals.insert(source_node_id, signal);
        queue.push_back((source_node_id, source.origin.session_id.clone(), signal));
    }

    while let Some((node_id, source_session, signal)) = queue.pop_front() {
        if signals.get(&node_id) != Some(&signal) || signal.distance >= max_hops {
            continue;
        }

        let mut neighbors = Vec::new();
        for &edge_id in storage.edges_from(node_id) {
            let edge = storage.get_edge(edge_id)?;
            if edge.edge_type == EdgeType::Temporal {
                neighbors.push((edge.target, false));
            }
        }
        for &edge_id in storage.edges_to(node_id) {
            let edge = storage.get_edge(edge_id)?;
            if edge.edge_type == EdgeType::Temporal {
                neighbors.push((edge.source, true));
            }
        }
        neighbors.sort_unstable();
        neighbors.dedup();

        for (neighbor_id, traversed_backward) in neighbors {
            let neighbor = storage.get_node(neighbor_id)?;
            if neighbor.node_type != KnowledgeType::Episodic
                || neighbor.origin.session_id != source_session
            {
                continue;
            }
            let next_signal = TemporalBridgeSignal {
                distance: signal.distance + 1,
                backward_hops: signal.backward_hops + usize::from(traversed_backward),
                ..signal
            };
            let should_update = signals
                .get(&neighbor_id)
                .is_none_or(|current| bridge_signal_is_better(next_signal, *current));
            if should_update {
                signals.insert(neighbor_id, next_signal);
                queue.push_back((neighbor_id, source_session.clone(), next_signal));
            }
        }
    }

    Ok(signals)
}

#[derive(Debug)]
struct AtomicFactCandidate {
    fact_id: AtomicFactId,
    dense_score: f64,
    lexical_overlap: usize,
    lexical_idf_score: f64,
    matched_terms: HashSet<String>,
    entity_matches: usize,
    subject_matches: usize,
    kind_priority: usize,
    method_action_eligible: bool,
    method_target_overlap: usize,
    source_session_id: String,
    source_node_ids: Vec<NodeId>,
}

const MAX_ATOMIC_ROUTING_COMPONENT_BYTES: usize = 1_024;
const MAX_ATOMIC_ROUTING_SURFACE_BYTES: usize = 4_096;
const MAX_ATOMIC_ROUTING_SPAN_BYTES: usize = 2_048;

struct AtomicRoutingMetadata<'a> {
    subject: &'a str,
    relation: &'a str,
    object: &'a str,
    evidence_object: &'a str,
    evidence_source: NodeId,
    evidence_start: usize,
    evidence_end: usize,
    requires_exact_object: bool,
}

struct AtomicEvidenceBinding<'a> {
    evidence_object: &'a str,
    evidence_source: NodeId,
    evidence_start: usize,
    evidence_end: usize,
    requires_exact_object: bool,
}

fn bounded_atomic_routing_component(value: &str) -> Option<&str> {
    let value = value.trim();
    (!value.is_empty()
        && value.len() <= MAX_ATOMIC_ROUTING_COMPONENT_BYTES
        && !value.chars().any(char::is_control))
    .then_some(value)
}

fn atomic_routing_subject(metadata: &HashMap<String, String>) -> Option<&str> {
    metadata
        .get(super::REVIEWED_DERIVATION_SUBJECT_KEY)
        .or_else(|| metadata.get("anamnesis:ground-subject"))
        .map(String::as_str)
}

fn atomic_routing_relation(metadata: &HashMap<String, String>) -> Option<&str> {
    metadata
        .get(super::REVIEWED_DERIVATION_PREDICATE_KEY)
        .or_else(|| metadata.get("anamnesis:ground-relation"))
        .map(String::as_str)
}

fn atomic_routing_object(metadata: &HashMap<String, String>) -> Option<&str> {
    metadata
        .get(super::REVIEWED_DERIVATION_OBJECT_KEY)
        .or_else(|| metadata.get("anamnesis:ground-object"))
        .map(String::as_str)
}

fn atomic_evidence_binding(fact: &AtomicFact) -> Option<AtomicEvidenceBinding<'_>> {
    let requires_exact_object = fact.metadata.contains_key("anamnesis:evidence-object");
    let evidence_object = bounded_atomic_routing_component(
        fact.metadata
            .get("anamnesis:evidence-object")
            .or_else(|| fact.metadata.get("anamnesis:ground-object"))?,
    )?;
    let evidence_source = fact
        .metadata
        .get("anamnesis:evidence-source-node-id")?
        .parse::<u64>()
        .ok()
        .map(NodeId)?;
    if !fact.source_node_ids.contains(&evidence_source) {
        return None;
    }
    let evidence_start = fact
        .metadata
        .get("anamnesis:evidence-span-start")?
        .parse::<usize>()
        .ok()?;
    let evidence_end = fact
        .metadata
        .get("anamnesis:evidence-span-end")?
        .parse::<usize>()
        .ok()?;
    if evidence_end <= evidence_start
        || evidence_end.saturating_sub(evidence_start) > MAX_ATOMIC_ROUTING_SPAN_BYTES
    {
        return None;
    }
    Some(AtomicEvidenceBinding {
        evidence_object,
        evidence_source,
        evidence_start,
        evidence_end,
        requires_exact_object,
    })
}

fn validity_bounds_are_nonempty(
    valid_from: Option<crate::graph::Timestamp>,
    valid_until: Option<crate::graph::Timestamp>,
) -> bool {
    match (valid_from, valid_until) {
        (Some(from), Some(until)) => from < until,
        _ => true,
    }
}

fn validity_window_matches_plan(
    plan: &RecallPlan,
    valid_from: Option<crate::graph::Timestamp>,
    valid_until: Option<crate::graph::Timestamp>,
    now: crate::graph::Timestamp,
) -> bool {
    if !validity_bounds_are_nonempty(valid_from, valid_until)
        || valid_from.is_some_and(|from| from > now)
    {
        return false;
    }
    plan_allows_historical_expired(plan) || valid_until.is_none_or(|until| now < until)
}

fn validity_windows_overlap(
    left_from: Option<crate::graph::Timestamp>,
    left_until: Option<crate::graph::Timestamp>,
    right_from: Option<crate::graph::Timestamp>,
    right_until: Option<crate::graph::Timestamp>,
) -> bool {
    let latest_from = match (left_from, right_from) {
        (Some(left), Some(right)) => Some(left.max(right)),
        (left, right) => left.or(right),
    };
    let earliest_until = match (left_until, right_until) {
        (Some(left), Some(right)) => Some(left.min(right)),
        (left, right) => left.or(right),
    };
    match (latest_from, earliest_until) {
        (Some(from), Some(until)) => from < until,
        _ => true,
    }
}

fn atomic_fact_record_is_live(fact: &AtomicFact) -> bool {
    !fact.content.trim().is_empty()
        && !fact
            .metadata
            .get("retracted")
            .is_some_and(|value| value == "true")
        && validity_bounds_are_nonempty(fact.valid_from, fact.valid_until)
}

fn atomic_fact_source_is_live<S: StorageAdapter>(
    storage: &S,
    fact: &AtomicFact,
    source_id: NodeId,
) -> Result<bool, Error> {
    if !atomic_fact_record_is_live(fact) || !fact.source_node_ids.contains(&source_id) {
        return Ok(false);
    }
    let source = match storage.get_node(source_id) {
        Ok(source) => source,
        Err(Error::NodeNotFound(_)) => return Ok(false),
        Err(error) => return Err(error),
    };
    if source.node_type != KnowledgeType::Episodic
        || source.content.trim().is_empty()
        || source.origin.session_id != fact.source_session_id
        || source.origin.scope != fact.scope
        || source.created_at > fact.observed_at
        || source
            .metadata
            .get("retracted")
            .is_some_and(|value| value == "true")
        || !validity_bounds_are_nonempty(source.valid_from, source.valid_until)
        || !validity_windows_overlap(
            fact.valid_from,
            fact.valid_until,
            source.valid_from,
            source.valid_until,
        )
        || !storage.atomic_fact_source_is_current(fact, source)?
    {
        return Ok(false);
    }
    Ok(true)
}

fn atomic_routing_metadata(fact: &AtomicFact) -> Option<AtomicRoutingMetadata<'_>> {
    let subject = bounded_atomic_routing_component(atomic_routing_subject(&fact.metadata)?)?;
    let relation = bounded_atomic_routing_component(atomic_routing_relation(&fact.metadata)?)?;
    let object = bounded_atomic_routing_component(atomic_routing_object(&fact.metadata)?)?;
    let evidence = atomic_evidence_binding(fact)?;
    let evidence_object = evidence.evidence_object;
    let surface_bytes = subject
        .len()
        .saturating_add(relation.len())
        .saturating_add(object.len())
        .saturating_add(evidence_object.len());
    if surface_bytes > MAX_ATOMIC_ROUTING_SURFACE_BYTES {
        return None;
    }

    Some(AtomicRoutingMetadata {
        subject,
        relation,
        object,
        evidence_object,
        evidence_source: evidence.evidence_source,
        evidence_start: evidence.evidence_start,
        evidence_end: evidence.evidence_end,
        requires_exact_object: evidence.requires_exact_object,
    })
}

fn atomic_routing_metadata_terms<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    fact: &AtomicFact,
    query_terms: &HashSet<String>,
    now: crate::graph::Timestamp,
    scope: &ScopePath,
) -> Result<HashSet<String>, Error> {
    let Some(metadata) = atomic_routing_metadata(fact) else {
        return Ok(HashSet::new());
    };
    let mut terms = HashSet::new();
    for value in [
        metadata.subject,
        metadata.relation,
        metadata.object,
        metadata.evidence_object,
    ] {
        terms.extend(facet_terms(value));
    }
    // Hydrate and validate the cited source only when this bounded metadata
    // projection could affect the current lexical route. The full fact sidecar
    // remains scan-based today, so avoiding one raw-node lookup per unrelated
    // fact materially limits the cost of this lane.
    if terms.is_disjoint(query_terms) {
        return Ok(HashSet::new());
    }

    if !atomic_fact_source_is_live(storage, fact, metadata.evidence_source)? {
        return Ok(HashSet::new());
    }
    let source = match storage.get_node(metadata.evidence_source) {
        Ok(source) => source,
        Err(Error::NodeNotFound(_)) => return Ok(HashSet::new()),
        Err(error) => return Err(error),
    };
    if source.node_type != KnowledgeType::Episodic
        || source.origin.session_id != fact.source_session_id
        || source.origin.scope != fact.scope
        || !storage.atomic_fact_source_is_current(fact, source)?
        || source.created_at > now
        || source
            .metadata
            .get("retracted")
            .is_some_and(|value| value == "true")
        || !validity_window_matches_plan(plan, source.valid_from, source.valid_until, now)
        || !atomic_scope_is_visible(scope, &source.origin.scope)
    {
        return Ok(HashSet::new());
    }
    let Some(evidence_span) = source
        .content
        .get(metadata.evidence_start..metadata.evidence_end)
    else {
        return Ok(HashSet::new());
    };
    let object_is_grounded = if metadata.requires_exact_object {
        evidence_span.contains(metadata.evidence_object)
    } else {
        normalized_phrase(evidence_span).contains(&normalized_phrase(metadata.evidence_object))
    };
    if !object_is_grounded {
        return Ok(HashSet::new());
    }
    Ok(terms)
}

fn max_query_cosine(query_embeddings: &[&[f64]], candidate_embedding: &[f64]) -> f64 {
    query_embeddings
        .iter()
        .map(|query_embedding| cosine_similarity(query_embedding, candidate_embedding))
        .max_by(f64::total_cmp)
        .unwrap_or(0.0)
}

#[derive(Clone)]
struct PremiseFactCandidate {
    member: PremiseBundleMember,
    source: crate::query::ReadoutCandidate,
    typed_strength: usize,
    dense_score: f64,
    predicate_overlap: usize,
}

#[derive(Debug)]
struct LivePremiseFact {
    authority: PremiseFactAuthority,
    subject: String,
    source_id: NodeId,
    evidence_object: String,
    evidence_span: String,
}

fn reviewed_premise_fact_is_complete(fact: &AtomicFact, now: crate::graph::Timestamp) -> bool {
    let reviewed_at = fact
        .metadata
        .get(super::REVIEWED_DERIVATION_REVIEWED_AT_KEY)
        .and_then(|value| value.parse::<u64>().ok())
        .map(crate::graph::Timestamp);
    fact.metadata
        .get(super::REVIEWED_DERIVATION_SCHEMA_KEY)
        .is_some_and(|value| value == "reviewed-routing-v1")
        && [
            super::REVIEWED_DERIVATION_REVIEWED_BY_KEY,
            super::REVIEWED_DERIVATION_REVIEW_PROFILE_KEY,
            super::REVIEWED_DERIVATION_IDEMPOTENCY_KEY,
            super::REVIEWED_DERIVATION_SUBJECT_KEY,
            super::REVIEWED_DERIVATION_PREDICATE_KEY,
            super::REVIEWED_DERIVATION_OBJECT_KEY,
            super::REVIEWED_DERIVATION_POLARITY_KEY,
            super::REVIEWED_DERIVATION_MODALITY_KEY,
        ]
        .iter()
        .all(|key| {
            fact.metadata
                .get(*key)
                .is_some_and(|value| !value.trim().is_empty())
        })
        && fact
            .metadata
            .get(super::REVIEWED_DERIVATION_POLARITY_KEY)
            .is_some_and(|value| matches!(value.as_str(), "affirmed" | "negated"))
        && fact
            .metadata
            .get(super::REVIEWED_DERIVATION_MODALITY_KEY)
            .is_some_and(|value| {
                matches!(
                    value.as_str(),
                    "observed"
                        | "reported"
                        | "inferred"
                        | "uncertain"
                        | "conditional"
                        | "planned"
                        | "hypothetical"
                )
            })
        && reviewed_at
            .is_some_and(|reviewed_at| reviewed_at <= now && reviewed_at <= fact.observed_at)
}

fn premise_fact_authority(
    fact: &AtomicFact,
    now: crate::graph::Timestamp,
) -> Option<PremiseFactAuthority> {
    let has_review_metadata = fact
        .metadata
        .keys()
        .any(|key| key.starts_with(super::REVIEWED_DERIVATION_METADATA_PREFIX));
    if has_review_metadata {
        return reviewed_premise_fact_is_complete(fact, now)
            .then_some(PremiseFactAuthority::ReviewedProjection);
    }
    Some(PremiseFactAuthority::GroundedRawSpan)
}

fn live_premise_source<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    fact: &AtomicFact,
    now: crate::graph::Timestamp,
    scope: &ScopePath,
) -> Result<Option<LivePremiseFact>, Error> {
    let Some(authority) = premise_fact_authority(fact, now) else {
        return Ok(None);
    };
    if !atomic_fact_record_is_live(fact)
        || fact.observed_at > now
        || !validity_window_matches_plan(plan, fact.valid_from, fact.valid_until, now)
        || !atomic_scope_is_visible(scope, &fact.scope)
    {
        return Ok(None);
    }
    let Some(metadata) = atomic_routing_metadata(fact) else {
        return Ok(None);
    };
    if authority == PremiseFactAuthority::GroundedRawSpan && !metadata.requires_exact_object {
        return Ok(None);
    }
    let subject = normalized_phrase(metadata.subject);
    if subject.len() < 3 || !normalized_contains_phrase(&normalized_phrase(&plan.query), &subject) {
        return Ok(None);
    }
    let Some((source_id, evidence_span)) =
        grounded_atomic_fact(storage, fact, metadata.evidence_source)?
    else {
        return Ok(None);
    };
    let source = storage.get_node(source_id)?;
    let (speaker, _) = parse_entity_tags(&source.entity_tags);
    if source.node_type != KnowledgeType::Episodic
        || source.created_at > now
        || !validity_window_matches_plan(plan, source.valid_from, source.valid_until, now)
        || !atomic_scope_is_visible(scope, &source.origin.scope)
        || speaker.as_deref().map(normalized_phrase).as_deref() != Some(subject.as_str())
    {
        return Ok(None);
    }
    Ok(Some(LivePremiseFact {
        authority,
        subject,
        source_id,
        evidence_object: metadata.evidence_object.to_owned(),
        evidence_span,
    }))
}

fn normalize_premise_term(term: String) -> String {
    match term.as_str() {
        "enjoyable" | "enjoyment" | "enjoyably" => "enjoy".to_owned(),
        _ => term,
    }
}

fn premise_terms(value: &str) -> HashSet<String> {
    facet_terms(value)
        .into_iter()
        .map(normalize_premise_term)
        .filter(|term| term != "doing")
        .collect()
}

fn premise_predicate_terms(
    fact: &AtomicFact,
    live: &LivePremiseFact,
    subject_terms: &HashSet<String>,
) -> HashSet<String> {
    let mut terms = match live.authority {
        PremiseFactAuthority::ReviewedProjection => premise_terms(&fact.content),
        PremiseFactAuthority::GroundedRawSpan => premise_terms(&live.evidence_object),
    };
    if live.authority == PremiseFactAuthority::ReviewedProjection {
        for value in [
            atomic_routing_relation(&fact.metadata),
            atomic_routing_object(&fact.metadata),
            fact.metadata
                .get("anamnesis:evidence-object")
                .map(String::as_str),
        ]
        .into_iter()
        .flatten()
        {
            terms.extend(premise_terms(value));
        }
    }
    terms.retain(|term| !subject_terms.contains(term));
    terms
}

fn premise_terms_have_opposing_place_modifiers(
    slot_terms: &HashSet<String>,
    fact_terms: &HashSet<String>,
) -> bool {
    let slot_indoor = slot_terms.contains("indoor");
    let slot_outdoor = slot_terms.contains("outdoor");
    let fact_indoor = fact_terms.contains("indoor");
    let fact_outdoor = fact_terms.contains("outdoor");

    (slot_indoor && !slot_outdoor && fact_outdoor && !fact_indoor)
        || (slot_outdoor && !slot_indoor && fact_indoor && !fact_outdoor)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OwnedEntityKind {
    Dog,
    Puppy,
}

fn premise_words(value: &str) -> Vec<String> {
    value
        .split(|character: char| !character.is_alphanumeric() && character != '\'')
        .filter(|word| !word.is_empty())
        .map(str::to_lowercase)
        .collect()
}

fn owned_entity_kind(word: &str) -> Option<OwnedEntityKind> {
    match word {
        "dog" | "dogs" => Some(OwnedEntityKind::Dog),
        "pup" | "pups" | "puppy" | "puppies" => Some(OwnedEntityKind::Puppy),
        _ => None,
    }
}

fn owned_entity_constraint(surface: &str) -> Option<OwnedEntityKind> {
    let words = premise_words(surface);
    words.windows(2).find_map(|pair| {
        (matches!(pair[0].as_str(), "his" | "her" | "their") || pair[0].ends_with("'s"))
            .then(|| owned_entity_kind(&pair[1]))
            .flatten()
    })
}

fn evidence_kind_satisfies_query(
    query_kind: OwnedEntityKind,
    evidence_kind: OwnedEntityKind,
) -> bool {
    match query_kind {
        OwnedEntityKind::Dog => {
            matches!(evidence_kind, OwnedEntityKind::Dog | OwnedEntityKind::Puppy)
        }
        OwnedEntityKind::Puppy => evidence_kind == OwnedEntityKind::Puppy,
    }
}

fn grounded_owned_entity_strength(
    fact: &AtomicFact,
    subject: &str,
    evidence_span: &str,
    query_kind: OwnedEntityKind,
) -> Option<usize> {
    let words = premise_words(evidence_span);
    let has_owned_entity = words.windows(2).any(|pair| {
        matches!(pair[0].as_str(), "my" | "our")
            && owned_entity_kind(&pair[1]).is_some_and(|evidence_kind| {
                evidence_kind_satisfies_query(query_kind, evidence_kind)
            })
    });
    if !has_owned_entity {
        return None;
    }

    let normalized_span = normalized_phrase(evidence_span);
    let has_grounded_named_entity = fact.entity_tags.iter().any(|tag| {
        let normalized_tag = normalized_phrase(tag);
        normalized_tag != subject
            && normalized_tag.len() > 2
            && normalized_contains_phrase(&normalized_span, &normalized_tag)
    });
    Some(if has_grounded_named_entity { 2 } else { 1 })
}

fn premise_slot_admission(
    fact: &AtomicFact,
    live: &LivePremiseFact,
    slot_surface: &str,
) -> Option<(usize, usize)> {
    let subject_terms = premise_terms(&live.subject);
    let fact_terms = premise_predicate_terms(fact, live, &subject_terms);
    if fact_terms.is_empty() {
        return None;
    }
    let mut slot_terms = premise_terms(slot_surface);
    slot_terms.retain(|term| !subject_terms.contains(term));
    if premise_terms_have_opposing_place_modifiers(&slot_terms, &fact_terms) {
        return None;
    }
    let predicate_overlap = slot_terms.intersection(&fact_terms).count();
    let typed_strength = match owned_entity_constraint(slot_surface) {
        Some(query_kind) => {
            grounded_owned_entity_strength(fact, &live.subject, &live.evidence_span, query_kind)?
        }
        None => 0,
    };
    (predicate_overlap > 0 || typed_strength > 0).then_some((typed_strength, predicate_overlap))
}

fn complete_distinct_premise_assignment(
    candidates: &[Vec<PremiseFactCandidate>],
    slot_index: usize,
    used_sources: &mut HashSet<NodeId>,
    selected: &mut Vec<PremiseFactCandidate>,
) -> bool {
    if slot_index == candidates.len() {
        return true;
    }
    for candidate in &candidates[slot_index] {
        if !used_sources.insert(candidate.member.source_node_id) {
            continue;
        }
        selected.push(candidate.clone());
        if complete_distinct_premise_assignment(candidates, slot_index + 1, used_sources, selected)
        {
            return true;
        }
        selected.pop();
        used_sources.remove(&candidate.member.source_node_id);
    }
    false
}

/// Resolve one all-or-none bundle from source-grounded facts using existing
/// clause vectors. Reviewed projections retain their complete review burden;
/// ordinary facts can admit only terms and owned-entity relations present in a
/// revalidated exact raw span. Dense similarity only orders already-admitted
/// facts and can never create a bundle member.
pub(super) fn route_premise_bundle<S: StorageAdapter>(
    storage: &S,
    plan: &RecallPlan,
    slots: &[PremiseBundleQuerySlot<'_>],
    now: crate::graph::Timestamp,
    scope: &ScopePath,
) -> Result<Option<RoutedPremiseBundle>, Error> {
    if plan.derivation != RecallDerivation::GroundedInference
        || plan_has_temporal_constraint(plan)
        || !(PREMISE_BUNDLE_MIN_SLOTS..=PREMISE_BUNDLE_MAX_SLOTS).contains(&slots.len())
        || slots.iter().enumerate().any(|(ordinal, slot)| {
            slot.slot_id.ordinal() != ordinal || slot.surface.trim().is_empty()
        })
    {
        return Ok(None);
    }

    let mut candidates_by_subject: HashMap<String, Vec<Vec<PremiseFactCandidate>>> = HashMap::new();
    for fact_id in storage.all_atomic_fact_ids() {
        let fact = storage.get_atomic_fact(fact_id)?;
        let Some(live) = live_premise_source(storage, plan, fact, now, scope)? else {
            continue;
        };
        let source = storage.get_node(live.source_id)?;
        let subject_slots = candidates_by_subject
            .entry(live.subject.clone())
            .or_insert_with(|| vec![Vec::new(); slots.len()]);
        for (slot_index, slot) in slots.iter().enumerate() {
            let Some((typed_strength, predicate_overlap)) =
                premise_slot_admission(fact, &live, slot.surface)
            else {
                continue;
            };
            let dense_score = cosine_similarity(slot.embedding, &fact.embedding);
            let source_cosine = source.embedding.as_ref().map_or(0.0, |embedding| {
                cosine_similarity(slot.embedding, embedding)
            });
            subject_slots[slot_index].push(PremiseFactCandidate {
                member: PremiseBundleMember {
                    slot_id: slot.slot_id,
                    fact_id,
                    source_node_id: live.source_id,
                    authority: live.authority,
                },
                source: crate::query::ReadoutCandidate {
                    node_id: live.source_id,
                    score: 1.0
                        + (typed_strength * 2) as f64
                        + predicate_overlap as f64
                        + dense_score.max(0.0),
                    activation: 1.0,
                    phi: source_cosine,
                    embedding_cosine: source_cosine,
                    salience: storage.get_salience(live.source_id)?,
                    impedance: 0.0,
                    scope_weight: crate::query::scoring::scope_weight(scope, &source.origin.scope),
                    trust_weight: 1.0,
                    stress: 0.0,
                },
                typed_strength,
                dense_score,
                predicate_overlap,
            });
        }
    }

    let mut subjects: Vec<_> = candidates_by_subject.into_iter().collect();
    subjects.sort_by(|left, right| left.0.cmp(&right.0));
    let mut best: Option<Vec<PremiseFactCandidate>> = None;
    for (_, mut candidates) in subjects {
        if candidates.iter().any(Vec::is_empty) {
            continue;
        }
        for slot_candidates in &mut candidates {
            slot_candidates.sort_by(|left, right| {
                right
                    .typed_strength
                    .cmp(&left.typed_strength)
                    .then_with(|| right.predicate_overlap.cmp(&left.predicate_overlap))
                    .then_with(|| right.dense_score.total_cmp(&left.dense_score))
                    .then_with(|| left.member.fact_id.cmp(&right.member.fact_id))
                    .then_with(|| left.member.source_node_id.cmp(&right.member.source_node_id))
            });
            let mut seen_sources = HashSet::new();
            slot_candidates
                .retain(|candidate| seen_sources.insert(candidate.member.source_node_id));
        }
        let mut selected = Vec::with_capacity(slots.len());
        if !complete_distinct_premise_assignment(&candidates, 0, &mut HashSet::new(), &mut selected)
        {
            continue;
        }
        let replace = best.as_ref().is_none_or(|current| {
            let selected_typed: usize = selected
                .iter()
                .map(|candidate| candidate.typed_strength)
                .sum();
            let current_typed: usize = current
                .iter()
                .map(|candidate| candidate.typed_strength)
                .sum();
            let selected_overlap: usize = selected
                .iter()
                .map(|candidate| candidate.predicate_overlap)
                .sum();
            let current_overlap: usize = current
                .iter()
                .map(|candidate| candidate.predicate_overlap)
                .sum();
            let selected_dense: f64 = selected.iter().map(|candidate| candidate.dense_score).sum();
            let current_dense: f64 = current.iter().map(|candidate| candidate.dense_score).sum();
            selected_typed > current_typed
                || (selected_typed == current_typed && selected_overlap > current_overlap)
                || (selected_typed == current_typed
                    && selected_overlap == current_overlap
                    && selected_dense.total_cmp(&current_dense).is_gt())
                || (selected_typed == current_typed
                    && selected_overlap == current_overlap
                    && selected_dense.total_cmp(&current_dense).is_eq()
                    && selected
                        .iter()
                        .map(|candidate| {
                            (candidate.member.fact_id, candidate.member.source_node_id)
                        })
                        .cmp(current.iter().map(|candidate| {
                            (candidate.member.fact_id, candidate.member.source_node_id)
                        }))
                        .is_lt())
        });
        if replace {
            best = Some(selected);
        }
    }

    let Some(selected) = best else {
        return Ok(None);
    };
    Ok(Some(RoutedPremiseBundle {
        trace: PremiseBundleTrace {
            members: selected.iter().map(|candidate| candidate.member).collect(),
        },
        sources: selected
            .into_iter()
            .map(|candidate| candidate.source)
            .collect(),
    }))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum AtomicRouteOrigin {
    Direct,
    AuxiliaryQuery,
    Chain { depth: usize },
}

#[derive(Debug)]
pub(super) struct RoutedAtomicSource {
    pub candidate: crate::query::ReadoutCandidate,
    pub kind_priority: usize,
    pub fact_ids: Vec<AtomicFactId>,
    pub fact_priorities: Vec<(AtomicFactId, usize)>,
    pub origin: AtomicRouteOrigin,
}

impl RoutedAtomicSource {
    pub(super) fn record_fact_priority(&mut self, fact_id: AtomicFactId, priority: usize) {
        if priority == 0 {
            return;
        }
        if let Some((_, existing)) = self
            .fact_priorities
            .iter_mut()
            .find(|(existing_id, _)| *existing_id == fact_id)
        {
            *existing = (*existing).max(priority);
        } else {
            self.fact_priorities.push((fact_id, priority));
        }
        self.kind_priority = self.kind_priority.max(priority);
    }

    pub(super) fn fact_markers(&self) -> Vec<AtomicSourceMarker> {
        self.fact_ids
            .iter()
            .map(|fact_id| AtomicSourceMarker {
                source_node_id: self.candidate.node_id,
                kind_priority: self
                    .fact_priorities
                    .iter()
                    .find_map(|(candidate_id, priority)| {
                        (*candidate_id == *fact_id).then_some(*priority)
                    })
                    .unwrap_or_default(),
                fact_id: Some(*fact_id),
            })
            .collect()
    }
}

/// Canonically oriented reviewed relation retained while a chain is traversed.
///
/// `from_fact_id` and `to_fact_id` always preserve the stored relation
/// orientation. They are deliberately independent of the order in which the
/// breadth-first traversal reached the two endpoints.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) struct AtomicRelationHop {
    pub(super) relation_id: AtomicFactRelationId,
    pub(super) from_fact_id: AtomicFactId,
    pub(super) to_fact_id: AtomicFactId,
    pub(super) kind: AtomicFactRelationKind,
}

/// One bounded traversal path and the raw evidence needed to render it.
///
/// `fact_ids` follows traversal order. `source_groups` has the same length and
/// contains the complete bounded raw-source group retained for each fact.
/// Selection treats the flattened source set as an indivisible unit.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct AtomicRelationPath {
    pub(super) fact_ids: Vec<AtomicFactId>,
    pub(super) hops: Vec<AtomicRelationHop>,
    pub(super) source_groups: Vec<Vec<NodeId>>,
}

/// One strong query clause bound to its existing dense embedding.
///
/// The embedding is borrowed from the ordinary query batch; constructing this
/// view never invokes a provider or creates another vector.
pub(super) struct PremiseBundleQuerySlot<'a> {
    pub slot_id: DensePremiseSlotId,
    pub surface: &'a str,
    pub embedding: &'a [f64],
}

/// Authority used to admit one premise member.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum PremiseFactAuthority {
    /// A complete engine-stamped review authorizes the bounded projection.
    ReviewedProjection,
    /// Only the revalidated byte-exact raw evidence span authorizes admission.
    GroundedRawSpan,
}

impl PremiseFactAuthority {
    fn trace_code(self) -> &'static str {
        match self {
            Self::ReviewedProjection => "r",
            Self::GroundedRawSpan => "g",
        }
    }

    fn from_trace_code(value: &str) -> Option<Self> {
        match value {
            "r" => Some(Self::ReviewedProjection),
            "g" => Some(Self::GroundedRawSpan),
            _ => None,
        }
    }
}

/// One exact fact/source allocation retained for a premise slot.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) struct PremiseBundleMember {
    pub slot_id: DensePremiseSlotId,
    pub fact_id: AtomicFactId,
    pub source_node_id: NodeId,
    pub authority: PremiseFactAuthority,
}

/// Dedicated bounded trace for one complete query-premise bundle.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct PremiseBundleTrace {
    pub members: Vec<PremiseBundleMember>,
}

/// One byte-grounded fact/source allocation in an event-boundary proof.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) struct EventBoundarySourceMember {
    pub fact_id: AtomicFactId,
    pub source_node_id: NodeId,
}

/// Explicit role assigned only by the dedicated event-boundary router.
///
/// This is intentionally independent of the generic atomic-fact priority
/// scale. Method, inference, and other typed lanes may use the same numeric
/// priorities without acquiring authority in an event-boundary proof.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EventBoundarySourceRole {
    Anchor,
    Target,
}

/// One role-bearing allocation emitted by the dedicated event-boundary route.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RoutedEventBoundarySourceMember {
    role: EventBoundarySourceRole,
    member: EventBoundarySourceMember,
}

/// Bounded raw-source proof for one resolved event boundary.
///
/// Anchors establish the boundary event; targets are the bounded answer-bearing
/// pool admitted on the requested side of that boundary and represented in the
/// fixed reranker surface. Final selection chooses at most two target members
/// in external-reranker order. The two roles remain distinct so this trace
/// cannot be confused with a dense premise bundle or a generic relation path.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct EventBoundarySourceGroup {
    pub anchors: Vec<EventBoundarySourceMember>,
    pub targets: Vec<EventBoundarySourceMember>,
}

/// Project one already-revalidated event-boundary group onto the canonical raw
/// sources that remain visibly available to the reader.
pub(super) fn event_boundary_validation_context(
    plan: &RecallPlan,
    group: Option<&EventBoundarySourceGroup>,
    visibly_delivered_source_node_ids: &[NodeId],
) -> GroundedDraftValidationContext {
    let Some(direction) = (plan.effective_temporal_constraint()
        == EffectiveTemporalConstraint::EventBoundary)
        .then(|| plan.temporal_constraint().direction())
        .flatten()
    else {
        return GroundedDraftValidationContext::membership_only();
    };
    let Some(group) = group.filter(|group| event_boundary_source_group_is_well_formed(group))
    else {
        return GroundedDraftValidationContext::membership_only();
    };
    let visibly_delivered: HashSet<_> = visibly_delivered_source_node_ids.iter().copied().collect();
    let mut anchor_source_node_ids = group
        .anchors
        .iter()
        .map(|member| member.source_node_id)
        .filter(|source_node_id| visibly_delivered.contains(source_node_id))
        .collect::<Vec<_>>();
    let mut target_source_node_ids = group
        .targets
        .iter()
        .map(|member| member.source_node_id)
        .filter(|source_node_id| visibly_delivered.contains(source_node_id))
        .collect::<Vec<_>>();
    anchor_source_node_ids.sort_unstable();
    anchor_source_node_ids.dedup();
    target_source_node_ids.sort_unstable();
    target_source_node_ids.dedup();
    if anchor_source_node_ids.is_empty()
        || target_source_node_ids.is_empty()
        || anchor_source_node_ids
            .iter()
            .any(|source_node_id| target_source_node_ids.binary_search(source_node_id).is_ok())
    {
        return GroundedDraftValidationContext::membership_only();
    }
    GroundedDraftValidationContext::with_event_boundary_evidence(
        EventBoundaryEvidence {
            direction,
            anchor_source_node_ids,
            target_source_node_ids,
        },
        plan,
        visibly_delivered_source_node_ids,
    )
}

/// Search-time bundle and its authoritative raw-source candidates.
pub(super) struct RoutedPremiseBundle {
    pub trace: PremiseBundleTrace,
    pub sources: Vec<crate::query::ReadoutCandidate>,
}

const PREMISE_BUNDLE_MIN_SLOTS: usize = 2;
const PREMISE_BUNDLE_MAX_SLOTS: usize = 3;
const PREMISE_BUNDLE_MAX_TRACE_BYTES: usize = 256;
const EVENT_BOUNDARY_GROUP_MIN_ROLE_MEMBERS: usize = 1;
const EVENT_BOUNDARY_GROUP_MAX_ANCHORS: usize = 2;
const EVENT_BOUNDARY_GROUP_MAX_TARGETS: usize = 12;
const EVENT_BOUNDARY_GROUP_MAX_TRACE_BYTES: usize = 1_024;

fn canonical_event_boundary_members(members: &mut [EventBoundarySourceMember]) {
    members.sort_by_key(|member| (member.fact_id, member.source_node_id));
}

fn event_boundary_source_group_is_well_formed(group: &EventBoundarySourceGroup) -> bool {
    let role_is_canonical = |members: &[EventBoundarySourceMember], max_members: usize| {
        (EVENT_BOUNDARY_GROUP_MIN_ROLE_MEMBERS..=max_members).contains(&members.len())
            && members.windows(2).all(|window| {
                (window[0].fact_id, window[0].source_node_id)
                    < (window[1].fact_id, window[1].source_node_id)
            })
    };
    if !role_is_canonical(&group.anchors, EVENT_BOUNDARY_GROUP_MAX_ANCHORS)
        || !role_is_canonical(&group.targets, EVENT_BOUNDARY_GROUP_MAX_TARGETS)
    {
        return false;
    }
    let mut fact_ids = HashSet::new();
    let mut source_ids = HashSet::new();
    group
        .anchors
        .iter()
        .chain(&group.targets)
        .all(|member| fact_ids.insert(member.fact_id) && source_ids.insert(member.source_node_id))
}

fn event_boundary_source_group(
    plan: &RecallPlan,
    routed: &[RoutedEventBoundarySourceMember],
) -> Option<EventBoundarySourceGroup> {
    if plan.effective_temporal_constraint() != EffectiveTemporalConstraint::EventBoundary {
        return None;
    }
    let mut anchors = Vec::new();
    let mut targets = Vec::new();
    let mut fact_ids = HashSet::new();
    let mut source_ids = HashSet::new();
    for routed_member in routed {
        let members = match routed_member.role {
            EventBoundarySourceRole::Anchor if anchors.len() < EVENT_BOUNDARY_GROUP_MAX_ANCHORS => {
                &mut anchors
            }
            EventBoundarySourceRole::Target if targets.len() < EVENT_BOUNDARY_GROUP_MAX_TARGETS => {
                &mut targets
            }
            _ => continue,
        };
        let member = routed_member.member;
        if fact_ids.contains(&member.fact_id) || source_ids.contains(&member.source_node_id) {
            continue;
        }
        fact_ids.insert(member.fact_id);
        source_ids.insert(member.source_node_id);
        members.push(member);
    }
    canonical_event_boundary_members(&mut anchors);
    canonical_event_boundary_members(&mut targets);
    let group = EventBoundarySourceGroup { anchors, targets };
    event_boundary_source_group_is_well_formed(&group).then_some(group)
}

const ATOMIC_CHAIN_MAX_PATHS: usize = 8;
const ATOMIC_CHAIN_MAX_FACTS_PER_PATH: usize = 3;
const ATOMIC_CHAIN_MAX_SOURCES_PER_FACT: usize = 2;
const ATOMIC_CHAIN_MAX_TRACE_BYTES: usize = 4_096;

