    #[test]
    fn item_finding_cannot_also_carry_an_exclusion_reason() {
        let contract = RecallPlan::infer("Where is the relay station located?").reader_contract();
        let make_draft = |disposition| {
            GroundedAnswerDraft::new(
                "Harbor",
                vec![
                    GroundedAnswerItem::new("Harbor", vec![NodeId(7)])
                        .with_finding_ids(vec!["f1".to_owned()]),
                ],
                vec![NodeId(7)],
                false,
            )
            .with_findings(vec![
                GroundedEvidenceFinding::new(
                    "f1",
                    "The relay station is in Harbor.",
                    vec![NodeId(7)],
                    disposition,
                )
                .with_answer_value("Harbor")
                .with_exclusion_reason("A competing scalar was preferred."),
            ])
            .with_reasoning_operator(
                GroundedReasoningOperator::new(GroundedReasoningOperatorKind::Direct)
                    .with_inputs(vec![GroundedOperatorInput::new(
                        GroundedOperatorInputRole::AnswerValue,
                        vec!["f1".to_owned()],
                    )])
                    .with_output("Harbor"),
            )
        };

        let error = contract
            .validate_grounded_draft(&make_draft(GroundedFindingDisposition::Item), &[NodeId(7)])
            .expect_err("an eligible item cannot also be marked with an exclusion reason");
        assert!(error.failures.contains(
            &GroundedDraftValidationFailure::ItemFindingHasExclusionReason { finding_index: 0 }
        ));
        let repair = contract.system_repair_instruction(&error);
        assert!(repair.contains("eligible item cannot also carry an exclusion reason"));

        assert!(
            contract
                .validate_grounded_draft(
                    &make_draft(GroundedFindingDisposition::Premise),
                    &[NodeId(7)]
                )
                .is_ok(),
            "a contextual premise may explain why it was not promoted"
        );
    }

    fn scalar_relation_value_draft(
        premise_fact: &str,
        premise_source: NodeId,
        value_fact: &str,
        value_source: NodeId,
        value: &str,
    ) -> GroundedAnswerDraft {
        let mut cited_sources = vec![premise_source];
        if value_source != premise_source {
            cited_sources.push(value_source);
        }
        GroundedAnswerDraft::new(
            value,
            vec![
                GroundedAnswerItem::new(value, cited_sources.clone())
                    .with_finding_ids(vec!["relation".to_owned(), "value".to_owned()]),
            ],
            cited_sources,
            false,
        )
        .with_findings(vec![
            GroundedEvidenceFinding::new(
                "relation",
                premise_fact,
                vec![premise_source],
                GroundedFindingDisposition::Premise,
            ),
            GroundedEvidenceFinding::new(
                "value",
                value_fact,
                vec![value_source],
                GroundedFindingDisposition::Item,
            )
            .with_answer_value(value),
        ])
        .with_reasoning_operator(
            GroundedReasoningOperator::new(GroundedReasoningOperatorKind::RelationValueResolution)
                .with_inputs(vec![
                    GroundedOperatorInput::new(
                        GroundedOperatorInputRole::Premise,
                        vec!["relation".to_owned()],
                    ),
                    GroundedOperatorInput::new(
                        GroundedOperatorInputRole::AnswerValue,
                        vec!["value".to_owned()],
                    ),
                ])
                .with_output(value),
        )
    }

    #[test]
    fn scalar_relationship_value_uses_a_dedicated_operator_without_reclassifying_controls() {
        let query = "Which country did the coordinator and technician plan to meet in?";
        let relation =
            RecallPlan::infer_with_answer_shape(query, AnswerShape::Relationship).reader_contract();
        assert_eq!(
            relation.requested_answer_spec().role(),
            RequestedAnswerRole::Value
        );
        assert_eq!(
            relation.requested_answer_spec().cardinality(),
            RequestedAnswerCardinality::One
        );
        assert_eq!(relation.requested_value_target(), Some("country"));
        assert!(!plan_uses_temporal_readout(&relation.plan));
        assert!(relation.allows_public_one_hop());
        assert_eq!(
            relation.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::RelationValueResolution
        );

        for stage in [
            RecallReaderStage::Answer,
            RecallReaderStage::Reflection,
            RecallReaderStage::Verification,
            RecallReaderStage::Repair,
        ] {
            let instruction = relation.instruction(stage);
            for required in [
                "requires RelationValueResolution",
                "source-grounded directed relation or event anchor",
                "separate Premise and AnswerValue inputs in that order",
                "one stable public relation step",
                "must not supply the personal relation",
                "sole answer item must consume every relation-resolution finding",
            ] {
                assert!(
                    instruction.contains(required),
                    "stage {stage:?} omitted {required:?}"
                );
            }
        }
        assert!(
            relation
                .context_guidance()
                .contains("requires RelationValueResolution")
        );
        let answer_instruction = relation.instruction(RecallReaderStage::Answer);
        for control in [
            "multi-speaker material",
            "exact source line",
            "entities, polarity, modality",
            "session-specific",
        ] {
            assert!(answer_instruction.contains(control), "missing {control:?}");
        }

        let fact = RecallPlan::infer_with_answer_shape(query, AnswerShape::Fact).reader_contract();
        assert!(fact.allows_public_one_hop());
        assert_eq!(
            fact.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::Direct
        );
        let temporal_relation =
            RecallPlan::infer_with_answer_shape(query, AnswerShape::Relationship)
                .with_temporal_constraint(TemporalConstraint::calendar_range())
                .reader_contract();
        assert!(plan_uses_temporal_readout(&temporal_relation.plan));
        assert_eq!(
            temporal_relation.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::Direct
        );
        let collection =
            RecallPlan::infer_with_answer_shape(query, AnswerShape::Collection).reader_contract();
        assert_eq!(
            collection.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::CollectionLedger
        );
        let inference = RecallPlan::infer_with_answer_shape(query, AnswerShape::Inference)
            .with_derivation(RecallDerivation::GroundedInference)
            .reader_contract();
        assert_eq!(
            inference.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::HypothesisComparison
        );
        let method = RecallPlan::infer_with_answer_shape(
            "How did the coordinator introduce the technician?",
            AnswerShape::Relationship,
        )
        .reader_contract();
        assert_eq!(
            method.requested_answer_spec().role(),
            RequestedAnswerRole::Method
        );
        assert_eq!(
            method.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::CollectionLedger
        );
        let descriptor = RecallPlan::infer_with_answer_shape(
            "How does the coordinator describe the route?",
            AnswerShape::Relationship,
        )
        .reader_contract();
        assert_eq!(
            descriptor.requested_answer_spec().role(),
            RequestedAnswerRole::PredicateDescriptor
        );
        assert_eq!(
            descriptor.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::Direct
        );
        let untyped_relation = RecallPlan::infer_with_answer_shape(
            "Why do the coordinator and technician meet?",
            AnswerShape::Relationship,
        )
        .reader_contract();
        assert_eq!(untyped_relation.requested_value_target(), None);
        assert_eq!(
            untyped_relation.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::Direct
        );
    }

    #[test]
    fn relation_value_resolution_accepts_direct_and_permitted_public_values() {
        let public_contract = RecallPlan::infer_with_answer_shape(
            "Which country did the coordinator and technician plan to meet in?",
            AnswerShape::Relationship,
        )
        .reader_contract();
        let direct = scalar_relation_value_draft(
            "The coordinator and technician agreed to meet in Japan.",
            NodeId(7),
            "The meeting country is Japan.",
            NodeId(7),
            "Japan",
        );
        assert!(
            public_contract
                .validate_grounded_draft(&direct, &[NodeId(7)])
                .is_ok()
        );

        let public_projection = scalar_relation_value_draft(
            "The coordinator and technician agreed to meet in Boston.",
            NodeId(7),
            "Boston resolves by one stable public geographic relation to the United States.",
            NodeId(7),
            "United States",
        );
        assert!(
            public_contract
                .validate_grounded_draft(&public_projection, &[NodeId(7)])
                .is_ok()
        );

        let direct_only = RecallPlan::infer_with_answer_shape(
            "Which company did the coordinator and technician discuss?",
            AnswerShape::Relationship,
        )
        .reader_contract();
        assert!(!direct_only.allows_public_one_hop());
        assert_eq!(
            direct_only.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::RelationValueResolution
        );
        assert!(
            direct_only
                .instruction(RecallReaderStage::Answer)
                .contains("does not authorize a public projection")
        );
        let separate_direct_source = scalar_relation_value_draft(
            "The coordinator and technician discussed the selected vendor.",
            NodeId(7),
            "The selected vendor is Northwind.",
            NodeId(9),
            "Northwind",
        );
        assert!(
            direct_only
                .validate_grounded_draft(&separate_direct_source, &[NodeId(7), NodeId(9)])
                .is_ok(),
            "a directly grounded requested value may have a distinct delivered source"
        );
    }

    #[test]
    fn relation_value_resolution_enforces_roles_coherence_and_bounded_recovery() {
        let contract = RecallPlan::infer_with_answer_shape(
            "Which country did the coordinator and technician plan to meet in?",
            AnswerShape::Relationship,
        )
        .reader_contract();
        let valid = || {
            scalar_relation_value_draft(
                "The coordinator and technician agreed to meet in Boston.",
                NodeId(7),
                "Boston resolves by one stable public geographic relation to the United States.",
                NodeId(7),
                "United States",
            )
        };

        let mut reversed = valid();
        reversed
            .reasoning_operator
            .as_mut()
            .expect("typed operator")
            .inputs
            .swap(0, 1);
        let reversed_error = contract
            .validate_grounded_draft(&reversed, &[NodeId(7)])
            .expect_err("the relation anchor must precede its resolved value");
        assert!(
            reversed_error
                .failures
                .contains(&GroundedDraftValidationFailure::RelationPremiseMustPrecedeAnswerValue)
        );

        let mut overlapping = valid();
        overlapping
            .reasoning_operator
            .as_mut()
            .expect("typed operator")
            .inputs[0]
            .finding_ids = vec!["value".to_owned()];
        let overlapping_error = contract
            .validate_grounded_draft(&overlapping, &[NodeId(7)])
            .expect_err("one finding cannot be both relation anchor and answer value");
        assert!(overlapping_error.failures.contains(
            &GroundedDraftValidationFailure::RelationFindingUsedByBothRoles { finding_index: 1 }
        ));

        let mut wrong_dispositions = valid();
        wrong_dispositions.findings[0].disposition = GroundedFindingDisposition::Item;
        wrong_dispositions.findings[0].answer_value = Some("Boston".to_owned());
        wrong_dispositions.findings[1].disposition = GroundedFindingDisposition::Premise;
        wrong_dispositions.findings[1].answer_value = None;
        let disposition_error = contract
            .validate_grounded_draft(&wrong_dispositions, &[NodeId(7)])
            .expect_err("operator roles require distinct matching dispositions");
        for (finding_index, role) in [
            (0, GroundedOperatorInputRole::Premise),
            (1, GroundedOperatorInputRole::AnswerValue),
        ] {
            assert!(disposition_error.failures.contains(
                &GroundedDraftValidationFailure::RelationFindingDispositionMismatch {
                    finding_index,
                    role,
                }
            ));
        }

        let mut omitted_anchor = valid();
        omitted_anchor.answer_items[0].finding_ids = vec!["value".to_owned()];
        let omitted_error = contract
            .validate_grounded_draft(&omitted_anchor, &[NodeId(7)])
            .expect_err("the sole answer item must consume the relation anchor");
        assert!(omitted_error.failures.contains(
            &GroundedDraftValidationFailure::RelationAnswerItemMissingOperatorFinding {
                finding_index: 0,
                role: GroundedOperatorInputRole::Premise,
            }
        ));

        let mut mismatched_value = valid();
        mismatched_value.findings[1].answer_value = Some("Japan".to_owned());
        let mismatch_error = contract
            .validate_grounded_draft(&mismatched_value, &[NodeId(7)])
            .expect_err("the resolved finding must equal the sole answer value");
        assert!(mismatch_error.failures.contains(
            &GroundedDraftValidationFailure::ItemFindingValueMismatch {
                finding_index: 1,
                item_index: 0,
            }
        ));

        let mut unresolved_competitor = valid();
        unresolved_competitor
            .reasoning_operator
            .as_mut()
            .expect("typed operator")
            .unresolved_competitors = vec!["Japan".to_owned()];
        let competitor_error = contract
            .validate_grounded_draft(&unresolved_competitor, &[NodeId(7)])
            .expect_err("a resolved scalar cannot retain a material competitor");
        assert!(
            competitor_error
                .failures
                .contains(&GroundedDraftValidationFailure::RelationValueHasUnresolvedCompetitors)
        );

        let mut ungrounded_anchor = valid();
        ungrounded_anchor.findings[0].source_node_ids.clear();
        let grounding_error = contract
            .validate_grounded_draft(&ungrounded_anchor, &[NodeId(7)])
            .expect_err("the relation premise must cite a delivered source");
        assert!(grounding_error.failures.contains(
            &GroundedDraftValidationFailure::MissingFindingCitation { finding_index: 0 }
        ));

        let mut outside_delivery_scope = valid();
        outside_delivery_scope.findings[0].source_node_ids = vec![NodeId(99)];
        outside_delivery_scope.answer_items[0]
            .source_node_ids
            .push(NodeId(99));
        outside_delivery_scope
            .cited_source_node_ids
            .push(NodeId(99));
        let scope_error = contract
            .validate_grounded_draft(&outside_delivery_scope, &[NodeId(7)])
            .expect_err("an undelivered source cannot ground the relation premise");
        assert!(scope_error.failures.contains(
            &GroundedDraftValidationFailure::UnknownFindingCitation {
                finding_index: 0,
                source_node_id: NodeId(99),
            }
        ));

        let unresolved = GroundedAnswerDraft::new("", Vec::new(), vec![NodeId(7)], true)
            .with_findings(vec![GroundedEvidenceFinding::new(
                "relation",
                "The delivered evidence grounds the requested relation but leaves its value ambiguous.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Premise,
            )])
            .with_reasoning_operator(
                GroundedReasoningOperator::new(
                    GroundedReasoningOperatorKind::RelationValueResolution,
                )
                .with_inputs(vec![GroundedOperatorInput::new(
                    GroundedOperatorInputRole::Premise,
                    vec!["relation".to_owned()],
                )])
                .with_unresolved_competitors(vec!["first value".to_owned(), "second value".to_owned()]),
            );
        assert!(
            contract
                .validate_grounded_draft(&unresolved, &[NodeId(7)])
                .is_ok(),
            "an honest unresolved draft may retain competitors and omit an output"
        );

        let repair_instruction = contract.system_repair_instruction(&reversed_error);
        assert!(repair_instruction.contains("place every source-grounded relation Premise input"));
        assert!(repair_instruction.contains("requires RelationValueResolution"));
        let mut recovery = GroundedDraftRecoveryState::new();
        assert_eq!(
            contract.action_after_adjudicated_draft(
                &mut recovery,
                ReaderFinalDisposition::Answer,
                GroundedDraftStatus::from_validation(
                    &contract.validate_grounded_draft(&reversed, &[NodeId(7)])
                ),
            ),
            GroundedReadoutAction::RepairAdjudicatedDraft
        );
        assert_eq!(
            contract.action_after_adjudicated_draft(
                &mut recovery,
                ReaderFinalDisposition::Answer,
                GroundedDraftStatus::Invalid,
            ),
            GroundedReadoutAction::PreserveDirectCandidate
        );
    }

    #[test]
    fn typed_binary_uses_polarity_output_with_an_assessed_proposition_item() {
        let contract = RecallPlan::infer("Does James live in Connecticut?").reader_contract();
        assert_eq!(contract.answer_form, ReaderAnswerForm::Binary);
        assert_eq!(
            contract.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::HypothesisComparison
        );
        let make_draft = |candidate: &str| {
            GroundedAnswerDraft::new(
                candidate,
                vec![
                    GroundedAnswerItem::new("Connecticut", vec![NodeId(7), NodeId(9)])
                        .with_finding_ids(vec!["f1".to_owned(), "f2".to_owned()]),
                ],
                vec![NodeId(7), NodeId(9)],
                false,
            )
            .with_findings(vec![
                GroundedEvidenceFinding::new(
                    "f1",
                    "James rents an apartment near McGee's bar.",
                    vec![NodeId(7)],
                    GroundedFindingDisposition::Item,
                )
                .with_answer_value("apartment near McGee's bar"),
                GroundedEvidenceFinding::new(
                    "f2",
                    "McGee's bar is the stable location anchor.",
                    vec![NodeId(9)],
                    GroundedFindingDisposition::Premise,
                ),
            ])
            .with_reasoning_operator(
                GroundedReasoningOperator::new(GroundedReasoningOperatorKind::HypothesisComparison)
                    .with_inputs(vec![GroundedOperatorInput::new(
                        GroundedOperatorInputRole::CandidateSupport,
                        vec!["f1".to_owned(), "f2".to_owned()],
                    )])
                    .with_compared_candidates(vec![GroundedComparedCandidate::new(
                        "Connecticut",
                        vec!["f1".to_owned(), "f2".to_owned()],
                    )])
                    .with_output(candidate),
            )
        };

        assert!(
            contract
                .validate_grounded_draft(
                    &make_draft("Yes — apartment near McGee's bar"),
                    &[NodeId(7), NodeId(9)]
                )
                .is_ok()
        );

        let bare_polarity = contract
            .validate_grounded_draft(&make_draft("Yes"), &[NodeId(7), NodeId(9)])
            .expect_err("bare polarity omits the required concrete support");
        assert!(
            bare_polarity
                .failures
                .contains(&GroundedDraftValidationFailure::BinaryCandidateMissingConcreteSupport)
        );
        let repair = contract.system_repair_instruction(&bare_polarity);
        assert!(repair.contains("shortest concrete discriminator or supporting phrase"));
        assert!(repair.contains("do not invent new evidence"));

        let mut recovery = GroundedDraftRecoveryState::new();
        assert_eq!(
            contract.action_after_adjudicated_draft(
                &mut recovery,
                ReaderFinalDisposition::Answer,
                GroundedDraftStatus::Invalid,
            ),
            GroundedReadoutAction::RepairAdjudicatedDraft
        );
        assert_eq!(
            contract.action_after_adjudicated_draft(
                &mut recovery,
                ReaderFinalDisposition::Answer,
                GroundedDraftStatus::Invalid,
            ),
            GroundedReadoutAction::PreserveDirectCandidate
        );

        let error = contract
            .validate_grounded_draft(&make_draft("Connecticut"), &[NodeId(7), NodeId(9)])
            .expect_err("a binary candidate must state its polarity");
        assert!(
            error
                .failures
                .contains(&GroundedDraftValidationFailure::BinaryCandidateMissingExplicitPolarity)
        );
    }

