    fn count_occurrence_item(
        id: &str,
        value: &str,
        occurrence_key: &str,
        actuality: GroundedOccurrenceActuality,
    ) -> GroundedEvidenceFinding {
        GroundedEvidenceFinding::new(
            id,
            format!("The record declares {value}."),
            vec![NodeId(7)],
            GroundedFindingDisposition::Item,
        )
        .with_answer_value(value)
        .with_occurrence_key(occurrence_key)
        .with_occurrence_actuality(actuality)
    }

    fn count_draft_from_findings(findings: Vec<GroundedEvidenceFinding>) -> GroundedAnswerDraft {
        let item_findings = findings
            .iter()
            .filter(|finding| finding.disposition() == GroundedFindingDisposition::Item)
            .collect::<Vec<_>>();
        let answer_items = item_findings
            .iter()
            .map(|finding| {
                GroundedAnswerItem::new(
                    finding.answer_value().unwrap_or_default(),
                    finding.source_node_ids().to_vec(),
                )
                .with_finding_ids(vec![finding.id().to_owned()])
            })
            .collect::<Vec<_>>();
        let item_ids = item_findings
            .iter()
            .map(|finding| finding.id().to_owned())
            .collect::<Vec<_>>();
        let count = answer_items.len().to_string();
        GroundedAnswerDraft::new(count.clone(), answer_items, vec![NodeId(7)], false)
            .with_findings(findings)
            .with_reasoning_operator(
                GroundedReasoningOperator::new(GroundedReasoningOperatorKind::CountLedger)
                    .with_inputs(vec![GroundedOperatorInput::new(
                        GroundedOperatorInputRole::Item,
                        item_ids,
                    )])
                    .with_output(count),
            )
    }

    #[test]
    fn strict_count_occurrence_ledger_counts_only_occurred_canonical_items() {
        let contract =
            RecallPlan::infer("How many maintenance visits were completed?").reader_contract();
        let mut findings = (1..=4)
            .map(|index| {
                count_occurrence_item(
                    &format!("f{index}"),
                    &format!("visit {index}"),
                    &format!("visit-{index}"),
                    GroundedOccurrenceActuality::Occurred,
                )
            })
            .collect::<Vec<_>>();
        findings.push(
            GroundedEvidenceFinding::new(
                "planned",
                "A fifth maintenance visit is planned.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Excluded,
            )
            .with_occurrence_key("visit-5")
            .with_occurrence_actuality(GroundedOccurrenceActuality::Planned)
            .with_exclusion_reason("The visit is planned rather than completed."),
        );
        let draft = count_draft_from_findings(findings);

        assert_eq!(
            contract.materialize_adjudicated_draft(&draft, &[NodeId(7)]),
            Ok(Some("4".to_owned())),
            "one source may support several independently identified occurrences"
        );
    }

    #[test]
    fn strict_count_occurrence_ledger_rejects_non_occurred_or_incomplete_items() {
        let contract =
            RecallPlan::infer("How many maintenance visits were completed?").reader_contract();
        let planned = count_draft_from_findings(vec![count_occurrence_item(
            "f1",
            "planned visit",
            "visit-1",
            GroundedOccurrenceActuality::Planned,
        )]);
        let error = contract
            .validate_adjudicated_draft(&planned, &[NodeId(7)])
            .expect_err("a planned occurrence cannot enter a retrospective count");
        assert!(error.failures.contains(
            &GroundedDraftValidationFailure::CountOccurrenceNotOccurred {
                finding_index: 0,
                actuality: GroundedOccurrenceActuality::Planned,
            }
        ));

        let incomplete = count_draft_from_findings(vec![
            count_occurrence_item(
                "f1",
                "first visit",
                "visit-1",
                GroundedOccurrenceActuality::Occurred,
            ),
            GroundedEvidenceFinding::new(
                "f2",
                "The record declares a second visit.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Item,
            )
            .with_answer_value("second visit"),
        ]);
        let error = contract
            .validate_adjudicated_draft(&incomplete, &[NodeId(7)])
            .expect_err("strict mode requires identity and actuality on every count item");
        assert!(error.failures.contains(
            &GroundedDraftValidationFailure::MissingCountOccurrenceKey { finding_index: 1 }
        ));
        assert!(error.failures.contains(
            &GroundedDraftValidationFailure::MissingCountOccurrenceActuality { finding_index: 1 }
        ));
    }

    #[test]
    fn strict_count_occurrence_ledger_merges_duplicates_under_one_canonical_finding() {
        let contract =
            RecallPlan::infer("How many maintenance visits were completed?").reader_contract();
        let duplicate = GroundedEvidenceFinding::new(
            "photo",
            "A photo shows the same completed visit.",
            vec![NodeId(7)],
            GroundedFindingDisposition::Excluded,
        )
        .with_occurrence_key("visit-1")
        .with_occurrence_actuality(GroundedOccurrenceActuality::Occurred)
        .with_duplicate_of("canonical")
        .with_exclusion_reason("This is another representation of the canonical visit.");
        let draft = count_draft_from_findings(vec![
            count_occurrence_item(
                "canonical",
                "first visit",
                "visit-1",
                GroundedOccurrenceActuality::Occurred,
            ),
            duplicate,
        ]);

        assert_eq!(
            contract.materialize_adjudicated_draft(&draft, &[NodeId(7)]),
            Ok(Some("1".to_owned()))
        );

        let duplicate_items = count_draft_from_findings(vec![
            count_occurrence_item(
                "f1",
                "first record",
                "visit-1",
                GroundedOccurrenceActuality::Occurred,
            ),
            count_occurrence_item(
                "f2",
                "second record",
                "visit-1",
                GroundedOccurrenceActuality::Occurred,
            ),
        ]);
        let error = contract
            .validate_adjudicated_draft(&duplicate_items, &[NodeId(7)])
            .expect_err("one occurrence identity cannot contribute two count items");
        assert!(error.failures.contains(
            &GroundedDraftValidationFailure::DuplicateCountOccurrenceKey {
                first_finding_index: 0,
                duplicate_finding_index: 1,
            }
        ));
    }

    #[test]
    fn strict_count_occurrence_ledger_rejects_invalid_duplicate_graphs_and_consumption() {
        let contract =
            RecallPlan::infer("How many maintenance visits were completed?").reader_contract();
        let canonical = || {
            count_occurrence_item(
                "canonical",
                "first visit",
                "visit-1",
                GroundedOccurrenceActuality::Occurred,
            )
        };
        let excluded_duplicate = |id: &str, target: &str| {
            GroundedEvidenceFinding::new(
                id,
                "Another representation was inspected.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Excluded,
            )
            .with_duplicate_of(target)
            .with_exclusion_reason("Duplicate representation.")
        };
        let typed_duplicate = |id: &str, target: &str, occurrence_key: &str| {
            excluded_duplicate(id, target)
                .with_occurrence_key(occurrence_key)
                .with_occurrence_actuality(GroundedOccurrenceActuality::Occurred)
        };

        for (label, findings, rejected_indices) in [
            (
                "self",
                vec![canonical(), excluded_duplicate("self", "self")],
                vec![1],
            ),
            (
                "dangling",
                vec![canonical(), excluded_duplicate("dangling", "missing")],
                vec![1],
            ),
            (
                "cycle",
                vec![
                    canonical(),
                    excluded_duplicate("cycle-a", "cycle-b"),
                    excluded_duplicate("cycle-b", "cycle-a"),
                ],
                vec![1, 2],
            ),
        ] {
            let error = contract
                .validate_adjudicated_draft(&count_draft_from_findings(findings), &[NodeId(7)])
                .expect_err("invalid duplicate graphs must fail closed");
            for finding_index in rejected_indices {
                assert!(
                    error.failures.contains(
                        &GroundedDraftValidationFailure::InvalidDuplicateOccurrenceTarget {
                            finding_index,
                        }
                    ),
                    "case={label}, failures={:?}",
                    error.failures
                );
            }
        }

        let premise_target = GroundedEvidenceFinding::new(
            "premise-target",
            "Context mentions another record.",
            vec![NodeId(7)],
            GroundedFindingDisposition::Premise,
        )
        .with_occurrence_key("premise-key")
        .with_occurrence_actuality(GroundedOccurrenceActuality::Occurred);
        let excluded_target = GroundedEvidenceFinding::new(
            "excluded-target",
            "A planned record was excluded.",
            vec![NodeId(7)],
            GroundedFindingDisposition::Excluded,
        )
        .with_occurrence_key("excluded-key")
        .with_occurrence_actuality(GroundedOccurrenceActuality::Planned)
        .with_exclusion_reason("The record did not occur.");
        for (label, target, duplicate) in [
            (
                "premise target",
                premise_target,
                typed_duplicate("duplicate", "premise-target", "premise-key"),
            ),
            (
                "excluded target",
                excluded_target,
                typed_duplicate("duplicate", "excluded-target", "excluded-key"),
            ),
        ] {
            let error = contract
                .validate_adjudicated_draft(
                    &count_draft_from_findings(vec![canonical(), target, duplicate]),
                    &[NodeId(7)],
                )
                .expect_err("a duplicate must target an occurred canonical item");
            assert!(
                error.failures.contains(
                    &GroundedDraftValidationFailure::InvalidDuplicateOccurrenceTarget {
                        finding_index: 2,
                    }
                ),
                "case={label}, failures={:?}",
                error.failures
            );
        }

        for (label, duplicate) in [
            (
                "mismatched key",
                typed_duplicate("duplicate", "canonical", "different-visit"),
            ),
            (
                "missing actuality",
                excluded_duplicate("duplicate", "canonical").with_occurrence_key("visit-1"),
            ),
        ] {
            let error = contract
                .validate_adjudicated_draft(
                    &count_draft_from_findings(vec![canonical(), duplicate]),
                    &[NodeId(7)],
                )
                .expect_err("duplicate metadata must match the canonical occurrence");
            assert!(
                error.failures.contains(
                    &GroundedDraftValidationFailure::InvalidDuplicateOccurrenceMetadata {
                        finding_index: 1,
                    }
                ),
                "case={label}, failures={:?}",
                error.failures
            );
        }

        let promoted_duplicate = count_draft_from_findings(vec![
            canonical(),
            count_occurrence_item(
                "promoted",
                "duplicate visit record",
                "visit-2",
                GroundedOccurrenceActuality::Occurred,
            )
            .with_duplicate_of("canonical"),
        ]);
        let error = contract
            .validate_adjudicated_draft(&promoted_duplicate, &[NodeId(7)])
            .expect_err("duplicate metadata requires an excluded finding");
        assert!(error.failures.contains(
            &GroundedDraftValidationFailure::CountItemHasDuplicateReference { finding_index: 1 }
        ));
        assert!(error.failures.contains(
            &GroundedDraftValidationFailure::DuplicateOccurrenceFindingNotExcluded {
                finding_index: 1,
            }
        ));

        let mut consumed_duplicate = count_draft_from_findings(vec![
            canonical(),
            excluded_duplicate("duplicate", "canonical"),
        ]);
        consumed_duplicate.answer_items[0] =
            GroundedAnswerItem::new("first visit", vec![NodeId(7)])
                .with_finding_ids(vec!["canonical".to_owned(), "duplicate".to_owned()]);
        consumed_duplicate.reasoning_operator = Some(
            GroundedReasoningOperator::new(GroundedReasoningOperatorKind::CountLedger)
                .with_inputs(vec![GroundedOperatorInput::new(
                    GroundedOperatorInputRole::Item,
                    vec!["canonical".to_owned(), "duplicate".to_owned()],
                )])
                .with_output("1"),
        );
        let error = contract
            .validate_adjudicated_draft(&consumed_duplicate, &[NodeId(7)])
            .expect_err("an excluded duplicate cannot enter items or operator inputs");
        assert!(error.failures.iter().any(|failure| matches!(
            failure,
            GroundedDraftValidationFailure::ExcludedFindingReferencedByAnswerItem {
                finding_index: 1,
                ..
            }
        )));
        assert!(error.failures.contains(
            &GroundedDraftValidationFailure::ExcludedFindingReferencedByOperatorInput {
                finding_index: 1,
            }
        ));
    }

    #[test]
    fn strict_count_failure_preserves_legacy_counts_and_direct_recovery_bytes() {
        let contract =
            RecallPlan::infer("How many maintenance visits were completed?").reader_contract();
        let legacy = GroundedAnswerDraft::new(
            "1",
            vec![
                GroundedAnswerItem::new("first visit", vec![NodeId(7)])
                    .with_finding_ids(vec!["f1".to_owned()]),
            ],
            vec![NodeId(7)],
            false,
        )
        .with_findings(vec![
            GroundedEvidenceFinding::new(
                "f1",
                "The first maintenance visit completed.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Item,
            )
            .with_answer_value("first visit"),
        ])
        .with_reasoning_operator(
            GroundedReasoningOperator::new(GroundedReasoningOperatorKind::CountLedger)
                .with_inputs(vec![GroundedOperatorInput::new(
                    GroundedOperatorInputRole::Item,
                    vec!["f1".to_owned()],
                )])
                .with_output("1"),
        );
        assert_eq!(
            contract.materialize_adjudicated_draft(&legacy, &[NodeId(7)]),
            Ok(Some("1".to_owned())),
            "absence of all occurrence metadata preserves the legacy wire"
        );

        let invalid = count_draft_from_findings(vec![count_occurrence_item(
            "f1",
            "planned visit",
            "visit-1",
            GroundedOccurrenceActuality::Planned,
        )]);
        let validation = contract.validate_adjudicated_draft(&invalid, &[NodeId(7)]);
        assert_eq!(
            GroundedDraftStatus::from_validation(&validation),
            GroundedDraftStatus::Invalid
        );
        let direct_candidate = "  Four completed visits.  ";
        let mut recovery = GroundedDraftRecoveryState::new();
        assert_eq!(
            contract.action_after_adjudicated_draft(
                &mut recovery,
                ReaderFinalDisposition::Answer,
                GroundedDraftStatus::Invalid,
            ),
            GroundedReadoutAction::RepairAdjudicatedDraft
        );
        let preserved = match contract.action_after_adjudicated_draft(
            &mut recovery,
            ReaderFinalDisposition::Answer,
            GroundedDraftStatus::Invalid,
        ) {
            GroundedReadoutAction::PreserveDirectCandidate => direct_candidate,
            _ => "",
        };
        assert_eq!(preserved.as_bytes(), direct_candidate.as_bytes());
    }

    #[test]
    fn count_ledger_uses_one_structural_item_finding_per_unit() {
        let contract =
            RecallPlan::infer("How many maintenance visits were completed?").reader_contract();
        let mut draft = GroundedAnswerDraft::new(
            "2",
            vec![
                GroundedAnswerItem::new("first visit", vec![NodeId(7)])
                    .with_finding_ids(vec!["f1".to_owned(), "p1".to_owned()]),
                GroundedAnswerItem::new("second visit", vec![NodeId(7)])
                    .with_finding_ids(vec!["f2".to_owned(), "p1".to_owned()]),
            ],
            vec![NodeId(7)],
            false,
        )
        .with_findings(vec![
            GroundedEvidenceFinding::new(
                "f1",
                "The first maintenance visit completed.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Item,
            )
            .with_answer_value("first visit"),
            GroundedEvidenceFinding::new(
                "f2",
                "The second maintenance visit completed.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Item,
            )
            .with_answer_value("second visit"),
            GroundedEvidenceFinding::new(
                "p1",
                "Both records refer to completed maintenance.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Premise,
            ),
        ])
        .with_reasoning_operator(
            GroundedReasoningOperator::new(GroundedReasoningOperatorKind::CountLedger)
                .with_inputs(vec![
                    GroundedOperatorInput::new(
                        GroundedOperatorInputRole::Item,
                        vec!["f1".to_owned(), "f2".to_owned()],
                    ),
                    GroundedOperatorInput::new(
                        GroundedOperatorInputRole::Premise,
                        vec!["p1".to_owned()],
                    ),
                ])
                .with_output("2"),
        );

        assert!(
            contract
                .validate_adjudicated_draft(&draft, &[NodeId(7)])
                .is_ok(),
            "one source may establish several independently represented units"
        );

        draft.answer_items = vec![
            GroundedAnswerItem::new("two visits", vec![NodeId(7)]).with_finding_ids(vec![
                "f1".to_owned(),
                "f2".to_owned(),
                "p1".to_owned(),
            ]),
        ];
        draft.candidate_answer = "1".to_owned();
        draft.reasoning_operator = draft
            .reasoning_operator
            .take()
            .map(|operator| operator.with_output("1"));
        let error = contract
            .validate_adjudicated_draft(&draft, &[NodeId(7)])
            .expect_err("two countable units cannot share one ledger entry");
        assert!(
            error
                .failures
                .contains(&GroundedDraftValidationFailure::LedgerItemFindingCount {
                    item_index: 0,
                    actual_count: 2,
                })
        );
    }

    #[test]
    fn frequency_cadence_accepts_a_schedule_or_three_occurrences() {
        let contract = RecallPlan::infer("How often does the technician inspect the filter?")
            .reader_contract();
        assert_eq!(
            contract.required_reasoning_operator_kind(),
            GroundedReasoningOperatorKind::FrequencyCadence
        );

        let occurrence_findings = ["2025-01-01", "2025-02-01", "2025-03-01"]
            .into_iter()
            .enumerate()
            .map(|(index, date)| {
                GroundedEvidenceFinding::new(
                    format!("f{}", index + 1),
                    format!("The filter was inspected on {date}."),
                    vec![NodeId(7)],
                    GroundedFindingDisposition::Item,
                )
                .with_answer_value(date)
            })
            .collect::<Vec<_>>();
        let occurrence_items = ["2025-01-01", "2025-02-01", "2025-03-01"]
            .into_iter()
            .enumerate()
            .map(|(index, date)| {
                GroundedAnswerItem::new(date, vec![NodeId(7)])
                    .with_finding_ids(vec![format!("f{}", index + 1)])
            })
            .collect::<Vec<_>>();
        let occurrence_draft =
            GroundedAnswerDraft::new("about monthly", occurrence_items, vec![NodeId(7)], false)
                .with_findings(occurrence_findings)
                .with_reasoning_operator(
                    GroundedReasoningOperator::new(GroundedReasoningOperatorKind::FrequencyCadence)
                        .with_inputs(vec![GroundedOperatorInput::new(
                            GroundedOperatorInputRole::Item,
                            vec!["f1".to_owned(), "f2".to_owned(), "f3".to_owned()],
                        )])
                        .with_output("about monthly"),
                );
        assert_eq!(
            contract.materialize_adjudicated_draft(&occurrence_draft, &[NodeId(7)]),
            Ok(Some("about monthly".to_owned()))
        );
        let mut quoted_occurrence_draft = occurrence_draft.clone();
        quoted_occurrence_draft.candidate_answer = "\"about monthly\"".to_owned();
        quoted_occurrence_draft.reasoning_operator = quoted_occurrence_draft
            .reasoning_operator
            .take()
            .map(|operator| operator.with_output("about monthly"));
        assert_eq!(
            contract.materialize_adjudicated_draft(&quoted_occurrence_draft, &[NodeId(7)]),
            Ok(Some("about monthly".to_owned()))
        );

        let mut insufficient = occurrence_draft.clone();
        insufficient.findings.truncate(2);
        insufficient.answer_items.truncate(2);
        insufficient.reasoning_operator = Some(
            GroundedReasoningOperator::new(GroundedReasoningOperatorKind::FrequencyCadence)
                .with_inputs(vec![GroundedOperatorInput::new(
                    GroundedOperatorInputRole::Item,
                    vec!["f1".to_owned(), "f2".to_owned()],
                )])
                .with_output("about monthly"),
        );
        let error = contract
            .validate_adjudicated_draft(&insufficient, &[NodeId(7)])
            .expect_err("two observations do not establish a regular cadence");
        assert!(error.failures.contains(
            &GroundedDraftValidationFailure::InsufficientFrequencyOccurrences { actual_count: 2 }
        ));

        let schedule = GroundedAnswerDraft::new(
            "every Tuesday",
            vec![
                GroundedAnswerItem::new("every Tuesday", vec![NodeId(9)])
                    .with_finding_ids(vec!["schedule".to_owned()]),
            ],
            vec![NodeId(9)],
            false,
        )
        .with_findings(vec![
            GroundedEvidenceFinding::new(
                "schedule",
                "The routine inspection is scheduled every Tuesday.",
                vec![NodeId(9)],
                GroundedFindingDisposition::Item,
            )
            .with_answer_value("every Tuesday"),
        ])
        .with_reasoning_operator(
            GroundedReasoningOperator::new(GroundedReasoningOperatorKind::FrequencyCadence)
                .with_inputs(vec![GroundedOperatorInput::new(
                    GroundedOperatorInputRole::ExplicitSchedule,
                    vec!["schedule".to_owned()],
                )])
                .with_output("every Tuesday"),
        );
        assert_eq!(
            contract.materialize_adjudicated_draft(&schedule, &[NodeId(9)]),
            Ok(Some("every Tuesday".to_owned()))
        );
    }

