    #[test]
    fn reader_contract_keeps_requested_value_distinct_from_its_anchor() {
        let contract =
            RecallPlan::infer("In which state is the shelter located?").reader_contract();
        assert_eq!(contract.plan.answer_shape, AnswerShape::Fact);
        assert!(contract.reflection_recommended());
        assert!(contract.allows_public_one_hop());

        let composer =
            RecallPlan::infer("Which popular music composer's tunes does the pianist play?")
                .reader_contract();
        assert_eq!(composer.plan.answer_shape, AnswerShape::Fact);
        assert!(composer.reflection_recommended());

        for stage in [
            RecallReaderStage::Answer,
            RecallReaderStage::Reflection,
            RecallReaderStage::Verification,
            RecallReaderStage::Repair,
        ] {
            let instruction = contract.instruction(stage);
            assert!(instruction.contains("requested"), "stage: {stage:?}");
            assert!(instruction.contains("state"), "stage: {stage:?}");
            assert!(instruction.contains("anchor"), "stage: {stage:?}");
            assert!(instruction.contains("one-hop relation"), "stage: {stage:?}");
        }

        let answer = contract.instruction(RecallReaderStage::Answer);
        assert!(answer.contains("do not return the anchor"));
        assert!(answer.contains("Requested answer type: state"));

        let guidance = contract.context_guidance();
        assert!(guidance.contains("Requested answer type: state"));
        assert!(guidance.contains("return the requested value itself rather than a nearby anchor"));

        let personal = RecallPlan::infer("Which company hired the engineer?").reader_contract();
        assert!(!personal.allows_public_one_hop());
        assert!(
            !personal
                .instruction(RecallReaderStage::Answer)
                .contains("permits one stable public one-hop relation step")
        );

        let plural = RecallPlan::infer("Which countries contain the sites?")
            .reader_contract()
            .instruction(RecallReaderStage::Answer);
        assert!(plural.contains("Requested answer type: countries"));
        assert!(!plural.contains("a countries"));
    }

    #[test]
    fn production_rule_separates_public_relation_depth_from_result_cardinality() {
        let possible_plural = RecallPlan::infer("Which countries might contain the relay sites?");
        let possible_contract = possible_plural.reader_contract();
        assert_eq!(possible_plural.answer_shape, AnswerShape::Collection);
        assert_eq!(
            possible_contract.requested_answer_spec().modality(),
            RequestedAnswerModality::Possible
        );
        assert!(matches!(
            possible_contract.requested_answer_spec().cardinality(),
            RequestedAnswerCardinality::Multiple | RequestedAnswerCardinality::Exhaustive
        ));
        assert_eq!(
            possible_contract.requested_value_target(),
            Some("countries")
        );

        for stage in [
            RecallReaderStage::Answer,
            RecallReaderStage::Reflection,
            RecallReaderStage::Verification,
            RecallReaderStage::Repair,
        ] {
            let instruction = possible_contract.instruction(stage);
            for required in [
                "permits one stable public one-hop relation step",
                "limits relation depth, not result cardinality",
                "multiple grounded anchors independently",
                "one specific grounded entity",
                "explicitly closed, small, stable, and canonical",
                "distinct item finding and ledger entry",
                "neither a grounded anchor nor an intermediate relation value",
                "never use public knowledge to invent a personal",
            ] {
                assert!(
                    instruction.contains(required),
                    "stage {stage:?} omitted {required:?}"
                );
            }
        }

        let possible_guidance = product_reader_guidance_for_plan(&possible_plural);
        assert!(possible_guidance.contains("limits relation depth, not result cardinality"));
        assert!(possible_guidance.contains("distinct item finding and ledger entry"));
        assert_eq!(
            possible_contract
                .context_guidance()
                .matches("limits relation depth, not result cardinality")
                .count(),
            1
        );

        let factual_plural =
            RecallPlan::infer("Which countries contain the relay sites?").reader_contract();
        assert_eq!(
            factual_plural.requested_answer_spec().modality(),
            RequestedAnswerModality::Factual
        );
        assert!(
            factual_plural
                .instruction(RecallReaderStage::Answer)
                .contains("map multiple grounded anchors independently")
        );
        assert!(
            !factual_plural
                .instruction(RecallReaderStage::Answer)
                .contains("For this possible multi-value request")
        );

        let singular =
            RecallPlan::infer("In which country is the relay station located?").reader_contract();
        assert_eq!(
            singular.requested_answer_spec().modality(),
            RequestedAnswerModality::Factual
        );
        assert_eq!(
            singular.requested_answer_spec().cardinality(),
            RequestedAnswerCardinality::One
        );
        let singular_instruction = singular.instruction(RecallReaderStage::Answer);
        assert!(singular_instruction.contains("For this singular factual request"));
        assert!(singular_instruction.contains("exactly one stable, unambiguous"));
        assert!(singular_instruction.contains("do not choose arbitrarily"));
    }

    #[test]
    fn production_rule_bounds_unnamed_modal_identity_fulfillment() {
        for query in [
            "Which software company likely hired the developer?",
            "Which software company might have hired the developer?",
        ] {
            let plan = RecallPlan::infer(query);
            let contract = plan.reader_contract();
            assert_eq!(plan.answer_shape, AnswerShape::Inference, "query: {query}");
            assert_eq!(
                plan.derivation,
                RecallDerivation::GroundedInference,
                "query: {query}"
            );
            assert_eq!(
                contract.requested_answer_spec().cardinality(),
                RequestedAnswerCardinality::One,
                "query: {query}"
            );
            assert!(matches!(
                contract.requested_answer_spec().modality(),
                RequestedAnswerModality::Likely | RequestedAnswerModality::Possible
            ));
            assert_eq!(contract.requested_value_target(), Some("software company"));
            assert_eq!(
                contract.required_reasoning_operator_kind(),
                GroundedReasoningOperatorKind::HypothesisComparison
            );

            for stage in [
                RecallReaderStage::Answer,
                RecallReaderStage::Reflection,
                RecallReaderStage::Verification,
                RecallReaderStage::Repair,
            ] {
                let instruction = contract.instruction(stage);
                for required in [
                    "HypothesisComparison",
                    "CandidateSupport",
                    "same subject",
                    "candidate-specific preference or intention",
                    "later actually fulfills",
                    "need not repeat the candidate name",
                    "mere list mention",
                    "different relation",
                    "equally or more strongly supported competitor",
                    "concrete contradiction",
                ] {
                    assert!(
                        instruction.contains(required),
                        "query {query:?}, stage {stage:?} omitted {required:?}"
                    );
                }
            }
            assert!(
                product_reader_guidance_for_plan(&plan)
                    .contains("later actually fulfills the same compatible role or category")
            );
        }

        for control in [
            "Which software company hired the developer?",
            "Which software companies might hire the developers?",
            "What might happen next?",
        ] {
            assert!(
                !RecallPlan::infer(control)
                    .reader_contract()
                    .instruction(RecallReaderStage::Answer)
                    .contains(NAMED_PREFERENCE_FULFILLMENT_RULE),
                "control unexpectedly enabled unnamed fulfillment: {control}"
            );
        }
    }

    #[test]
    fn reader_contract_emits_stage_and_shape_specific_rules() {
        let contract =
            RecallPlan::infer("How often did the worker renew its lease?").reader_contract();
        let reflection = contract.instruction(RecallReaderStage::Reflection);
        assert!(reflection.contains("every slot"));
        assert!(reflection.contains("source id"));
        assert!(reflection.contains("supported cadence"));

        let verification = contract.instruction(RecallReaderStage::Verification);
        assert!(verification.contains("Treat the draft as untrusted"));
        assert!(verification.contains("verified temporal arithmetic"));
        assert!(verification.contains("do not replace it with an abstention"));
        assert!(verification.contains("shortest verified complete answer"));

        let inference = RecallPlan::infer("Might the worker use the retry queue?")
            .reader_contract()
            .instruction(RecallReaderStage::Reflection);
        assert!(inference.contains("best-supported plausible conclusion"));
        assert!(inference.contains("without requiring the source"));

        let count =
            RecallPlan::infer("How many deployments did the worker complete?").reader_contract();
        assert!(
            count
                .instruction(RecallReaderStage::Reflection)
                .contains("source-cited event ledger")
        );
        assert!(
            count
                .instruction(RecallReaderStage::Verification)
                .contains("Recompute the count")
        );
        assert!(
            count
                .instruction(RecallReaderStage::Verification)
                .contains("rescan the whole delivered evidence")
        );
    }

