    #[test]
    fn production_rule_keeps_scheduled_time_across_later_ongoing_observations() {
        let plan = RecallPlan::infer("When did the certification course take place?");
        assert_eq!(plan.answer_shape, AnswerShape::Temporal);
        let contract = plan.reader_contract();

        for stage in [
            RecallReaderStage::Answer,
            RecallReaderStage::Reflection,
            RecallReaderStage::Verification,
            RecallReaderStage::Repair,
        ] {
            let instruction = contract.instruction(stage);
            for required in [
                "scheduled absolute or relative time",
                "same event is underway",
                "without its own start or event date",
                "Resolve a relative schedule against that source's observation time",
                "not a replacement start or event date",
                "same subject and event identity rather than topic similarity",
                "reschedules, postpones, cancels",
                "do not treat the schedule alone as proof of completion",
            ] {
                assert!(
                    instruction.contains(required),
                    "stage {stage:?} omitted {required:?}"
                );
            }
        }

        assert!(
            contract
                .context_guidance()
                .contains("later underway observation")
        );
        assert!(
            !RecallPlan::infer("How long did the certification course take?")
                .reader_contract()
                .instruction(RecallReaderStage::Answer)
                .contains(TEMPORAL_SCHEDULE_IDENTITY_RULE)
        );
    }

    #[test]
    fn unresolved_reverification_is_independent_of_the_failed_draft() {
        let contract = RecallPlan::infer("Would Alice take another trip soon?").reader_contract();
        let instruction = contract.unresolved_reverification_instruction();

        assert!(instruction.contains("independent verification pass"));
        assert!(instruction.contains("untrusted control state, not evidence"));
        assert!(instruction.contains("do not copy or require its proposed slots"));
        assert!(instruction.contains("full current contract is authoritative"));
        assert!(instruction.contains("requested modality"));
    }

    #[test]
    fn grounded_inference_collection_combines_modality_and_complete_item_ledgers() {
        let inferred = RecallPlan::infer("What personality traits might the operator have?");
        assert_eq!(inferred.answer_shape, AnswerShape::Collection);
        assert_eq!(inferred.derivation, RecallDerivation::GroundedInference);
        assert!(inferred.reader_contract().reflection_recommended());

        for stage in [
            RecallReaderStage::Answer,
            RecallReaderStage::Reflection,
            RecallReaderStage::Verification,
        ] {
            let instruction = inferred.reader_contract().instruction(stage);
            assert!(
                instruction.contains("every") || instruction.contains("complete"),
                "stage: {stage:?}"
            );
            assert!(instruction.contains("modality"), "stage: {stage:?}");
            assert!(instruction.contains("one-hop bridge"), "stage: {stage:?}");
            assert!(instruction.contains("alternative"), "stage: {stage:?}");
            assert!(
                instruction.contains("source-specific action, object, or value"),
                "stage: {stage:?}"
            );
            assert!(
                instruction.contains("broad topic label"),
                "stage: {stage:?}"
            );
        }

        let overridden = RecallPlan::infer("List the supported traits.")
            .with_derivation(RecallDerivation::GroundedInference);
        assert_eq!(overridden.answer_shape, AnswerShape::Collection);
        assert_eq!(overridden.derivation, RecallDerivation::GroundedInference);
        assert!(
            overridden
                .reader_contract()
                .context_guidance()
                .contains("distinct plausible item")
        );
    }

    #[test]
    fn duration_reader_contract_requires_a_grounded_event_chain() {
        for query in [
            "How long did the vehicle restoration take?",
            "What was the elapsed time of the migration?",
            "What was the duration of the incident?",
            "복원 작업은 얼마 동안 진행됐어?",
        ] {
            let plan = RecallPlan::infer(query);
            assert_eq!(plan.answer_shape, AnswerShape::Temporal, "query: {query}");
            assert_eq!(plan.recall_intent, RecallIntent::Temporal, "query: {query}");
            assert!(plan.reader_contract().reflection_recommended());
        }

        let contract =
            RecallPlan::infer("How long did the vehicle restoration take?").reader_contract();
        let reflection = contract.instruction(RecallReaderStage::Reflection);
        for required_slot in [
            "entity identity",
            "start or projection",
            "intervening progress",
            "completion or end",
            "elapsed duration",
        ] {
            assert!(
                reflection.contains(required_slot),
                "missing duration slot: {required_slot}"
            );
        }
        assert!(reflection.contains("exact source ids"));
        assert!(reflection.contains("same speaker"));
        assert!(reflection.contains("same-session linkage"));
        assert!(reflection.contains("cross-session event continuity"));
        assert!(reflection.contains("lexical similarity alone is insufficient"));
        assert!(reflection.contains("projection as a forecast"));
        assert!(reflection.contains("whole delivered evidence"));

        let answer = contract.instruction(RecallReaderStage::Answer);
        assert!(answer.contains("source-grounded chronological event chain"));
        assert!(answer.contains("explicit source-stated duration"));
        assert!(answer.contains("grounded start and completion or end timestamps"));
        assert!(answer.contains("never use retrieval time"));

        let verification = contract.instruction(RecallReaderStage::Verification);
        assert!(verification.contains("Rebuild the source-cited chronological event chain"));
        assert!(verification.contains("before accepting the draft or an abstention"));
        assert!(verification.contains("same-speaker ownership"));
        assert!(verification.contains("recompute elapsed time"));

        let guidance = contract.context_guidance();
        assert!(guidance.contains("source-grounded chronological event chain"));
        assert!(guidance.contains("same-speaker ownership"));
        assert!(guidance.contains("cross-session event continuity"));
        assert!(guidance.contains("never use retrieval time"));
    }

    fn temporal_point_draft(
        candidate: &str,
        reference_value: &str,
        duration_value: &str,
        inputs: Vec<GroundedOperatorInput>,
        duration_source_node_ids: Vec<NodeId>,
    ) -> GroundedAnswerDraft {
        GroundedAnswerDraft::new(
            candidate,
            vec![
                GroundedAnswerItem::new(candidate, vec![NodeId(7), NodeId(9)])
                    .with_finding_ids(vec!["reference".to_owned(), "duration".to_owned()]),
            ],
            vec![NodeId(7), NodeId(9)],
            false,
        )
        .with_findings(vec![
            GroundedEvidenceFinding::new(
                "reference",
                "The source observation was recorded on 2023-08-23.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Premise,
            )
            .with_answer_value(reference_value),
            GroundedEvidenceFinding::new(
                "duration",
                format!("The event had begun {duration_value} before that observation."),
                duration_source_node_ids,
                GroundedFindingDisposition::Premise,
            )
            .with_answer_value(duration_value),
        ])
        .with_reasoning_operator(
            GroundedReasoningOperator::new(GroundedReasoningOperatorKind::TemporalPoint)
                .with_inputs(inputs)
                .with_output(candidate),
        )
    }

    fn valid_temporal_point_inputs() -> Vec<GroundedOperatorInput> {
        vec![
            GroundedOperatorInput::new(
                GroundedOperatorInputRole::ReferenceTime,
                vec!["reference".to_owned()],
            ),
            GroundedOperatorInput::new(
                GroundedOperatorInputRole::ElapsedDuration,
                vec!["duration".to_owned()],
            ),
        ]
    }

    fn direct_temporal_point_draft(value: &str) -> GroundedAnswerDraft {
        GroundedAnswerDraft::new(
            value,
            vec![
                GroundedAnswerItem::new(value, vec![NodeId(7)])
                    .with_finding_ids(vec!["date".to_owned()]),
            ],
            vec![NodeId(7)],
            false,
        )
        .with_findings(vec![
            GroundedEvidenceFinding::new(
                "date",
                format!("The source grounds the calendar value {value}."),
                vec![NodeId(7)],
                GroundedFindingDisposition::Item,
            )
            .with_answer_value(value),
        ])
        .with_reasoning_operator(
            GroundedReasoningOperator::new(GroundedReasoningOperatorKind::TemporalPoint)
                .with_inputs(vec![GroundedOperatorInput::new(
                    GroundedOperatorInputRole::AnswerValue,
                    vec!["date".to_owned()],
                )])
                .with_output(value),
        )
    }

    #[test]
    fn temporal_point_granularity_distinguishes_exact_day_from_generic_when() {
        for query in [
            "What exact date did the exhibition begin?",
            "What day did the exhibition begin?",
            "On which date did the exhibition begin?",
        ] {
            let spec = RecallPlan::infer(query).reader_contract();
            assert_eq!(
                spec.requested_answer_spec().temporal_granularity(),
                Some(RequestedTemporalGranularity::ExactDay),
                "query: {query}"
            );
        }

        for query in [
            "When did the exhibition begin?",
            "What month did the exhibition begin?",
            "Which week did the exhibition begin?",
        ] {
            let contract = RecallPlan::infer(query).reader_contract();
            assert_eq!(
                contract.requested_answer_spec().role(),
                RequestedAnswerRole::TemporalPoint,
                "query: {query}"
            );
            assert_eq!(
                contract.requested_answer_spec().temporal_granularity(),
                Some(RequestedTemporalGranularity::EvidenceCompatible),
                "query: {query}"
            );
        }
    }

    #[test]
    fn generic_when_preserves_supported_month_and_bounded_week_granularity() {
        let contract = RecallPlan::infer("When did the exhibition take place?").reader_contract();
        for value in [
            "June 2023",
            "early August, 2023",
            "last week of September 2023",
            "25 September 2023 through 1 October 2023",
            "2023-09-25 through 2023-10-01",
        ] {
            assert_eq!(
                contract.materialize_adjudicated_draft(
                    &direct_temporal_point_draft(value),
                    &[NodeId(7)],
                ),
                Ok(Some(value.to_owned())),
                "value: {value}"
            );
        }
    }

    #[test]
    fn exact_day_request_rejects_coarser_calendar_values() {
        let contract =
            RecallPlan::infer("What exact date did the exhibition take place?").reader_contract();
        for value in [
            "June 2023",
            "early August 2023",
            "25 September 2023 through 1 October 2023",
        ] {
            let error = contract
                .validate_adjudicated_draft(&direct_temporal_point_draft(value), &[NodeId(7)])
                .expect_err("an exact-day request must not accept coarser calendar evidence");
            assert!(
                error
                    .failures
                    .contains(&GroundedDraftValidationFailure::InvalidTemporalPointReference),
                "value={value:?}, failures={:?}",
                error.failures
            );
        }
    }

    #[test]
    fn generic_when_rejects_duration_and_ambiguous_or_unsupported_granularity() {
        let contract = RecallPlan::infer("When did the exhibition take place?").reader_contract();
        for value in [
            "1 week",
            "last week",
            "around June 2023",
            "2023",
            "06/07/2023",
            "25 September through 1 October 2023",
        ] {
            let error = contract
                .validate_adjudicated_draft(&direct_temporal_point_draft(value), &[NodeId(7)])
                .expect_err("unsupported or ambiguous when-values must fail closed");
            assert!(
                error
                    .failures
                    .contains(&GroundedDraftValidationFailure::InvalidTemporalPointReference),
                "value={value:?}, failures={:?}",
                error.failures
            );
        }
    }

