    #[test]
    fn temporal_point_wrong_or_missing_roles_and_citations_fail_closed() {
        let contract = RecallPlan::infer("When did the exhibition begin?").reader_contract();
        for inputs in [
            vec![GroundedOperatorInput::new(
                GroundedOperatorInputRole::ReferenceTime,
                vec!["reference".to_owned()],
            )],
            vec![
                GroundedOperatorInput::new(
                    GroundedOperatorInputRole::StartBoundary,
                    vec!["reference".to_owned()],
                ),
                GroundedOperatorInput::new(
                    GroundedOperatorInputRole::ExplicitDuration,
                    vec!["duration".to_owned()],
                ),
            ],
        ] {
            let error = contract
                .validate_adjudicated_draft(
                    &temporal_point_draft(
                        "2023-08-16",
                        "2023-08-23",
                        "1 week",
                        inputs,
                        vec![NodeId(9)],
                    ),
                    &[NodeId(7), NodeId(9)],
                )
                .expect_err("missing or wrong temporal-point roles must fail");
            assert!(error.failures.iter().any(|failure| matches!(
                failure,
                GroundedDraftValidationFailure::MissingOperatorInputRole { .. }
            )));
        }

        let missing_citation = temporal_point_draft(
            "2023-08-16",
            "2023-08-23",
            "1 week",
            valid_temporal_point_inputs(),
            Vec::new(),
        );
        let error = contract
            .validate_adjudicated_draft(&missing_citation, &[NodeId(7), NodeId(9)])
            .expect_err("an uncited duration cannot participate in the calculation");
        assert!(
            error
                .failures
                .contains(&GroundedDraftValidationFailure::MissingFindingCitation {
                    finding_index: 1
                })
        );
    }

    #[test]
    fn temporal_point_calendar_ambiguity_fails_closed() {
        let contract = RecallPlan::infer("When did the exhibition begin?").reader_contract();
        let ambiguous_reference = temporal_point_draft(
            "2023-08-16",
            "08/23/2023",
            "1 week",
            valid_temporal_point_inputs(),
            vec![NodeId(9)],
        );
        let error = contract
            .validate_adjudicated_draft(&ambiguous_reference, &[NodeId(7), NodeId(9)])
            .expect_err("a locale-ambiguous numeric date cannot anchor the calculation");
        assert!(
            error
                .failures
                .contains(&GroundedDraftValidationFailure::InvalidTemporalPointReference)
        );

        for duration in [
            "about 1 month",
            "nearly 1 month",
            "several months",
            "1 month and 2 days",
        ] {
            let ambiguous_duration = temporal_point_draft(
                "2023-07-23",
                "2023-08-23",
                duration,
                valid_temporal_point_inputs(),
                vec![NodeId(9)],
            );
            let error = contract
                .validate_adjudicated_draft(&ambiguous_duration, &[NodeId(7), NodeId(9)])
                .expect_err("approximate and compound calendar durations must fail closed");
            assert!(
                error
                    .failures
                    .contains(&GroundedDraftValidationFailure::InvalidTemporalPointElapsedDuration),
                "duration={duration:?}, failures={:?}",
                error.failures
            );
        }
    }

