    #[test]
    fn temporal_point_invalid_after_repair_preserves_direct_candidate_bytes() {
        let contract = RecallPlan::infer("When did the exhibition begin?").reader_contract();
        let direct_candidate = "  Around August 16, 2023.  ";
        let mut recovery = GroundedDraftRecoveryState::new();
        assert_eq!(
            contract.action_after_adjudicated_draft(
                &mut recovery,
                ReaderFinalDisposition::Answer,
                GroundedDraftStatus::Invalid,
            ),
            GroundedReadoutAction::RepairAdjudicatedDraft
        );
        let exhausted = contract.action_after_adjudicated_draft(
            &mut recovery,
            ReaderFinalDisposition::Answer,
            GroundedDraftStatus::Invalid,
        );
        let preserved = match exhausted {
            GroundedReadoutAction::PreserveDirectCandidate => direct_candidate,
            _ => "",
        };
        assert_eq!(preserved.as_bytes(), direct_candidate.as_bytes());
    }

