    #[test]
    fn grounded_draft_prunes_only_unknown_supplemental_citations() {
        let contract = RecallPlan::infer("When did Alice resume playing drums?").reader_contract();
        let draft = GroundedAnswerDraft::new(
            "February 2022",
            vec![GroundedAnswerItem::new(
                "February 2022",
                vec![NodeId(7), NodeId(9)],
            )],
            vec![NodeId(7), NodeId(9)],
            false,
        );

        let pruned = contract
            .prune_unknown_supplemental_citations(&draft, &[NodeId(7)])
            .expect("one delivered citation remains for the draft and item");
        assert_eq!(pruned.cited_source_node_ids, vec![NodeId(7)]);
        assert_eq!(pruned.answer_items[0].source_node_ids, vec![NodeId(7)]);
        assert!(
            contract
                .validate_grounded_draft(&pruned, &[NodeId(7)])
                .is_ok()
        );

        let unsupported = GroundedAnswerDraft::new(
            "February 2022",
            vec![GroundedAnswerItem::new("February 2022", vec![NodeId(9)])],
            vec![NodeId(9)],
            false,
        );
        assert_eq!(
            contract.prune_unknown_supplemental_citations(&unsupported, &[NodeId(7)]),
            None
        );
    }

    fn scalar_hypothesis_draft_with_omitted_item_citation() -> GroundedAnswerDraft {
        GroundedAnswerDraft::new(
            "garden",
            vec![
                GroundedAnswerItem::new("garden", vec![NodeId(7)])
                    .with_finding_ids(vec!["f1".to_owned(), "f2".to_owned()]),
            ],
            vec![NodeId(7), NodeId(9), NodeId(11)],
            false,
        )
        .with_findings(vec![
            GroundedEvidenceFinding::new(
                "f1",
                "The operator enjoys quiet outdoor spaces.",
                vec![NodeId(7)],
                GroundedFindingDisposition::Item,
            )
            .with_answer_value("outdoor spaces"),
            GroundedEvidenceFinding::new(
                "f2",
                "The operator values calm surroundings.",
                vec![NodeId(9)],
                GroundedFindingDisposition::Item,
            )
            .with_answer_value("calm surroundings"),
            GroundedEvidenceFinding::new(
                "f3",
                "The operator also reads outdoors.",
                vec![NodeId(11)],
                GroundedFindingDisposition::Premise,
            ),
        ])
        .with_reasoning_operator(
            GroundedReasoningOperator::new(GroundedReasoningOperatorKind::HypothesisComparison)
                .with_inputs(vec![GroundedOperatorInput::new(
                    GroundedOperatorInputRole::CandidateSupport,
                    vec!["f1".to_owned(), "f2".to_owned()],
                )])
                .with_compared_candidates(vec![
                    GroundedComparedCandidate::new(
                        "garden",
                        vec!["f1".to_owned(), "f2".to_owned()],
                    ),
                    GroundedComparedCandidate::new("arcade", Vec::new()),
                ])
                .with_output("garden"),
        )
    }

    #[test]
    fn grounded_draft_reconciles_only_citations_from_existing_item_findings() {
        let contract =
            RecallPlan::infer("Would the operator be more interested in a garden or an arcade?")
                .reader_contract();
        let draft = scalar_hypothesis_draft_with_omitted_item_citation();
        assert_eq!(
            contract.validate_grounded_draft(&draft, &[NodeId(7), NodeId(9), NodeId(11)]),
            Err(GroundedDraftValidationError {
                failures: vec![
                    GroundedDraftValidationFailure::AnswerItemMissingFindingCitation {
                        item_index: 0,
                        finding_index: 1,
                        source_node_id: NodeId(9),
                    },
                ],
            })
        );

        let reconciled = contract
            .reconcile_missing_answer_item_finding_citations(
                &draft,
                &[NodeId(7), NodeId(9), NodeId(11)],
            )
            .expect("an existing finding citation is safe to copy to its answer item");
        assert_eq!(
            reconciled.answer_items[0].source_node_ids,
            vec![NodeId(7), NodeId(9)],
            "an unreferenced finding citation must not be added"
        );
        assert!(
            contract
                .validate_adjudicated_draft(&reconciled, &[NodeId(7), NodeId(9), NodeId(11)])
                .is_ok()
        );
    }

    #[test]
    fn grounded_draft_citation_reconciliation_refuses_any_other_failure() {
        let contract =
            RecallPlan::infer("Would the operator be more interested in a garden or an arcade?")
                .reader_contract();
        let mut draft = scalar_hypothesis_draft_with_omitted_item_citation();
        let mut findings = draft.findings().to_vec();
        findings.push(
            GroundedEvidenceFinding::new(
                "f4",
                "No source states an arcade preference.",
                Vec::new(),
                GroundedFindingDisposition::Excluded,
            )
            .with_exclusion_reason("No delivered support."),
        );
        draft = draft.with_findings(findings);

        let error = contract
            .validate_grounded_draft(&draft, &[NodeId(7), NodeId(9), NodeId(11)])
            .expect_err("the uncited finding remains a distinct failure");
        assert!(error.failures.iter().any(|failure| matches!(
            failure,
            GroundedDraftValidationFailure::MissingFindingCitation { finding_index: 3 }
        )));
        assert_eq!(
            contract.reconcile_missing_answer_item_finding_citations(
                &draft,
                &[NodeId(7), NodeId(9), NodeId(11)]
            ),
            None
        );
    }

