    #[test]
    fn grounded_reconciliation_leaves_polarity_and_alternative_meaning_to_the_reader() {
        let binary = RecallPlan::infer("Does the worker use the retry queue?").reader_contract();
        let binary_draft =
            GroundedAnswerDraft::new("Yes; retry queue", Vec::new(), vec![NodeId(11)], false);
        let binary_attribution = [RecallSourceAttribution::new(
            NodeId(11),
            Some("worker".to_owned()),
            "worker: uses the retry queue",
            "session-a",
            NodeId(11),
            0,
        )];
        assert!(
            binary
                .reconcile_grounded_draft_with_attributions(
                    &binary_draft,
                    "No; primary queue",
                    &[NodeId(11)],
                    &binary_attribution,
                )
                .is_none()
        );

        let alternatives =
            RecallPlan::infer("Would the operator choose the first or second route?")
                .reader_contract();
        let alternative_draft =
            GroundedAnswerDraft::new("the second route", Vec::new(), vec![NodeId(13)], false);
        let alternative_attribution = [RecallSourceAttribution::new(
            NodeId(13),
            Some("operator".to_owned()),
            "operator: chose the second route",
            "session-a",
            NodeId(13),
            0,
        )];
        assert!(
            alternatives
                .reconcile_grounded_draft_with_attributions(
                    &alternative_draft,
                    "Yes; lower latency",
                    &[NodeId(13)],
                    &alternative_attribution,
                )
                .is_none()
        );
    }

    fn fixture_node(
        id: NodeId,
        node_type: KnowledgeType,
        content: String,
        session_id: String,
    ) -> Node {
        Node {
            id,
            node_type,
            name: content.clone(),
            summary: None,
            content,
            embedding: None,
            created_at: Timestamp(1),
            updated_at: Timestamp(1),
            accessed_at: Timestamp(1),
            valid_from: None,
            valid_until: None,
            salience: 0.5,
            retained_action: 0.0,
            evidence_prior: 0.0,
            access_count: 0,
            access_history: VecDeque::new(),
            tier: MemoryTier::Auto,
            origin: Origin {
                peer_id: PeerId(0),
                source_kind: crate::graph::SourceKind::AgentObservation,
                session_id,
                scope: ScopePath::universal(),
                confidence: 0.9,
            },
            entity_tags: Vec::new(),
            metadata: HashMap::new(),
        }
    }

    fn test_readout_candidate(node_id: NodeId, score: f64) -> ReadoutCandidate {
        ReadoutCandidate {
            node_id,
            score,
            activation: 1.0,
            phi: 0.0,
            embedding_cosine: 0.0,
            salience: 0.5,
            impedance: 1.0,
            scope_weight: 1.0,
            trust_weight: 1.0,
            stress: 0.0,
        }
    }

    fn add_test_turn(storage: &mut SqliteStorage, session: &str, content: &str) -> NodeId {
        let node_id = storage.next_node_id();
        storage
            .set_node(fixture_node(
                node_id,
                KnowledgeType::Episodic,
                content.to_owned(),
                session.to_owned(),
            ))
            .expect("test dialogue turn");
        node_id
    }

    fn add_test_speaker_turn(
        storage: &mut SqliteStorage,
        session: &str,
        speaker: &str,
        content: &str,
    ) -> NodeId {
        let node_id = storage.next_node_id();
        let mut node = fixture_node(
            node_id,
            KnowledgeType::Episodic,
            content.to_owned(),
            session.to_owned(),
        );
        node.entity_tags = vec![format!("speaker-{}", normalized_phrase(speaker))];
        storage.set_node(node).expect("test speaker dialogue turn");
        node_id
    }

    fn connect_test_turns(storage: &mut SqliteStorage, source: NodeId, target: NodeId) {
        let edge_id = storage.next_edge_id();
        storage
            .set_edge(Edge::seeded(
                edge_id,
                source,
                target,
                EdgeType::Temporal,
                1.0,
                EdgeSource::Manual,
                Timestamp(1),
                Timestamp(1),
                HashMap::new(),
            ))
            .expect("test temporal edge");
    }

    fn add_test_semantic_view(
        storage: &mut SqliteStorage,
        source: NodeId,
        content: &str,
    ) -> NodeId {
        let session_id = storage
            .get_node(source)
            .expect("semantic source")
            .origin
            .session_id
            .clone();
        let semantic = storage.next_node_id();
        storage
            .set_node(fixture_node(
                semantic,
                KnowledgeType::Semantic,
                content.to_owned(),
                session_id,
            ))
            .expect("test semantic view");
        let edge_id = storage.next_edge_id();
        storage
            .set_edge(Edge::seeded(
                edge_id,
                semantic,
                source,
                EdgeType::ExtractedFrom,
                1.0,
                EdgeSource::Manual,
                Timestamp(1),
                Timestamp(1),
                HashMap::new(),
            ))
            .expect("semantic source edge");
        semantic
    }

