    #[test]
    fn atomic_cues_append_to_native_semantic_rerank_context() {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let previous = add_test_turn(
            &mut storage,
            "project-session",
            "Bob asked about the delayed launch.",
        );
        let raw = add_test_turn(
            &mut storage,
            "project-session",
            "Alice completed the cobalt launch project.",
        );
        let next = add_test_turn(
            &mut storage,
            "project-session",
            "The team celebrated afterward.",
        );
        connect_test_turns(&mut storage, previous, raw);
        connect_test_turns(&mut storage, raw, next);
        let semantic_content = "Bob asked about the delayed launch.\n\
            Alice completed the cobalt launch project.\n\
            The team celebrated afterward.";
        let semantic = add_test_semantic_view(&mut storage, raw, semantic_content);
        seed_grounded_atomic_fact(
            &mut storage,
            AtomicFactId(901),
            raw,
            "completed the cobalt launch project",
            "cobalt launch project",
        );
        let marker = AtomicSourceMarker {
            source_node_id: raw,
            kind_priority: 0,
            fact_id: Some(AtomicFactId(901)),
        };
        let ranking = vec![test_readout_candidate(semantic, 1.0)];
        let plan = RecallPlan::infer_with_answer_shape(
            "What projects did Alice complete?",
            AnswerShape::Collection,
        );

        let documents = compile_rerank_documents(&storage, &plan, &ranking, 1, &[marker])
            .expect("semantic document with grounded cue");
        let rerank_text = documents[0].rerank_text();

        assert_eq!(documents[0].text, semantic_content);
        assert!(rerank_text.starts_with(semantic_content));
        assert!(rerank_text.contains("Grounded retrieval cues:"));
        assert!(rerank_text.contains("Fact: Alice completed cobalt launch project"));
        assert!(
            rerank_text
                .find("Grounded retrieval cues:")
                .is_some_and(|position| position >= semantic_content.len())
        );
        assert_eq!(documents[0].source_node_ids, [previous, raw, next]);
        assert_eq!(
            documents[0].scoring_source_node_ids(),
            [previous, raw, next]
        );
        assert!(documents[0].representative_text_is_bound());
    }

    #[test]
    fn complex_route_recovers_the_immediate_same_session_reply() {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let question = add_test_speaker_turn(
            &mut storage,
            "design-session",
            "reviewer",
            "Reviewer: What motivated Alice's cobalt pattern?",
        );
        let answer = add_test_speaker_turn(
            &mut storage,
            "design-session",
            "alice",
            "Alice: I chose it to catch attention and make people smile.",
        );
        connect_test_turns(&mut storage, question, answer);
        let unrelated = add_test_turn(
            &mut storage,
            "other-session",
            "Operator: The staging queue completed normally.",
        );
        let ranking = vec![
            test_readout_candidate(question, 2.0),
            test_readout_candidate(unrelated, 1.0),
        ];
        let query_embedding = [1.0, 0.0];
        let plan = RecallPlan::infer("Why would Alice choose the cobalt pattern?");

        let routed = route_same_session_reply_sources(
            &storage,
            &plan,
            &ranking,
            &[query_embedding.as_slice()],
            Timestamp(10),
            &ScopePath::universal(),
            &HashSet::new(),
        )
        .expect("bounded reply route");

        assert_eq!(
            routed
                .iter()
                .map(|candidate| candidate.node_id)
                .collect::<Vec<_>>(),
            [answer]
        );

        let already_represented = vec![
            test_readout_candidate(question, 2.0),
            test_readout_candidate(answer, 1.5),
        ];
        assert!(
            route_same_session_reply_sources(
                &storage,
                &plan,
                &already_represented,
                &[query_embedding.as_slice()],
                Timestamp(10),
                &ScopePath::universal(),
                &HashSet::new(),
            )
            .expect("already represented answer")
            .is_empty()
        );
    }

