    #[test]
    fn factual_action_reply_route_reuses_exact_subject_and_fact_authority() {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let mut ranking = Vec::new();
        let mut answers = Vec::new();
        for (index, answer_speaker, relation, object) in [
            (0usize, "technician", "built", "a portable device"),
            (1, "designer", "created", "a diagnostic device"),
            (2, "technician", "planned to build", "a folding device"),
            (3, "technician", "created", "a public website"),
        ] {
            let session = format!("action-reply-{index}");
            let question = add_test_speaker_turn(
                &mut storage,
                &session,
                "reviewer",
                "Reviewer: Which devices did the technician try to build?",
            );
            let answer =
                add_test_speaker_turn(&mut storage, &session, answer_speaker, "temporary answer");
            connect_test_turns(&mut storage, question, answer);
            seed_ranked_action_event(
                &mut storage,
                answer,
                &session,
                "the technician",
                relation,
                object,
            );
            ranking.push(test_readout_candidate(question, 4.0 - index as f64));
            answers.push(answer);
        }

        let plan = RecallPlan::infer("What kinds of devices has the technician tried to build?");
        let scope = ScopePath::universal();
        let authority = strict_factual_action_source_ids(&storage, &plan, Timestamp(100), &scope)
            .expect("strict action authority");
        assert!(authority.contains(&answers[0]));
        assert!(authority.contains(&answers[1]));
        assert!(!authority.contains(&answers[2]));
        assert!(!authority.contains(&answers[3]));

        let query_embedding = [1.0, 0.0];
        let routed = route_same_session_reply_sources(
            &storage,
            &plan,
            &ranking,
            &[query_embedding.as_slice()],
            Timestamp(100),
            &scope,
            &authority,
        )
        .expect("strict factual-action reply route");
        assert_eq!(
            routed
                .iter()
                .map(|candidate| candidate.node_id)
                .collect::<Vec<_>>(),
            [answers[0]]
        );
    }

    #[test]
    fn cross_speaker_reply_explicitly_owned_by_named_asker_routes_and_bridges() {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let question = add_test_speaker_turn(
            &mut storage,
            "presentation-session",
            "alice",
            "Alice: Did I do well in the cobalt presentation?",
        );
        let answer = add_test_speaker_turn(
            &mut storage,
            "presentation-session",
            "bob",
            "Bob: You did great in the cobalt presentation.",
        );
        connect_test_turns(&mut storage, question, answer);
        let unrelated = add_test_turn(
            &mut storage,
            "other-session",
            "Operator: The deployment queue completed normally.",
        );
        let plan = RecallPlan::infer_with_answer_shape(
            "How did Alice perform in the cobalt presentation?",
            AnswerShape::Relationship,
        );
        let query_embedding = [1.0, 0.0];

        let routed = route_same_session_reply_sources(
            &storage,
            &plan,
            &[
                test_readout_candidate(question, 2.0),
                test_readout_candidate(unrelated, 1.0),
            ],
            &[query_embedding.as_slice()],
            Timestamp(10),
            &ScopePath::universal(),
            &HashSet::new(),
        )
        .expect("explicit asker-owned reply route");
        assert_eq!(
            routed
                .iter()
                .map(|candidate| candidate.node_id)
                .collect::<Vec<_>>(),
            [answer]
        );

        let documents = compile_rerank_documents(
            &storage,
            &plan,
            &[
                test_readout_candidate(unrelated, 2.0),
                test_readout_candidate(answer, 1.0),
            ],
            2,
            &[],
        )
        .expect("explicit asker-owned reply bridge");
        let answer_document = documents
            .iter()
            .find(|document| document.node_id == answer)
            .expect("native answer document");
        assert!(
            answer_document
                .rerank_text()
                .contains("Immediate same-session question:")
        );
        assert!(answer_document.rerank_text().contains("Did I do well"));

        let named_answer = add_test_speaker_turn(
            &mut storage,
            "presentation-session-named",
            "bob",
            "Bob: Yes, Alice did great in the cobalt presentation.",
        );
        let first_person_answer = add_test_speaker_turn(
            &mut storage,
            "presentation-session-control",
            "bob",
            "Bob: No, I have not tried Alice's cobalt presentation technique.",
        );
        assert!(same_session_reply_preserves_named_speaker_ownership(
            &plan,
            storage.get_node(question).expect("question source"),
            storage.get_node(named_answer).expect("named answer source"),
        ));
        assert!(!same_session_reply_preserves_named_speaker_ownership(
            &plan,
            storage.get_node(question).expect("question source"),
            storage
                .get_node(first_person_answer)
                .expect("first-person answer source"),
        ));
    }

