    fn seed_ranked_method_event(
        storage: &mut SqliteStorage,
        source_node_id: NodeId,
        session_id: &str,
        relation: &str,
        object: &str,
    ) -> AtomicFactId {
        let evidence = format!("The coordinator {relation} {object} for the workshop.");
        let mut source = storage
            .get_node(source_node_id)
            .expect("ranked method source")
            .clone();
        source.name = evidence.clone();
        source.content = evidence.clone();
        source.origin.session_id = session_id.to_owned();
        storage
            .set_node(source)
            .expect("updated ranked method source");

        let fact_id = storage.next_atomic_fact_id().expect("method fact id");
        seed_structured_atomic_fact(
            storage,
            fact_id,
            source_node_id,
            &evidence,
            "the coordinator",
            relation,
            object,
            object,
            &evidence,
        );
        let mut fact = storage
            .get_atomic_fact(fact_id)
            .expect("ranked method fact")
            .clone();
        fact.metadata
            .insert("anamnesis:fact-kind".to_owned(), "event".to_owned());
        storage
            .set_atomic_fact(fact)
            .expect("typed ranked method fact");
        fact_id
    }

