    #[allow(clippy::too_many_arguments)]
    fn seed_reviewed_premise_fact(
        storage: &mut SqliteStorage,
        source_content: &str,
        speaker: &str,
        subject: &str,
        predicate: &str,
        object: &str,
        embedding: Vec<f64>,
        scope: ScopePath,
        observed_at: Timestamp,
    ) -> (NodeId, AtomicFactId) {
        let source_id = storage.next_node_id();
        let mut source = fixture_node(
            source_id,
            KnowledgeType::Episodic,
            source_content.to_owned(),
            format!("premise-session-{}", source_id.0),
        );
        source.created_at = observed_at;
        source.updated_at = observed_at;
        source.accessed_at = observed_at;
        source.origin.scope = scope.clone();
        source.entity_tags = vec![format!("speaker-{}", normalized_phrase(speaker))];
        source.embedding = Some(embedding.clone());
        storage.set_node(source).expect("reviewed premise source");
        let source = storage
            .get_node(source_id)
            .expect("stored reviewed premise source");
        let incarnation = storage
            .atomic_source_incarnation(source)
            .expect("source incarnation");
        let evidence_start = source
            .content
            .find(object)
            .expect("premise object appears byte-exactly");
        let source_session_id = source.origin.session_id.clone();
        let fact_id = storage
            .next_atomic_fact_id()
            .expect("reviewed premise fact id");
        let metadata = HashMap::from([
            (
                super::super::REVIEWED_DERIVATION_SCHEMA_KEY.to_owned(),
                "reviewed-routing-v1".to_owned(),
            ),
            (
                super::super::REVIEWED_DERIVATION_SUBJECT_KEY.to_owned(),
                subject.to_owned(),
            ),
            (
                super::super::REVIEWED_DERIVATION_PREDICATE_KEY.to_owned(),
                predicate.to_owned(),
            ),
            (
                super::super::REVIEWED_DERIVATION_OBJECT_KEY.to_owned(),
                object.to_owned(),
            ),
            (
                super::super::REVIEWED_DERIVATION_POLARITY_KEY.to_owned(),
                "affirmed".to_owned(),
            ),
            (
                super::super::REVIEWED_DERIVATION_MODALITY_KEY.to_owned(),
                "observed".to_owned(),
            ),
            (
                super::super::REVIEWED_DERIVATION_REVIEWED_BY_KEY.to_owned(),
                "fixture-reviewer".to_owned(),
            ),
            (
                super::super::REVIEWED_DERIVATION_REVIEW_PROFILE_KEY.to_owned(),
                "fixture-profile".to_owned(),
            ),
            (
                super::super::REVIEWED_DERIVATION_REVIEWED_AT_KEY.to_owned(),
                observed_at.0.to_string(),
            ),
            (
                super::super::REVIEWED_DERIVATION_IDEMPOTENCY_KEY.to_owned(),
                format!("premise-fixture-{}", fact_id.0),
            ),
            ("anamnesis:evidence-object".to_owned(), object.to_owned()),
            (
                "anamnesis:evidence-source-node-id".to_owned(),
                source_id.0.to_string(),
            ),
            (
                "anamnesis:evidence-span-start".to_owned(),
                evidence_start.to_string(),
            ),
            (
                "anamnesis:evidence-span-end".to_owned(),
                (evidence_start + object.len()).to_string(),
            ),
            (
                crate::storage::atomic_source_incarnation_key(source_id),
                incarnation,
            ),
        ]);
        storage
            .set_atomic_fact(AtomicFact {
                id: fact_id,
                content: format!("{subject} {predicate} {object}"),
                embedding,
                source_node_ids: vec![source_id],
                entity_tags: vec![subject.to_owned()],
                source_session_id,
                scope,
                observed_at,
                valid_from: None,
                valid_until: None,
                metadata,
            })
            .expect("reviewed premise fact");
        (source_id, fact_id)
    }

    #[allow(clippy::too_many_arguments)]
    fn seed_grounded_premise_fact(
        storage: &mut SqliteStorage,
        source_content: &str,
        speaker: &str,
        subject: &str,
        relation: &str,
        object: &str,
        embedding: Vec<f64>,
        mut fact_entity_tags: Vec<String>,
        scope: ScopePath,
        observed_at: Timestamp,
    ) -> (NodeId, AtomicFactId) {
        let source_id = storage.next_node_id();
        let mut source = fixture_node(
            source_id,
            KnowledgeType::Episodic,
            source_content.to_owned(),
            format!("grounded-premise-session-{}", source_id.0),
        );
        source.created_at = observed_at;
        source.updated_at = observed_at;
        source.accessed_at = observed_at;
        source.origin.scope = scope.clone();
        source.entity_tags = vec![format!("speaker-{}", normalized_phrase(speaker))];
        source.embedding = Some(embedding.clone());
        storage.set_node(source).expect("grounded premise source");
        let source = storage
            .get_node(source_id)
            .expect("stored grounded premise source");
        let incarnation = storage
            .atomic_source_incarnation(source)
            .expect("source incarnation");
        let evidence_start = source
            .content
            .find(object)
            .expect("ordinary evidence object appears byte-exactly");
        let source_session_id = source.origin.session_id.clone();
        let fact_id = storage
            .next_atomic_fact_id()
            .expect("grounded premise fact id");
        let metadata = HashMap::from([
            ("anamnesis:ground-subject".to_owned(), subject.to_owned()),
            ("anamnesis:ground-relation".to_owned(), relation.to_owned()),
            ("anamnesis:ground-object".to_owned(), object.to_owned()),
            ("anamnesis:evidence-object".to_owned(), object.to_owned()),
            (
                "anamnesis:evidence-source-node-id".to_owned(),
                source_id.0.to_string(),
            ),
            (
                "anamnesis:evidence-span-start".to_owned(),
                evidence_start.to_string(),
            ),
            (
                "anamnesis:evidence-span-end".to_owned(),
                (evidence_start + object.len()).to_string(),
            ),
            (
                crate::storage::atomic_source_incarnation_key(source_id),
                incarnation,
            ),
        ]);
        if !fact_entity_tags
            .iter()
            .any(|tag| normalized_phrase(tag) == normalized_phrase(subject))
        {
            fact_entity_tags.push(subject.to_owned());
        }
        storage
            .set_atomic_fact(AtomicFact {
                id: fact_id,
                content: format!("{subject} {relation} {object}"),
                embedding,
                source_node_ids: vec![source_id],
                entity_tags: fact_entity_tags,
                source_session_id,
                scope,
                observed_at,
                valid_from: None,
                valid_until: None,
                metadata,
            })
            .expect("grounded premise fact");
        (source_id, fact_id)
    }

    fn widen_grounded_premise_evidence_span(
        storage: &mut SqliteStorage,
        fact_id: AtomicFactId,
        evidence_span: &str,
    ) {
        let mut fact = storage
            .get_atomic_fact(fact_id)
            .expect("grounded fact to widen")
            .clone();
        let source_id = *fact
            .source_node_ids
            .first()
            .expect("grounded fact source id");
        let source = storage
            .get_node(source_id)
            .expect("grounded fact source to widen");
        let evidence_start = source
            .content
            .find(evidence_span)
            .expect("wider evidence span appears byte-exactly");
        fact.metadata.insert(
            "anamnesis:evidence-span-start".to_owned(),
            evidence_start.to_string(),
        );
        fact.metadata.insert(
            "anamnesis:evidence-span-end".to_owned(),
            evidence_start
                .saturating_add(evidence_span.len())
                .to_string(),
        );
        storage
            .set_atomic_fact(fact)
            .expect("wider grounded evidence span");
    }

    fn grounded_premise_slot_admission(
        storage: &SqliteStorage,
        fact_id: AtomicFactId,
        query: &str,
        slot_surface: &str,
    ) -> Option<(usize, usize)> {
        let plan = RecallPlan::infer(query);
        let fact = storage
            .get_atomic_fact(fact_id)
            .expect("grounded premise fact");
        let live =
            live_premise_source(storage, &plan, fact, Timestamp(10), &ScopePath::universal())
                .expect("grounded premise authority validation")
                .expect("live grounded premise fact");
        premise_slot_admission(fact, &live, slot_surface)
    }

    fn cooking_dog_plan() -> RecallPlan {
        RecallPlan::infer("How might Andrew enjoy an indoor activity while making his dog happy?")
    }

    fn route_cooking_dog_bundle(
        storage: &SqliteStorage,
        now: Timestamp,
        scope: &ScopePath,
    ) -> Result<Option<RoutedPremiseBundle>, Error> {
        route_premise_bundle_for_query(storage, &cooking_dog_plan().query, now, scope)
    }

    fn route_premise_bundle_for_query(
        storage: &SqliteStorage,
        query: &str,
        now: Timestamp,
        scope: &ScopePath,
    ) -> Result<Option<RoutedPremiseBundle>, Error> {
        let plan = RecallPlan::infer(query);
        let dense_plan = crate::api::planned_complex_dense_query_plan(&plan.query, true);
        let embeddings = [vec![1.0, 0.0], vec![0.0, 1.0], vec![0.0, 0.0]];
        let slots = dense_plan
            .premise_slots
            .iter()
            .map(|slot| PremiseBundleQuerySlot {
                slot_id: slot.id,
                surface: &dense_plan.variants[slot.variant_index],
                embedding: &embeddings[slot.id.ordinal()],
            })
            .collect::<Vec<_>>();
        route_premise_bundle(storage, &plan, &slots, now, scope)
    }

    fn ordinary_cooking_owned_pet_fixture(
        owned_source: &str,
        owned_object: &str,
        owned_embedding: Vec<f64>,
        owned_tags: Vec<String>,
    ) -> (SqliteStorage, Vec<NodeId>, Vec<AtomicFactId>) {
        let mut storage = SqliteStorage::in_memory().expect("ordinary premise fixture");
        let (cooking_source, cooking_fact) = seed_grounded_premise_fact(
            &mut storage,
            "I've been getting into cooking and trying new recipes - it's been enjoyable.",
            "Andrew",
            "Andrew",
            "finds",
            "cooking and trying new recipes - it's been enjoyable",
            vec![1.0, 0.0],
            vec!["Andrew".to_owned()],
            ScopePath::universal(),
            Timestamp(5),
        );
        let (owned_source_id, owned_fact) = seed_grounded_premise_fact(
            &mut storage,
            owned_source,
            "Andrew",
            "Andrew",
            "introduced",
            owned_object,
            owned_embedding,
            owned_tags,
            ScopePath::universal(),
            Timestamp(6),
        );
        (
            storage,
            vec![cooking_source, owned_source_id],
            vec![cooking_fact, owned_fact],
        )
    }

