    #[test]
    fn cooking_and_dog_premises_form_one_complete_reviewed_bundle() {
        let (storage, source_ids, fact_ids) = cooking_dog_fixture();
        let plan = cooking_dog_plan();
        assert_eq!(plan.answer_shape, AnswerShape::Inference);
        assert_eq!(plan.derivation, RecallDerivation::GroundedInference);

        let routed = route_cooking_dog_bundle(&storage, Timestamp(10), &ScopePath::universal())
            .expect("reviewed premise route")
            .expect("complete cooking and dog bundle");
        assert_eq!(routed.trace.members.len(), 2);
        assert_eq!(
            routed
                .trace
                .members
                .iter()
                .map(|member| member.slot_id.ordinal())
                .collect::<Vec<_>>(),
            vec![0, 1]
        );
        assert_eq!(
            routed
                .trace
                .members
                .iter()
                .map(|member| member.source_node_id)
                .collect::<Vec<_>>(),
            source_ids
        );
        assert_eq!(
            routed
                .trace
                .members
                .iter()
                .map(|member| member.fact_id)
                .collect::<Vec<_>>(),
            fact_ids
        );
    }

