    #[test]
    fn premise_bundle_deduplicates_one_raw_source_across_slots() {
        let mut storage = SqliteStorage::in_memory().expect("same-source fixture");
        let (source_id, first_fact_id) = seed_reviewed_premise_fact(
            &mut storage,
            "I enjoy indoor cooking and make my dog happy.",
            "Andrew",
            "Andrew",
            "enjoy",
            "indoor cooking",
            vec![1.0, 0.0],
            ScopePath::universal(),
            Timestamp(5),
        );
        let first = storage
            .get_atomic_fact(first_fact_id)
            .expect("first same-source fact")
            .clone();
        let mut second = first.clone();
        second.id = storage
            .next_atomic_fact_id()
            .expect("second same-source id");
        second.content = "Andrew make my dog happy".to_owned();
        second.embedding = vec![0.0, 1.0];
        second.metadata.insert(
            super::super::REVIEWED_DERIVATION_PREDICATE_KEY.to_owned(),
            "make".to_owned(),
        );
        second.metadata.insert(
            super::super::REVIEWED_DERIVATION_OBJECT_KEY.to_owned(),
            "my dog happy".to_owned(),
        );
        second.metadata.insert(
            super::super::REVIEWED_DERIVATION_IDEMPOTENCY_KEY.to_owned(),
            "same-source-dog".to_owned(),
        );
        second.metadata.insert(
            "anamnesis:evidence-object".to_owned(),
            "my dog happy".to_owned(),
        );
        let source = storage.get_node(source_id).expect("same raw source");
        let start = source.content.find("my dog happy").expect("dog evidence");
        second.metadata.insert(
            "anamnesis:evidence-span-start".to_owned(),
            start.to_string(),
        );
        second.metadata.insert(
            "anamnesis:evidence-span-end".to_owned(),
            (start + "my dog happy".len()).to_string(),
        );
        storage
            .set_atomic_fact(second)
            .expect("second same-source fact");

        assert!(
            route_cooking_dog_bundle(&storage, Timestamp(10), &ScopePath::universal())
                .expect("same source is deduplicated")
                .is_none()
        );
    }

