    #[test]
    fn premise_bundle_preselection_and_final_selection_preserve_fixed_heads() {
        let (storage, ranking, _) = ranked_fixture();
        let plan = cooking_dog_plan();
        let bundle = PremiseBundleTrace {
            members: vec![
                PremiseBundleMember {
                    slot_id: DensePremiseSlotId::from_ordinal(0),
                    fact_id: AtomicFactId(700),
                    source_node_id: ranking[68].node_id,
                    authority: PremiseFactAuthority::ReviewedProjection,
                },
                PremiseBundleMember {
                    slot_id: DensePremiseSlotId::from_ordinal(1),
                    fact_id: AtomicFactId(701),
                    source_node_id: ranking[69].node_id,
                    authority: PremiseFactAuthority::ReviewedProjection,
                },
            ],
        };
        let preselected = coverage_preselected_ranking_with_premise_bundle(
            &storage,
            &plan,
            &ranking,
            50,
            &[],
            Some(&bundle),
        )
        .expect("atomic bundle preselection");
        assert_eq!(preselected.len(), 50);
        assert_eq!(preselected[..30], ranking[..30]);
        assert!(
            preselected
                .iter()
                .any(|candidate| candidate.node_id == ranking[68].node_id)
        );
        assert!(
            preselected
                .iter()
                .any(|candidate| candidate.node_id == ranking[69].node_id)
        );

        let reranked = ranking
            .iter()
            .map(|candidate| RerankedCandidate {
                node_id: candidate.node_id,
                score: candidate.score,
            })
            .collect::<Vec<_>>();
        let baseline = reranked[..14].to_vec();
        let selected =
            premise_bundle_group_ranking(&storage, &reranked, &baseline, 14, Some(&bundle), &[])
                .expect("atomic final bundle selection");
        assert_eq!(selected.len(), 14);
        assert_eq!(selected[..12], baseline[..12]);
        assert!(
            selected
                .iter()
                .any(|candidate| candidate.node_id == ranking[68].node_id)
        );
        assert!(
            selected
                .iter()
                .any(|candidate| candidate.node_id == ranking[69].node_id)
        );

        let unrepresentable = PremiseBundleTrace {
            members: vec![
                bundle.members[0],
                bundle.members[1],
                PremiseBundleMember {
                    slot_id: DensePremiseSlotId::from_ordinal(2),
                    fact_id: AtomicFactId(702),
                    source_node_id: ranking[70].node_id,
                    authority: PremiseFactAuthority::ReviewedProjection,
                },
            ],
        };
        assert_eq!(
            premise_bundle_group_ranking(
                &storage,
                &reranked,
                &baseline,
                14,
                Some(&unrepresentable),
                &[],
            )
            .expect("three missing additions apply none"),
            baseline
        );
    }

    #[test]
    fn premise_bundle_preselection_restores_a_required_native_tail_row() {
        let (mut storage, ranking, _) = ranked_fixture();
        let plan = cooking_dog_plan();
        let matching_surface = "Andrew enjoy indoor activity making dog happy";

        // Make every later native Semantic row as facet-rich as the deeper
        // candidate. The ordinary deeper-facet lane can then exchange only
        // rank 31 (index 30), which deliberately represents one bundle member.
        for candidate in ranking.iter().take(50).skip(31) {
            let mut node = storage
                .get_node(candidate.node_id)
                .expect("native tail fixture")
                .clone();
            node.content = matching_surface.to_owned();
            storage.set_node(node).expect("facet-rich native tail");
        }
        let mut deeper = storage
            .get_node(ranking[68].node_id)
            .expect("deeper facet fixture")
            .clone();
        deeper.content = matching_surface.to_owned();
        storage.set_node(deeper).expect("deeper facet candidate");

        let bundle = PremiseBundleTrace {
            members: vec![
                PremiseBundleMember {
                    slot_id: DensePremiseSlotId::from_ordinal(0),
                    fact_id: AtomicFactId(710),
                    source_node_id: ranking[30].node_id,
                    authority: PremiseFactAuthority::ReviewedProjection,
                },
                PremiseBundleMember {
                    slot_id: DensePremiseSlotId::from_ordinal(1),
                    fact_id: AtomicFactId(711),
                    source_node_id: ranking[69].node_id,
                    authority: PremiseFactAuthority::ReviewedProjection,
                },
            ],
        };
        let selected = coverage_preselected_ranking_with_premise_bundle(
            &storage,
            &plan,
            &ranking,
            50,
            &[],
            Some(&bundle),
        )
        .expect("native tail bundle restoration");

        assert_eq!(selected.len(), 50);
        assert_eq!(selected[..30], ranking[..30]);
        assert!(
            selected
                .iter()
                .any(|candidate| candidate.node_id == ranking[68].node_id),
            "the earlier deeper-facet exchange must occur in this fixture"
        );
        for required_index in [30, 69] {
            assert!(
                selected
                    .iter()
                    .any(|candidate| candidate.node_id == ranking[required_index].node_id),
                "the final lane must restore every required bundle source"
            );
        }
    }

    fn seed_temporal_structured_fact(
        storage: &mut SqliteStorage,
        subject: &str,
        activity: &str,
        observed_at: Timestamp,
    ) -> (NodeId, AtomicFactId) {
        let source_id = storage.next_node_id();
        let source_content = format!("{subject} was pursuing {activity}.");
        let mut source = fixture_node(
            source_id,
            KnowledgeType::Episodic,
            source_content.clone(),
            format!("{subject}-{activity}-session"),
        );
        source.created_at = observed_at;
        source.updated_at = observed_at;
        source.accessed_at = observed_at;
        source.embedding = Some(vec![0.0, 1.0]);
        storage.set_node(source).expect("temporal raw source");

        let fact_id = storage.next_atomic_fact_id().expect("temporal fact id");
        seed_structured_atomic_fact(
            storage,
            fact_id,
            source_id,
            &format!("{subject} pursued {activity}"),
            subject,
            "pursued",
            activity,
            activity,
            &source_content,
        );
        let mut fact = storage
            .get_atomic_fact(fact_id)
            .expect("temporal structured fact")
            .clone();
        fact.metadata
            .insert("anamnesis:fact-kind".to_owned(), "event".to_owned());
        storage
            .set_atomic_fact(fact)
            .expect("typed temporal structured fact");
        (source_id, fact_id)
    }

    #[allow(clippy::too_many_arguments)]
    fn seed_ranked_temporal_event(
        storage: &mut SqliteStorage,
        source_id: NodeId,
        subject: &str,
        relation: &str,
        object: &str,
        observed_at: Timestamp,
        scope: ScopePath,
    ) -> AtomicFactId {
        let evidence = format!("{subject} {relation} {object}.");
        let mut source = storage
            .get_node(source_id)
            .expect("ranked temporal source")
            .clone();
        source.node_type = KnowledgeType::Episodic;
        source.name = evidence.clone();
        source.content = evidence.clone();
        source.created_at = observed_at;
        source.updated_at = observed_at;
        source.accessed_at = observed_at;
        source.origin.session_id = format!("temporal-session-{}", source_id.0);
        source.origin.scope = scope.clone();
        storage
            .set_node(source)
            .expect("updated ranked temporal source");

        let fact_id = storage.next_atomic_fact_id().expect("temporal fact id");
        seed_structured_atomic_fact(
            storage, fact_id, source_id, &evidence, subject, relation, object, object, &evidence,
        );
        let mut fact = storage
            .get_atomic_fact(fact_id)
            .expect("ranked temporal fact")
            .clone();
        fact.metadata
            .insert("anamnesis:fact-kind".to_owned(), "event".to_owned());
        storage
            .set_atomic_fact(fact)
            .expect("typed ranked temporal fact");
        fact_id
    }

    #[allow(clippy::too_many_arguments)]
    fn seed_reviewed_event_boundary_fact(
        storage: &mut SqliteStorage,
        source_content: &str,
        subject: &str,
        predicate: &str,
        object: &str,
        evidence_object: &str,
        modality: &str,
        polarity: &str,
        observed_at: Timestamp,
        scope: ScopePath,
    ) -> (NodeId, AtomicFactId) {
        let (source_id, fact_id) = seed_reviewed_premise_fact(
            storage,
            source_content,
            subject,
            subject,
            predicate,
            evidence_object,
            vec![0.0, 1.0],
            scope,
            observed_at,
        );
        let mut fact = storage
            .get_atomic_fact(fact_id)
            .expect("reviewed event-boundary fact")
            .clone();
        fact.content = format!("{subject} {predicate} {object}");
        fact.metadata.insert(
            super::super::REVIEWED_DERIVATION_OBJECT_KEY.to_owned(),
            object.to_owned(),
        );
        fact.metadata.insert(
            super::super::REVIEWED_DERIVATION_MODALITY_KEY.to_owned(),
            modality.to_owned(),
        );
        fact.metadata.insert(
            super::super::REVIEWED_DERIVATION_POLARITY_KEY.to_owned(),
            polarity.to_owned(),
        );
        fact.valid_from = Some(observed_at);
        fact.metadata
            .insert("anamnesis:evidence-span-start".to_owned(), "0".to_owned());
        fact.metadata.insert(
            "anamnesis:evidence-span-end".to_owned(),
            source_content.len().to_string(),
        );
        storage
            .set_atomic_fact(fact)
            .expect("updated reviewed event-boundary fact");
        (source_id, fact_id)
    }

    #[allow(clippy::too_many_arguments)]
    fn seed_legacy_event_boundary_fact(
        storage: &mut SqliteStorage,
        source_content: &str,
        subject: &str,
        relation: &str,
        object: &str,
        evidence_object: &str,
        fact_kind: &str,
        observed_at: Timestamp,
        scope: ScopePath,
    ) -> (NodeId, AtomicFactId) {
        let source_id = storage.next_node_id();
        let mut source = fixture_node(
            source_id,
            KnowledgeType::Episodic,
            source_content.to_owned(),
            format!("event-boundary-session-{}", source_id.0),
        );
        source.created_at = observed_at;
        source.updated_at = observed_at;
        source.accessed_at = observed_at;
        source.origin.scope = scope;
        source.embedding = Some(vec![0.0, 1.0]);
        storage.set_node(source).expect("legacy boundary source");
        let fact_id = storage
            .next_atomic_fact_id()
            .expect("legacy boundary fact id");
        seed_structured_atomic_fact(
            storage,
            fact_id,
            source_id,
            &format!("{subject} {relation} {object}"),
            subject,
            relation,
            object,
            evidence_object,
            source_content,
        );
        let mut fact = storage
            .get_atomic_fact(fact_id)
            .expect("legacy event-boundary fact")
            .clone();
        fact.valid_from = Some(observed_at);
        fact.metadata
            .insert("anamnesis:fact-kind".to_owned(), fact_kind.to_owned());
        storage
            .set_atomic_fact(fact)
            .expect("updated legacy event-boundary fact");
        (source_id, fact_id)
    }

    fn routed_event_boundary_fact_ids(
        storage: &SqliteStorage,
        query: &str,
        now: Timestamp,
        scope: &ScopePath,
    ) -> HashSet<AtomicFactId> {
        let query_embedding = [0.0, 1.0];
        route_atomic_fact_sources(
            storage,
            &RecallPlan::infer(query),
            &[query_embedding.as_slice()],
            now,
            scope,
        )
        .expect("event-boundary route")
        .iter()
        .flat_map(|source| source.fact_ids.iter().copied())
        .collect()
    }

    fn routed_event_boundary_fact_priorities(
        storage: &SqliteStorage,
        query: &str,
        now: Timestamp,
        scope: &ScopePath,
    ) -> HashMap<AtomicFactId, usize> {
        let query_embedding = [0.0, 1.0];
        let mut priorities = HashMap::new();
        for source in route_atomic_fact_sources(
            storage,
            &RecallPlan::infer(query),
            &[query_embedding.as_slice()],
            now,
            scope,
        )
        .expect("event-boundary priorities")
        {
            for (fact_id, priority) in source.fact_priorities {
                priorities
                    .entry(fact_id)
                    .and_modify(|existing: &mut usize| *existing = (*existing).max(priority))
                    .or_insert(priority);
            }
        }
        priorities
    }

    struct EventBoundaryGroupFixture {
        storage: SqliteStorage,
        plan: RecallPlan,
        as_of: Timestamp,
        group: EventBoundarySourceGroup,
        anchor: EventBoundarySourceMember,
        targets: [EventBoundarySourceMember; 2],
    }

    fn event_boundary_group_fixture() -> EventBoundaryGroupFixture {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let (first_source, first_fact) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan struggled to find accessible housing.",
            "Morgan",
            "struggled",
            "to find accessible housing",
            "accessible housing",
            "observed",
            "affirmed",
            Timestamp(10),
            ScopePath::universal(),
        );
        let (second_source, second_fact) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan found choosing a veterinarian difficult.",
            "Morgan",
            "found difficult",
            "choosing a veterinarian",
            "veterinarian",
            "observed",
            "affirmed",
            Timestamp(20),
            ScopePath::universal(),
        );
        let (anchor_source, anchor_fact) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan adopted Pip.",
            "Morgan",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(30),
            ScopePath::universal(),
        );
        let plan = RecallPlan::infer("What problems did Morgan face before adopting Pip?");
        let as_of = Timestamp(40);
        let group =
            canonical_event_boundary_source_group(&storage, &plan, as_of, &ScopePath::universal())
                .expect("event-boundary source group route")
                .expect("bounded event-boundary source group");
        let anchor = EventBoundarySourceMember {
            fact_id: anchor_fact,
            source_node_id: anchor_source,
        };
        let mut targets = [
            EventBoundarySourceMember {
                fact_id: first_fact,
                source_node_id: first_source,
            },
            EventBoundarySourceMember {
                fact_id: second_fact,
                source_node_id: second_source,
            },
        ];
        canonical_event_boundary_members(&mut targets);
        assert_eq!(group.anchors, vec![anchor]);
        assert_eq!(group.targets, targets);
        EventBoundaryGroupFixture {
            storage,
            plan,
            as_of,
            group,
            anchor,
            targets,
        }
    }

    fn seed_reviewed_atomic_relation(
        storage: &mut SqliteStorage,
        from_fact_id: AtomicFactId,
        to_fact_id: AtomicFactId,
        kind: AtomicFactRelationKind,
        key: &str,
    ) -> AtomicFactRelationId {
        let id = storage.next_atomic_fact_relation_id().expect("relation id");
        storage
            .set_atomic_fact_relation(AtomicFactRelation {
                id,
                from_fact_id,
                to_fact_id,
                kind,
                reviewed_by: "reviewer".to_owned(),
                review_profile: "policy-v1".to_owned(),
                reviewed_at: Timestamp(2),
                idempotency_key: key.to_owned(),
                scope: ScopePath::universal(),
                valid_from: None,
                valid_until: None,
                metadata: HashMap::new(),
            })
            .expect("reviewed relation");
        id
    }

    fn atomic_chain_fixture(contents: &[&str]) -> (SqliteStorage, Vec<NodeId>, Vec<AtomicFactId>) {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let mut source_ids = Vec::with_capacity(contents.len());
        let mut fact_ids = Vec::with_capacity(contents.len());
        for (index, content) in contents.iter().enumerate() {
            let source_id = storage.next_node_id();
            let mut source = fixture_node(
                source_id,
                KnowledgeType::Episodic,
                (*content).to_owned(),
                format!("chain-session-{index}"),
            );
            source.embedding = Some(vec![1.0, 0.0]);
            storage.set_node(source).expect("chain raw source");
            let fact_id = storage.next_atomic_fact_id().expect("chain fact id");
            seed_legacy_atomic_fact(&mut storage, fact_id, source_id);
            source_ids.push(source_id);
            fact_ids.push(fact_id);
        }
        (storage, source_ids, fact_ids)
    }

    fn seed_atomic_routing_case(
        storage: &mut SqliteStorage,
        content: &str,
        configure_source: impl FnOnce(&mut Node),
        configure_fact: impl FnOnce(&mut AtomicFact),
    ) -> (NodeId, AtomicFactId) {
        let source_id = storage.next_node_id();
        let mut source = fixture_node(
            source_id,
            KnowledgeType::Episodic,
            content.to_owned(),
            format!("routing-case-{}", source_id.0),
        );
        source.embedding = Some(vec![1.0]);
        configure_source(&mut source);
        storage.set_node(source).expect("routing-case source");

        let fact_id = storage.next_atomic_fact_id().expect("routing-case fact id");
        seed_legacy_atomic_fact(storage, fact_id, source_id);
        let mut fact = storage
            .get_atomic_fact(fact_id)
            .expect("routing-case fact")
            .clone();
        configure_fact(&mut fact);
        storage
            .set_atomic_fact(fact)
            .expect("configured routing-case fact");
        (source_id, fact_id)
    }

    fn direct_atomic_route(source_id: NodeId, fact_id: AtomicFactId) -> RoutedAtomicSource {
        RoutedAtomicSource {
            candidate: ReadoutCandidate {
                node_id: source_id,
                score: 1.0,
                activation: 1.0,
                phi: 1.0,
                embedding_cosine: 1.0,
                salience: 0.5,
                impedance: 0.0,
                scope_weight: 1.0,
                trust_weight: 1.0,
                stress: 0.0,
            },
            kind_priority: 0,
            fact_ids: vec![fact_id],
            fact_priorities: Vec::new(),
            origin: AtomicRouteOrigin::Direct,
        }
    }

    fn expand_chain_from_seed(
        storage: &SqliteStorage,
        source_id: NodeId,
        fact_id: AtomicFactId,
        now: Timestamp,
        scope: &ScopePath,
    ) -> (Vec<RoutedAtomicSource>, AtomicChainDiagnostics) {
        let query_embedding = [1.0, 0.0];
        let expansion = expand_atomic_fact_relation_sources(
            storage,
            &RecallPlan::infer("How are the recorded events and their causes related?"),
            &[direct_atomic_route(source_id, fact_id)],
            &[query_embedding.as_slice()],
            now,
            scope,
        )
        .expect("bounded relation chain expansion");
        (expansion.sources, expansion.diagnostics)
    }

    #[test]
    fn classifies_retrieval_intents_without_a_model() {
        assert_eq!(
            RecallPlan::infer("How many times did Alice move?").recall_intent,
            RecallIntent::Enumeration
        );
        assert_eq!(
            RecallPlan::infer("When did Alice move?").recall_intent,
            RecallIntent::Temporal
        );
        assert_eq!(
            RecallPlan::infer("What is the relationship between Alice and Bob?").recall_intent,
            RecallIntent::Relational
        );
        assert_eq!(
            RecallPlan::infer("Where does Alice live?").recall_intent,
            RecallIntent::Direct
        );
    }

    #[test]
    fn temporal_precedence_prevents_coverage_reordering() {
        assert_eq!(
            RecallPlan::infer("When did Alice and Bob meet?").recall_intent,
            RecallIntent::Temporal
        );
    }

    #[test]
    fn separates_temporal_retrieval_from_answer_shape() {
        assert_eq!(
            RecallPlan::infer("When did Alice move?").answer_shape,
            AnswerShape::Temporal
        );
        assert_eq!(
            RecallPlan::infer("Could you tell me which week Alice moved?").answer_shape,
            AnswerShape::Temporal
        );
        let constrained = RecallPlan::infer("Where did Alice move four years ago?");
        assert_eq!(constrained.recall_intent, RecallIntent::Temporal);
        assert_eq!(constrained.answer_shape, AnswerShape::Fact);
        assert!(constrained.has_temporal_constraint);
        let dated = RecallPlan::infer("Which activity did Alice pursue on 5 June 2023?");
        assert_eq!(dated.recall_intent, RecallIntent::Temporal);
        assert_eq!(dated.answer_shape, AnswerShape::Fact);
        assert!(dated.has_temporal_constraint);
        assert!(
            !RecallPlan::infer("When did Alice move?").has_temporal_constraint,
            "requesting a time is not itself an evidence-time constraint"
        );
    }

    #[test]
    fn classifies_typed_temporal_constraints_without_widening_event_boundaries() {
        let calendar = RecallPlan::infer("Which activity happened in June 2023?");
        assert_eq!(
            calendar.temporal_constraint().kind(),
            TemporalConstraintKind::CalendarRange
        );
        assert_eq!(calendar.temporal_constraint().direction(), None);

        for (query, direction) in [
            (
                "Which projects finished before 2020?",
                TemporalBoundaryDirection::Before,
            ),
            (
                "Which projects started after June 2023?",
                TemporalBoundaryDirection::After,
            ),
        ] {
            let plan = RecallPlan::infer(query);
            assert_eq!(
                plan.temporal_constraint().kind(),
                TemporalConstraintKind::CalendarRange,
                "{query}"
            );
            assert_eq!(
                plan.temporal_constraint().direction(),
                Some(direction),
                "{query}"
            );
        }

        for (query, direction) in [
            (
                "What problems arose before adopting Toby?",
                TemporalBoundaryDirection::Before,
            ),
            (
                "What changed after the product launch?",
                TemporalBoundaryDirection::After,
            ),
            (
                "What happened before a launch?",
                TemporalBoundaryDirection::Before,
            ),
            (
                "What changed after 3 attempts?",
                TemporalBoundaryDirection::After,
            ),
        ] {
            let plan = RecallPlan::infer(query);
            assert_eq!(
                plan.temporal_constraint().kind(),
                TemporalConstraintKind::EventBoundary,
                "{query}"
            );
            assert_eq!(
                plan.temporal_constraint().direction(),
                Some(direction),
                "{query}"
            );
            assert!(temporal_constraint_blocks_expansion(&plan), "{query}");
        }

        let trend = RecallPlan::infer("How did Alice's interests change over time?");
        assert_eq!(
            trend.temporal_constraint().kind(),
            TemporalConstraintKind::Trend
        );
        assert!(!temporal_constraint_blocks_expansion(&trend));

        for query in [
            "When did Alice move?",
            "How long did the restoration take?",
            "How often did Alice exercise?",
        ] {
            let plan = RecallPlan::infer(query);
            assert_eq!(
                plan.temporal_constraint().kind(),
                TemporalConstraintKind::None,
                "{query}"
            );
            assert!(!plan.has_temporal_constraint, "{query}");
        }
    }

    #[test]
    fn temporal_constraint_parser_rejects_lexical_and_ambiguous_boundaries() {
        for query in [
            "What happened at the afterparty?",
            "What did Alice do beforehand?",
            "After all, what did Alice choose?",
            "Before long, what did Alice choose?",
        ] {
            let plan = RecallPlan::infer(query);
            assert_eq!(
                plan.temporal_constraint().kind(),
                TemporalConstraintKind::None,
                "{query}"
            );
            assert!(!plan.has_temporal_constraint, "{query}");
        }

        for query in [
            "What changed after launch and before retirement?",
            "Which events happened after 2010 and before 2020?",
        ] {
            let plan = RecallPlan::infer(query);
            assert_eq!(
                plan.temporal_constraint().kind(),
                TemporalConstraintKind::EventBoundary,
                "{query}"
            );
            assert_eq!(plan.temporal_constraint().direction(), None, "{query}");
            assert!(plan.has_temporal_constraint, "{query}");
            assert!(temporal_constraint_blocks_expansion(&plan), "{query}");
        }
    }

    #[test]
    fn typed_temporal_override_synchronizes_legacy_plan_fields() {
        let trend = RecallPlan::infer("Which projects did Alice complete?")
            .with_temporal_constraint(TemporalConstraint::trend());
        assert!(trend.has_temporal_constraint);
        assert_eq!(trend.recall_intent, RecallIntent::Temporal);
        assert_eq!(
            trend.temporal_constraint().kind(),
            TemporalConstraintKind::Trend
        );

        let mut typed_wins = trend.clone();
        typed_wins.has_temporal_constraint = false;
        typed_wins.recall_intent = RecallIntent::Direct;
        assert_eq!(
            typed_wins.effective_temporal_constraint(),
            EffectiveTemporalConstraint::Trend
        );
        assert!(plan_has_temporal_constraint(&typed_wins));
        assert!(plan_uses_temporal_readout(&typed_wins));
        assert!(plan_allows_historical_expired(&typed_wins));
        assert!(uses_dense_query_expansion(&typed_wins));
        assert!(uses_atomic_fact_expansion(&typed_wins));
        assert_eq!(adaptive_delivery_limit(&typed_wins, 12), 12);

        let cleared = trend.with_temporal_constraint(TemporalConstraint::none());
        assert!(!cleared.has_temporal_constraint);
        assert_eq!(cleared.recall_intent, RecallIntent::Enumeration);

        let mut legacy = RecallPlan::infer("Which projects did Alice complete?");
        legacy.has_temporal_constraint = true;
        assert_eq!(
            legacy.effective_temporal_constraint(),
            EffectiveTemporalConstraint::LegacyUnknown
        );
        assert!(plan_has_temporal_constraint(&legacy));
        assert!(plan_uses_temporal_readout(&legacy));
        assert!(!plan_allows_historical_expired(&legacy));
        assert!(temporal_constraint_blocks_expansion(&legacy));
    }

    #[test]
    fn classifies_recall_coverage_from_general_answer_language() {
        let inference = RecallPlan::infer("What might Alice do next?");
        assert_eq!(inference.answer_shape, AnswerShape::Inference);
        assert_eq!(inference.coverage, RecallCoverage::Focused);

        for query in [
            "Which projects did Alice complete?",
            "What hobbies does Alice enjoy?",
            "Which cities has Alice visited?",
            "Which projects did one of Alice's teams complete?",
            "In what ways does Alice contribute to the project?",
            "In what ways is Alice participating in the community?",
        ] {
            let bare_plural = RecallPlan::infer(query);
            assert_eq!(bare_plural.answer_shape, AnswerShape::Collection, "{query}");
            assert_eq!(bare_plural.coverage, RecallCoverage::Multiple, "{query}");
        }

        for query in [
            "Which are some projects Alice completed?",
            "What are examples of hobbies Alice enjoys?",
            "What are a few cities Alice visited?",
            "Which one of these projects did Alice complete?",
            "List some projects Alice completed.",
        ] {
            let partial = RecallPlan::infer(query);
            assert_eq!(partial.answer_shape, AnswerShape::Collection, "{query}");
            assert_eq!(partial.coverage, RecallCoverage::Multiple, "{query}");
        }

        for query in [
            "List the projects Alice completed.",
            "What are all the projects Alice completed?",
            "Name every project Alice completed.",
            "Which projects did Alice inspect in each workspace?",
        ] {
            let plan = RecallPlan::infer(query);
            assert_eq!(plan.answer_shape, AnswerShape::Collection, "{query}");
            assert_eq!(plan.coverage, RecallCoverage::Exhaustive, "{query}");
        }

        assert_eq!(
            RecallPlan::infer("How many projects did Alice complete?").coverage,
            RecallCoverage::Exhaustive
        );
        assert_eq!(
            RecallPlan::infer("How often did Alice practice?").coverage,
            RecallCoverage::Exhaustive
        );
    }

    #[test]
    fn recall_coverage_is_orthogonal_to_temporal_constraints() {
        let ordinary = RecallPlan::infer("Which are some projects Alice completed before 2020?");
        assert_eq!(ordinary.recall_intent, RecallIntent::Temporal);
        assert_eq!(ordinary.answer_shape, AnswerShape::Collection);
        assert_eq!(ordinary.coverage, RecallCoverage::Multiple);
        assert!(ordinary.has_temporal_constraint);

        let exhaustive = RecallPlan::infer("List every project Alice completed before 2020.");
        assert_eq!(exhaustive.recall_intent, RecallIntent::Temporal);
        assert_eq!(exhaustive.answer_shape, AnswerShape::Collection);
        assert_eq!(exhaustive.coverage, RecallCoverage::Exhaustive);
        assert!(exhaustive.has_temporal_constraint);
    }

    #[test]
    fn over_time_is_a_temporal_retrieval_constraint() {
        let plan = RecallPlan::infer("What diet change did Sam adopt over time?");

        assert_eq!(plan.answer_shape, AnswerShape::Fact);
        assert_eq!(plan.recall_intent, RecallIntent::Temporal);
        assert!(plan.has_temporal_constraint);
        assert_eq!(
            plan.temporal_constraint().kind(),
            TemporalConstraintKind::Trend
        );
        assert_eq!(adaptive_delivery_limit(&plan, 20), 20);
    }

    #[test]
    fn trend_reader_contract_preserves_chronology_and_modality() {
        let contract =
            RecallPlan::infer("How did Alice's interests change over time?").reader_contract();
        assert!(
            contract
                .instruction(RecallReaderStage::Reflection)
                .contains("source-cited chronological ledger")
        );
        assert!(
            contract
                .instruction(RecallReaderStage::Verification)
                .contains("plan, condition, or hypothetical")
        );
        assert!(contract.context_guidance().contains("Preserve modality"));
    }

    #[test]
    fn detects_answer_shapes_beyond_sentence_prefixes() {
        assert_eq!(
            RecallPlan::infer("Do you remember when Alice moved?").answer_shape,
            AnswerShape::Temporal
        );
        assert_eq!(
            RecallPlan::infer("Alice moved on which date?").answer_shape,
            AnswerShape::Temporal
        );
        assert_eq!(
            RecallPlan::infer("John은 몇번 이사했어?").answer_shape,
            AnswerShape::Count
        );
        assert_eq!(
            RecallPlan::infer("Please list every city Alice visited.").answer_shape,
            AnswerShape::Collection
        );
        assert_eq!(
            RecallPlan::infer("What deployment tools has Nimbus developed?").answer_shape,
            AnswerShape::Collection
        );
        assert_eq!(
            RecallPlan::infer("What operational incidents does Nimbus face?").answer_shape,
            AnswerShape::Collection
        );
        assert_eq!(
            RecallPlan::infer("What kind of writing does Alice do?").answer_shape,
            AnswerShape::Collection
        );
        let coordinated =
            RecallPlan::infer("What new diet and lifestyle change did Alice adopt over time?");
        assert_eq!(coordinated.answer_shape, AnswerShape::Collection);
        assert!(coordinated.has_temporal_constraint);
        assert_eq!(
            RecallPlan::infer("What kind of cache does Nimbus use?").answer_shape,
            AnswerShape::Fact
        );
        assert_eq!(
            RecallPlan::infer("Which storage engine does the service use?").answer_shape,
            AnswerShape::Fact
        );
        assert_eq!(
            RecallPlan::infer("Would the release team postpone the rollout?").answer_shape,
            AnswerShape::Inference
        );
        assert_eq!(
            RecallPlan::infer("What might Alice do next?").answer_shape,
            AnswerShape::Inference
        );
        assert_eq!(
            RecallPlan::infer("Which deployment mode does the team prefer more than others?")
                .answer_shape,
            AnswerShape::Inference
        );
        assert_eq!(
            RecallPlan::infer("Which region could the service potentially run in?").answer_shape,
            AnswerShape::Inference
        );
        assert_eq!(
            RecallPlan::infer("Could you tell me when Alice moved?").answer_shape,
            AnswerShape::Temporal
        );
        assert_eq!(
            RecallPlan::infer("How long did the restoration take?").answer_shape,
            AnswerShape::Temporal
        );
        let frequency = RecallPlan::infer("How often does the worker refresh its lease?");
        assert_eq!(frequency.answer_shape, AnswerShape::Frequency);
        assert_eq!(frequency.recall_intent, RecallIntent::Temporal);
        assert_eq!(
            RecallPlan::infer("Why did the service move its queue?").answer_shape,
            AnswerShape::Relationship
        );
        let shared_reason = RecallPlan::infer("Why do the API and worker share a queue?");
        assert_eq!(shared_reason.answer_shape, AnswerShape::Relationship);
        assert_eq!(shared_reason.recall_intent, RecallIntent::Relational);
        assert_eq!(adaptive_delivery_limit(&shared_reason, 20), 20);
        let manner = RecallPlan::infer("How did the team roll out the schema migration?");
        assert_eq!(manner.answer_shape, AnswerShape::Relationship);
        assert_eq!(manner.recall_intent, RecallIntent::Relational);
        let origin = RecallPlan::infer("Where did the backup move from 4 years ago?");
        assert_eq!(origin.answer_shape, AnswerShape::Relationship);
        assert_eq!(origin.recall_intent, RecallIntent::Temporal);
        let completed = RecallPlan::infer("What has the release team done with the migration?");
        assert_eq!(completed.answer_shape, AnswerShape::Collection);
        assert_eq!(completed.recall_intent, RecallIntent::Enumeration);
        let yes_no = RecallPlan::infer("Does the worker use the retry queue?");
        assert_eq!(yes_no.answer_shape, AnswerShape::Inference);
        assert_eq!(yes_no.recall_intent, RecallIntent::Relational);
        let candidate =
            RecallPlan::infer("What rollout strategy could the team use to reduce downtime?");
        assert_eq!(candidate.answer_shape, AnswerShape::Inference);
        assert_eq!(candidate.recall_intent, RecallIntent::Relational);
        let candidate_guidance = product_reader_guidance(&RecallPlan::infer(
            "Which option would best satisfy the stated constraints?",
        ));
        let consequence_guidance =
            product_reader_guidance(&RecallPlan::infer("What might happen next?"));
        assert_ne!(candidate_guidance, consequence_guidance);
        assert!(candidate_guidance.contains("one concise"));
        assert!(candidate_guidance.contains("modality=likely"));
        assert!(consequence_guidance.contains("modality=possible"));
        let inference_guidance =
            product_reader_guidance(&RecallPlan::infer("What might Alice do next?"));
        assert!(inference_guidance.contains("widely known background knowledge"));
        assert!(inference_guidance.contains("never invent personal facts"));
        assert!(
            inference_guidance
                .contains("Ground every personal, session-specific, or changing premise")
        );
        assert!(inference_guidance.contains("yes/no or likely question"));
        assert!(facet_terms("Which option is preferred?").contains("prefer"));
        assert!(facet_terms("This option is a favorite.").contains("prefer"));
        assert!(
            product_reader_guidance(&RecallPlan::infer("Where does Alice live?"))
                .contains("requested attribute and granularity")
        );
        assert!(
            product_reader_guidance(&RecallPlan::infer(
                "Which activity was Alice pursuing on March 16, 2022?"
            ))
            .contains("resolved event times")
        );
        assert!(
            product_reader_guidance(&RecallPlan::infer("How long did the restoration take?"))
                .contains("source-grounded chronological event chain")
        );
        assert!(
            product_reader_guidance(&RecallPlan::infer(
                "Which regions might the service use given its latency constraints?"
            ))
            .contains("every distinct plausible item")
        );
        assert!(
            product_reader_guidance(&RecallPlan::infer(
                "Where did the backup move from 4 years ago?"
            ))
            .contains("resolves its referenced entity")
        );
        assert!(
            product_reader_guidance(&RecallPlan::infer("Which projects did Alice complete?"))
                .contains("every distinct item")
        );
        let configured_policy =
            RecallPlan::infer("What cache policy is configured for the worker?");
        assert_eq!(configured_policy.answer_shape, AnswerShape::Fact);
        assert_eq!(configured_policy.recall_intent, RecallIntent::Direct);
        assert_eq!(
            RecallPlan::infer("Which regions might the service use given its latency constraints?")
                .answer_shape,
            AnswerShape::Collection
        );
    }

    #[test]
