    #[test]
    fn temporal_evidence_requires_query_subject_overlap() {
        let query = "When did John visit the greenhouse?";
        assert!(temporal_evidence_matches(
            query,
            "John visited the greenhouse last week."
        ));
        assert!(!temporal_evidence_matches(
            query,
            "John won an intense basketball game last week."
        ));
        assert!(temporal_evidence_matches(
            "Which release did Nimbus publish in January 2023?",
            "Nimbus: Two weeks ago I published release 4.2."
        ));
    }

    #[test]
    fn temporal_complex_atomic_admission_is_range_bounded_and_fail_closed() {
        let fact_at = |id, observed_at| AtomicFact {
            id: AtomicFactId(id),
            content: "Alice reported a health incident".to_owned(),
            embedding: vec![1.0],
            source_node_ids: vec![NodeId(id)],
            entity_tags: vec!["Alice".to_owned()],
            source_session_id: format!("session-{id}"),
            scope: ScopePath::universal(),
            observed_at: Timestamp(observed_at),
            valid_from: None,
            valid_until: None,
            metadata: HashMap::new(),
        };
        let plan = RecallPlan::infer_with_answer_shape(
            "Which health incidents did Alice face in 2023?",
            AnswerShape::Collection,
        );
        let within_2023 = fact_at(1, 1_685_577_600_000);
        let before_2023 = fact_at(2, 1_625_097_600_000);

        assert!(plan.has_temporal_constraint);
        assert!(atomic_fact_matches_temporal_constraint(
            &plan,
            &within_2023,
            Timestamp(1_700_000_000_000)
        ));
        assert!(!atomic_fact_matches_temporal_constraint(
            &plan,
            &before_2023,
            Timestamp(1_700_000_000_000)
        ));

        let unresolved = RecallPlan::infer_with_answer_shape(
            "What problems did Alice face before adopting Toby?",
            AnswerShape::Collection,
        );
        assert!(unresolved.has_temporal_constraint);
        assert!(!atomic_fact_matches_temporal_constraint(
            &unresolved,
            &within_2023,
            Timestamp(1_700_000_000_000)
        ));

        let trend = RecallPlan::infer_with_answer_shape(
            "Which health incidents did Alice face over time?",
            AnswerShape::Collection,
        );
        assert!(atomic_fact_matches_temporal_constraint(
            &trend,
            &within_2023,
            Timestamp(1_700_000_000_000)
        ));
        assert!(atomic_fact_matches_temporal_constraint(
            &trend,
            &before_2023,
            Timestamp(1_700_000_000_000)
        ));
    }

