    #[test]
    fn claim_slot_selection_preserves_the_head_and_recovers_missing_fact_provenance() {
        let (mut storage, readout, _) = ranked_fixture();
        let mut ranking: Vec<_> = readout
            .iter()
            .map(|candidate| RerankedCandidate {
                node_id: candidate.node_id,
                score: candidate.score,
            })
            .collect();
        let claim_source = storage.next_node_id();
        storage
            .set_node(fixture_node(
                claim_source,
                KnowledgeType::Episodic,
                "Alice completed the missing cobalt project".to_owned(),
                "claim-session".to_owned(),
            ))
            .expect("claim source");
        let bridge_candidate = storage.next_node_id();
        storage
            .set_node(fixture_node(
                bridge_candidate,
                KnowledgeType::Semantic,
                "Alice project evidence bridge".to_owned(),
                "claim-session".to_owned(),
            ))
            .expect("bridge candidate");
        for source in [ranking[19].node_id, claim_source] {
            let edge_id = storage.next_edge_id();
            storage
                .set_edge(Edge::seeded(
                    edge_id,
                    bridge_candidate,
                    source,
                    EdgeType::ExtractedFrom,
                    1.0,
                    EdgeSource::Manual,
                    Timestamp(1),
                    Timestamp(1),
                    HashMap::new(),
                ))
                .expect("bridge provenance");
        }
        ranking.push(RerankedCandidate {
            node_id: bridge_candidate,
            score: -1.0,
        });
        seed_legacy_atomic_fact(&mut storage, AtomicFactId(1), ranking[0].node_id);
        seed_legacy_atomic_fact(&mut storage, AtomicFactId(2), claim_source);
        let markers = [
            AtomicSourceMarker {
                source_node_id: ranking[0].node_id,
                kind_priority: 0,
                fact_id: Some(AtomicFactId(1)),
            },
            AtomicSourceMarker {
                source_node_id: claim_source,
                kind_priority: 0,
                fact_id: Some(AtomicFactId(2)),
            },
        ];

        let selected = compile_ranking(
            &storage,
            &RecallPlan::infer("How many projects did Alice complete?"),
            &ranking,
            EvidenceSelection::Auto,
            20,
            &markers,
        )
        .expect("claim-slot selection");

        assert_eq!(selected.len(), 20);
        assert_eq!(
            selected[..12],
            ranking[..12],
            "the authoritative reranker head must not be removed"
        );
        assert!(
            selected
                .iter()
                .any(|candidate| candidate.node_id == bridge_candidate),
            "a candidate that adds a missing claim while preserving the victim's raw source may replace a redundant tail row"
        );
    }

    #[test]
    fn exhaustive_collection_reserves_multiple_distinct_grounded_claims() {
        let (mut storage, readout, _) = ranked_fixture();
        let ranking: Vec<_> = readout
            .iter()
            .map(|candidate| RerankedCandidate {
                node_id: candidate.node_id,
                score: candidate.score,
            })
            .collect();
        let cobalt_source = ranking[25].node_id;
        let amber_source = ranking[55].node_id;
        for (source_id, content) in [
            (cobalt_source, "Alice completed the cobalt project"),
            (amber_source, "Alice completed the amber project"),
        ] {
            let mut source = storage
                .get_node(source_id)
                .expect("grounded collection source")
                .clone();
            source.content = content.to_owned();
            source.name = content.to_owned();
            storage
                .set_node(source)
                .expect("updated grounded collection source");
        }
        seed_grounded_atomic_fact(
            &mut storage,
            AtomicFactId(1),
            cobalt_source,
            "Alice completed the cobalt project",
            "cobalt project",
        );
        seed_grounded_atomic_fact(
            &mut storage,
            AtomicFactId(2),
            amber_source,
            "Alice completed the amber project",
            "amber project",
        );
        let markers = [
            AtomicSourceMarker {
                source_node_id: cobalt_source,
                kind_priority: 0,
                fact_id: Some(AtomicFactId(1)),
            },
            AtomicSourceMarker {
                source_node_id: amber_source,
                kind_priority: 0,
                fact_id: Some(AtomicFactId(2)),
            },
        ];

        let multiple_plan = RecallPlan::infer("Which are some projects Alice completed?");
        assert_eq!(multiple_plan.coverage, RecallCoverage::Multiple);
        let multiple = compile_ranking(
            &storage,
            &multiple_plan,
            &ranking,
            EvidenceSelection::Auto,
            20,
            &markers,
        )
        .expect("multiple collection selection");

        let exhaustive_plan = RecallPlan::infer("List every project Alice completed.");
        assert_eq!(exhaustive_plan.coverage, RecallCoverage::Exhaustive);
        let exhaustive = compile_ranking(
            &storage,
            &exhaustive_plan,
            &ranking,
            EvidenceSelection::Auto,
            20,
            &markers,
        )
        .expect("exhaustive collection selection");

        let selected_grounded_claims = |selected: &[RerankedCandidate]| {
            [cobalt_source, amber_source]
                .into_iter()
                .filter(|source_id| {
                    selected
                        .iter()
                        .any(|candidate| candidate.node_id == *source_id)
                })
                .count()
        };
        assert_eq!(multiple.len(), 20);
        assert_eq!(exhaustive.len(), 20);
        assert_eq!(multiple[..12], ranking[..12]);
        assert_eq!(exhaustive[..12], ranking[..12]);
        assert_eq!(
            selected_grounded_claims(&multiple),
            1,
            "ordinary collections retain their single grounded reserve"
        );
        assert_eq!(
            selected_grounded_claims(&exhaustive),
            2,
            "explicitly exhaustive collections preserve each distinct grounded item within the bounded reserve"
        );
    }

