    #[test]
    fn grounded_atomic_fact_rejects_empty_objects_and_non_positive_spans() {
        let (mut storage, ranking, _) = ranked_fixture();
        let source_id = ranking[0].node_id;
        let evidence = "Alice completed the cobalt launch project";
        let mut source = storage
            .get_node(source_id)
            .expect("grounded source")
            .clone();
        source.name = evidence.to_owned();
        source.content = evidence.to_owned();
        storage.set_node(source).expect("updated grounded source");
        let fact_id = AtomicFactId(2);
        seed_grounded_atomic_fact(
            &mut storage,
            fact_id,
            source_id,
            evidence,
            "cobalt launch project",
        );
        let valid = storage
            .get_atomic_fact(fact_id)
            .expect("grounded fact")
            .clone();

        let mut empty_object = valid.clone();
        empty_object
            .metadata
            .insert("anamnesis:ground-object".to_owned(), "   ".to_owned());
        storage
            .set_atomic_fact(empty_object)
            .expect("empty object fact");
        assert!(
            grounded_atomic_fact(
                &storage,
                storage.get_atomic_fact(fact_id).expect("empty object fact"),
                source_id,
            )
            .expect("empty object validation")
            .is_none()
        );

        let start = valid
            .metadata
            .get("anamnesis:evidence-span-start")
            .expect("span start")
            .clone();
        let mut empty_span = valid.clone();
        empty_span
            .metadata
            .insert("anamnesis:evidence-span-end".to_owned(), start.clone());
        storage
            .set_atomic_fact(empty_span)
            .expect("empty span fact");
        assert!(
            grounded_atomic_fact(
                &storage,
                storage.get_atomic_fact(fact_id).expect("empty span fact"),
                source_id,
            )
            .expect("empty span validation")
            .is_none()
        );

        let mut reversed_span = valid;
        reversed_span.metadata.insert(
            "anamnesis:evidence-span-start".to_owned(),
            evidence.len().to_string(),
        );
        reversed_span
            .metadata
            .insert("anamnesis:evidence-span-end".to_owned(), start);
        storage
            .set_atomic_fact(reversed_span)
            .expect("reversed span fact");
        assert!(
            grounded_atomic_fact(
                &storage,
                storage
                    .get_atomic_fact(fact_id)
                    .expect("reversed span fact"),
                source_id,
            )
            .expect("reversed span validation")
            .is_none()
        );
    }

