    #[test]
    fn exhaustive_collection_keeps_common_bounded_coverage_lanes() {
        let exhaustive = RecallPlan::infer("List every project Alice completed.");
        assert_eq!(exhaustive.coverage, RecallCoverage::Exhaustive);
        assert_eq!(trace_atomic_preselection_budget(&exhaustive), (2, 1));
        assert_eq!(subject_raw_promotion_limit(&exhaustive, usize::MAX), 4);

        let method = RecallPlan::infer("How did the coordinator promote the workshop?");
        assert!(is_factual_method_request(&method));
        assert_eq!(trace_atomic_preselection_budget(&method), (4, 2));

        for plan in [
            RecallPlan::infer("Which are some projects Alice completed?"),
            RecallPlan::infer("Why did Alice complete the project?"),
            RecallPlan::infer("What project might Alice complete next?"),
            RecallPlan::infer("Where did Alice complete the project?"),
        ] {
            assert_eq!(
                trace_atomic_preselection_budget(&plan),
                (2, 1),
                "non-exhaustive plan changed its atomic budget: {:?}",
                plan
            );
            assert_eq!(
                subject_raw_promotion_limit(&plan, usize::MAX),
                4,
                "non-exhaustive plan changed its raw budget: {:?}",
                plan
            );
        }

        let temporal_exhaustive =
            RecallPlan::infer("List every project Alice completed before 2020.");
        assert_eq!(temporal_exhaustive.coverage, RecallCoverage::Exhaustive);
        assert!(temporal_exhaustive.has_temporal_constraint);
        assert_eq!(subject_raw_promotion_limit(&temporal_exhaustive, 99), 4);
    }

    #[test]
    fn exhaustive_collection_preselection_keeps_common_head_and_session_bounds() {
        let (mut storage, ranking, _) = ranked_fixture();
        for candidate in ranking.iter().take(50).skip(30) {
            let mut node = storage
                .get_node(candidate.node_id)
                .expect("semantic tail candidate")
                .clone();
            node.name = "Alice completed a pottery project overview".to_owned();
            node.content = node.name.clone();
            storage.set_node(node).expect("semantic tail candidate");
        }

        let deep_indices = [60usize, 61, 62, 63, 64, 65, 66];
        let sessions = [
            "crowded-session",
            "crowded-session",
            "crowded-session",
            "second-session",
            "second-session",
            "third-session",
            "third-session",
        ];
        for (offset, (&ranking_index, session)) in deep_indices.iter().zip(sessions).enumerate() {
            let source_id = ranking[ranking_index].node_id;
            let evidence = format!("Alice completed pottery project item {offset}");
            let mut source = storage.get_node(source_id).expect("deep source").clone();
            source.origin.session_id = session.to_owned();
            source.name = evidence.clone();
            source.content = evidence.clone();
            storage.set_node(source).expect("deep source");
            seed_structured_atomic_fact(
                &mut storage,
                AtomicFactId(500 + offset as u64),
                source_id,
                &evidence,
                "Alice",
                "completed",
                &format!("pottery project item {offset}"),
                &format!("pottery project item {offset}"),
                &evidence,
            );
        }

        let plan = RecallPlan::infer("List every pottery project Alice completed.");
        assert_eq!(plan.coverage, RecallCoverage::Exhaustive);
        let selected = coverage_preselected_ranking(&storage, &plan, &ranking, 50, &[])
            .expect("bounded exhaustive collection preselection");

        assert_eq!(DEFAULT_RERANK_CANDIDATE_LIMIT, 50);
        assert_eq!(DEFAULT_RERANK_PROTECTED_HEAD_LIMIT, 30);
        assert_eq!(DEFAULT_RERANK_FINAL_LIMIT, 20);
        assert_eq!(selected.len(), DEFAULT_RERANK_CANDIDATE_LIMIT);
        assert_eq!(
            selected[..DEFAULT_RERANK_PROTECTED_HEAD_LIMIT],
            ranking[..DEFAULT_RERANK_PROTECTED_HEAD_LIMIT]
        );
        let selected_ids: HashSet<_> = selected.iter().map(|candidate| candidate.node_id).collect();
        assert_eq!(
            selected_ids.len(),
            selected.len(),
            "duplicates spend no slots"
        );

        let selected_deep: Vec<_> = deep_indices
            .iter()
            .filter(|&&index| selected_ids.contains(&ranking[index].node_id))
            .copied()
            .collect();
        assert_eq!(selected_deep.len(), 2);
        let mut selected_by_session = HashMap::new();
        for ranking_index in selected_deep {
            let session = storage
                .get_node(ranking[ranking_index].node_id)
                .expect("selected deep source")
                .origin
                .session_id
                .clone();
            *selected_by_session.entry(session).or_insert(0usize) += 1;
        }
        assert_eq!(selected_by_session.len(), 2);
        assert!(selected_by_session.values().all(|&count| count == 1));
    }

