    #[test]
    fn action_preselection_preserves_head_candidate_cap_and_session_bounds() {
        let (mut storage, ranking, _) = ranked_fixture();
        // Give the ordinary rank-31..50 tail the same query facets so this
        // control measures only the dedicated trace replacement lane rather
        // than the independent rare-facet exchange that follows it.
        for candidate in ranking
            .iter()
            .take(DEFAULT_RERANK_CANDIDATE_LIMIT)
            .skip(DEFAULT_RERANK_PROTECTED_HEAD_LIMIT)
        {
            let mut node = storage
                .get_node(candidate.node_id)
                .expect("ordinary action-facet tail")
                .clone();
            node.name = "The technician discussed building portable devices.".to_owned();
            node.content = node.name.clone();
            storage
                .set_node(node)
                .expect("normalized action-facet tail");
        }
        let cases = [
            (60usize, "crowded-session", "built", "a portable device"),
            (61, "crowded-session", "created", "a diagnostic device"),
            (62, "crowded-session", "developed", "a weatherproof device"),
            (63, "second-session", "made", "a folding device"),
            (64, "second-session", "produced", "a wireless device"),
        ];
        for (index, session, relation, object) in cases {
            seed_ranked_action_event(
                &mut storage,
                ranking[index].node_id,
                session,
                "the technician",
                relation,
                object,
            );
        }

        let plan = RecallPlan::infer("What kinds of devices has the technician tried to build?");
        assert_eq!(trace_atomic_preselection_budget(&plan), (4, 2));
        let selected = coverage_preselected_ranking(&storage, &plan, &ranking, 50, &[])
            .expect("bounded action preselection");

        assert_eq!(selected.len(), DEFAULT_RERANK_CANDIDATE_LIMIT);
        assert_eq!(
            selected[..DEFAULT_RERANK_PROTECTED_HEAD_LIMIT],
            ranking[..DEFAULT_RERANK_PROTECTED_HEAD_LIMIT]
        );
        let selected_ids: HashSet<_> = selected.iter().map(|candidate| candidate.node_id).collect();
        let selected_deep = cases
            .iter()
            .filter(|(index, ..)| selected_ids.contains(&ranking[*index].node_id))
            .collect::<Vec<_>>();
        assert_eq!(selected_deep.len(), 4);
        let mut selected_by_session = HashMap::new();
        for (_, session, ..) in selected_deep {
            *selected_by_session.entry(*session).or_insert(0usize) += 1;
        }
        assert!(
            selected_by_session.values().all(|&count| count <= 2),
            "action trace replacements remain capped at two per session"
        );
    }

    #[test]
    fn action_preselection_rejects_future_and_expired_trace_facts_at_as_of() {
        let (mut storage, ranking, _) = ranked_fixture();
        for candidate in ranking
            .iter()
            .take(DEFAULT_RERANK_CANDIDATE_LIMIT)
            .skip(DEFAULT_RERANK_PROTECTED_HEAD_LIMIT)
        {
            let mut node = storage
                .get_node(candidate.node_id)
                .expect("ordinary action-facet tail")
                .clone();
            node.name = "The technician discussed building portable devices.".to_owned();
            node.content = node.name.clone();
            storage
                .set_node(node)
                .expect("normalized action-facet tail");
        }

        let valid_source = ranking[60].node_id;
        let _valid_fact = seed_ranked_action_event(
            &mut storage,
            valid_source,
            "valid-action-session",
            "the technician",
            "built",
            "a portable device",
        );
        let future_source = ranking[61].node_id;
        let future_fact = seed_ranked_action_event(
            &mut storage,
            future_source,
            "future-action-session",
            "the technician",
            "created",
            "a diagnostic device",
        );
        let expired_source = ranking[62].node_id;
        let expired_fact = seed_ranked_action_event(
            &mut storage,
            expired_source,
            "expired-action-session",
            "the technician",
            "developed",
            "a weatherproof device",
        );
        let mut future = storage
            .get_atomic_fact(future_fact)
            .expect("future action fact")
            .clone();
        future.observed_at = Timestamp(101);
        storage
            .set_atomic_fact(future)
            .expect("future action fact updates");
        let mut expired = storage
            .get_atomic_fact(expired_fact)
            .expect("expired action fact")
            .clone();
        expired.valid_from = Some(Timestamp(1));
        expired.valid_until = Some(Timestamp(100));
        storage
            .set_atomic_fact(expired)
            .expect("expired action fact updates");

        let plan = RecallPlan::infer("What kinds of devices has the technician tried to build?");
        let selected = coverage_preselected_ranking_with_premise_bundle_at(
            &storage,
            &plan,
            &ranking,
            DEFAULT_RERANK_CANDIDATE_LIMIT,
            &[],
            None,
            Timestamp(100),
            &ScopePath::universal(),
        )
        .expect("as-of action preselection");
        let selected_ids = selected
            .iter()
            .map(|candidate| candidate.node_id)
            .collect::<HashSet<_>>();

        assert_eq!(selected.len(), DEFAULT_RERANK_CANDIDATE_LIMIT);
        assert_eq!(
            selected[..DEFAULT_RERANK_PROTECTED_HEAD_LIMIT],
            ranking[..DEFAULT_RERANK_PROTECTED_HEAD_LIMIT]
        );
        assert!(selected_ids.contains(&valid_source));
        assert!(!selected_ids.contains(&future_source));
        assert!(!selected_ids.contains(&expired_source));
    }

