    #[test]
    fn event_boundary_route_grounds_the_anchor_before_selecting_one_side() {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let (_, first_problem) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan had difficulty locating pet-friendly housing.",
            "Morgan",
            "had difficulty",
            "locating pet-friendly housing",
            "pet-friendly housing",
            "observed",
            "affirmed",
            Timestamp(10),
            ScopePath::universal(),
        );
        let (_, second_problem) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan struggled to choose a veterinarian.",
            "Morgan",
            "struggled",
            "to choose a veterinarian",
            "veterinarian",
            "observed",
            "affirmed",
            Timestamp(20),
            ScopePath::universal(),
        );
        let (_, adoption) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan adopted Pip.",
            "Morgan",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(30),
            ScopePath::universal(),
        );
        let (_, later_activity) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan found training Pip difficult.",
            "Morgan",
            "found difficult",
            "training Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(40),
            ScopePath::universal(),
        );
        let plan = RecallPlan::infer("What problems did Morgan face before adopting Pip?");
        assert_eq!(
            plan.temporal_constraint().kind(),
            TemporalConstraintKind::EventBoundary
        );
        let query_embedding = [0.0, 1.0];

        let routed = route_atomic_fact_sources(
            &storage,
            &plan,
            &[query_embedding.as_slice()],
            Timestamp(50),
            &ScopePath::universal(),
        )
        .expect("event-relative route");
        let routed_facts: HashSet<_> = routed
            .iter()
            .flat_map(|source| source.fact_ids.iter().copied())
            .collect();

        assert!(
            routed_facts.contains(&adoption),
            "the boundary remains grounded"
        );
        assert!(routed_facts.contains(&first_problem));
        assert!(routed_facts.contains(&second_problem));
        assert!(!routed_facts.contains(&later_activity));
    }

    #[test]
    fn event_boundary_source_group_builder_is_plan_gated_bounded_distinct_and_canonical() {
        let plan = RecallPlan::infer("What problems did Morgan face before adopting Pip?");
        let route = |source_id: u64, fact_id: u64, role: EventBoundarySourceRole| {
            RoutedEventBoundarySourceMember {
                role,
                member: EventBoundarySourceMember {
                    fact_id: AtomicFactId(fact_id),
                    source_node_id: NodeId(source_id),
                },
            }
        };
        let routed = vec![
            route(30, 30, EventBoundarySourceRole::Anchor),
            route(10, 10, EventBoundarySourceRole::Anchor),
            route(20, 20, EventBoundarySourceRole::Anchor),
            route(40, 40, EventBoundarySourceRole::Target),
            route(60, 60, EventBoundarySourceRole::Target),
            route(50, 50, EventBoundarySourceRole::Target),
        ];

        let group = event_boundary_source_group(&plan, &routed).expect("bounded source group");
        assert_eq!(group.anchors.len(), 2);
        assert_eq!(group.targets.len(), 3);
        assert!(group.anchors.windows(2).all(|window| {
            (window[0].fact_id, window[0].source_node_id)
                < (window[1].fact_id, window[1].source_node_id)
        }));
        assert!(group.targets.windows(2).all(|window| {
            (window[0].fact_id, window[0].source_node_id)
                < (window[1].fact_id, window[1].source_node_id)
        }));
        let members = group.anchors.iter().chain(&group.targets);
        assert_eq!(
            members
                .clone()
                .map(|member| member.fact_id)
                .collect::<HashSet<_>>()
                .len(),
            5
        );
        assert_eq!(
            members
                .map(|member| member.source_node_id)
                .collect::<HashSet<_>>()
                .len(),
            5
        );
        assert!(
            event_boundary_source_group(
                &RecallPlan::infer("What problems does Morgan face?"),
                &routed,
            )
            .is_none()
        );
    }

    #[test]
    fn event_boundary_source_group_accepts_twelve_targets_and_rejects_thirteen() {
        let plan = RecallPlan::infer("What problems did Morgan face before adopting Pip?");
        let anchor = RoutedEventBoundarySourceMember {
            role: EventBoundarySourceRole::Anchor,
            member: EventBoundarySourceMember {
                fact_id: AtomicFactId(1),
                source_node_id: NodeId(1),
            },
        };
        let mut routed = vec![anchor];
        routed.extend((0..13).map(|offset| RoutedEventBoundarySourceMember {
            role: EventBoundarySourceRole::Target,
            member: EventBoundarySourceMember {
                fact_id: AtomicFactId(100 + offset),
                source_node_id: NodeId(100 + offset),
            },
        }));

        let group = event_boundary_source_group(&plan, &routed).expect("bounded target pool");
        assert_eq!(group.targets.len(), EVENT_BOUNDARY_GROUP_MAX_TARGETS);
        assert!(group.targets.iter().all(|member| member.fact_id.0 < 112));
        assert!(encode_event_boundary_source_group(&group).is_some());

        let mut oversized = group;
        oversized.targets.push(EventBoundarySourceMember {
            fact_id: AtomicFactId(112),
            source_node_id: NodeId(112),
        });
        canonical_event_boundary_members(&mut oversized.targets);
        assert!(!event_boundary_source_group_is_well_formed(&oversized));
        assert!(encode_event_boundary_source_group(&oversized).is_none());
    }

    #[test]
    fn event_boundary_source_group_uses_only_dedicated_roles_not_generic_priorities() {
        let mut fixture = event_boundary_group_fixture();
        let planned_fact_id = fixture.targets[0].fact_id;
        let mut planned = fixture
            .storage
            .get_atomic_fact(planned_fact_id)
            .expect("planned target fact")
            .clone();
        planned.metadata.insert(
            super::super::REVIEWED_DERIVATION_MODALITY_KEY.to_owned(),
            "planned".to_owned(),
        );
        fixture
            .storage
            .set_atomic_fact(planned)
            .expect("planned target mutation");

        let query_embedding = [1.0, 0.0];
        let mut routed = route_event_boundary_fact_sources_with_roles(
            &fixture.storage,
            &fixture.plan,
            &[query_embedding.as_slice()],
            fixture.as_of,
            &ScopePath::universal(),
        )
        .expect("dedicated role route");
        assert!(
            routed
                .sources
                .iter()
                .flat_map(|source| &source.fact_ids)
                .any(|fact_id| *fact_id == planned_fact_id),
            "ordinary target routing may still carry the fact as a generic candidate"
        );
        assert!(
            routed
                .members
                .iter()
                .all(|member| member.member.fact_id != planned_fact_id),
            "generic candidate priority cannot grant a target proof role"
        );
        for source in &mut routed.sources {
            source.record_fact_priority(planned_fact_id, 4);
        }
        let group = event_boundary_source_group(&fixture.plan, &routed.members)
            .expect("remaining explicit event roles");
        assert!(
            group
                .anchors
                .iter()
                .chain(&group.targets)
                .all(|member| member.fact_id != planned_fact_id)
        );
    }

    #[test]
    fn event_boundary_source_group_codec_rejects_malformed_duplicate_and_noncanonical_traces() {
        let fixture = event_boundary_group_fixture();
        let encoded =
            encode_event_boundary_source_group(&fixture.group).expect("canonical group trace");
        assert_eq!(
            parse_event_boundary_source_group(std::slice::from_ref(&encoded)),
            Some(fixture.group.clone())
        );

        let malformed = [
            "event_boundary_source_group:v1:a=;t=2.2".to_owned(),
            "event_boundary_source_group:v1:a=1.1;t=".to_owned(),
            "event_boundary_source_group:v1:a=1.1,2.2,3.3;t=4.4".to_owned(),
            "event_boundary_source_group:v1:a=2.2,1.1;t=3.3".to_owned(),
            "event_boundary_source_group:v1:a=1.1;t=1.2".to_owned(),
            "event_boundary_source_group:v1:a=1.1;t=2.1".to_owned(),
            "event_boundary_source_group:v1:t=2.2;a=1.1".to_owned(),
            "event_boundary_source_group:v1:a=one.1;t=2.2".to_owned(),
            format!(
                "{EVENT_BOUNDARY_SOURCE_GROUP_TRACE_PREFIX}{}",
                "x".repeat(EVENT_BOUNDARY_GROUP_MAX_TRACE_BYTES + 1)
            ),
        ];
        for trace in malformed {
            assert!(
                parse_event_boundary_source_group(std::slice::from_ref(&trace)).is_none(),
                "malformed trace must fail closed: {trace}"
            );
        }
        assert!(parse_event_boundary_source_group(&[encoded.clone(), encoded.clone()]).is_none());

        let mut noncanonical = fixture.group.clone();
        noncanonical.targets.reverse();
        assert!(encode_event_boundary_source_group(&noncanonical).is_none());
    }

    #[test]
    fn event_boundary_source_group_projects_candidate_fifty_and_requires_a_target() {
        let mut fixture = event_boundary_group_fixture();
        let mut ordinary = Vec::new();
        for index in 0..48 {
            let id = fixture.storage.next_node_id();
            fixture
                .storage
                .set_node(fixture_node(
                    id,
                    KnowledgeType::Episodic,
                    format!("ordinary candidate {index}"),
                    format!("ordinary-session-{index}"),
                ))
                .expect("ordinary candidate");
            ordinary.push(id);
        }
        let mut node_ids = vec![
            fixture.anchor.source_node_id,
            fixture.targets[0].source_node_id,
        ];
        node_ids.extend(ordinary.iter().take(47).copied());
        node_ids.push(fixture.targets[1].source_node_id);
        node_ids.push(ordinary[47]);
        let mut ranking = node_ids
            .iter()
            .enumerate()
            .map(|(index, node_id)| test_readout_candidate(*node_id, 100.0 - index as f64))
            .collect::<Vec<_>>();

        assert!(
            encode_represented_event_boundary_source_group(
                &fixture.storage,
                &fixture.group,
                &ranking,
                DEFAULT_RERANK_CANDIDATE_LIMIT,
            )
            .expect("represented group encoding")
            .is_some()
        );
        ranking.swap(49, 50);
        let one_target = encode_represented_event_boundary_source_group(
            &fixture.storage,
            &fixture.group,
            &ranking,
            DEFAULT_RERANK_CANDIDATE_LIMIT,
        )
        .expect("one-target group encoding")
        .expect("one represented target remains a valid group");
        let projected = parse_event_boundary_source_group(&[one_target])
            .expect("projected one-target group trace");
        assert_eq!(projected.anchors.len(), 1);
        assert_eq!(projected.targets.len(), 1);

        let no_target_ranking = ranking
            .iter()
            .filter(|candidate| {
                fixture
                    .targets
                    .iter()
                    .all(|target| target.source_node_id != candidate.node_id)
            })
            .cloned()
            .collect::<Vec<_>>();
        assert!(
            encode_represented_event_boundary_source_group(
                &fixture.storage,
                &fixture.group,
                &no_target_ranking,
                DEFAULT_RERANK_CANDIDATE_LIMIT,
            )
            .expect("zero-target group encoding")
            .is_none(),
            "a candidate surface without an answer-bearing target must not emit a trace"
        );
    }

    #[test]
    fn event_boundary_source_group_revalidates_exact_current_routing_as_one_unit() {
        let mut fixture = event_boundary_group_fixture();
        let ranking = fixture
            .group
            .anchors
            .iter()
            .chain(&fixture.group.targets)
            .enumerate()
            .map(|(index, member)| {
                test_readout_candidate(member.source_node_id, 10.0 - index as f64)
            })
            .collect::<Vec<_>>();
        let encoded =
            encode_event_boundary_source_group(&fixture.group).expect("canonical group trace");
        assert_eq!(
            validated_event_boundary_source_group(
                &fixture.storage,
                &fixture.plan,
                std::slice::from_ref(&encoded),
                &ranking,
                fixture.as_of,
                &ScopePath::universal(),
            )
            .expect("validated event-boundary group"),
            Some(fixture.group.clone())
        );

        let mut omitted = fixture.group.clone();
        omitted.targets.pop();
        let omitted =
            encode_event_boundary_source_group(&omitted).expect("well-formed omitted trace");
        assert!(
            validated_event_boundary_source_group(
                &fixture.storage,
                &fixture.plan,
                &[omitted],
                &ranking,
                fixture.as_of,
                &ScopePath::universal(),
            )
            .expect("omitted trace validation")
            .is_none(),
            "the trace must equal the complete canonical candidate projection"
        );

        let forged_source = fixture.storage.next_node_id();
        fixture
            .storage
            .set_node(fixture_node(
                forged_source,
                KnowledgeType::Episodic,
                "Morgan mentioned housing.".to_owned(),
                "forged-session".to_owned(),
            ))
            .expect("forged source");
        let mut forged = fixture.group.clone();
        forged.targets[0].source_node_id = forged_source;
        canonical_event_boundary_members(&mut forged.targets);
        let forged = encode_event_boundary_source_group(&forged).expect("well-formed forged trace");
        assert!(
            validated_event_boundary_source_group(
                &fixture.storage,
                &fixture.plan,
                &[forged],
                &ranking,
                fixture.as_of,
                &ScopePath::universal(),
            )
            .expect("forged trace validation")
            .is_none()
        );

        let stale_source_id = fixture.targets[0].source_node_id;
        let mut stale_source = fixture
            .storage
            .get_node(stale_source_id)
            .expect("target source")
            .clone();
        stale_source.content.push_str(" Altered after routing.");
        fixture
            .storage
            .set_node(stale_source)
            .expect("replace target source incarnation");
        assert!(
            validated_event_boundary_source_group(
                &fixture.storage,
                &fixture.plan,
                &[encoded],
                &ranking,
                fixture.as_of,
                &ScopePath::universal(),
            )
            .expect("stale trace validation")
            .is_none()
        );
    }

    #[test]
    fn event_boundary_source_group_revalidation_rejects_invalid_roles() {
        for invalidation in [
            "wrong-side",
            "wrong-subject",
            "modal",
            "retracted",
            "missing-valid-from",
        ] {
            let mut fixture = event_boundary_group_fixture();
            let ranking = fixture
                .group
                .anchors
                .iter()
                .chain(&fixture.group.targets)
                .enumerate()
                .map(|(index, member)| {
                    test_readout_candidate(member.source_node_id, 10.0 - index as f64)
                })
                .collect::<Vec<_>>();
            let encoded =
                encode_event_boundary_source_group(&fixture.group).expect("canonical group trace");
            let target_fact_id = fixture.targets[0].fact_id;
            let mut fact = fixture
                .storage
                .get_atomic_fact(target_fact_id)
                .expect("target fact")
                .clone();
            match invalidation {
                "wrong-side" => fact.valid_from = Some(Timestamp(35)),
                "wrong-subject" => {
                    fact.metadata.insert(
                        super::super::REVIEWED_DERIVATION_SUBJECT_KEY.to_owned(),
                        "Riley".to_owned(),
                    );
                }
                "modal" => {
                    fact.metadata.insert(
                        super::super::REVIEWED_DERIVATION_MODALITY_KEY.to_owned(),
                        "planned".to_owned(),
                    );
                }
                "retracted" => {
                    fact.metadata
                        .insert("retracted".to_owned(), "true".to_owned());
                }
                "missing-valid-from" => fact.valid_from = None,
                _ => unreachable!("closed invalidation fixture"),
            }
            fixture
                .storage
                .set_atomic_fact(fact)
                .expect("invalidated target fact");
            assert!(
                validated_event_boundary_source_group(
                    &fixture.storage,
                    &fixture.plan,
                    &[encoded],
                    &ranking,
                    fixture.as_of,
                    &ScopePath::universal(),
                )
                .expect("invalid role validation")
                .is_none(),
                "stale trace must not bypass {invalidation}"
            );
        }
    }

    #[test]
    fn event_boundary_source_group_final_selection_is_complete_and_preserves_protected_sources() {
        let mut fixture = event_boundary_group_fixture();
        let mut ranking = Vec::new();
        ranking.push(RerankedCandidate {
            node_id: fixture.anchor.source_node_id,
            score: 100.0,
        });
        for index in 0..24 {
            let id = fixture.storage.next_node_id();
            fixture
                .storage
                .set_node(fixture_node(
                    id,
                    KnowledgeType::Episodic,
                    format!("ordinary final evidence {index}"),
                    format!("final-session-{index}"),
                ))
                .expect("ordinary final evidence");
            ranking.push(RerankedCandidate {
                node_id: id,
                score: 99.0 - index as f64,
            });
        }
        ranking.push(RerankedCandidate {
            node_id: fixture.targets[0].source_node_id,
            score: -1.0,
        });
        ranking.push(RerankedCandidate {
            node_id: fixture.targets[1].source_node_id,
            score: -2.0,
        });
        let baseline = ranking[..20].to_vec();
        let path_source = baseline[19].node_id;
        let premise_sources = [baseline[17].node_id, baseline[18].node_id];
        let paths = [AtomicRelationPath {
            fact_ids: Vec::new(),
            hops: Vec::new(),
            source_groups: vec![vec![path_source]],
        }];
        let premise_bundle = PremiseBundleTrace {
            members: premise_sources
                .iter()
                .enumerate()
                .map(|(ordinal, source_node_id)| PremiseBundleMember {
                    slot_id: DensePremiseSlotId::from_ordinal(ordinal),
                    fact_id: AtomicFactId(10_000 + ordinal as u64),
                    source_node_id: *source_node_id,
                    authority: PremiseFactAuthority::GroundedRawSpan,
                })
                .collect(),
        };

        let selected = event_boundary_source_group_ranking(
            &fixture.storage,
            &ranking,
            &baseline,
            20,
            Some(&fixture.group),
            &paths,
            Some(&premise_bundle),
        )
        .expect("complete event-boundary final group");
        assert_eq!(selected.len(), 20);
        assert_eq!(selected[..12], baseline[..12]);
        for required in [
            fixture.anchor.source_node_id,
            fixture.targets[0].source_node_id,
            fixture.targets[1].source_node_id,
            path_source,
            premise_sources[0],
            premise_sources[1],
        ] {
            assert!(
                selected
                    .iter()
                    .any(|candidate| candidate.node_id == required),
                "required or already-protected source {required:?} must survive"
            );
        }

        let missing_target_ranking = ranking
            .iter()
            .copied()
            .filter(|candidate| candidate.node_id != fixture.targets[1].source_node_id)
            .collect::<Vec<_>>();
        assert_eq!(
            event_boundary_source_group_ranking(
                &fixture.storage,
                &missing_target_ranking,
                &baseline,
                20,
                Some(&fixture.group),
                &paths,
                Some(&premise_bundle),
            )
            .expect("single representable target group")
            .iter()
            .filter(|candidate| {
                fixture
                    .targets
                    .iter()
                    .any(|target| target.source_node_id == candidate.node_id)
            })
            .count(),
            1,
            "a canonical candidate projection with one target remains a valid complete group"
        );

        let no_anchor_baseline = ranking[1..21].to_vec();
        assert_eq!(
            event_boundary_source_group_ranking(
                &fixture.storage,
                &ranking,
                &no_anchor_baseline,
                20,
                Some(&fixture.group),
                &[],
                None,
            )
            .expect("missing anchor event-boundary group"),
            no_anchor_baseline,
            "target evidence cannot be forced without a retained boundary anchor"
        );

        let narrow_baseline = ranking[..13].to_vec();
        assert_eq!(
            event_boundary_source_group_ranking(
                &fixture.storage,
                &ranking,
                &narrow_baseline,
                13,
                Some(&fixture.group),
                &[],
                None,
            )
            .expect("insufficient mutable tail"),
            narrow_baseline,
            "a single tail slot must not admit a partial two-target group"
        );
    }

    #[test]
    fn event_boundary_source_group_uses_external_reranker_order_for_two_targets() {
        let mut fixture = event_boundary_group_fixture();
        let (third_source, third_fact) = seed_reviewed_event_boundary_fact(
            &mut fixture.storage,
            "Morgan struggled to arrange accessible transport.",
            "Morgan",
            "struggled",
            "to arrange accessible transport",
            "accessible transport",
            "observed",
            "affirmed",
            Timestamp(25),
            ScopePath::universal(),
        );
        fixture.group.targets.push(EventBoundarySourceMember {
            fact_id: third_fact,
            source_node_id: third_source,
        });
        canonical_event_boundary_members(&mut fixture.group.targets);
        assert!(event_boundary_source_group_is_well_formed(&fixture.group));

        let mut ranking = vec![RerankedCandidate {
            node_id: fixture.anchor.source_node_id,
            score: 100.0,
        }];
        for index in 0..20 {
            let id = fixture.storage.next_node_id();
            fixture
                .storage
                .set_node(fixture_node(
                    id,
                    KnowledgeType::Episodic,
                    format!("reranker-order control {index}"),
                    format!("reranker-order-session-{index}"),
                ))
                .expect("reranker-order control");
            ranking.push(RerankedCandidate {
                node_id: id,
                score: 90.0 - index as f64,
            });
        }
        let preferred_targets = [third_source, fixture.targets[0].source_node_id];
        let excluded_target = fixture.targets[1].source_node_id;
        for (offset, source_id) in [preferred_targets[0], preferred_targets[1], excluded_target]
            .into_iter()
            .enumerate()
        {
            ranking.push(RerankedCandidate {
                node_id: source_id,
                score: -(offset as f64),
            });
        }
        let baseline = ranking[..20].to_vec();
        let selected = event_boundary_source_group_ranking(
            &fixture.storage,
            &ranking,
            &baseline,
            20,
            Some(&fixture.group),
            &[],
            None,
        )
        .expect("reranker-ordered target reserve");
        for source_id in preferred_targets {
            assert!(
                selected
                    .iter()
                    .any(|candidate| candidate.node_id == source_id)
            );
        }
        assert!(
            selected
                .iter()
                .all(|candidate| candidate.node_id != excluded_target),
            "the third target in external ranking cannot consume the two-target reserve"
        );
    }

