    #[test]
    fn event_boundary_order_uses_explicit_fact_time_and_requires_it() {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let (target_source, target) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan struggled to locate accessible housing.",
            "Morgan",
            "struggled",
            "to locate accessible housing",
            "accessible housing",
            "observed",
            "affirmed",
            Timestamp(50),
            ScopePath::universal(),
        );
        let mut source = storage
            .get_node(target_source)
            .expect("target source")
            .clone();
        source.valid_from = Some(Timestamp(50));
        storage.set_node(source).expect("later source validity");
        let mut target_fact = storage
            .get_atomic_fact(target)
            .expect("target fact")
            .clone();
        target_fact.valid_from = Some(Timestamp(10));
        storage
            .delete_atomic_fact(target)
            .expect("replace target fact authority");
        storage
            .set_atomic_fact(target_fact)
            .expect("target fact time");
        let stored_target = storage.get_atomic_fact(target).expect("stored target");
        let target_metadata = atomic_routing_metadata(stored_target).expect("target metadata");
        assert_eq!(
            event_boundary_fact_time(stored_target, Timestamp(60)),
            Some(Timestamp(10))
        );
        assert!(
            grounded_atomic_fact(&storage, stored_target, target_metadata.evidence_source)
                .expect("target grounding")
                .is_some()
        );
        assert!(event_boundary_fact_states_difficulty(
            stored_target,
            &target_metadata,
            Timestamp(60)
        ));

        let (_, anchor) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan adopted Pip.",
            "Morgan",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(40),
            ScopePath::universal(),
        );
        let mut anchor_fact = storage
            .get_atomic_fact(anchor)
            .expect("anchor fact")
            .clone();
        anchor_fact.valid_from = Some(Timestamp(30));
        storage
            .set_atomic_fact(anchor_fact)
            .expect("anchor fact time");

        let (_, missing_time) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan adopted Pip in an undated account.",
            "Morgan",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(20),
            ScopePath::universal(),
        );
        let mut undated = storage
            .get_atomic_fact(missing_time)
            .expect("undated fact")
            .clone();
        undated.valid_from = None;
        storage.set_atomic_fact(undated).expect("remove fact time");

        let routed = routed_event_boundary_fact_ids(
            &storage,
            "What problems did Morgan face before adopting Pip?",
            Timestamp(60),
            &ScopePath::universal(),
        );
        assert!(routed.contains(&anchor));
        assert!(
            routed.contains(&target),
            "target was observed after the anchor but has earlier explicit fact time"
        );
        assert!(!routed.contains(&missing_time));
    }

