    #[test]
    fn event_boundary_anchor_rejects_wrong_subject_scope_future_and_stale_sources() {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let scope_a = ScopePath::new("workspace/a").expect("scope a");
        let scope_b = ScopePath::new("workspace/b").expect("scope b");
        let (_, target) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan had difficulty finding housing.",
            "Morgan",
            "had difficulty",
            "finding housing",
            "housing",
            "observed",
            "affirmed",
            Timestamp(10),
            scope_a.clone(),
        );
        let (_, wrong_subject) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Riley adopted Pip.",
            "Riley",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(20),
            scope_a.clone(),
        );
        let (_, wrong_scope) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan adopted Pip.",
            "Morgan",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(25),
            scope_b,
        );
        let (stale_source, stale_fact) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan adopted Pip during the spring.",
            "Morgan",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(28),
            scope_a.clone(),
        );
        let mut changed_source = storage
            .get_node(stale_source)
            .expect("stale source")
            .clone();
        changed_source.content = "Morgan discussed a different event.".to_owned();
        storage
            .set_node(changed_source)
            .expect("changed stale source");
        let (_, retracted) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan adopted Pip in a retracted account.",
            "Morgan",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(29),
            scope_a.clone(),
        );
        let mut retracted_fact = storage
            .get_atomic_fact(retracted)
            .expect("retracted event fact")
            .clone();
        retracted_fact
            .metadata
            .insert("retracted".to_owned(), "true".to_owned());
        storage
            .set_atomic_fact(retracted_fact)
            .expect("retract event fact");
        let (_, valid_anchor) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan adopted Pip.",
            "Morgan",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(30),
            scope_a.clone(),
        );
        let (_, future) = seed_reviewed_event_boundary_fact(
            &mut storage,
            "Morgan adopted Pip in a future record.",
            "Morgan",
            "adopted",
            "Pip",
            "Pip",
            "observed",
            "affirmed",
            Timestamp(60),
            scope_a.clone(),
        );

        let routed = routed_event_boundary_fact_ids(
            &storage,
            "What problems did Morgan face before adopting Pip?",
            Timestamp(50),
            &scope_a,
        );
        assert!(routed.contains(&valid_anchor));
        assert!(routed.contains(&target));
        for rejected in [wrong_subject, wrong_scope, stale_fact, retracted, future] {
            assert!(!routed.contains(&rejected));
        }
    }

    #[test]
    fn temporal_fact_reserve_admits_observed_or_event_interval_overlap() {
        const MAY_8_2023: u64 = 1_683_504_000_000;
        const DAY_MS: u64 = 86_400_000;
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let (observed_source, _) = seed_temporal_structured_fact(
            &mut storage,
            "Nimbus",
            "trail running",
            Timestamp(MAY_8_2023 + 3_600_000),
        );
        let (event_source, event_fact_id) = seed_temporal_structured_fact(
            &mut storage,
            "Nimbus",
            "route planning",
            Timestamp(MAY_8_2023 + DAY_MS * 2),
        );
        let mut event_fact = storage
            .get_atomic_fact(event_fact_id)
            .expect("event fact")
            .clone();
        event_fact.valid_from = Some(Timestamp(MAY_8_2023));
        event_fact.valid_until = Some(Timestamp(MAY_8_2023 + DAY_MS));
        storage
            .set_atomic_fact(event_fact)
            .expect("event interval stores");

        let plan = RecallPlan::infer_with_answer_shape(
            "What activity was Nimbus pursuing on 2023-05-08?",
            AnswerShape::Fact,
        );
        assert_eq!(plan.recall_intent, RecallIntent::Temporal);
        let query_embedding = [0.0, 1.0];
        let routed = route_atomic_fact_sources(
            &storage,
            &plan,
            &[query_embedding.as_slice()],
            Timestamp(MAY_8_2023 + DAY_MS * 4),
            &ScopePath::universal(),
        )
        .expect("temporal fact reserve");
        let routed_ids: HashSet<_> = routed
            .iter()
            .map(|source| source.candidate.node_id)
            .collect();
        assert_eq!(
            routed_ids,
            HashSet::from([observed_source, event_source]),
            "either an observation point or explicit fact interval may satisfy the date"
        );
    }

