    #[test]
    fn temporal_fact_final_selector_preserves_one_external_order_witness() {
        const MAY_8_2023: u64 = 1_683_504_000_000;
        const DAY_MS: u64 = 86_400_000;
        let (mut storage, readout, _) = ranked_fixture();
        let ranking: Vec<_> = readout
            .iter()
            .map(|candidate| RerankedCandidate {
                node_id: candidate.node_id,
                score: candidate.score,
            })
            .collect();
        let first_source = ranking[24].node_id;
        let first_fact = seed_ranked_temporal_event(
            &mut storage,
            first_source,
            "Orion",
            "pursued",
            "a coastal survey",
            Timestamp(MAY_8_2023 + 3_600_000),
            ScopePath::universal(),
        );
        let second_source = ranking[28].node_id;
        let second_fact = seed_ranked_temporal_event(
            &mut storage,
            second_source,
            "Orion",
            "pursued",
            "an archive review",
            Timestamp(MAY_8_2023 + 7_200_000),
            ScopePath::universal(),
        );
        let plan = RecallPlan::infer_with_answer_shape(
            "What activity was Orion pursuing on 2023-05-08?",
            AnswerShape::Fact,
        );
        let markers = [
            AtomicSourceMarker {
                source_node_id: second_source,
                kind_priority: 0,
                fact_id: Some(second_fact),
            },
            AtomicSourceMarker {
                source_node_id: first_source,
                kind_priority: 0,
                fact_id: Some(first_fact),
            },
        ];
        let validated = validated_final_selection_atomic_source_markers(
            &storage,
            &plan,
            &markers,
            Timestamp(MAY_8_2023 + DAY_MS),
            &ScopePath::universal(),
        )
        .expect("temporal witness markers validate");
        let selected = temporal_fact_witness_ranking(
            &storage,
            &plan,
            &ranking,
            &ranking[..20],
            20,
            &validated,
        )
        .expect("one final temporal witness");

        assert_eq!(selected.len(), 20);
        assert_eq!(&selected[..12], &ranking[..12]);
        assert!(
            selected
                .iter()
                .any(|candidate| candidate.node_id == first_source),
            "the first matching external-reranker document must be preserved"
        );
        assert!(
            selected
                .iter()
                .all(|candidate| candidate.node_id != second_source),
            "the temporal Fact lane may reserve at most one final document"
        );
    }

