    #[test]
    fn trend_atomic_routing_admits_expired_history_without_widening_other_authority_gates() {
        let mut storage = SqliteStorage::in_memory().expect("in-memory storage");
        let (expired_source, _) = seed_atomic_routing_case(
            &mut storage,
            "expired historical evidence",
            |source| {
                source.valid_from = Some(Timestamp(1));
                source.valid_until = Some(Timestamp(5));
            },
            |fact| {
                fact.valid_from = Some(Timestamp(1));
                fact.valid_until = Some(Timestamp(5));
            },
        );
        seed_atomic_routing_case(
            &mut storage,
            "future fact evidence",
            |_| {},
            |fact| fact.observed_at = Timestamp(10),
        );
        seed_atomic_routing_case(
            &mut storage,
            "future source evidence",
            |source| {
                source.created_at = Timestamp(10);
                source.updated_at = Timestamp(10);
                source.accessed_at = Timestamp(10);
            },
            |_| {},
        );
        seed_atomic_routing_case(
            &mut storage,
            "retracted fact evidence",
            |_| {},
            |fact| {
                fact.metadata
                    .insert("retracted".to_owned(), "true".to_owned());
            },
        );
        seed_atomic_routing_case(
            &mut storage,
            "retracted source evidence",
            |source| {
                source
                    .metadata
                    .insert("retracted".to_owned(), "true".to_owned());
            },
            |_| {},
        );
        seed_atomic_routing_case(
            &mut storage,
            "malformed fact evidence",
            |_| {},
            |fact| {
                fact.valid_from = Some(Timestamp(6));
                fact.valid_until = Some(Timestamp(5));
            },
        );
        seed_atomic_routing_case(
            &mut storage,
            "malformed source evidence",
            |source| {
                source.valid_from = Some(Timestamp(6));
                source.valid_until = Some(Timestamp(5));
            },
            |_| {},
        );
        seed_atomic_routing_case(
            &mut storage,
            "disjoint historical evidence",
            |source| {
                source.valid_from = Some(Timestamp(1));
                source.valid_until = Some(Timestamp(3));
            },
            |fact| {
                fact.valid_from = Some(Timestamp(3));
                fact.valid_until = Some(Timestamp(5));
            },
        );
        seed_atomic_routing_case(
            &mut storage,
            "disjoint scope evidence",
            |source| {
                source.origin.scope = ScopePath::new("workspace/a").expect("source scope");
            },
            |_| {},
        );
        let (reincarnated_source, _) =
            seed_atomic_routing_case(&mut storage, "reincarnated evidence", |_| {}, |_| {});
        let replacement = storage
            .get_node(reincarnated_source)
            .expect("original source")
            .clone();
        storage
            .delete_node(reincarnated_source)
            .expect("original source deletes");
        assert_eq!(storage.next_node_id(), reincarnated_source);
        storage
            .set_node(replacement)
            .expect("replacement source stores");

        let plan = RecallPlan::infer_with_answer_shape(
            "How did the evidence change over time?",
            AnswerShape::Fact,
        )
        .with_temporal_constraint(TemporalConstraint::trend());
        let query_embedding = [1.0];
        let routed = route_atomic_fact_sources(
            &storage,
            &plan,
            &[query_embedding.as_slice()],
            Timestamp(5),
            &ScopePath::new("workspace/b").expect("query scope"),
        )
        .expect("historical trend route");

        assert_eq!(
            routed
                .iter()
                .map(|source| source.candidate.node_id)
                .collect::<Vec<_>>(),
            vec![expired_source],
            "Trend may recover expired history, but no other authority boundary"
        );

        let current = RecallPlan::infer_with_answer_shape(
            "How is the evidence related?",
            AnswerShape::Relationship,
        );
        let current_routed = route_atomic_fact_sources(
            &storage,
            &current,
            &[query_embedding.as_slice()],
            Timestamp(5),
            &ScopePath::new("workspace/b").expect("current query scope"),
        )
        .expect("current route");
        assert!(
            current_routed
                .iter()
                .all(|source| source.candidate.node_id != expired_source),
            "non-Trend routes retain half-open current-validity semantics"
        );
    }

