            storage.set_node(source).expect("scoped source stores");
            let mut fact = storage
                .get_atomic_fact(fact_id)
                .expect("scoped fact exists")
                .clone();
            fact.scope = scope;
            storage.set_atomic_fact(fact).expect("scoped fact stores");
